/* ------------------------------------------------------------------ world -- */
#define TILE   4.0f          /* world metres per map tile */
#define MAPW   CG_W         /* generated at boot by citygen.h */
#define MAPH   CG_H
#define ROADW  7            /* max lanes a "straight" corridor spans (widest avenues) */

/* tiles: '.' road  ',' pavement  '~' water  ' ' grass  'B' bridge  '#'/'O'/'H' buildings.
 * The city is a const flash array (city_map.h, baked from assets/city.png) — ZERO
 * per-tile SRAM. Autotiling + lane-corridor info are computed on the fly for the
 * ~200 visible tiles each frame, so the map scales to any size for free. */
static char tile_at(int x, int z) {
    if (x < 0 || z < 0 || x >= MAPW || z >= MAPH) return '~';   /* water border (island) */
    return (char)g_city[z*MAPW + x];
}
static int is_roadlike(int x, int z){ char c=tile_at(x,z); return c=='.'||c=='B'; }  /* road/bridge */
static int is_road(int x, int z) { char c = tile_at(x, z); return c=='.'||c==','||c=='B'; }
static int is_solid(int x, int z){ char c = tile_at(x, z); return c=='#'||c=='O'||c=='H'; }

/* GARAGE bays: a few building tiles carved open (drivable, no collider, no cube) so you
 * can drive a car IN to respray / sell. Registered at marker placement; used by the
 * passability, collision, and building-draw code below. */
#define NGARAGE 6
static struct { int16_t x, z; uint8_t kind; int8_t ox, oz; } g_gar[NGARAGE]; static int g_ngar;  /* (ox,oz)=opening dir (out toward the street) */
static int is_garage(int x, int z){ for(int i=0;i<g_ngar;i++) if(g_gar[i].x==x && g_gar[i].z==z) return 1; return 0; }
static int garage_kind_at(int x, int z){ for(int i=0;i<g_ngar;i++) if(g_gar[i].x==x && g_gar[i].z==z) return g_gar[i].kind; return -1; }

/* corridor classification for lane markings, computed on demand (capped scans). */
static void corridor_info(int x, int z, int *orient, int *pos, int *span) {
    *orient = 0; *pos = 0; *span = 1;
    if (!is_roadlike(x,z)) return;
    int eN=0,eS=0,eE=0,eW=0, cap=ROADW+2;
    while (eN<cap && is_roadlike(x,z-1-eN)) eN++;
    while (eS<cap && is_roadlike(x,z+1+eS)) eS++;
    while (eE<cap && is_roadlike(x+1+eE,z)) eE++;
    while (eW<cap && is_roadlike(x-1-eW,z)) eW++;
    int vext=eN+eS+1, hext=eE+eW+1;
    if (vext<=ROADW && hext>ROADW)      { *orient=1; *pos=eN; *span=vext; }
    else if (hext<=ROADW && vext>ROADW) { *orient=2; *pos=eW; *span=hext; }
    else                                { *orient=3; }
}
/* Traffic lights cost FOUR BYTES for the whole city: this clock. A junction's
 * phase is a pure function of its tile coordinates and the time, so nothing is
 * stored per junction and none of it has to be found, built or recycled as the
 * player moves. corridor_info() already reports orient==3 for a crossing, so
 * even "where are the junctions" is derived from the map on demand. */
static float    g_ltime;                /* traffic-light clock, seconds */

/* Is this tile a real CROSSING?
 *
 * corridor_info's orient==3 is its else-branch: it means "neither a clean
 * one-axis corridor", which is true of a crossing AND of a short isolated road
 * stub whose extents are both SMALLER than a road width. Using it alone put
 * traffic lights on scraps of road that cross nothing. This requires both
 * extents to actually exceed ROADW, which is the crossing case only. */
static int is_junction(int x, int z) {
    if (!is_roadlike(x,z)) return 0;
    int eN=0,eS=0,eE=0,eW=0, cap=ROADW+2;
    while (eN<cap && is_roadlike(x,z-1-eN)) eN++;
    while (eS<cap && is_roadlike(x,z+1+eS)) eS++;
    while (eE<cap && is_roadlike(x+1+eE,z)) eE++;
    while (eW<cap && is_roadlike(x-1-eW,z)) eW++;
    return (eN+eS+1) > ROADW && (eE+eW+1) > ROADW;
}

/* Traffic lights, with no state per junction.
 *
 * LIGHT_CYCLE is the full period; each axis holds green for half of it, minus
 * LIGHT_AMBER at the end of its turn. The junction's tile coordinates are
 * hashed into an offset so neighbouring crossings are not all in lockstep —
 * without that the whole grid blinks as one and the city looks mechanical.
 *
 * axis: 0 = traffic travelling along X (east-west), 1 = along Z. Returns
 * LIGHT_GREEN / LIGHT_AMBER / LIGHT_RED. */
/* 10 s, not 16: half the cycle is your red, so 16 meant waiting up to 8 s at a
 * junction, which is an age in a game. 10 caps the wait at 5 s and keeps the
 * stop short. */
#define LIGHT_CYCLE 10.0f
#define LIGHT_AMBER  1.4f
enum { LIGHT_GREEN, LIGHT_AMBER_ON, LIGHT_RED };
static int light_state(int ix, int iz, int axis) {
    unsigned h = ((unsigned)ix * 73856093u) ^ ((unsigned)iz * 19349663u);
    float t = g_ltime + (float)(h & 1023) * (LIGHT_CYCLE / 1024.0f);
    float ph = t - LIGHT_CYCLE * floorf(t / LIGHT_CYCLE);        /* 0 .. CYCLE */
    float half = LIGHT_CYCLE * 0.5f;
    float mine = (axis == 0) ? ph : ph - half;                   /* time into MY green window */
    if (mine < 0.0f || mine >= half) return LIGHT_RED;
    return (mine >= half - LIGHT_AMBER) ? LIGHT_AMBER_ON : LIGHT_GREEN;
}
/* Which axis a heading travels along: 0 = X, 1 = Z. */
static int light_axis(float heading) {
    return (fabsf(cosf(heading)) >= fabsf(sinf(heading))) ? 0 : 1;
}

/* EDGE16 road autotile neighbour mask, computed inline from the flash map. */
static int road_mask(int x, int z) {
    int m=0;
    if (is_roadlike(x,z-1)) m|=MOTE_NB_N;
    if (is_roadlike(x+1,z)) m|=MOTE_NB_E;
    if (is_roadlike(x,z+1)) m|=MOTE_NB_S;
    if (is_roadlike(x-1,z)) m|=MOTE_NB_W;
    return m;
}
/* water continues under bridges (and off-map), so shorelines don't wrap around them */
static int is_waterlike(int x,int z){ char c=tile_at(x,z); return c=='~'||c=='B'; }
static int water_mask(int x, int z) {
    int m=0;
    if (is_waterlike(x,z-1)) m|=MOTE_NB_N;
    if (is_waterlike(x+1,z)) m|=MOTE_NB_E;
    if (is_waterlike(x,z+1)) m|=MOTE_NB_S;
    if (is_waterlike(x-1,z)) m|=MOTE_NB_W;
    return m;
}

/* ZEBRA CROSSINGS: one bit per tile, rebuilt for every generated city. A zebra
 * lives on a corridor tile whose neighbour along the corridor is a REAL
 * junction (3+ approaches). The painter draws the stripes here and pedestrians
 * may ONLY cross roads on these tiles. bit set = zebra. */
static uint8_t g_zebra[(CG_W*CG_H+7)/8];
static int zebra_at(int x,int z){
    if (x<0||z<0||x>=MAPW||z>=MAPH) return 0;
    int i=z*MAPW+x; return (g_zebra[i>>3]>>(i&7))&1;
}
static int junction_approaches(int x,int z){
    static const int DX[4]={0,1,0,-1}, DZ[4]={-1,0,1,0};
    int appr=0;
    for (int k=0;k<4;k++){
        for (int s=1;s<=ROADW+2;s++){
            int xx=x+DX[k]*s, zz=z+DZ[k]*s, oo,pp2,ss2;
            if (!is_roadlike(xx,zz)) break;
            corridor_info(xx,zz,&oo,&pp2,&ss2);
            if (oo==3) continue;
            if (oo == ((k==0||k==2)?2:1)) appr++;
            break;
        }
    }
    return appr;
}
static void build_zebra_map(void){
    for (int i=0;i<(MAPW*MAPH+7)/8;i++) g_zebra[i]=0;
    for (int z=1;z<MAPH-1;z++)for (int x=1;x<MAPW-1;x++){
        int o,p,span; 
        if (!is_roadlike(x,z)) continue;
        corridor_info(x,z,&o,&p,&span);
        if (o!=1 && o!=2) continue;
        static const int DX2[2]={1,-1};
        for (int k=0;k<2;k++){
            int jx = o==1 ? x+DX2[k] : x, jz = o==1 ? z : z+DX2[k];
            int oo,pp2,ss2;
            if (!is_roadlike(jx,jz)) continue;
            corridor_info(jx,jz,&oo,&pp2,&ss2);
            if (oo==3 && junction_approaches(jx,jz)>=3){
                int i=z*MAPW+x; g_zebra[i>>3]|=(uint8_t)(1<<(i&7));
                break;
            }
        }
    }
}

/* ---------------------------------------------------------- textured ground -- */
/* One reusable flat quad on y=0. Its face_uvs are rewritten per tile before each
 * draw; scene_add_object emits the UVs immediately, so sharing is safe. */
static MeshVert g_gv[4] = { {-127,0,-127},{127,0,-127},{127,0,127},{-127,0,127} };
static MeshFace g_gf[2] = { {0,1,2, 0,127,0}, {0,2,3, 0,127,0} };  /* normal +y */
static uint8_t  g_guv[12];
static Mesh     g_ground;
static void build_ground(void) {
    g_ground = (Mesh){ .verts=g_gv, .faces=g_gf, .nverts=4, .nfaces=2,
                       .scale=TILE*0.5f, .bound_r=TILE*0.72f, .texture=&ground_img };
    g_ground.face_uvs = g_guv;
}

/* one shared flat GROUND QUAD reused for every sprite entity (trees / people): a 1m
 * quad in the XZ plane, textured + colour-keyed, DEPTH-TESTED against the buildings so
 * it occludes correctly. Its texture + UVs are mutated per draw, exactly like g_ground.
 * (scale 0.5 → verts span ±0.5 m; mote_draw_ex's scale then sets the metre size.) */
static MeshVert g_qv[4] = { {-127,0,-127},{127,0,-127},{127,0,127},{-127,0,127} };
static MeshFace g_qf[2] = { {0,1,2, 0,127,0}, {0,2,3, 0,127,0} };   /* normal +y → faces the top-down camera */
static uint8_t  g_quv2[12];
static Mesh     g_quad;
static void build_quad(void){
    g_quad = (Mesh){ .verts=g_qv, .faces=g_qf, .nverts=4, .nfaces=2,
                     .scale=0.5f, .bound_r=0.9f, .texture=0 };
    g_quad.face_uvs = g_quv2;
}
#define TURRET_LEN_M 8.00f
#define TURRET_WID_M 3.20f
/* Task 9: the tank turret — a cab box + a long barrel box, built from
 * gta3_box (the proven winding exposed by gta3_veh.h/.c) instead of drawn as
 * a rotated flat sprite. Both share one .scale (TURRET_LEN_M*0.5, set in
 * build_turret below), so their normalised int8 coordinates below are metres
 * expressed as (metres / (TURRET_LEN_M*0.5)) * 127. Untextured, so — per the
 * trap this task exists to pre-empt — their winding is exactly what
 * test_veh.c's turret-shaped sweep checks. */
static MeshVert g_turcabv[8], g_turbarv[8];
static MeshFace g_turcabf[12], g_turbarf[12];
static Mesh     g_turcab, g_turbar;
/* Build the two turret boxes once, in the same normalised int8 space as
 * gta3_veh_build's body/cabin: coordinates below are metres * (127 /
 * (TURRET_LEN_M*0.5)). The cab sits centred on the pivot with a little
 * forward bias; the barrel starts inside the cab (so the two boxes overlap
 * rather than leaving a gap) and runs most of the way to the front edge of
 * the TURRET_LEN_M envelope. Both meshes carry their own fixed .scale, so
 * callers draw them with scene_add_object_ex rather than *_scaled. */
static void build_turret(void){
    int nf;
    /* -46..46 wide and 38 tall, not -32..32 by 25: at the smaller size the
     * turret read as a box someone had left on the roof rather than the mass
     * the whole vehicle is built around. A real turret is most of the hull's
     * width and the tallest thing on it. */
    gta3_box(g_turcabv, g_turcabf, &nf, -46,46, 0,38, -52,26);   /* cab */
    g_turcab = (Mesh){ .verts=g_turcabv, .faces=g_turcabf, .nverts=8, .nfaces=nf,
                       .scale=TURRET_LEN_M*0.5f, .bound_r=1.6f, .color=0xFFFF };
    gta3_box(g_turbarv, g_turbarf, &nf, -7,7, 16,26, 20,124);    /* barrel */
    g_turbar = (Mesh){ .verts=g_turbarv, .faces=g_turbarf, .nverts=8, .nfaces=nf,
                       .scale=TURRET_LEN_M*0.5f, .bound_r=1.6f, .color=0xFFFF };
}
static void quad_uv(const MoteImage *img, int fx,int fy,int fw,int fh){
    g_quad.texture=img; int tw=img->w, th=img->h;
    uint8_t u0=(uint8_t)(fx*255/tw), u1=(uint8_t)((fx+fw)*255/tw);
    uint8_t v0=(uint8_t)(fy*255/th), v1=(uint8_t)((fy+fh)*255/th);
    uint8_t U[4]={u0,u1,u1,u0}, V[4]={v0,v0,v1,v1};
    int idx[2][3]={{0,1,2},{0,2,3}};
    for(int f=0;f<2;f++)for(int k=0;k<3;k++){ g_quv2[f*6+k*2]=U[idx[f][k]]; g_quv2[f*6+k*2+1]=V[idx[f][k]]; }
}
/* draw a sprite cell as a flat ground quad, len_m along the heading x wid_m across.
 * NO_DEPTH_WRITE: it's depth-TESTED against the buildings (so they occlude it) but writes
 * no depth, so overlapping sprites layer by draw order — like the old overlay, but now
 * correctly hidden behind buildings. oriented → rotate about Y to the heading. */
static void draw_ground_sprite(const MoteImage *img, float wx,float wz, float yaw,
                               int fx,int fy,int fw,int fh, float len_m, float wid_m, int oriented){
    quad_uv(img, fx,fy,fw,fh);
    float hl=len_m*0.5f, hw=wid_m*0.5f, md=hl>hw?hl:hw; if(md<0.01f) md=0.01f;
    int8_t X=(int8_t)(hw/md*127.0f), Z=(int8_t)(hl/md*127.0f);
    g_qv[0].x=-X; g_qv[0].z=-Z; g_qv[1].x=X; g_qv[1].z=-Z;   /* rectangle: X=across, Z=along heading */
    g_qv[2].x= X; g_qv[2].z= Z; g_qv[3].x=-X; g_qv[3].z= Z;
    g_quad.scale=md; g_quad.bound_r=md*1.7f;
    Mat3 b=m3_identity(); if(oriented) m3_rotate_local(&b, 1, -(yaw + 1.5708f));   /* image-up (−Z) → heading */
    MoteObject o = { .pos=v3(wx,0.09f,wz), .basis=b, .mesh=&g_quad };
    mote->scene_add_object_ex(&o, MOTE_DRAW_NO_DEPTH_WRITE);
}
/* atlas cell -> the two-triangle UV set (cell is 16px of a 128px-wide atlas). */
/* ground.png is TWO rows of 8 cells: cell = row*8 + col. It was one row, but
 * ground_uv packs u as cell*32 into a uint8_t, so cell 8 wraps to u=0 and the
 * sheet was hard-capped at 8 — all of which were already in use. */
enum { G_ASPHALT, G_DASH, G_PAVE, G_GRASS, G_WATER, G_CROSS, G_EDGE, G_DIRT,
       G_SAND, G_SANDWET };
static void ground_uv(int cell) {
    int col = cell & 7, row = cell >> 3;
    uint8_t u0 = (uint8_t)(col * 32), u1 = (uint8_t)(col * 32 + 31);
    uint8_t v0 = (uint8_t)(row * 128), v1 = (uint8_t)(row * 128 + 127);
    uint8_t U[4] = { u0, u1, u1, u0 }, V[4] = { v0, v0, v1, v1 };
    int idx[2][3] = { {0,1,2}, {0,2,3} };
    for (int f = 0; f < 2; f++)
        for (int k = 0; k < 3; k++) { g_guv[f*6+k*2] = U[idx[f][k]]; g_guv[f*6+k*2+1] = V[idx[f][k]]; }
}
static int ground_cell(char c) {
    switch (c) { case ',': return G_PAVE;  case '~': return G_WATER;
                 case ' ': return G_GRASS; default:  return G_DIRT; }
}
/* UV for a cell in the 4x4 / 32px / 128px road sheet (u = px*2 into 0..255). */
static void road_uv(int cell) {
    int col = cell & 3, row = cell >> 2;
    uint8_t u0 = (uint8_t)(col*64), u1 = (uint8_t)(col*64+63);
    uint8_t v0 = (uint8_t)(row*64), v1 = (uint8_t)(row*64+63);
    uint8_t U[4]={u0,u1,u1,u0}, V[4]={v0,v0,v1,v1};
    int idx[2][3]={{0,1,2},{0,2,3}};
    for (int f=0;f<2;f++) for (int k=0;k<3;k++){ g_guv[f*6+k*2]=U[idx[f][k]]; g_guv[f*6+k*2+1]=V[idx[f][k]]; }
}

/* --------------------------------------------------------- textured buildings -- */
/* Buildings are procedural MASSING, not a grid of separate random columns. Each
 * solid tile draws a FULL-tile textured cube (facade walls + roof), so contiguous
 * same-class tiles butt together with no gaps and read as ONE structure. Two things
 * make blocks look like buildings rather than dice:
 *   1. A stable per-BUILDING hash (bld_seed: the top-left corner of the contiguous
 *      same-class region) drives ONE facade texture + ONE coherent height for the
 *      whole building — no per-tile texture/height noise, so nothing shimmers.
 *   2. Interior tiles rise above edge tiles (setback / tiered core), and rare
 *      hash-picked buildings become landmark towers — real stepped rooftops.
 * Height is quantised to NBLV discrete levels (one precomputed cube mesh each);
 * a building draws the mesh for its level, textured by one of NBTEX atlases.
 * Everything is derived from the flash tile map + fixed hashes: deterministic per
 * seed, identical every frame (no Math.random / time in the render path). */
#define NBLV  14                                       /* discrete height levels */
#define NBTEX 8                                         /* facade|roof atlases */
static const float g_lvl_h[NBLV] = { 2.6f,3.3f,4.0f,4.8f,5.7f,6.8f,8.0f,9.4f,
                                     11.0f,12.8f,15.0f,17.5f,20.5f,24.0f };
static MeshVert g_bv[NBLV][8];
static MeshFace g_bf[NBLV][12];
static uint8_t  g_buv[NBLV][72];
static float    g_bmd[NBLV];
static Mesh     g_bmesh[NBLV][NBTEX];
static Mesh     g_hmesh[NBLV];       /* untextured haze band, shares g_bv[L] verts */
/* g_hmesh's own face array: same triangles as g_bf[L] but with b/c swapped.
 * The textured path (raster_tex_tri) culls on area MAGNITUDE only, so g_bf's
 * winding has never mattered until now. The flat path (tri_core) requires
 * POSITIVE screen-space area and drops anything else — g_bf's winding turns
 * out negative there, so g_hmesh needs reversed vertex order to render at
 * all. Normals are copied unchanged: mote_pipe's backface pre-cull uses the
 * stored normal, not the winding, so this only flips the rasteriser's area
 * sign and leaves which faces are front-facing untouched. */
static MeshFace g_hf[NBLV][12];

/* one built mesh pair per vehicle silhouette (Task 6's gta3_veh.h) — shared by
 * every car of that silhouette, tinted per-draw from CAR_COL. */
static Gta3VehMesh g_veh[GTA3_SIL_N];
/* Pristine x half-extents per silhouette, so the per-draw aspect squeeze
 * below always scales from the original rather than from an already-squeezed
 * value. Vertex 1 is (+x, y0, z0) in box()'s corner layout. */
#define VEH_WHEEL_R 26.0f   /* draw the wheel line only within this range */
#define VEH_DETAIL_R 22.0f  /* trim panels and lamps: closer still */
static int8_t g_veh_bx[GTA3_SIL_N], g_veh_cx[GTA3_SIL_N], g_veh_wx[GTA3_SIL_N];
/* Pristine cabin roofline and z extents, for the same reason as the x extents
 * above: draw_vehicle_mesh mutates the shared mesh per car, so every draw has
 * to start from the built values rather than from whatever the last car left
 * behind. Without these the jitter compounds and a car walks its own roof off
 * over a few hundred frames. */
static int8_t g_veh_cy[GTA3_SIL_N], g_veh_cz0[GTA3_SIL_N], g_veh_cz1[GTA3_SIL_N];

static void build_bgeom(int L, float hx, float hy, float hz) {
    float md = hx; if (hy > md) md = hy; if (hz > md) md = hz; g_bmd[L] = md;
    int8_t X=(int8_t)(hx/md*127), Y=(int8_t)(hy/md*127), Z=(int8_t)(hz/md*127);
    int8_t C[8][3] = { {-X,-Y,-Z},{X,-Y,-Z},{X,Y,-Z},{-X,Y,-Z},
                       {-X,-Y, Z},{X,-Y, Z},{X,Y, Z},{-X,Y, Z} };
    for (int i=0;i<8;i++){ g_bv[L][i].x=C[i][0]; g_bv[L][i].y=C[i][1]; g_bv[L][i].z=C[i][2]; }
    struct { uint8_t a,b,c,d; int8_t nx,ny,nz; int roof; } Q[6] = {
        {0,1,2,3, 0,0,-127, 0},{5,4,7,6, 0,0,127, 0},{4,0,3,7,-127,0,0, 0},
        {1,5,6,2,127,0,0, 0},{4,5,1,0,0,-127,0, 0},{3,2,6,7,0,127,0, 1} };
    int fi=0;
    for (int q=0;q<6;q++){
        uint8_t r[4]={Q[q].a,Q[q].b,Q[q].c,Q[q].d};
        int8_t nx=Q[q].nx,ny=Q[q].ny,nz=Q[q].nz;
        uint8_t uL=Q[q].roof?128:0, uR=Q[q].roof?255:127;
        uint8_t U[4]={uL,uR,uR,uL}, V[4]={0,0,255,255};
        g_bf[L][fi]=(MeshFace){r[0],r[1],r[2],nx,ny,nz};
        g_buv[L][fi*6+0]=U[0];g_buv[L][fi*6+1]=V[0];g_buv[L][fi*6+2]=U[1];g_buv[L][fi*6+3]=V[1];g_buv[L][fi*6+4]=U[2];g_buv[L][fi*6+5]=V[2]; fi++;
        g_bf[L][fi]=(MeshFace){r[0],r[2],r[3],nx,ny,nz};
        g_buv[L][fi*6+0]=U[0];g_buv[L][fi*6+1]=V[0];g_buv[L][fi*6+2]=U[2];g_buv[L][fi*6+3]=V[2];g_buv[L][fi*6+4]=U[3];g_buv[L][fi*6+5]=V[3]; fi++;
    }
}
static void build_buildings(void) {
    const MoteImage *tex[NBTEX] = { &bld_brick_img, &bld_office_img, &bld_tower_img,
                                    &bld_concrete_img, &bld_glass_img, &bld_painted_img,
                                    &bld_brownstone_img, &bld_panel_img };
    for (int L=0; L<NBLV; L++) {
        build_bgeom(L, TILE*0.5f, g_lvl_h[L]*0.5f, TILE*0.5f);      /* full-tile footprint: blocks merge */
        for (int t=0; t<NBTEX; t++)
            g_bmesh[L][t] = (Mesh){ .verts=g_bv[L], .faces=g_bf[L], .nverts=8, .nfaces=12,
                                    .scale=g_bmd[L], .bound_r=g_bmd[L]*1.75f,
                                    .texture=tex[t], .face_uvs=g_buv[L] };
    }
    /* The far band draws UNTEXTURED, so it can be tinted toward the background
     * and so it costs max_tris rather than max_tex_tris. A per-draw colour does
     * NOT suppress a texture — mote_pipe.c picks the textured path purely on
     * (mesh->texture && mesh->face_uvs), and obj->color only feeds the flat
     * path. Hence a parallel mesh with no texture, sharing the same geometry. */
    for (int L=0; L<NBLV; L++) {
        for (int f=0; f<12; f++)
            g_hf[L][f] = (MeshFace){ g_bf[L][f].a, g_bf[L][f].c, g_bf[L][f].b,
                                     g_bf[L][f].nx, g_bf[L][f].ny, g_bf[L][f].nz };
        g_hmesh[L] = (Mesh){ .verts=g_bv[L], .faces=g_hf[L], .nverts=8, .nfaces=12,
                             .scale=g_bmd[L], .bound_r=g_bmd[L]*1.75f,
                             .texture=0, .face_uvs=0, .color=MOTE_RGB565(60,64,78) };
    }
}

/* GARAGE meshes: a low box with a ROOF + back/side walls but the STREET-FACING wall
 * removed, so you drive in under the roof. One mesh per opening direction (0:+X 1:-X
 * 2:+Z 3:-Z open). Built once at init; drawn on garage tiles by draw_buildings_window. */
#define GARAGE_H 3.6f
static MeshVert gr_v[4][8];
static MeshFace gr_f[4][10];
static uint8_t  gr_uv[4][60];
static float    gr_md;
static Mesh     gr_mesh[4];
static void build_garages(void){
    float hx=TILE*0.5f, hy=GARAGE_H*0.5f, hz=TILE*0.5f;
    float md=hx; if(hy>md)md=hy; if(hz>md)md=hz; gr_md=md;
    int8_t X=(int8_t)(hx/md*127), Y=(int8_t)(hy/md*127), Z=(int8_t)(hz/md*127);
    int8_t C[8][3] = { {-X,-Y,-Z},{X,-Y,-Z},{X,Y,-Z},{-X,Y,-Z},
                       {-X,-Y, Z},{X,-Y, Z},{X,Y, Z},{-X,Y, Z} };
    struct { uint8_t a,b,c,d; int8_t nx,ny,nz; int roof; } Q[6] = {
        {0,1,2,3, 0,0,-127, 0},{5,4,7,6, 0,0,127, 0},{4,0,3,7,-127,0,0, 0},
        {1,5,6,2,127,0,0, 0},{4,5,1,0,0,-127,0, 0},{3,2,6,7,0,127,0, 1} };
    static const int SKIP[4] = { 3, 2, 1, 0 };   /* which wall face is the open front, per dir */
    for (int gi=0; gi<4; gi++){
        for (int i=0;i<8;i++){ gr_v[gi][i].x=C[i][0]; gr_v[gi][i].y=C[i][1]; gr_v[gi][i].z=C[i][2]; }
        int fi=0;
        for (int q=0;q<6;q++){
            if (q==SKIP[gi] || q==4) continue;    /* drop the open front + the floor */
            uint8_t r[4]={Q[q].a,Q[q].b,Q[q].c,Q[q].d};
            uint8_t uL=Q[q].roof?128:0, uR=Q[q].roof?255:127;
            uint8_t U[4]={uL,uR,uR,uL}, V[4]={0,0,255,255};
            gr_f[gi][fi]=(MeshFace){r[0],r[1],r[2],Q[q].nx,Q[q].ny,Q[q].nz};
            gr_uv[gi][fi*6+0]=U[0];gr_uv[gi][fi*6+1]=V[0];gr_uv[gi][fi*6+2]=U[1];gr_uv[gi][fi*6+3]=V[1];gr_uv[gi][fi*6+4]=U[2];gr_uv[gi][fi*6+5]=V[2]; fi++;
            gr_f[gi][fi]=(MeshFace){r[0],r[2],r[3],Q[q].nx,Q[q].ny,Q[q].nz};
            gr_uv[gi][fi*6+0]=U[0];gr_uv[gi][fi*6+1]=V[0];gr_uv[gi][fi*6+2]=U[2];gr_uv[gi][fi*6+3]=V[2];gr_uv[gi][fi*6+4]=U[3];gr_uv[gi][fi*6+5]=V[3]; fi++;
        }
        gr_mesh[gi]=(Mesh){ .verts=gr_v[gi], .faces=gr_f[gi], .nverts=8, .nfaces=fi,
                            .scale=gr_md, .bound_r=gr_md*1.75f, .texture=&bld_concrete_img, .face_uvs=gr_uv[gi] };
    }
}
/* garage dir index (0:+X 1:-X 2:+Z 3:-Z open) for a garage tile, or -1 */
static int garage_dir(int x, int z){
    for (int i=0;i<g_ngar;i++) if (g_gar[i].x==x && g_gar[i].z==z){
        int ox=g_gar[i].ox, oz=g_gar[i].oz;
        return ox>0?0 : ox<0?1 : oz>0?2 : 3;
    }
    return -1;
}

static unsigned hash_u(unsigned h){ h^=h>>13; h*=2654435761u; h^=h>>15; return h; }
/* A real city has coherent DEVELOPMENTS (a run of buildings built alike) inside larger
 * DISTRICTS (downtown vs. outskirts). We derive both from position, not per-tile class:
 *   - DEV cell (~4 tiles): every building tile in it shares one facade + base height,
 *     so a block reads as one development instead of mismatched dice.
 *   - DISTRICT field (~16 tiles, smoothed over neighbours): a slow height bias so towers
 *     CLUSTER into a downtown and taper to low blocks at the edges — a skyline, not noise. */
#define BLK_DEV  4
#define BLK_DIST 16
static unsigned dev_hash(int x, int z){
    int bx=(int)floorf((float)x/BLK_DEV), bz=(int)floorf((float)z/BLK_DEV);
    return hash_u((unsigned)(bx*2654435761u) ^ (unsigned)(bz*40503u));
}
/* District elevation 0..9: one value per ~16-tile zone (full range -> real downtown-vs-
 * outskirts contrast), nudged toward its dominant neighbour so downtown zones stay
 * contiguous instead of a lone tall zone beside a lone short one. */
static int district_elev(int x, int z){
    int bx=(int)floorf((float)x/BLK_DIST), bz=(int)floorf((float)z/BLK_DIST);
    int self = (int)(hash_u((unsigned)(bx*374761393u) ^ (unsigned)(bz*668265263u)) % 10u);
    int east = (int)(hash_u((unsigned)((bx+1)*374761393u) ^ (unsigned)(bz*668265263u)) % 10u);
    int south= (int)(hash_u((unsigned)(bx*374761393u) ^ (unsigned)((bz+1)*668265263u)) % 10u);
    return (self*2 + east + south) / 4;                /* weighted toward self: contiguous zones, full range kept */
}
/* 0 = edge tile, 1 = 4-neighbours solid, 2 = full 8-neighbours solid (deep core). */
static int bld_interior(int x, int z) {
    int n4 = is_solid(x-1,z)+is_solid(x+1,z)+is_solid(x,z-1)+is_solid(x,z+1);
    if (n4 < 4) return 0;
    int n8 = n4 + is_solid(x-1,z-1)+is_solid(x+1,z-1)+is_solid(x-1,z+1)+is_solid(x+1,z+1);
    return n8 >= 8 ? 2 : 1;
}
/* Height level: DISTRICT band (downtown tall, outskirts low) + a small per-development
 * jitter + the mapgen class as a nudge + a tiered setback core, so a whole block shares
 * a coherent height that steps up at its centre. */
static int bld_level(int x, int z) {
    char c = tile_at(x, z);
    unsigned d = dev_hash(x, z);
    int band  = district_elev(x, z);                   /* 0..9 downtown gradient */
    int classb= c=='#' ? 0 : c=='O' ? 1 : 2;           /* mapgen intent as a gentle nudge */
    int base  = 1 + band + classb + (int)(d & 1u);     /* coherent across the development */
    int inter = bld_interior(x, z);
    base += inter;                                     /* stepped / setback core */
    if (band >= 7 && inter == 2 && ((d>>11) & 3u)==0u) base += 4;  /* downtown landmark tower */
    if (base < 0) base = 0; if (base >= NBLV) base = NBLV-1;
    return base;
}
/* One facade|roof atlas per DEVELOPMENT (whole block shares a style), biased by the
 * district band: low blocks = brick/painted/masonry, tall downtown = tower/glass. */
static int bld_tex(int x, int z) {
    static const uint8_t cand[3][4] = { {0,5,6,3}, {1,3,7,5}, {2,4,7,1} };
    int band = district_elev(x, z); int ci = band<4 ? 0 : band<7 ? 1 : 2;
    return cand[ci][(dev_hash(x,z) >> 17) & 3u];
}

/* The helicopter's altitude, declared here because the floor helpers below need
 * it and they sit next to the rest of the world geometry. The rest of the
 * aircraft's state, and why altitude lives outside the physics at all, is at
 * HELI_SLOT further down. */
static float g_heli_y, g_heli_vy;

/* The surface under a world point: a building's roof if it stands there, the
 * road otherwise. Building heights are already quantised per tile, so landing on
 * a roof costs one lookup and no new state. */
static float floor_y(float wx, float wz) {
    int tx = (int)(wx / TILE), tz = (int)(wz / TILE);
    char c = tile_at(tx, tz);
    if ((c == '#' || c == 'O' || c == 'H') && !is_garage(tx, tz))
        return g_lvl_h[bld_level(tx, tz)];
    return 0.0f;
}

/* The lowest the helicopter may descend at this position.
 *
 * Water is not a landing surface — it holds a hover. There is exactly one
 * helicopter in a city and no way to get another, so letting a descent over the
 * river sink it would make a mis-timed landing permanently cost you the
 * feature. Everything else lands normally, roofs included.
 *
 * '~' directly rather than in_water_w(), which is declared hundreds of lines
 * further down; the test is one tile lookup either way. */
#define HELI_WATER_HOVER 2.6f
static float heli_floor(float wx, float wz) {
    if (tile_at((int)(wx / TILE), (int)(wz / TILE)) == '~') return HELI_WATER_HOVER;
    return floor_y(wx, wz);
}
/* Is the aircraft off the ground? Over water the answer is ALWAYS yes, however
 * low it is: there is nothing there to be down on. Asking the height alone got
 * this wrong by 0.2 m — the hover clamp parks it at HELI_WATER_HOVER and the
 * height test wanted more than that before it counted as flying, so a descent
 * over the river went "landed" for one frame and the drown check took it.
 * Every caller asks this rather than comparing heights itself. */
static int heli_aloft(float wx, float wz) {
    if (tile_at((int)(wx / TILE), (int)(wz / TILE)) == '~') return 1;
    return g_heli_y > floor_y(wx, wz) + 0.2f;
}

/* Is this world point on open water?
 *
 * '~' only. NOT is_waterlike(), which also counts bridge tiles: a bridge deck
 * is a road with water underneath it, and a boat that could motor along one
 * would be a boat driving down a street.
 *
 * The one predicate is consulted by everything that cares — the drown
 * exemption in physics_pass, the movement gate in sail_boat, and the exit gate
 * on RB — so those three can never disagree about where the boat may be. That
 * is the same shape heli_aloft() has, and for the same reason: the helicopter
 * shipped a bug where two of its three callers compared heights themselves and
 * differed by 0.2 m. */
static int boat_afloat(float wx, float wz) {
    return tile_at((int)(wx / TILE), (int)(wz / TILE)) == '~';
}

/* ---------------------------------------------------------------- camera ---- */
/* Chase camera: eye behind and above the player/car, looking ahead of it. See
 * gta3_camera.h for the framing/smoothing/collision rationale. */
/* 55, not 60: a 60 degree horizontal field behind a car reads as fisheye on a
 * 128x128 panel, and every extra degree is more city inside the draw cone. */
#define FOV       55.0f
/* Chase framing, metres. The car values interpolate on speed over 0..CAM_SPD. */
#define CAM_FOOT_D   4.5f
#define CAM_FOOT_H   2.4f
#define CAM_FOOT_L   3.0f
#define CAM_CAR_D0   6.5f
#define CAM_CAR_H0   2.8f
#define CAM_CAR_L0   4.0f
#define CAM_CAR_D1  10.0f
#define CAM_CAR_H1   3.6f
#define CAM_CAR_L1   9.0f
#define CAM_SPD     18.0f    /* speed, m/s, at which the framing is fully out */
/* Helicopter framing. The car values put a 7 m aircraft 6.5 m from the lens,
 * where its canopy alone fills the frame and you are flying blind — measured,
 * not guessed: the first capture was a black rectangle across the whole screen
 * and nothing else. Back off and look further ahead so the ground the aircraft
 * is over stays in shot, which is the only thing worth seeing from up there. */
#define CAM_HELI_D  20.0f
#define CAM_HELI_H   7.0f
#define CAM_HELI_L  14.0f

/* Draw distances, metres. Ground is shorter than buildings on purpose: past
 * ~50 m the road is near edge-on and mostly hidden by facades anyway. */
#define VIEW_GROUND_R   52.0f
#define VIEW_BLD_R     112.0f
#define VIEW_HAZE_R     70.0f    /* beyond this, buildings go untextured + tinted */
#define VIEW_BLD_CAP     110     /* max building submissions per frame */

/* ------------------------------------------------------------ day / night ---
 * Atmosphere only — nothing in the simulation reads the time of day.
 *
 * One float walks a four-keyframe palette (night / dawn / day / dusk). The sky
 * is a vertical gradient painted by set_background_cb (ABI v26), a per-band
 * pass that runs on BOTH cores before any geometry, with depth already cleared.
 * Cost is ~nil: the engine already fills the background every frame, so this
 * writes the same pixels with a per-row colour instead of one flat one.
 *
 * The part that matters: `haze_far` and the ground skirt are DERIVED from
 * sky_hor rather than stored separately. Both exist to blend the world edge
 * into the sky — see haze_tint() and draw_ground_skirt() — so if the sky moved
 * while they stayed put, the hard horizon seam those two were added to remove
 * would come straight back, as a wrongly-coloured band where ground meets sky. */
#define DAY_SECONDS  240.0f      /* one full cycle */

typedef struct { uint8_t r, g, b; } Rgb;
typedef struct { Rgb top, hor, haze_near; Vec3 sun; } TodKey;

/* sun is the direction TOWARD the light. mote_pipe shades a face as
 * 0.25 + 0.75*max(0, n·sun), so a sun below the horizon simply parks the world
 * on its 0.25 ambient floor — dark but readable, which is what night wants. */
static const TodKey TOD[4] = {
    /* midnight */ {{ 10, 12, 22}, { 26, 30, 44}, { 40, 44, 60}, { 0.30f,  0.15f, -0.30f}},
    /* dawn     */ {{ 40, 54, 96}, {216,140, 96}, {150,120,120}, { 0.90f,  0.20f, -0.10f}},
    /* noon     */ {{ 70,110,175}, {150,175,205}, {120,140,160}, { 0.25f,  0.92f, -0.30f}},
    /* dusk     */ {{ 46, 44, 92}, {226,110, 70}, {150,110,110}, {-0.90f,  0.18f,  0.10f}},
};

static float    g_tod = 0.60f;          /* [0,1), 0 = midnight; start just before dusk */
/* Weather. Entirely procedural — no particle array, because GAME_RAM had well
 * under 4 KB spare when this went in. Intensity is two slow sines of different
 * periods (about 8.7 and 24 minutes) so storms arrive irregularly rather than
 * on a visible loop, and every raindrop's position is a hash of its index and
 * the clock. 16 bytes of state for the whole system. */
static float    g_wtime;                /* weather clock, seconds */
static float    g_wet;                  /* 0 = dry, 1 = downpour */
static float    g_flash;                /* lightning, decays to 0 */
static float    g_flash_cd;             /* seconds until the next strike */
static Rgb      g_sky_hor, g_haze_near; /* this frame's palette, read by the render pass */
static Vec3     g_sun_dir;              /* lerped sun, reused for the sky body and the night test */
static uint16_t g_sky_row[MOTE_FB_H];   /* precomputed gradient, one colour per scanline */
/* Stars. Screen positions are recomputed once per frame from the camera's
 * heading and plotted by sky_band, rather than submitted as scene points: the
 * background pass already walks every sky pixel on both cores, so a star costs
 * one store, and the point pool is spent on water shimmer.
 *
 * 72 x 2 bytes. GAME_RAM had 3928 bytes spare when this went in, so the budget
 * is real — stars are a table, rain further down is procedural for the same
 * reason. */
#define SKY_HOR_Y 56   /* gradient reaches the horizon colour here, flat below */
#define STARS 72
static uint8_t  g_star_x[STARS], g_star_y[STARS];
static uint8_t  g_star_lit;             /* 0 = daylight, else brightness 1..255 */

static Rgb rgb_lerp(Rgb a, Rgb b, float t) {
    Rgb o; o.r = (uint8_t)(a.r + (b.r - a.r) * t);
           o.g = (uint8_t)(a.g + (b.g - a.g) * t);
           o.b = (uint8_t)(a.b + (b.b - a.b) * t); return o;
}
static uint16_t rgb565(Rgb c) { return MOTE_RGB565(c.r, c.g, c.b); }

/* Band callback: runs on both cores over disjoint row ranges. It only READS
 * g_sky_row, which tod_advance rewrites once per frame in update — before any
 * rendering — so there is no cross-core write to race on. */
static void sky_band(uint16_t *fb, int y0, int y1) {
    for (int y = y0; y < y1; y++) {
        uint16_t c = g_sky_row[y], *row = fb + y * MOTE_FB_W;
        for (int x = 0; x < MOTE_FB_W; x++) row[x] = c;
    }
    /* Stars over the fresh gradient. This callback runs on BOTH cores for
     * different bands, so it only reads the table — everything it needs was
     * computed once in the update pass. */
    if (!g_star_lit) return;
    int v = g_star_lit;
    uint16_t dim = MOTE_RGB565((150*v)/255, (158*v)/255, (185*v)/255);
    uint16_t brt = MOTE_RGB565((230*v)/255, (236*v)/255, (255*v)/255);
    for (int i = 0; i < STARS; i++) {
        int sy = g_star_y[i];
        if (sy < y0 || sy >= y1) continue;
        fb[sy * MOTE_FB_W + g_star_x[i]] = (i & 3) ? dim : brt;
    }
}

static void weather_advance(float dt) {
    g_wtime += dt;
    /* Two incommensurate periods, so the pattern does not visibly repeat. The
     * -0.45 threshold and 2.2 gain mean it is raining maybe a fifth of the
     * time, ramping in and out over a minute or so rather than switching. */
    float w = sinf(g_wtime * 0.0121f) * 0.6f + sinf(g_wtime * 0.0043f + 1.7f) * 0.4f;
    /* Measured over six simulated hours of this exact formula:
     *
     *     0.45 / 2.2   raining 20.3%   storming 10.7%   (first attempt)
     *     0.80 / 4.0   raining  6.3%   storming  1.9%
     *     0.86 / 5.0   raining  4.2%   storming  0.9%   (here)
     *
     * A wet fifth of the time read as a climate rather than as weather. At
     * 4.2% rain shows up now and then and is gone again, and the high
     * threshold caps intensity so a full downpour stays rare. */
    g_wet = mote_clampf((w - 0.86f) * 5.0f, 0.0f, 1.0f);
#ifdef MOTE_HOST
    /* MOTE_GTA_WET=0.8 pins the intensity, so a capture can be taken in a storm
     * without running out to the minute the cycle happens to produce one. Same
     * shape as MOTE_GTA_TOD. */
    { static int read = 0; static float pin = -1.0f;
      if (!read) { read = 1; const char *e = getenv("MOTE_GTA_WET"); if (e) pin = (float)atof(e); }
      if (pin >= 0.0f) g_wet = pin; }
#endif

    if (g_flash > 0.0f) g_flash -= dt * 6.0f;        /* a strike is brief */
    if (g_flash < 0.0f) g_flash = 0.0f;
    if (g_wet > 0.55f) {                             /* only heavy rain thunders */
        g_flash_cd -= dt;
        if (g_flash_cd <= 0.0f) {
            g_flash = 1.0f;
            /* Hash the clock rather than call frand(): this runs before the RNG
             * is declared, and keeping weather off the game RNG means a storm
             * cannot shift car or ped spawns. */
            unsigned h = (unsigned)(g_wtime * 1000.0f) * 2654435761u;
            g_flash_cd = 2.5f + (float)(h >> 24) * (7.0f / 255.0f);
        }
    } else g_flash_cd = 1.5f;
}

static void tod_advance(float dt) {
    g_tod += dt / DAY_SECONDS;
    while (g_tod >= 1.0f) g_tod -= 1.0f;
#ifdef MOTE_HOST
    /* MOTE_GTA_TOD=0.85 pins the clock, so a headless capture can be taken at a
     * chosen hour without driving the run out to the right frame number. Test
     * hook only — same shape as MOTE_GTA_VIEW and MOTE_GTA_SEED. */
    { static int read = 0; static float pin = -1.0f;
      if (!read) { read = 1; const char *e = getenv("MOTE_GTA_TOD"); if (e) pin = (float)atof(e); }
      if (pin >= 0.0f) g_tod = pin; }
#endif

    float f = g_tod * 4.0f; int k = (int)f; float t = f - (float)k;
    const TodKey *a = &TOD[k & 3], *b = &TOD[(k + 1) & 3];

    Rgb top    = rgb_lerp(a->top,  b->top,  t);
    g_sky_hor  = rgb_lerp(a->hor,  b->hor,  t);
    g_haze_near = rgb_lerp(a->haze_near, b->haze_near, t);

    /* Reach the horizon colour ABOVE the visual horizon, then hold it flat.
     * Ramping over the full 128 rows would land g_sky_hor at y=127, which the
     * ground covers — so the sky just above the horizon would be some midpoint
     * of the ramp while haze_tint and the skirt blend to g_sky_hor, and the
     * seam those exist to hide would reappear in a new colour. The camera's
     * horizon drifts with pitch and look-ahead, so flatten from SKY_HOR_Y and
     * let it land anywhere below that. Rows past it cost nothing: geometry
     * covers them. */
    /* Storm tint, then lightning, both folded into the palette BEFORE the rows
     * are baked — so the flash lights the whole sky in one pass rather than
     * needing a separate full-screen blend, and the haze/skirt that blend to
     * g_sky_hor stay in agreement with it. */
    if (g_wet > 0.0f) {
        const Rgb ST_TOP = { 52, 56, 64 }, ST_HOR = { 96, 100, 110 }, ST_HAZE = { 82, 86, 96 };
        float w = g_wet * 0.85f;
        top         = rgb_lerp(top, ST_TOP, w);
        g_sky_hor   = rgb_lerp(g_sky_hor, ST_HOR, w);
        g_haze_near = rgb_lerp(g_haze_near, ST_HAZE, w);
    }
    if (g_flash > 0.0f) {
        const Rgb LIT = { 236, 240, 255 };
        float fl = g_flash * 0.8f;
        top       = rgb_lerp(top, LIT, fl);
        g_sky_hor = rgb_lerp(g_sky_hor, LIT, fl);
    }
    for (int y = 0; y < MOTE_FB_H; y++) {
        float t = (y >= SKY_HOR_Y) ? 1.0f : (float)y / (float)SKY_HOR_Y;
        g_sky_row[y] = rgb565(rgb_lerp(top, g_sky_hor, t));
    }

    g_sun_dir = v3_norm(v3_lerp(a->sun, b->sun, t));
    mote->scene_set_sun(g_sun_dir);
    mote->scene_set_background(rgb565(g_sky_hor));   /* used only if the cb is absent */
}

/* engine/render/mote_scene3d.c's billboard pool (k_vtbl.config.max_billboards,
 * below) is shared by EVERY entity billboard this frame — peds, cops, pickups,
 * the phonebox marker, and trees — and exhaustion is SILENT: scene_add_billboard
 * just returns 0 past the cap, so whatever was submitted after the pool filled
 * simply never renders, with nothing to say so. bb_add() (below) is the one
 * place that submits, so it is the one place that has to guard this. */
#define MAX_BILLBOARDS   112

static Mat3  cam_basis;
static Vec3  cam_pos;
static float cam_focal;      /* 64 / tan(fov/2) — set in init */
static float view_x, view_z; /* world point the camera is centred on */
static Gta3Cam  g_cam;
static Gta3View g_view;
static int   g_bb_used;      /* billboards submitted this frame — reset each frame
                              * in g_update once g_view is current; see bb_add(). */
static float g_titlet;       /* title/death-screen orbit angle accumulator; reset in reset_game() */

/* Width of `s` in the title font, by summing each glyph's pen advance. The
 * MoteFont layout (engine/render/mote_2d.h) is public, so this is the same
 * arithmetic text_font() does when it walks the string — no guessing, and no
 * constant to go stale if title.font.h is re-baked at a different size.
 * Codepoints outside the baked range contribute nothing, which is what
 * text_font does with them too. */
static int title_w(const char *s) {
    int w = 0;
    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {
        int g = (int)*p - (int)title.first;
        if (g >= 0 && g < (int)title.count) w += title.glyphs[g].adv;
    }
    return w;
}

/* One centred line of the logo: black drop shadow one pixel down and right,
 * warm gold face over it. */
static void title_line(uint16_t *fb, const char *s, int y) {
    int x = (MOTE_FB_W - title_w(s)) / 2;
    mote->text_font(fb, &title, s, x + 2, y + 2, MOTE_RGB565(12,10,14));
    mote->text_font(fb, &title, s, x,     y,     MOTE_RGB565(244,204,72));
}

/* world -> logical 128x128 screen, EXACTLY like engine mote_pipe.c */
static int world_to_screen(Vec3 w, float *sx, float *sy, float *px_per_m) {
    Vec3 rel = v3_sub(w, cam_pos);
    float vx = v3_dot(cam_basis.r[0], rel);
    float vy = v3_dot(cam_basis.r[1], rel);
    float vz = v3_dot(cam_basis.r[2], rel);
    if (vz <= 0.5f) return 0;                       /* near plane */
    float inv = 1.0f / vz;
    *sx = 64.0f + cam_focal * vx * inv;
    *sy = 64.0f - cam_focal * vy * inv;
    if (px_per_m) *px_per_m = cam_focal * inv;
    return 1;
}

/* Which of the four side-view columns to show for a character facing `yaw`.
 * The angle is measured against the CAMERA forward, not a world axis, so the
 * choice follows the view: a ped walking away from the camera shows its back
 * whichever compass direction that happens to be.
 * 0 back, 1 front, 2 left, 3 right — matching make_chars3d.py's column order.
 *
 * rel is in the game's "driver's right" yaw convention (-sin(yaw), cos(yaw)),
 * i.e. yaw+90. world_to_screen actually projects against cam_basis.r[0] =
 * cross((0,1,0), forward), which is yaw-90 -- the OPPOSITE of driver's right
 * (see the note at screen_or_edge, game.c:4489, and draw_radar, game.c:4607,
 * which hit the same mismatch). So rel=+90 ("driver's right" of camera
 * forward) actually projects to screen-LEFT, and vice versa: the left/right
 * columns below are swapped relative to a naive reading of rel. */
static int facing_cell(float yaw) {
    float cyaw = atan2f(cam_basis.r[2].z, cam_basis.r[2].x);
    float rel = gta3_wrap_angle(yaw - cyaw);
    if (rel > -0.785f && rel <= 0.785f) return 0;        /* same way as the camera: back */
    if (rel > 0.785f && rel <= 2.356f)  return 2;
    if (rel < -0.785f && rel >= -2.356f) return 3;
    return 1;                                            /* toward the camera: front */
}

static int g_bb_budget_drop;  /* diagnostic only: submissions rejected by the budget
                               * check specifically (in view, but the pool was full) —
                               * as opposed to the much more common frustum/radius
                               * rejection. Reset alongside g_bb_used. */
/* The one place that submits an entity billboard, so it is the one place
 * that has to guard the pool (see MAX_BILLBOARDS above): rejects anything
 * outside the view cone/radius via gta3_view_tile (g_view is current for
 * this frame by the time anything below calls this — set in chase_camera,
 * called at the top of the 3D build in g_update) BEFORE spending a slot on
 * it, then rejects anything once the frame's count reaches the pool size.
 * `radius_m` bounds distance, `tile_m` is roughly the billboard's own width
 * in metres — gta3_view_tile slackens the cone test by it so an object
 * doesn't visibly pop as it crosses the edge. Returns 1 iff it actually
 * submitted (and counted) a billboard. */
static int bb_add(const MoteImage *img, float x, float y, float z,
                  int fx, int fy, int fw, int fh, float world_h, uint8_t blend,
                  float radius_m, float tile_m) {
    if (!gta3_view_tile(&g_view, x, y, z, radius_m, tile_m)) return 0;
    if (g_bb_used >= MAX_BILLBOARDS) { g_bb_budget_drop++; return 0; }
    if (!mote->scene_add_billboard(v3(x, y, z), img, fx, fy, fw, fh, world_h, blend)) return 0;
    g_bb_used++;
    return 1;
}

/* A person, as an upright camera-facing quad with a shadow under it. 1.8 m is
 * roughly human height in this world's scale, and the shadow is what stops a
 * billboard reading as a sticker floating over the road. */
/* 1.32, not the 1.8 a real person would be: on a 128x128 panel with the camera
 * 4.5 m back, 1.8 m filled about a third of the frame height and crowded the
 * view. It went 1.8 -> 1.6 -> 1.45 -> 1.32 by eye on captures, each step a
 * request to free up screen. Physics and the ped collision radius are
 * untouched — this is the billboard's drawn height only. */
#define CHAR_H 1.32f
/* The ground shadow scales WITH the figure. Held at a fixed 0.42 it kept
 * spreading out from under a shrinking sprite, which reads as a person
 * hovering. 0.26 of height matches the 0.42/1.6 the 1.6 m figure had. */
#define CHAR_SHADOW_R (CHAR_H * 0.2625f)
/* The sprite cells are 16 px wide but the figure only occupies columns 3..12,
 * so a full-cell quad is a quarter empty air either side and the people look
 * stocky. Drawing a narrower sub-rect keeps every pixel of the figure — the
 * quad's aspect follows the source rect, and world_h is unchanged, so they get
 * thinner without getting shorter.
 *
 * Measured per cell across all three sheets: ped and cop are 3..12 everywhere,
 * the player is 3..12 walking and 4..15 firing. The two firing poses (player
 * sheet, rows 4 and 5) therefore take their own, wider rect so the extended
 * gun arm is not clipped.
 *
 * This is as far as the RECT can go — 3..12 is the figure's own extent, and
 * the engine takes the quad's aspect straight from the source rect
 * (mote_scene3d.c: q->hw = q->hh * fw/fh), so there is no narrower quad to
 * draw the same pixels into. Anything thinner has to come out of the art, and
 * did: assets/make_slim.py pulled one pixel off each side of every row 9 px or
 * wider, which took the torso from 10 px to 8 and left the 4 px head and 6 px
 * legs alone. Measured on a capture, the shirt went from 21 px across to 17.
 * The cell extents are still 3..12 because narrower rows keep their outermost
 * columns; no single row is wider than 8. */
/* Tightened again to the measured extent itself: columns 3..12 is 10 px, so
 * cx 3 / cw 10 keeps every pixel of the figure with no margin and takes
 * another 17% off the width. The firing poses run 4..15, which is 12 px, so
 * they narrow the same way instead of taking the whole 16-wide cell. */
#define CHAR_CELL_X 3
#define CHAR_CELL_W 10
#define CHAR_FIRE_X 4
#define CHAR_FIRE_W 12
static void draw_character(const MoteImage *img, float x, float z, float yaw,
                           int variant, int frame, int nframes) {
    int col = facing_cell(yaw);
    int row = variant * nframes + frame;
    int wide = (nframes == 6 && frame >= 4);        /* player's aim/fire poses */
    int cx = wide ? CHAR_FIRE_X : CHAR_CELL_X, cw = wide ? CHAR_FIRE_W : CHAR_CELL_W;
    if (!bb_add(img, x, CHAR_H * 0.5f, z, col * 16 + cx, row * 16, cw, 16, CHAR_H,
               MOTE_BLEND_NONE, VIEW_GROUND_R, 1.0f))
        return;                        /* off-screen or out of billboard budget: no shadow either */
    mote->scene_add_shadow_ex(v3(x, 0.02f, z), v3(CHAR_SHADOW_R, 0, 0), v3(0, 0, CHAR_SHADOW_R), 0.5f);
}

/* An upright camera-facing sprite that is not a person: a tree, a pickup, a
 * phone box. Anchored at the ground, so `h` is its full world height.
 * radius_m/tile_m feed bb_add's view-cone test — see there. */
static void draw_upright(const MoteImage *img, float x, float z,
                         int fx, int fy, int fw, int fh, float h,
                         float radius_m, float tile_m) {
    bb_add(img, x, h * 0.5f, z, fx, fy, fw, fh, h, MOTE_BLEND_NONE, radius_m, tile_m);
}

/* -------------------------------------------------------------- entities ---- */
/* 8 car sprites (cars.png cells) + BUS + TANK (own sprites). Index also selects
 * the stats row in VSTAT. */
/* vehicle types = the 48 cars2 sheet cells (+ bus/tank). Notable cells: */
#define NCARTYPE   CARS2_N
#define VEH_BUS    NCARTYPE
#define VEH_TANK   (NCARTYPE+1)
#define VEH_HELI   (NCARTYPE+2)
#define VEH_BOAT   (NCARTYPE+3)
#define NVEH       (NCARTYPE+4)
#define CAR_POLICE    26   /* dark POLICE cruiser (lightbar) */
#define CAR_POLICE2   39   /* white highway patrol           */
#define CAR_TAXI      30   /* teal cab (TAXI sign)           */
#define CAR_AMBULANCE 18
#define CAR_FIRETRUCK 19
#define CAR_TOWTRUCK  27
#define CAR_SPORTS    34   /* red sports (the starter)       */
#define CAR_SEDAN     45   /* mundane saloon (cop-avoid fallback) */
enum { DRV_NONE, DRV_NPC, DRV_PLAYER, DRV_COP };
typedef struct { float x,z,yaw,spd; uint8_t type, driver, alive; float hp; float firecd;
                 uint8_t wrecked;          /* burnt husk — visible, pushable, not drivable */
                 uint8_t lamp; } Car;      /* LAMP_* below: brake / reverse, set by drive_car */
enum { LAMP_OFF, LAMP_BRAKE, LAMP_REV };
static void draw_vehicle_mesh(const Car *c);   /* defined below; used by dm_draw_remote above its definition */

/* per-vehicle handling. accel m/s^2 · maxspd m/s · turn · mass · length · width ·
 * grip (tyre lat_damp — HIGH = planted, LOW = tail-happy/slidey). */
typedef struct { float accel, maxspd, turn, mass, len, wid, grip; } VStat;
static VStat VSTAT[NVEH];          /* built at init from the sheet's measured art sizes */
#define CARS2_MPP 0.118f           /* metres per sheet pixel: +20%% size (46 px car ~ 5.4 m) */
/* per-car CLASS, reviewed cell by cell (same performance categories as before):
 *   0 SEDAN      1 COMPACT    2 COUPE     3 SPORTS     4 RACER (the "lambo")
 *   5 MUSCLE     6 HOTHATCH   7 CLASSIC   8 CLASSICSPT 9 LUXURY
 *  10 WAGON     11 VAN       12 PICKUP   13 JEEP      14 TAXI
 *  15 POLICE    16 AMBULANCE 17 FIRETRUCK 18 TOWTRUCK */
static const uint8_t CAR_CLS[54] = {
 /* 0*/ 7, 8, 9, 8, 7, 2, 8, 9,    /* navy classic, grn cabrio, blk limo, silver 300SL, maroon, tan coupe, blue cabrio, white luxe */
 /* 8*/ 9, 7, 0, 1, 3, 1, 1, 2,    /* blk limo, cream cabrio, blk sedan, grey cmp, red roadster, silver cmp, grn cmp, blue coupe */
 /*16*/ 3,13,16,17,10, 2, 6, 5,    /* red sports, army jeep, AMBULANCE, FIRETRUCK, blue SUV, silver coupe, yellow hatch, blk muscle */
 /*24*/ 0,10,15,18,12, 2,14,11,    /* beige sedan, brown wagon, POLICE, towtruck, white pickup, purple coupe, teal TAXI, grey van */
 /*32*/ 2, 0, 3, 4,11, 0, 0,15,    /* teal coupe, blue sedan, red sports, striped RACER, big van, magenta sedan, beige sedan, patrol */
 /*40*/14,10, 0, 1,12, 0, 1,13,   /* yellow cab, estate, blk sedan, orange cmp, old pickup, maroon sedan, teal cmp, beige jeep */
 /*48*/ 4, 4, 8, 4, 3, 3 };        /* Countach, lime lambo, green speedster, F40, red coupe, silver 911 */
/*                        accel maxspd turn  grip  massx */
/* accel · maxspd · turn · grip (tyre lat_damp) · mass factor.
 *
 * The SPORTS tier was barely quicker than a taxi: 25 against the sedan's 18,
 * on a scale where vmax is maxspd * 1.3. It now runs 28 with grip up from 26
 * to 29 and more steering authority, so it both goes and holds on.
 *
 * RACER is the top tier and now does a genuine 100 mph. maxspd is not the top
 * speed: drag (pull = 1 - (v/vmax)^2) settles a car near 86% of vmax rather
 * than at it, so the number was swept against a measured run rather than
 * derived -- 31 gave 77 mph, 36 gave 88, 40 gave 95, and 43 gives 101.
 * Measured top speeds now: RACER 101 mph, SPORTS 70, a plain sedan 40. */
static const float CLS_STAT[19][5] = {
 /* SEDAN     */ { 25, 18, 2.4f, 22, 1.00f },
 /* COMPACT   */ { 26, 18, 2.7f, 24, 0.95f },
 /* COUPE     */ { 27, 20, 2.6f, 22, 1.00f },
 /* SPORTS    */ { 39, 28, 3.05f, 29, 0.92f },
 /* RACER     */ { 43, 43, 3.25f, 31, 0.88f },
 /* MUSCLE    */ { 33, 24, 2.1f, 15, 1.15f },
 /* HOTHATCH  */ { 30, 21, 2.9f, 25, 0.90f },
 /* CLASSIC   */ { 21, 16, 2.2f, 20, 1.10f },
 /* CLASSICSPT*/ { 33, 24, 2.8f, 25, 1.00f },
 /* LUXURY    */ { 24, 19, 2.1f, 18, 1.25f },
 /* WAGON     */ { 22, 16, 2.2f, 20, 1.10f },
 /* VAN       */ { 19, 15, 1.8f, 20, 1.20f },
 /* PICKUP    */ { 21, 16, 2.0f, 21, 1.15f },
 /* JEEP      */ { 22, 16, 2.3f, 26, 1.10f },
 /* TAXI      */ { 28, 20, 2.7f, 24, 1.00f },
 /* POLICE    */ { 35, 24, 2.8f, 27, 1.10f },
 /* AMBULANCE */ { 22, 17, 1.9f, 22, 1.30f },
 /* FIRETRUCK */ { 14, 12, 1.5f, 24, 2.20f },
 /* TOWTRUCK  */ { 17, 13, 1.7f, 22, 1.60f },
};
static void build_vstats(void) {
    for (int i=0;i<CARS2_N;i++){
        float len = cars2_ah[i]*CARS2_MPP, wid = cars2_aw[i]*CARS2_MPP;
        const float *cs = CLS_STAT[CAR_CLS[i]];
        VSTAT[i] = (VStat){ cs[0], cs[1], cs[2], len*wid*0.11f*cs[4], len, wid, cs[3] };
    }
    VSTAT[VEH_BUS] =(VStat){ 12, 12, 1.2f, 3.4f, 8.6f, 3.77f, 22 };   /* +10%%: wider would block 2-lane roads */
    VSTAT[VEH_TANK]=(VStat){ 9,  8,  1.5f, 8.0f, 6.2f,  3.92f, 28 };
    /* wid is the real 2.6 m, not len. It was 7.0 to make the mesh's wid/len
     * squeeze a no-op, but draw_vehicle_mesh skips that squeeze for the
     * helicopter outright now, so the only things wid still drives are the
     * PHYSICS BOX and the shadow — and a 7 m square collision box held the
     * player 3.5 m off the centre on every side, which is outside the reach
     * test, so RB could never get you in. That was the bug. */
    VSTAT[VEH_HELI]=(VStat){ 7, 24, 1.9f, 3.0f, 7.0f,  2.6f,   6 };
    /* A boat: long, light for its size, and with almost no lateral grip — a
     * hull slides through a turn rather than biting like a tyre, and grip 4
     * against a car's 22 is what produces that without a second physics model.
     * wid is the real 2.8 m and not the length: it drives the collision box
     * and the shadow, and a 7 m square box would hold the player too far off
     * the hull to ever get aboard (the mistake the helicopter shipped with). */
    VSTAT[VEH_BOAT]=(VStat){ 8, 17, 1.35f, 4.0f, 7.0f, 2.8f, 4 };
}

typedef struct { float x,z,yaw,spd; uint8_t variant, alive, hp; float animt; float flee;
                 uint8_t iscop; float firecd;
                 float rage;               /* seconds left fighting back (see ped_brave) */
                 uint8_t gang; } Ped;      /* a street crew member — see GANG_N below */
/* A small, FIXED minority will swing back instead of running. Derived from the
 * ped slot rather than stored or rolled, so the same slot always behaves the
 * same way for as long as that person exists, and it costs nothing: 1 in 8. */
static int ped_brave(int i){ return (((unsigned)i * 2654435761u) >> 29) == 0; }

/* ------------------------------------------------------------ street crew ---
 * A RARE knot of people who are hostile on sight rather than when provoked,
 * standing together on one corner. Put the boot into all of them and the last
 * one down is carrying the crew's takings.
 *
 * One crew per city at most, and only in some cities, so running into them is
 * an event rather than a feature of every street. They are marked by a flag on
 * the ped rather than by slot, because foot cops take whatever ped slot is
 * free and would otherwise inherit a dead crew member's identity.
 *
 * The takings drop as a handful of ordinary cash pickups rather than a new
 * kind: it needs no sprite cell, it reads as a payout because there are
 * several of them, and each one is collected by the code that already exists. */
#define GANG_N       4       /* members in a crew */
#define GANG_SIGHT  15.0f    /* metres at which they come for you */
#define GANG_PURSE   6       /* cash pickups the last one down drops */
static uint8_t g_gang_alive;     /* members still standing; 0 = no crew in this city */

/* Sprint stamina: 1 = full, 0 = empty. g_stam_spent latches at empty so you
 * cannot re-trigger until it has recovered past STAM_ARM. */
static float   g_stam = 1.0f;
static uint8_t g_stam_spent;
enum { MODE_FOOT, MODE_CAR };
typedef struct { float x,z,yaw; int mode; int car; float animt; } Player;

typedef struct { float x,z; uint8_t variant; } Tree;

#define NCAR  18
#define NPED  34
#define NTREE 140
static Car    cars[NCAR];
static Ped    peds[NPED];
static Tree   trees[NTREE]; static int ntree;
static Player player;

/* ---- 2D physics (ABI v42): each vehicle is an oriented-box rigid body ---- */
#define NSTAT 60                       /* nearby static colliders (buildings + trees) */
static MoteBody2D  bodies[NCAR+NSTAT]; /* [0..NCAR) vehicles · [NCAR..) static world */
static int         g_nbodies;          /* bodies in the last physics step (debug box draw) */
static MoteWorld2D pworld;
static float       npc_target[NCAR];   /* NPC desired heading */
static float       stuck_t[NCAR];      /* time spent unable to move (stuck detection) */
/* ------------------------------------------------------------- helicopter ---
 * The one flyable aircraft, parked at generation in cars[HELI_SLOT] beside the
 * tank's cars[NCAR-1]. Altitude lives HERE, not in the physics: MoteBody2D has
 * no y at all, so the solver keeps doing x/z and the height is one float.
 *
 * g_heli_y is the world y of the skids, not a height above whatever is below —
 * absolute is what the camera, the mesh and the ceiling all want, and the floor
 * is only needed at the moment of landing.
 *
 * While airborne the body carries MOTE_B2D_SENSOR, which the solver honours by
 * detecting overlaps and applying no impulse, so the aircraft passes over cars
 * and walls instead of shouldering them along the street. Masks cannot do this
 * job: mote_phys2d.c:194 skips the filter when either mask is zero, and every
 * body in this game has zero. */
#define HELI_SLOT    (NCAR-2)
/* The boat, like the tank at NCAR-1 and the helicopter at NCAR-2, is a one-off
 * placed at generation rather than streamed traffic. Three of the eighteen car
 * slots are now reserved this way. */
#define BOAT_SLOT    (NCAR-3)
#define HELI_CEIL    45.0f     /* metres. The tallest building level is 24.0 m
                                * (g_lvl_h[13]), and the ground draw window has
                                * to widen with altitude — see draw_ground_window.
                                * 45 clears every roof and stays inside budget. */
#define HELI_CLIMB    9.0f     /* m/s, full collective */
#define HELI_YAW      1.9f     /* rad/s */
#define HELI_ACC     11.0f     /* m/s^2 along the nose */
#define HELI_DRAG     0.9f     /* per second, so it coasts rather than stops dead */
static float g_rotor;                  /* blade phase, radians — visual only */
/* Stopped at a red light LAST frame. Without this, waiting at a light is
 * indistinguishable from being wedged: stuck_t climbs while the car sits still,
 * and at 1 s the jam recovery cancels `blocked`, picks a fresh heading and
 * floors the throttle — so no car ever actually waited at a red, it paused for
 * a second and then drove through the junction. */
static uint8_t     red_wait[NCAR];
enum { AIS_CRUISE=0, AIS_TURN=1 };     /* NPC driving state machine */
static uint8_t     ai_state[NCAR];
static float       turn_wx[NCAR], turn_wz[NCAR];   /* TURN exit waypoint (hugs the corner) */
static uint8_t     lane_pref[NCAR];     /* preferred RIGHT-side lane (0 = kerb lane, 1,2… inward) */
static float       steerhold[NCAR];    /* progressive steering: builds while a turn is held */

static float frand(void); static int irand(int n);   /* RNG defined below */
static void car_body_init(int i) {
    Car *c = &cars[i]; const VStat *v = &VSTAT[c->type];
    /* every vehicle's collider is ART-EXACT: VSTAT len/wid are the true art sizes */
    float hl = v->len*0.5f, hw = v->wid*0.5f;
    bodies[i] = mote_body2d_box(c->x, c->z, hl, hw, c->yaw, v->mass*380.0f);
    bodies[i].friction = 0.3f; bodies[i].restitution = 0.38f;  /* low grab + real bounce: cars GLANCE off
                                                                   each other (walls stay dull - rest=min) */
    bodies[i].ang_damp = 3.0f; bodies[i].lin_damp = 0.35f;    /* light rolling resistance; low-ish so drifts hold */
    bodies[i].lat_damp = v->grip;                             /* per-car tyre grip (muscle slides, sports plant) */
    /* apply_drive re-applies this every frame with the wet-road penalty. */
    npc_target[i] = c->yaw; ai_state[i] = AIS_CRUISE; lane_pref[i] = (uint8_t)irand(3);
}

/* apply throttle/brake/steer to a car body: accelerate ALONG its heading and steer.
 * Tyre lateral grip is handled by the solver (MoteBody2D.grip) every substep, so a
 * collision-imparted sideways velocity gets bled by the tyres, not floated away. */
static void apply_drive(MoteBody2D *b, const VStat *v, float throttle, float brake, float steer, float dt) {
    int ci = (int)(b - bodies);
    /* Wet roads: bleed up to 22% of tyre grip in a downpour. Re-applied every
     * frame rather than set at spawn, because the weather changes under cars
     * that are already driving. Light on purpose — the brief asked for a
     * little looseness, not an ice rink. */
    b->lat_damp = v->grip * (1.0f - 0.22f * g_wet);
    float c=cosf(b->angle), s=sinf(b->angle);
    /* drive ONLY along the heading; the engine's tyre model owns the sideways
     * velocity, so a hard turn's momentum builds into a real slide. */
    float ofs = b->vx*c + b->vy*s;                    /* current forward speed */
    /* Acceleration falls away as speed rises, instead of being constant until it
     * slams into a clamp. pull = 1 - (v/vmax)^2 is the standard drag shape: full
     * shove off the line, tapering to nothing as the car approaches its top
     * speed, so the car settles onto vmax rather than pinning to it.
     *
     * The multiplier drops 1.5 -> 1.0 at the same time. Flat 1.5 put a sedan at
     * its 84 km/h top speed in 0.6 s, which is what made it feel fake: there
     * was no sense of gathering speed, just an instant jump to the clamp. With
     * drag at 1.0 the same car passes 50% in 0.51 s and 95% in 1.71 s — still
     * brisk for an arcade city, but you can feel it pulling. */
    float vmax = v->maxspd * 1.3f;
    float frac = mote_clampf(fabsf(ofs) / vmax, 0.0f, 1.0f);
    float pull = 1.0f - frac * frac;
    float tfs = ofs + (throttle*v->accel*1.0f*pull - brake*v->accel*1.7f)*dt;
    tfs = mote_clampf(tfs, -vmax*0.45f, vmax);      /* kept as a bound; drag should reach it first */
    float dfs = tfs - ofs;
    b->vx += c*dfs; b->vy += s*dfs;                   /* change speed along heading; leave lateral alone */
    /* progressive steering (builds while held, snaps on reversal, relaxes on release).
     * Yaw rate is ~constant with speed, so the turning RADIUS (= v / yaw) is naturally
     * tight at a crawl and wide at speed. Held hard at speed, the low grip lets go. */
    if (steer == 0.0f)                         steerhold[ci] -= steerhold[ci]*mote_clampf(7.0f*dt,0,1);
    else if (steerhold[ci]*steer < 0.0f)       steerhold[ci] = steer*0.30f;      /* reversal */
    else                                       steerhold[ci] = mote_clampf(steerhold[ci] + steer*4.6f*dt, -1.0f, 1.0f);
    float spd  = fabsf(tfs);
    float gate = mote_clampf((spd-0.45f)*0.9f, 0.0f, 1.0f);   /* DEAD when still: wheels need some roll to turn */
    /* steering-wheel model: yaw carries the SIGN of travel — wheel held left drives a
     * left arc forward, and re-traces that same arc when backing up (yaw flips). */
    float rev  = (tfs < 0.0f) ? -1.0f : 1.0f;
    /* Extra yaw authority at TOWN speeds only. Yaw rate used to be flat above
     * the gate, so turning radius (v / yaw) grew straight with speed and city
     * corners needed a run-up. This lifts yaw by up to 45% below ~14 m/s and
     * leaves fast driving exactly as it was, so corners tighten without making
     * the highway twitchy. */
    float turnfac = 1.0f + 0.45f * (1.0f - mote_clampf(spd * (1.0f/14.0f), 0.0f, 1.0f));
    float targ = steerhold[ci] * v->turn * 0.82f * turnfac * gate * rev;
    b->avel += (targ - b->avel) * mote_clampf(9.0f*dt, 0.0f, 1.0f);   /* 7 -> 9: wheel bites sooner */
}
static float ang_diff(float target, float cur){ float d=target-cur; while(d>3.14159f)d-=6.2832f; while(d<-3.14159f)d+=6.2832f; return d; }
/* brake > 0 is only used by the red-light hold: cutting the throttle alone
 * leaves a car coasting on lin_damp 0.35, which drifts it straight through the
 * junction. Measured: with throttle-cut only, NPCs stopped at a red essentially
 * never reached rest. */
static void ai_drive_b(int i, float target_yaw, float throttle, float brake, float dt) {
    float d = ang_diff(target_yaw, bodies[i].angle);
    /* PROPORTIONAL, not bang-bang. This used to be full lock left, full lock
     * right, or nothing, with the deadband at 0.06 rad — so a car holding a
     * straight line sawed between the two, which is the visible weave down a
     * street. Steering effort now scales with how far off heading the car
     * actually is, and the deadband widens slightly, so small errors are
     * corrected gently and only a real corner asks for full lock. */
    float steer = mote_clampf(d * 3.2f, -1.0f, 1.0f);
    if (d > -0.035f && d < 0.035f) steer = 0.0f;
    apply_drive(&bodies[i], &VSTAT[cars[i].type], throttle, brake, steer, dt);
    if (brake > 0.0f) {          /* brakes hold to a stop; they never reverse */
        MoteBody2D *b = &bodies[i];
        float c2=cosf(b->angle), s2=sinf(b->angle), fs=b->vx*c2+b->vy*s2;
        if (fs < 0.0f) { b->vx -= c2*fs; b->vy -= s2*fs; }
    }
}
static void ai_drive(int i, float target_yaw, float throttle, float dt) {
    ai_drive_b(i, target_yaw, throttle, 0.0f, dt);
}
/* is another vehicle close ahead? (so NPCs coast/queue instead of ramming) */
/* brake only for a car that is genuinely in MY lane, ahead, and going roughly MY way
 * (never for oncoming or cross traffic — they pass, they don't block). */
static int car_ahead(int i) {
    const VStat *v=&VSTAT[cars[i].type];
    float ang=bodies[i].angle, c=cosf(ang), s=sinf(ang);
    float spd=bodies[i].vx*c+bodies[i].vy*s;
    float look=v->len*0.5f + 3.0f + (spd>0?spd*0.6f:0.0f);   /* braking distance grows with speed */
    for (int j=0;j<NCAR;j++){ if(j==i || !cars[j].alive) continue;
        float dx=cars[j].x-cars[i].x, dz=cars[j].z-cars[i].z;
        float fwd = dx*c + dz*s;                       /* ahead distance */
        if (fwd < 0.5f || fwd > look) continue;
        float lat = -dx*s + dz*c; if (lat<0) lat=-lat; /* lateral offset from my path */
        if (lat > 1.7f) continue;                      /* not in my lane */
        if (fabsf(ang_diff(bodies[j].angle, ang)) > 2.0f) continue;  /* oncoming → ignore */
        return 1;
    }
    return 0;
}

static uint32_t g_rng = 0x1234abcd;
static float frand(void) { g_rng = g_rng*1664525u + 1013904223u; return (g_rng>>8) * (1.0f/16777216.0f); }
static int   irand(int n) { return (int)(frand()*n); }

/* car world size: 4.4 m long x 2.0 m wide (sprite cell 22x36) */
#define CAR_LEN 4.4f
#define CAR_WID 2.0f

static int is_drivable(int x,int z){ char c=tile_at(x,z); return c=='.'||c=='B'; }  /* AI: road/bridge */
/* a QUIET spot to stash the tank: clear 3x3 pavement/grass pocket, no street
 * within 2 tiles, and at least one straight drivable escape run within 8 tiles
 * (so the prize is hidden but never sealed in). */
/* A helicopter needs a CLEAR PAD, not a hiding place: a 3x3 of open ground with
 * nothing solid within two tiles, so the rotor is not inside a facade and you
 * can lift straight out. It does NOT need an escape run — that is the whole
 * point of the thing — so unlike tank_hideout it never asks for a road. */
static int heli_pad(int x,int z){
    for (int dz=-2;dz<=2;dz++)for (int dx=-2;dx<=2;dx++){
        char c=tile_at(x+dx,z+dz);
        if (c!=','&&c!=' ') return 0;
    }
    return 1;
}
static int tank_hideout(int x,int z){
    for (int dz=-1;dz<=1;dz++)for (int dx=-1;dx<=1;dx++){
        char c=tile_at(x+dx,z+dz);
        if (c!=','&&c!=' ') return 0;
    }
    for (int dz=-2;dz<=2;dz++)for (int dx=-2;dx<=2;dx++)
        if (is_drivable(x+dx,z+dz)) return 0;
    static const int DX4[4]={1,-1,0,0}, DZ4[4]={0,0,1,-1};
    for (int k=0;k<4;k++){
        for (int s2=2;s2<=8;s2++){
            char c=tile_at(x+DX4[k]*s2, z+DZ4[k]*s2);
            if (c=='.'||c=='B') return 1;              /* an escape run to a road */
            if (c!=','&&c!=' ') break;                 /* blocked: try another way */
        }
    }
    return 0;
}
/* heading (radians) aligned with the road at this tile: the cardinal with the
 * longest drivable run — so a spawned car faces ALONG the street, not a wall. */
static float road_heading(int x,int z){
    static const float H[4]={ 0.0f, 1.5708f, 3.14159f, -1.5708f };  /* E S W N */
    int best=0, bestrun=-1;
    for (int k=0;k<4;k++){ int dx=(k==0)-(k==2), dz=(k==1)-(k==3), run=0;
        for (int s=1;s<=6;s++){ if (is_drivable(x+dx*s, z+dz*s)) run++; else break; }
        if (run>bestrun){ bestrun=run; best=k; } }
    return H[best];
}
static int walkable_world(float wx,float wz){ int tx=(int)(wx/TILE),tz=(int)(wz/TILE); char c=tile_at(tx,tz); return (c!='#'&&c!='O'&&c!='H'&&c!='~') || is_garage(tx,tz); }
static int drivable_world(float wx,float wz){ int tx=(int)(wx/TILE),tz=(int)(wz/TILE); char c=tile_at(tx,tz); return (c!='#'&&c!='O'&&c!='H'&&c!='~') || is_garage(tx,tz); }
static int road_world(float wx,float wz){ return is_drivable((int)(wx/TILE),(int)(wz/TILE)); }  /* road/bridge only (AI cars stay off pavement) */

static int pav_or_grass(int x,int z){ char c=tile_at(x,z); return c==','||c==' '; }
/* find a tile satisfying ok() in an annulus [rmin,rmax] metres from (px,pz). */
static int find_near(float px,float pz,float rmin,float rmax,int(*ok)(int,int),float*ox,float*oz){
    for (int t=0;t<48;t++){
        float a=frand()*6.2832f, r=rmin+frand()*(rmax-rmin);
        int x=(int)((px+cosf(a)*r)/TILE), z=(int)((pz+sinf(a)*r)/TILE);
        if (x<1||z<1||x>=MAPW-1||z>=MAPH-1) continue;
        if (ok(x,z)){ *ox=x*TILE+TILE*0.5f; *oz=z*TILE+TILE*0.5f; return 1; }
    }
    return 0;
}
/* a road tile clear of other cars (so vehicles never spawn stacked → instant jam) */
static float road_run(float x,float z,float dx,float dz,float cap);   /* defined below */
/* given a road-tile centre (cx,cz), pick a valid travel direction and shift the spawn
 * into THAT direction's right-hand lane, facing along it — so cars never start in the
 * oncoming lane (a big source of head-on collisions). */
static void place_in_lane(float *cx, float *cz, float *oyaw){
    int tx=(int)(*cx/TILE), tz=(int)(*cz/TILE);
    float bx=(tx+0.5f)*TILE, bz=(tz+0.5f)*TILE;
    /* TWO-WAY: the travel direction follows which HALF of the corridor this tile is in
     * (right-hand traffic): horizontal roads — north half drives WEST, south half EAST;
     * vertical — west half SOUTH, east half NORTH. Junctions fall back to longest-run. */
    int o,pp,span; corridor_info(tx,tz,&o,&pp,&span);
    if (o==3){                       /* junction tile: use the nearest CORRIDOR's lane rule */
        static const int DX4[4]={1,-1,0,0}, DZ4[4]={0,0,1,-1};
        for (int r=1;r<=3 && o==3;r++) for (int k=0;k<4 && o==3;k++){
            int xx=tx+DX4[k]*r, zz=tz+DZ4[k]*r, oo,p2,s2;
            corridor_info(xx,zz,&oo,&p2,&s2);
            if (oo==1||oo==2){ o=oo; pp=p2; span=s2; tx=xx; tz=zz;
                bx=(tx+0.5f)*TILE; bz=(tz+0.5f)*TILE; }
        }
    }
    float yaw;
    if      (o==1) yaw = (pp*2 < span) ? 3.14159f : 0.0f;
    else if (o==2) yaw = (pp*2 < span) ? 1.5708f : -1.5708f;
    else           yaw = road_heading(tx,tz);
    float rx=-sinf(yaw), rz=cosf(yaw);                        /* driver's right */
    float rdist=road_run(bx,bz, rx,rz, 7.0f);
    float move=rdist-1.8f; if(move<0) move=0;                 /* sit ~1.8 m from the right kerb */
    *cx = bx + rx*move; *cz = bz + rz*move; *oyaw = yaw;
}
/* TRUE road-network distance (metres, approx) between two world points, via BFS
 * on a coarse 4x4-tile grid (64x64 cells, ~12 KB bss). Returns -1 if there is no
 * road route — a courier target straight across a river without a nearby bridge
 * is a 3x detour, and the mission timer must know that. */
#define RD_N 64
static uint8_t  rd_dist[RD_N*RD_N];
static uint16_t rd_q[RD_N*RD_N];
static int rd_cell_road(int cx,int cz){
    for (int dz=0;dz<4;dz++)for (int dx=0;dx<4;dx++)
        if (is_drivable(cx*4+dx, cz*4+dz)) return 1;
    return 0;
}
static float road_dist(float ax,float az,float bx,float bz){
    int sa=(int)(ax/TILE)/4 + ((int)(az/TILE)/4)*RD_N;
    int sb=(int)(bx/TILE)/4 + ((int)(bz/TILE)/4)*RD_N;
    if (sa<0||sb<0||sa>=RD_N*RD_N||sb>=RD_N*RD_N) return -1.0f;
    for (int i=0;i<RD_N*RD_N;i++) rd_dist[i]=0xFF;
    int head=0, tail=0;
    rd_dist[sa]=0; rd_q[tail++]= (uint16_t)sa;
    while (head<tail){
        int c=rd_q[head++];
        if (c==sb) break;
        int cx=c%RD_N, cz=c/RD_N;
        uint8_t d=rd_dist[c];
        if (d>=250) continue;
        static const int DX[4]={1,-1,0,0}, DZ[4]={0,0,1,-1};
        for (int k=0;k<4;k++){
            int nx=cx+DX[k], nz=cz+DZ[k];
            if (nx<0||nz<0||nx>=RD_N||nz>=RD_N) continue;
            int n=nz*RD_N+nx;
            if (rd_dist[n]!=0xFF || !rd_cell_road(nx,nz)) continue;
            rd_dist[n]=(uint8_t)(d+1); rd_q[tail++]=(uint16_t)n;
        }
    }
    if (rd_dist[sb]==0xFF) return -1.0f;
    return rd_dist[sb]*4.0f*TILE;                    /* cells -> metres */
}

/* THE RACER'S ROUTER. A greedy car needs a distance field that reflects REAL road
 * connectivity: rd_cell_road links any two cells that each merely contain some road,
 * so a dead-end stub makes cells look joined — a lie that traps a greedy racer in a
 * blind corridor (it reads "shorter this way" into a wall). rd_edge fixes that: two
 * coarse cells are adjacent only if their roads actually TOUCH at the shared border.
 * race_field then BFS-floods cell distances FROM the checkpoint; the racer descends
 * that field at each junction, which on an accurate graph has no local minima. */
static int rd_edge(int cx,int cz,int nx,int nz){
    if (nx==cx+1){ for(int d=0;d<4;d++) if(is_drivable(cx*4+3,cz*4+d)&&is_drivable(nx*4+0,nz*4+d)) return 1; return 0; }
    if (nx==cx-1){ for(int d=0;d<4;d++) if(is_drivable(cx*4+0,cz*4+d)&&is_drivable(nx*4+3,nz*4+d)) return 1; return 0; }
    if (nz==cz+1){ for(int d=0;d<4;d++) if(is_drivable(cx*4+d,cz*4+3)&&is_drivable(nx*4+d,nz*4+0)) return 1; return 0; }
    if (nz==cz-1){ for(int d=0;d<4;d++) if(is_drivable(cx*4+d,cz*4+0)&&is_drivable(nx*4+d,nz*4+3)) return 1; return 0; }
    return 0;
}
static uint8_t rf_dist[RD_N*RD_N];                  /* racer field: cell distance to the checkpoint */
static int     rf_valid=0; static float rf_tx=-1, rf_tz=-1;
static void race_field(float tx,float tz){
    rf_valid=0;
    for (int i=0;i<RD_N*RD_N;i++) rf_dist[i]=0xFF;
    int sb=(int)(tx/TILE)/4 + ((int)(tz/TILE)/4)*RD_N;
    if (sb<0||sb>=RD_N*RD_N) return;
    int head=0, tail=0; rf_dist[sb]=0; rd_q[tail++]=(uint16_t)sb;   /* reuse rd_q (transient) */
    while (head<tail){
        int c=rd_q[head++], cx=c%RD_N, cz=c/RD_N; uint8_t d=rf_dist[c];
        if (d>=250) continue;
        static const int DX[4]={1,-1,0,0}, DZ[4]={0,0,1,-1};
        for (int k=0;k<4;k++){
            int nx=cx+DX[k], nz=cz+DZ[k];
            if (nx<0||nz<0||nx>=RD_N||nz>=RD_N) continue;
            int n=nz*RD_N+nx;
            if (rf_dist[n]!=0xFF || !rd_cell_road(nx,nz) || !rd_edge(cx,cz,nx,nz)) continue;
            rf_dist[n]=(uint8_t)(d+1); rd_q[tail++]=(uint16_t)n;
        }
    }
    rf_tx=tx; rf_tz=tz; rf_valid=1;
}
/* cost-to-checkpoint at a world point (in coarse cells); huge if unrouteable */
static float race_cost(float x,float z){
    int cx=(int)(x/TILE)/4, cz=(int)(z/TILE)/4;
    if (!rf_valid||cx<0||cz<0||cx>=RD_N||cz>=RD_N) return 1e6f;
    uint8_t d=rf_dist[cz*RD_N+cx];
    return d==0xFF ? 1e6f : (float)d;
}


static int find_road_clear(float px,float pz,float rmin,float rmax,float*ox,float*oz){
    for (int t=0;t<56;t++){
        float a=frand()*6.2832f, r=rmin+frand()*(rmax-rmin);
        int x=(int)((px+cosf(a)*r)/TILE), z=(int)((pz+sinf(a)*r)/TILE);
        if (x<2||z<2||x>=MAPW-2||z>=MAPH-2 || !is_drivable(x,z)) continue;
        float wx=x*TILE+TILE*0.5f, wz=z*TILE+TILE*0.5f; int clear=1;
        for (int j=0;j<NCAR;j++){ if(!cars[j].alive) continue;
            float dx=cars[j].x-wx, dz=cars[j].z-wz; if (dx*dx+dz*dz < 42.0f){ clear=0; break; } }
        if (clear){ *ox=wx; *oz=wz; return 1; }
    }
    return 0;
}

static void spawn_world(void) {
    ntree = 0;                                        /* trees are drawn procedurally now */
    /* player spawn: a pavement tile beside a road — in a RANDOM district each run */
    int cx=MAPW/2, cz=MAPH/2, sx=cx, sz=cz, done=0;
    for (int t=0;t<24 && !done;t++){
        int bx=MAPW/4+irand(MAPW/2), bz=MAPH/4+irand(MAPH/2);   /* central half */
        for (int r=0;r<10 && !done;r++)
            for (int dz=-r;dz<=r && !done;dz++) for (int dx=-r;dx<=r && !done;dx++){
                int x=bx+dx,z=bz+dz; if(x<2||z<2||x>=MAPW-2||z>=MAPH-2) continue;
                if (tile_at(x,z)==',' && (is_roadlike(x+1,z)||is_roadlike(x-1,z)||is_roadlike(x,z+1)||is_roadlike(x,z-1)))
                    { sx=x; sz=z; done=1; } }
    }
    for (int r=0;r<40 && !done;r++)                       /* fallback: the old centre search */
        for (int dz=-r;dz<=r && !done;dz++) for (int dx=-r;dx<=r && !done;dx++){
            int x=cx+dx,z=cz+dz; if(x<2||z<2||x>=MAPW-2||z>=MAPH-2) continue;
            if (tile_at(x,z)==',' && (is_roadlike(x+1,z)||is_roadlike(x-1,z)||is_roadlike(x,z+1)||is_roadlike(x,z-1)))
                { sx=x; sz=z; done=1; } }
    player.mode=MODE_FOOT; player.car=-1;
    player.x=sx*TILE+TILE*0.5f; player.z=sz*TILE+TILE*0.5f; player.yaw=-1.5708f; player.animt=0;

    /* traffic + parked cars, well-spaced on roads, each FACING ALONG the street */
    for (int i=0;i<NCAR;i++){ float ox,oz;                    /* moving traffic (cars[0] becomes jackable) */
        if (i<8 && find_road_clear(player.x,player.z, 12.0f, 62.0f, &ox,&oz)){
            int ty=irand(NCARTYPE); if(ty==CAR_POLICE||ty==CAR_POLICE2||ty==CAR_FIRETRUCK)ty=CAR_SEDAN;
            if(irand(20)==0)ty=VEH_BUS;  /* buses rare */
#ifdef MOTE_HOST
            /* test: MOTE_GTA_CARTYPE=<n> forces the type of the first eight
             * traffic cars, which is how a silhouette gets looked at on
             * camera. Traffic types are random, so catching a specific one
             * otherwise means driving around until it turns up. See CAR_CLS
             * for which type is which class. */
            { const char *f=getenv("MOTE_GTA_CARTYPE"); if(f) ty=atoi(f); }
#endif
            float yaw; place_in_lane(&ox,&oz,&yaw);              /* right lane, facing along the street */
            cars[i]=(Car){ ox,oz,yaw,0,(uint8_t)ty,DRV_NPC,1 };
            npc_target[i]=yaw; stuck_t[i]=0;
        } else cars[i].alive=0;
    }
    /* a jackable car right next to the player — a RANDOM type each run */
    { float ox,oz; if (find_near(player.x,player.z, 2.0f, 3.4f, is_drivable, &ox,&oz)){
        int ty=irand(NCARTYPE); if(ty==CAR_POLICE||ty==CAR_POLICE2||ty==CAR_FIRETRUCK)ty=CAR_SEDAN;
#ifdef MOTE_HOST
        /* The starter car too, not just the traffic: this is the one
         * MOTE_GTA_INCAR picks, since it is the nearest, and it OVERWRITES
         * cars[0] after the traffic loop has run — so forcing the traffic
         * type alone left the car you actually drive on a random type. */
        { const char *f=getenv("MOTE_GTA_CARTYPE"); if(f) ty=atoi(f); }
#endif

        cars[0]=(Car){ ox,oz, road_heading((int)(ox/TILE),(int)(oz/TILE)), 0, (uint8_t)ty,DRV_NONE,1 }; } }
    /* pedestrians on nearby pavement/grass */
    for (int i=0;i<NPED;i++){ float ox,oz;                    /* ~22 pedestrians; rest free for foot-cops */
        if (i<22 && find_near(player.x,player.z, 4.0f, 34.0f, pav_or_grass, &ox,&oz))
            peds[i]=(Ped){ ox,oz,(float)(irand(4))*1.5708f,0,(uint8_t)irand(4),1,2,0,0 };
        else peds[i].alive=0;
    }
    for (int i=0;i<NCAR;i++){ cars[i].hp=100.0f; cars[i].firecd=0; }
    for (int i=0;i<NPED;i++){ if(peds[i].alive) peds[i].hp=2; }

    /* the hidden TANK — parked in a QUIET OFF-ROAD pocket far away: a clear 3x3
     * of pavement/grass with no street within 2 tiles (so you never trip over it
     * on a highway), but with a straight drivable escape run so the prize can
     * actually be driven out. */
    { float ox,oz; int placed=0;
      for (int pass=0; pass<2 && !placed; pass++){
          float rmin = pass==0 ? 130.0f : 80.0f;
          if (find_near(player.x,player.z, rmin, 260.0f, tank_hideout, &ox,&oz)){
              cars[NCAR-1]=(Car){ ox,oz,(float)(irand(4))*1.5708f,0,VEH_TANK,DRV_NONE,1,600.0f,0 };
              placed=1;
          }
      }
      if (!placed && find_near(player.x,player.z, 100.0f, 240.0f, is_drivable, &ox,&oz))
          { cars[NCAR-1]=(Car){ ox,oz,-1.5708f,0,VEH_TANK,DRV_NONE,1,600.0f,0 }; placed=1; }
      if (!placed) cars[NCAR-1]=(Car){ (MAPW-6)*TILE,(MAPH-6)*TILE,0,0,VEH_TANK,DRV_NONE,1,600.0f,0 };
#ifdef MOTE_HOST
      if (getenv("MOTE_GTA_DEBUG"))
          fprintf(stderr,"[TANK] hidden at tile (%d,%d) hideout=%d\n",
                  (int)(cars[NCAR-1].x/TILE),(int)(cars[NCAR-1].z/TILE),placed);
#endif
    }

    /* the HELICOPTER — same treatment as the tank, on an open pad rather than in
     * a pocket. It sits nearer than the tank does: the reward for finding it is
     * the flying, not the walk. */
    { float ox,oz; int placed=0;
      for (int pass=0; pass<2 && !placed; pass++){
          float rmin = pass==0 ? 70.0f : 30.0f;
          if (find_near(player.x,player.z, rmin, 200.0f, heli_pad, &ox,&oz)){
              cars[HELI_SLOT]=(Car){ ox,oz,(float)(irand(4))*1.5708f,0,VEH_HELI,DRV_NONE,1,100.0f,0 };
              placed=1;
          }
      }
      if (!placed && find_near(player.x,player.z, 30.0f, 240.0f, pav_or_grass, &ox,&oz))
          { cars[HELI_SLOT]=(Car){ ox,oz,0,0,VEH_HELI,DRV_NONE,1,100.0f,0 }; placed=1; }
      if (!placed) cars[HELI_SLOT].alive=0;
      g_heli_y = 0.0f; g_heli_vy = 0.0f;
#ifdef MOTE_HOST
      if (getenv("MOTE_GTA_DEBUG"))
          fprintf(stderr,"[HELI] pad at tile (%d,%d) placed=%d\n",
                  (int)(cars[HELI_SLOT].x/TILE),(int)(cars[HELI_SLOT].z/TILE),placed);
#endif
    }
}

/* =========================================================== crime layer === */
enum { ST_TITLE, ST_PLAY, ST_WASTED, ST_BUSTED, ST_DMLINK };
enum { W_FIST, W_PISTOL, W_SMG, W_SHOTGUN, W_FLAME, W_ROCKET, W_UZI, W_MINIGUN, W_GRENADE, NWEAP };
enum { PK_CASH, PK_PISTOL, PK_SMG, PK_SHOTGUN, PK_HEALTH, PK_FLAME, PK_ROCKET, PK_PACKAGE };
enum { MK_GUN, MK_SPRAY, MK_PHONE, MK_DOCK };
enum { MI_NONE, MI_COURIER, MI_RAMPAGE, MI_GETAWAY, MI_HIT,
       MI_DELIVER,   /* fetch a named car, drive it to the drop undamaged */
       MI_PICKUP,    /* grab N scattered packages before the clock */
       MI_REPO,      /* ram-wreck a fleeing target car */
       MI_ESCORT,    /* keep a VIP on foot alive to the drop */
       MI_SMUGGLE,   /* reach the drop while staying under a heat cap */
       MI_DEMO,      /* wreck N marked cars */
       MI_VIGIL,     /* cull N of a target gang variant */
       MI_WANTED,    /* provoke and SURVIVE N stars for a duration */
       MI_CIRCUIT,   /* time trial: hit a chain of checkpoints before the clock */
       MI_RIVAL,     /* race a rubber-band sports-car rival through the checkpoints */
       MI_COUNT };

