static int   rival_car, rival_i;  /* RIVAL: rival's car slot + its checkpoint progress (a REAL AI car) */
/* RIVAL rubber-band top speeds (m/s). Traffic cruises at 9.5; the racer runs faster,
 * and modulates by who's ahead so the street race stays tight and beatable. */
#define RIVAL_CAP_AHEAD   10.0f     /* rival is a checkpoint ahead of the player → ease off (but still race) */
#define RIVAL_CAP_EVEN_LO 11.5f     /* same leg, rival already closer than the player → coast */
#define RIVAL_CAP_EVEN    13.0f     /* same leg, roughly level */
#define RIVAL_CAP_BEHIND  15.5f     /* rival is behind (or trailing on the leg) → floor it */
#define RIVAL_ARRIVE2    100.0f     /* checkpoint arrival radius^2 (10 m — a car needs some slack) */
static const char *g_msg; static float g_msg_t;
static float hosp_x, hosp_z;
static int   g_showmap, g_mapsx, g_mapsy; static float g_maptime;   /* full-map view */
static int   g_lookback;      /* LB held on foot: swing the camera round */
static int   g_radar_on = 1;  /* minimap on/off — a SETTINGS row (was RB on the map screen) */
static int   g_ctlpage;       /* the CONTROLS page, opened from SETTINGS */
/* The pause screen has two tabs: LB/RB flip between the city map and settings.
 * g_setsel is the highlighted settings row; g_setmsg flashes the result of a
 * save or load for a couple of seconds so the button press has an answer. */
enum { TAB_MAP, TAB_SET, TAB_N };
/* SET_HELI and SET_TANK are TEMPORARY DEBUG ROWS. They bring the one-off
 * vehicles to you instead of making you find where they were hidden, which is
 * the only way to test either on the device — MOTE_GTA_TP_HELI and
 * MOTE_GTA_TP_TANK are host-only, and a scripted env var is no use with the
 * handheld in your hands.
 *
 * To remove them: delete the two enum rows, their two NAME entries, and their
 * two cases in the settings switch. Nothing else refers to them. */
enum { SET_MINIMAP, SET_SOUND, SET_CONTROLS, SET_HELI, SET_TANK, SET_SAVE, SET_LOAD, SET_N };
static int   g_menutab = TAB_MAP, g_setsel;
static const char *g_setmsg; static float g_setmsg_t;
/* SOUND on/off, persisted.
 *
 * It rides slot 0, the blob that already carries the best-cash record, because
 * that is the one the game reads at boot whether or not you have a saved game.
 * The blob grows from two ints to three; the loader accepts the OLD two-int
 * form and leaves sound on, so an existing save does not lose its record and
 * does not come back muted.
 *
 * Written the moment it is toggled rather than at death, which is the only
 * other time slot 0 is flushed — a setting you changed and then quit without
 * dying would otherwise not stick, which is exactly how someone would test it. */
#define SAVE0_MAGIC 0x47544131
static uint8_t g_sound_on = 1;
/* THREE SAVE SLOTS, numbered 1..3 in the menu. Slot 0 of the platform's eight
 * is this preferences blob, so the game's saves start at 1 and g_slot is the
 * 0-based index into them.
 *
 * Which slot you last picked rides the same flags word as the sound setting —
 * two bits, free, and it means the menu comes back where you left it. */
#define NSAVE_SLOT 3
static uint8_t g_slot;                  /* 0..NSAVE_SLOT-1; platform slot = g_slot + 1 */
static void save_prefs(void);
/* Where a debug-delivered vehicle lands: ALWAYS straight in front of you,
 * stepping closer until the tile is somewhere one can sit. A pad search picks a
 * random bearing, which half the time puts the thing behind your back and makes
 * the row look broken; for a debug affordance, predictable beats tidy. */
static float pl_x(void), pl_z(void), pl_yaw(void);
static void bring_here(float *ox, float *oz) {
    float fx = cosf(pl_yaw()), fz = sinf(pl_yaw());
    *ox = pl_x(); *oz = pl_z();                  /* worst case: on top of you */
    for (float d = 9.0f; d >= 3.0f; d -= 1.0f) {
        float cx = pl_x() + fx * d, cz = pl_z() + fz * d;
        char tc = tile_at((int)(cx / TILE), (int)(cz / TILE));
        if (tc == ',' || tc == ' ' || tc == '.') { *ox = cx; *oz = cz; break; }
    }
}

/* ================================================== 2P DEATHMATCH state ====
 * Same generated city on both units (nonce winner rolls the seed and sends it),
 * NO traffic/peds/police, weapon caches respawn, cars are parked props both
 * sides share by index. Each unit simulates its own player; hits are decided
 * by the shooter against the replicated avatar and applied by the victim.
 * wire (after 0xA5): 'H' proto nonce16 · 'S' seed32 · 'P' x16 z16 yaw8 flags8
 * cartype8 hp8 (~15 Hz = keepalive) · 'F' (fire flash) · 'D' dmg · 'K' (died) ·
 * 'C' caridx (peer entered car) · 'X' caridx x16 z16 yaw8 fl8 (car returned) ·
 * 'T' pickidx · 'Q' quit */
#define DM_PROTO 1
#define DM_FRAGS 10
static int      g_dm;                        /* deathmatch session active */
static void     dm_die(void);
static uint16_t dm_my_nonce, dm_peer_nonce;
static int      dm_sent_hello, dm_got_hello, dm_started;
static float    dm_hello_t;
static uint32_t dm_seed;
static float    dm_send_t, dm_rx_age, dm_dead_t, dm_ramcd;
static int      dm_frags, dm_peer_frags, dm_end;   /* end: 1 win 2 lose 3 link lost */
static float    rp_x, rp_z, rp_yaw, rp_dx2, rp_dz2, rp_anim, rp_fire_t;
static int      rp_mode, rp_cartype, rp_moving, rp_hp;
static float    dm_spawnx, dm_spawnz;
static float    g_dmpkt[NPICK];              /* pickup respawn timers */
static uint8_t  dm_msg[128]; static int dm_msg_len;  /* holds a 65-byte 'm' chunk or a 'V' traffic list */
static int      dm_auth;                     /* this unit simulates the shared traffic */
static int      dm_peer_car = -1;            /* authority: the car slot the PEER is driving (exclude from 'V') */
static float    dm_tx[NCAR], dm_tz[NCAR], dm_tyaw2[NCAR];  /* peer: streamed traffic targets (lerped) */
static float    dm_tvx[NCAR], dm_tvz[NCAR];                 /* peer: velocity estimated from 'V' deltas
                                                              (so a jacked car keeps its momentum) */
static uint8_t  dm_tpresent[NCAR];           /* peer: was this slot in the last 'V'? */
static float    dm_vsend_t;                  /* authority: traffic-broadcast cadence */
/* MAP TRANSFER (fixes cross-arch desync): citygen uses sinf/atan2f for rivers,
 * which don't match bit-for-bit between the x86 Studio and the ARM device — so
 * the same seed made DIFFERENT cities. Instead the nonce winner GENERATES the
 * city, then STREAMS the raw g_city bytes to the peer in 0xA5 'm' chunks; both
 * end up byte-identical. The integer spawn/car/cache RNG (irand) is deterministic
 * given the identical map, so only the map itself needs sending. */
#define CITY_BYTES (MAPW*MAPH)
#define DM_CHUNK   60
static int      dm_phase;                    /* 0 handshake · 1 map xfer · 2 playing */
static int      dm_map_pos;                  /* authority: g_city bytes queued */
static int      dm_map_recv;                 /* peer: g_city bytes written */
static uint8_t  dm_out[68]; static int dm_out_len, dm_out_off;   /* pending outbound chunk */
/* map-transfer integrity: the authority streams, then sends its city hash ('Z');
 * the peer verifies and acks ('Y') or asks for a full re-stream ('R'). Chunks can
 * no longer be silently lost (link-ring pressure, transport hiccups) — a bad map
 * is re-sent until the hashes agree, and NOBODY plays on a corrupt city. */
static uint32_t dm_peer_hash; static int dm_got_hash, dm_map_acked; static float dm_verify_t;
/* authority->peer WORLD PLACEMENT ('W' cars+spawns, 'w' caches): the peer never
 * trusts its own generation of gameplay objects — determinism-by-discipline
 * broke once (RNG fork -> phantom cars) and silently breaks again the moment
 * anyone adds a transcendental to placement. The authority's world is the world. */
static int dm_w_done, dm_wc_done;           /* peer: world msgs applied */
static int dm_world_acked; static float dm_world_t;  /* authority: peer confirmed 'W'+'w' */
static float dm_rreq_t; static int dm_rreq_mark;      /* peer: 'R' repeat until bytes resume */
#ifdef MOTE_HOST
static void dm_world_hash_log(const char *tag);
#endif
static uint32_t dm_city_fnv(void){ uint32_t h=2166136261u;
    for (int i=0;i<CITY_BYTES;i++){ h^=g_city[i]; h*=16777619u; } return h; }
static int dm_flush_out(void){              /* 1 = fully drained (FIFO took it all) */
    while (dm_out_off < dm_out_len){
        int w = mote->link_send(dm_out+dm_out_off, dm_out_len-dm_out_off);
        if (w<=0) return 0;                  /* FIFO full — resume next frame */
        dm_out_off += w;
    }
    return 1;
}
static void dm_send2(uint8_t t, uint8_t v){ uint8_t m[3]={0xA5,t,v}; mote->link_send(m,3); }
/* Authority streams every ambient car (not either player's) so both units see the
 * SAME traffic. Entry: idx(bit7=wrecked) x16 z16 yaw8 — 6 bytes. Position-scaled ×8. */
static void dm_send_traffic(void){
    uint8_t m[3+NCAR*6]; int n=0, o=3;
    for (int i=0;i<NCAR;i++){
        if (!cars[i].alive || i==player.car || i==dm_peer_car) continue;
        int16_t xi=(int16_t)(cars[i].x*8.0f), zi=(int16_t)(cars[i].z*8.0f);
        m[o++]=(uint8_t)(i | (cars[i].wrecked?0x80:0));
        m[o++]=(uint8_t)xi; m[o++]=(uint8_t)(xi>>8);
        m[o++]=(uint8_t)zi; m[o++]=(uint8_t)(zi>>8);
        m[o++]=(uint8_t)(int8_t)(cars[i].yaw*40.5845f);
        n++;
    }
    m[0]=0xA5; m[1]='V'; m[2]=(uint8_t)n;
    mote->link_send(m, o);
}
static void dm_send1(uint8_t t){ uint8_t m[2]={0xA5,t}; mote->link_send(m,2); }

/*                                     fist  pistol smg   shotgun flame rocket uzi   minigun grenade */
static const float W_CD[NWEAP]     = { 0.32f, 0.30f, 0.085f, 0.62f, 0.055f, 1.15f, 0.05f, 0.03f, 0.9f };
static const int   W_PELLETS[NWEAP]= { 0,     1,     1,      5,     0,      0,     1,     2,     0    };
static const float W_SPREAD[NWEAP] = { 0,     0.015f,0.06f,  0.26f, 0,      0,     0.11f, 0.15f, 0    };
static const char *WNAME[NWEAP]    = { "FIST","PISTOL","SMG","SHOTGUN","FLAMER","ROCKET","UZI","MINIGUN","GRENADE" };

/* streamed engine drone (saw + sub-octave + noise), pitched to car speed —
 * adapted from motokart. g_eng_f/g_eng_a are set each frame from g_update. */
static volatile float g_eng_f = 32.0f, g_eng_a = 0.0f;
static float g_eng_ph, g_eng_ph2, g_eng_nz; static uint32_t g_eng_rng = 0x2ab3c1u;
static int engine_fill(int16_t *out, int n) {
    float inc = g_eng_f/22050.0f, inc2 = inc*0.5f, a = g_eng_a;
    for (int i=0;i<n;i++){
        g_eng_ph += inc;   if(g_eng_ph>=1)g_eng_ph-=1;
        g_eng_ph2+= inc2;  if(g_eng_ph2>=1)g_eng_ph2-=1;
        float saw=g_eng_ph*2-1, saw2=g_eng_ph2*2-1;
        g_eng_rng=g_eng_rng*1664525u+1013904223u;
        float nz=((int)(g_eng_rng>>9)&0x3FFF)/8192.0f-1.0f;
        g_eng_nz+=(nz-g_eng_nz)*0.5f;
        float v=saw*0.5f+saw2*0.32f+g_eng_nz*0.18f;
        int s=(int)(v*a*8000.0f); if(s>32767)s=32767; else if(s<-32768)s=-32768;
        out[i]=(int16_t)s;
    }
    return n;
}

static void reset_game(void);

static void g_init(void) {
    int v47 = (mote->abi_version>=47 && mote->ui_font);
    g_fmed   = v47 ? mote->ui_font(MOTE_FONT_MED)   : 0;   /* 1.5x  labels/standard */
    g_fread  = v47 ? mote->ui_font(MOTE_FONT_READ)  : 0;   /* 1.66x headers/banners */
    g_flarge = v47 ? mote->ui_font(MOTE_FONT_LARGE) : 0;   /* 2x    big impact words */
    if (mote->audio_set_stream) mote->audio_set_stream(engine_fill);
    /* Sky + sun now come from the day/night palette; seed them before the first
     * frame so nothing renders against an unset background. The gradient needs
     * set_background_cb (ABI v26); without it tod_advance's
     * scene_set_background fallback leaves a flat sky that still cycles. */
    tod_advance(0.0f);
    if (mote->set_background_cb) mote->set_background_cb(sky_band);
    cam_focal = 64.0f / tanf(FOV * (3.14159265f / 180.0f) * 0.5f);
    build_vstats();
    for (int s = 0; s < GTA3_SIL_N; s++) {
        gta3_veh_build(&g_veh[s], s);
        g_veh_bx[s] = g_veh[s].bv[1].x;
        g_veh_cx[s] = g_veh[s].cv[1].x;
        g_veh_wx[s] = g_veh[s].wv[1].x;
        /* gta3_box corner order: y1 (the roof) is at 2,3,6,7; z0 at 0..3, z1 at 4..7. */
        g_veh_cy[s]  = g_veh[s].cv[3].y;
        g_veh_cz0[s] = g_veh[s].cv[0].z;
        g_veh_cz1[s] = g_veh[s].cv[4].z;
    }
    build_ground();
    build_quad();
    build_turret();
    build_buildings();
    build_garages();
    if (mote->load){
        int b[3]={0,0,1}; int got = mote->load(0,b,sizeof b);
        /* Two ints is the old blob: record only, sound stays on. Three is the
         * current one, whose third int is the flags word. */
        if (got >= (int)(2*sizeof(int)) && b[0]==SAVE0_MAGIC){
            best_cash = b[1];
            if (got >= (int)(3*sizeof(int))) {
                g_sound_on = (uint8_t)(b[2] & 1);
                g_slot     = (uint8_t)((b[2] >> 1) & 3);
                if (g_slot >= NSAVE_SLOT) g_slot = 0;
            }
        }
    }
    reset_game();
    g_state = ST_TITLE;
}

/* World-space cone test for a tile centre. Replaces the old screen-space test,
 * which was written for a camera pointing straight down. */
static int tile_visible_r(int x, int z, float y, float radius) {
    return gta3_view_tile(&g_view, x*TILE+TILE*0.5f, y, z*TILE+TILE*0.5f,
                          radius, TILE);
}

/* thin flat quad on the road surface, for lane paint */
static void paint_quad(float x0, float z0, float x1, float z1, uint16_t col) {
    mote->scene_add_tri(v3(x0,0.03f,z0), v3(x1,0.03f,z0), v3(x1,0.03f,z1), col, 0);
    mote->scene_add_tri(v3(x0,0.03f,z0), v3(x1,0.03f,z1), v3(x0,0.03f,z1), col, 0);
}
/* a lane line along X (E-W) at world z=zc; dashed unless solid */
static void line_x(float xa, float xb, float zc, uint16_t col, int solid) {
    float w = 0.20f;
    if (solid) { paint_quad(xa, zc-w, xb, zc+w, col); return; }
    float x0 = floorf(xa/2.0f)*2.0f;                 /* dash phase in WORLD space: tiles align */
    for (float x=x0; x<xb-0.05f; x+=2.2f){ float a=x<xa?xa:x, b=x+1.25f<xb?x+1.25f:xb;
        if (b>a) paint_quad(a, zc-w, b, zc+w, col); }
}
static void line_z(float za, float zb, float xc, uint16_t col, int solid) {
    float w = 0.20f;
    if (solid) { paint_quad(xc-w, za, xc+w, zb, col); return; }
    float z0 = floorf(za/2.0f)*2.0f;
    for (float z=z0; z<zb-0.05f; z+=2.2f){ float a=z<za?za:z, b=z+1.25f<zb?z+1.25f:zb;
        if (b>a) paint_quad(xc-w, a, xc+w, b, col); }
}

static void road_markings(int x, int z) {
    int o,p,span; corridor_info(x, z, &o, &p, &span);
    if (!o) return;
    float x0=x*TILE, z0=z*TILE;
    uint16_t white = MOTE_RGB565(210,210,218);
    uint16_t yel   = MOTE_RGB565(210,210,218);   /* median: double WHITE (user pref) */
    if (o == 1) {                                   /* horizontal corridor: E-W lanes */
        if (p > 0 && !zebra_at(x,z)) {              /* lines break at zebra crossings */
            int median = (p == span/2);
            if (median){
                if (span <= 2)                      /* minor street: single dashed centre */
                    line_x(x0, x0+TILE, z0, white, 0);
                else {                              /* arterial: double solid median */
                    line_x(x0, x0+TILE, z0-0.22f, yel, 1);
                    line_x(x0, x0+TILE, z0+0.22f, yel, 1);
                }
            }
            else line_x(x0, x0+TILE, z0, white, 0);               /* dashed lane separator */
        }
        /* ZEBRA across the junction FACE (full road width, this tile paints its
         * slice) with the STOP BAR behind it on the inbound half. */
        if (zebra_at(x,z)) {
            float zc=(z-p+span*0.5f)*TILE, half=span*TILE*0.5f;
            int oo,pp2,ss2;
            uint16_t zeb = MOTE_RGB565(214,214,222);
            if (is_roadlike(x+1,z)){ corridor_info(x+1,z,&oo,&pp2,&ss2);
                if (oo==3){
                    for (float zz=z0+0.18f; zz<z0+TILE-0.4f; zz+=1.05f)
                        paint_quad(x0+TILE-1.85f, zz, x0+TILE-0.30f, zz+0.62f, zeb);
                    float za=zc>z0?zc:z0, zb=(zc+half)<z0+TILE?(zc+half):z0+TILE;
                    if (zb>za+0.05f) paint_quad(x0+TILE-2.65f, za+0.10f, x0+TILE-2.10f, zb-0.10f, white);
                } }
            if (is_roadlike(x-1,z)){ corridor_info(x-1,z,&oo,&pp2,&ss2);
                if (oo==3){
                    for (float zz=z0+0.18f; zz<z0+TILE-0.4f; zz+=1.05f)
                        paint_quad(x0+0.30f, zz, x0+1.85f, zz+0.62f, zeb);
                    float za=(zc-half)>z0?(zc-half):z0, zb=zc<z0+TILE?zc:z0+TILE;
                    if (zb>za+0.05f) paint_quad(x0+2.10f, za+0.10f, x0+2.65f, zb-0.10f, white);
                } }
        }
    } else if (o == 2) {                            /* vertical corridor: N-S lanes */
        if (p > 0 && !zebra_at(x,z)) {
            int median = (p == span/2);
            if (median){
                if (span <= 2)
                    line_z(z0, z0+TILE, x0, white, 0);
                else {
                    line_z(z0, z0+TILE, x0-0.22f, yel, 1);
                    line_z(z0, z0+TILE, x0+0.22f, yel, 1);
                }
            }
            else line_z(z0, z0+TILE, x0, white, 0);
        }
        /* zebra + stop bar, vertical roads (southbound keeps WEST) */
        if (zebra_at(x,z)) {
            float xc=(x-p+span*0.5f)*TILE, half=span*TILE*0.5f;
            int oo,pp2,ss2;
            uint16_t zeb = MOTE_RGB565(214,214,222);
            if (is_roadlike(x,z+1)){ corridor_info(x,z+1,&oo,&pp2,&ss2);
                if (oo==3){
                    for (float xx=x0+0.18f; xx<x0+TILE-0.4f; xx+=1.05f)
                        paint_quad(xx, z0+TILE-1.85f, xx+0.62f, z0+TILE-0.30f, zeb);
                    float xa=(xc-half)>x0?(xc-half):x0, xb=xc<x0+TILE?xc:x0+TILE;
                    if (xb>xa+0.05f) paint_quad(xa+0.10f, z0+TILE-2.65f, xb-0.10f, z0+TILE-2.10f, white);
                } }
            if (is_roadlike(x,z-1)){ corridor_info(x,z-1,&oo,&pp2,&ss2);
                if (oo==3){
                    for (float xx=x0+0.18f; xx<x0+TILE-0.4f; xx+=1.05f)
                        paint_quad(xx, z0+0.30f, xx+0.62f, z0+1.85f, zeb);
                    float xa=xc>x0?xc:x0, xb=(xc+half)<x0+TILE?(xc+half):x0+TILE;
                    if (xb>xa+0.05f) paint_quad(xa+0.10f, z0+2.10f, xb-0.10f, z0+2.65f, white);
                } }
        }
    } else {                                        /* junction complex: bend, T, or cross? */
        /* orient==3 covers plain BENDS too. Count the APPROACH ROADS: scan out through
         * the junction block each way until a corridor with the matching orientation is
         * reached. A bend connects 2 roads — only a real T (3) or cross (4) gets the
         * junction markings; corners stay clean asphalt. */
        static const int DX[4]={0,1,0,-1}, DZ[4]={-1,0,1,0};   /* N E S W */
        int appr=0, hasH=0, hasV=0; float zm=0, xm=0, sxs=0, szs=0; int spH=0, spV=0;
        for (int k=0;k<4;k++){
            for (int s=1;s<=ROADW+2;s++){
                int xx=x+DX[k]*s, zz=z+DZ[k]*s, oo,pp2,ss2;
                if (!is_roadlike(xx,zz)) break;                 /* left the road */
                corridor_info(xx,zz,&oo,&pp2,&ss2);
                if (oo==3) continue;                            /* still inside the block */
                if (oo == ((k==0||k==2)?2:1)){                  /* corridor heading our way */
                    appr++;
                    if (k==1||k==3){ hasH=1; sxs=(k==1)?1.0f:-1.0f;   /* E/W: horizontal road */
                                     zm=(zz-pp2+ss2*0.5f)*TILE; spH=ss2; }
                    else            { hasV=1; szs=(k==2)?1.0f:-1.0f;   /* N/S: vertical road */
                                     xm=(xx-pp2+ss2*0.5f)*TILE; spV=ss2; }
                }
                break;
            }
        }
        /* BOX JUNCTION: a big junction block (3x3+ of junction cells) gets
         * yellow cross-hatch with a solid border — drivers read it as
         * "keep clear", and the huge arterial crossings stop being bare
         * asphalt fields. Painted per-tile with world-phased diagonals so
         * the pattern flows unbroken across the whole box. */
        {
            int exL=0,exR=0,exU=0,exD=0, oj,pj,sj;
            #define JCELL(ax,az) (is_roadlike(ax,az) && (corridor_info(ax,az,&oj,&pj,&sj), oj==3))
            while (exL<ROADW+2 && JCELL(x-1-exL,z)) exL++;
            while (exR<ROADW+2 && JCELL(x+1+exR,z)) exR++;
            while (exU<ROADW+2 && JCELL(x,z-1-exU)) exU++;
            while (exD<ROADW+2 && JCELL(x,z+1+exD)) exD++;
            int ew=exL+exR+1, eh=exU+exD+1;
            if (ew>=3 && eh>=3 && appr>=3){                  /* real multi-lane boxes only */
                uint16_t ybox = MOTE_RGB565(210,180,70);
                /* clean YELLOW BORDER around the box (no interior hatch) */
                if (!JCELL(x-1,z)) line_z(z0-0.05f, z0+TILE+0.05f, x0+0.30f, ybox, 1);
                if (!JCELL(x+1,z)) line_z(z0-0.05f, z0+TILE+0.05f, x0+TILE-0.30f, ybox, 1);
                if (!JCELL(x,z-1)) line_x(x0-0.05f, x0+TILE+0.05f, z0+0.30f, ybox, 1);
                if (!JCELL(x,z+1)) line_x(x0-0.05f, x0+TILE+0.05f, z0+TILE-0.30f, ybox, 1);
            }
            #undef JCELL
        }
        if (appr < 3){
            /* BEND: curved DOUBLE-YELLOW median — a quarter arc tangent to both roads'
             * median lines (centre offset R from each), drawn only inside this tile so
             * the full curve emerges across the bend block. */
            if (hasH && hasV){
                uint16_t yel = MOTE_RGB565(210,210,218);   /* median arc: white */
                float R = ((spH<spV?spH:spV)*TILE)*0.5f;
                float Cx = xm + sxs*R, Cz = zm + szs*R;
                float v1x=0, v1z=-szs, v2x=-sxs, v2z=0;         /* toward the two tangent points */
                for (int rr=0; rr<2; rr++){
                    float Ra = R + (rr? 0.22f : -0.22f);        /* double line */
                    for (int t=0; t<=22; t++){
                        float u=(float)t/22.0f;
                        float vx=(1-u)*v1x+u*v2x, vz=(1-u)*v1z+u*v2z;
                        float il=1.0f/sqrtf(vx*vx+vz*vz); vx*=il; vz*=il;
                        float pxw=Cx+vx*Ra, pzw=Cz+vz*Ra;
                        if (pxw>=x0 && pxw<x0+TILE && pzw>=z0 && pzw<z0+TILE)
                            paint_quad(pxw-0.20f, pzw-0.20f, pxw+0.20f, pzw+0.20f, yel);
                    }
                }
                /* roads of DIFFERENT widths: the arc (radius = narrower road) ends short of
                 * the wider road's corridor — bridge each tangent point to the corridor
                 * edge with straight median segments so the lines connect without a gap. */
                { float xEdge = xm + sxs*(spV*TILE*0.5f);       /* where the straight medians resume */
                  float zEdge = zm + szs*(spH*TILE*0.5f);
                  for (int rr=0; rr<2; rr++){
                    float off = rr? 0.22f : -0.22f;
                    float a = Cx<xEdge?Cx:xEdge, b = Cx<xEdge?xEdge:Cx;
                    float ca = a>x0?a:x0, cb = b<x0+TILE?b:x0+TILE;
                    if (cb>ca+0.02f) line_x(ca, cb, zm+off, yel, 1);
                    a = Cz<zEdge?Cz:zEdge; b = Cz<zEdge?zEdge:Cz;
                    ca = a>z0?a:z0; cb = b<z0+TILE?b:z0+TILE;
                    if (cb>ca+0.02f) line_z(ca, cb, xm+off, yel, 1);
                  }
                }
            }
            return;                                             /* no crosswalks on a bend */
        }
        /* (zebras now live on the corridor tiles facing the junction) */
    }
}

/* A flat haze-coloured skirt under the world, out to roughly VIEW_BLD_R, so an
 * open sightline (a plaza, a junction, a lake crossing) shows ground fading
 * toward the background instead of a hard one-row cut once real ground tiles
 * run out at VIEW_GROUND_R. Two triangles via scene_add_tri, which is
 * DOUBLE-SIDED (drawn regardless of winding) — unlike scene_add_object, so
 * it is immune to the winding trap g_hmesh needed fixing for (g_quadShade,
 * the same trap's other victim, was removed in Task 7 with its only caller).
 * Slightly below y=0 so real ground tiles always win the depth test.
 *
 * Colour: roughly the MIDPOINT of haze_tint's ramp, not its t=1 (background)
 * end. At exactly the background colour the skirt is a visual no-op — those
 * pixels already rendered as background when nothing was there, so filling
 * them with same-coloured geometry changes the depth buffer but not the
 * image. The actual defect was the HARD CUT from textured ground straight to
 * background; a same-coloured skirt can't soften that, it just backfills one
 * side with the other's colour. A mid-tone between haze_tint's near (60,64,78)
 * and far (24,26,32) values gives the cut somewhere to land that isn't the
 * sky itself: ground -> hazy ground -> sky. */
/* Water shimmer: animated specular flecks on visible water tiles, a deterministic
 * per-tile phase so each fleck twinkles independently.
 *
 * These are scene_add_point, NOT overlay dots. As overlay drawing they had no
 * depth test and painted straight onto the framebuffer after the 3D pass, so
 * sparkles on water BEHIND a building drew over the building — the same defect
 * the bullet tracers had before they moved to scene_add_line. Points are
 * depth-TESTED against the scene (they just don't write depth), which is
 * exactly what a specular fleck wants.
 *
 * Gated on the view cone and capped: the scan is 21x21 tiles and a lake fills
 * most of them, which would otherwise spend the whole point pool on water
 * that is behind the camera. */
#define WATER_FLECKS_MAX 56
/* Sun elevation as a sine of the clock: -1 at midnight, 0 at dawn, +1 at noon,
 * 0 at dusk. Separate from g_sun_dir, whose four TOD[] keyframes are SHADING
 * directions with a positive y at every hour — asking them whether the sun is
 * up gives "always". The sky disc and the car lamps both ask this instead. */
static float sun_elev(void) { return sinf(6.2831853f * (g_tod - 0.25f)); }

/* Lay the stars out for this frame.
 *
 * Each star owns a fixed azimuth and elevation derived from its index, so the
 * field is stable: turn around and the same stars come back. Only the screen
 * projection moves. Azimuth is measured against the camera's heading and
 * mapped across the frame by the same focal length the 3D pass uses, so they
 * pan at the right rate instead of sliding.
 *
 * Brightness follows sun elevation rather than a hard night flag, so they fade
 * up through dusk instead of switching on. */
static void stars_update(Vec3 fwd) {
    float e = sun_elev();
    float lit = (0.10f - e) * 4.0f;              /* fully out well after sunset */
    if (lit <= 0.0f) { g_star_lit = 0; return; }
    if (lit > 1.0f) lit = 1.0f;
    g_star_lit = (uint8_t)(lit * 255.0f);

    float cam_az = atan2f(fwd.x, fwd.z);
    for (int i = 0; i < STARS; i++) {
        unsigned h = ((unsigned)i * 2654435761u) ^ 0x9e3779b9u;
        float az   = (float)(h & 1023) * (6.2831853f / 1024.0f);
        float elev = 0.06f + (float)((h >> 10) & 255) * (0.55f / 255.0f);
        float rel  = az - cam_az;
        while (rel >  3.1415927f) rel -= 6.2831853f;
        while (rel < -3.1415927f) rel += 6.2831853f;
        if (rel < -1.2f || rel > 1.2f) { g_star_y[i] = 255; continue; }   /* behind: park off-band */
        int sx = (int)(MOTE_FB_W * 0.5f + cam_focal * tanf(rel));
        int sy = (int)((1.0f - elev / 0.61f) * (float)SKY_HOR_Y);
        if (sx < 0 || sx >= MOTE_FB_W || sy < 0 || sy >= SKY_HOR_Y) { g_star_y[i] = 255; continue; }
        g_star_x[i] = (uint8_t)sx; g_star_y[i] = (uint8_t)sy;
    }
}

/* The sun (or, once it has set, the moon) as a single screen-facing disc.
 *
 * Until now the "sun" was only a lighting direction — the cycle changed how
 * things were lit with nothing in the sky to explain why.
 *
 * The disc does NOT ride g_sun_dir. Those four TOD[] vectors are shading
 * directions, picked so faces are lit pleasantly at each keyframe, and every
 * one of them has a positive y — midnight's is (0.30, 0.15, -0.30). Driving
 * the disc from them means the sun never sets and the moon never appears;
 * measured, that is exactly what happened. So the disc gets its own arc from
 * g_tod: azimuth sweeps a full turn per day, elevation is a sine that is -1 at
 * midnight, 0 at dawn, +1 at noon, 0 at dusk. Lighting keeps g_sun_dir
 * untouched. Both run off g_tod, so they stay in step without a second clock.
 *
 * Placed far out and depth-TESTED (scene_add_disc does not write depth), so
 * buildings occlude it exactly as they should. Below the horizon the sun is
 * replaced by the moon at the antipode — up all night, setting at dawn. */
#define SKY_BODY_D 300.0f
#define SKY_BODY_ELEV 0.075f   /* ~4.3 deg: inside the ~5.5 deg the camera can see */
static void draw_sky_body(void) {
    float az   = 6.2831853f * g_tod;
    float elev = sun_elev();
    int night = (elev < 0.0f);
    if (night) { elev = -elev; az += 3.1415927f; }
    if (elev < 0.02f) return;                 /* right at the horizon: skip the sliver */

    /* Compress elevation into the sliver of sky this camera can actually see.
     *
     * The chase camera pitches about 22 degrees DOWN (eye at 2.4 m looking at
     * GTA3_CAM_LOOK_Y 1.2 m about 3 m ahead) and has a 55 degree vertical
     * field, so the top of the frame sits near +5.5 degrees of elevation. A
     * true noon sun at 67 degrees projects roughly 70 px ABOVE the screen and
     * is never seen; measured, before this was added. Elevation is therefore
     * scaled from 0..90 degrees into 0..SKY_BODY_ELEV. Azimuth is untouched,
     * so the disc still tracks across the sky and still rises and sets, just
     * within a band that is on screen. */
    float de = asinf(elev > 1.0f ? 1.0f : elev) * (SKY_BODY_ELEV / 1.5707963f);
    float ce = cosf(de);
    Vec3 d = v3(sinf(az) * ce, sinf(de), cosf(az) * ce);

    Vec3 p = v3(cam_pos.x + d.x * SKY_BODY_D,
                cam_pos.y + d.y * SKY_BODY_D,
                cam_pos.z + d.z * SKY_BODY_D);
    if (night) {
        mote->scene_add_disc(p, 12.0f, MOTE_RGB565(226, 230, 238));
    } else {
        /* Low sun reddens toward the horizon colour it is painting anyway, so
         * the disc and the sky agree at dawn and dusk instead of a white dot
         * sitting on an orange band.
         *
         * A HALO and a bright core, because the clouds sit in the same band of
         * sky at a similar size and the plain warm disc was being read as one
         * of them. The halo is the warm tone at the old radius; the core is a
         * smaller, much brighter disc on top of it, which nothing else in the
         * sky has. */
        float lift = elev > 0.45f ? 1.0f : elev / 0.45f;
        Rgb warm = { 250, 180, 90 };
        Rgb core = { 255, 246, 214 };
        Rgb glow = rgb_lerp(g_sky_hor, warm, 0.55f + 0.45f * lift);
        mote->scene_add_disc(p, 19.0f, rgb565(glow));
        mote->scene_add_disc(p, 11.0f, rgb565(rgb_lerp(glow, core, 0.75f)));
    }
}

/* Daytime clouds: 7 puffs, two discs each, with NO state at all.
 *
 * Each puff's bearing and height come from a hash of its index, so the field
 * is stable the way the star field is; g_tod adds a slow eastward drift, which
 * is the only thing that moves. Nothing is stored, so this costs zero RAM and
 * 14 discs in the FX pass.
 *
 * Elevation is confined to the same narrow band the sun disc uses. The chase
 * camera pitches about 22 degrees down and the top of the frame sits near
 * +5.5 degrees, so a cloud at a realistic height is simply above the screen.
 * 0.020..0.075 rad keeps them in the strip of sky that is actually drawn.
 *
 * They are discs, which are depth-TESTED but do not write depth, so a building
 * in front covers them and they never paint over the skyline.
 *
 * Only in daylight: they fade in with the sun between elevation 0.10 and 0.30
 * and are gone at night, when the star field has the sky instead. */
#define CLOUDS   7
#define CLOUD_D  260.0f
static void draw_clouds(void) {
    float e = sun_elev();
    if (e < 0.10f) return;
    float fade = (e < 0.30f) ? (e - 0.10f) / 0.20f : 1.0f;
    /* Off-white, not white. The sun is the brightest thing in the sky and it
     * has to stay that way — a pure white puff the same size as the disc is
     * what made the two hard to tell apart. */
    Rgb pale = { 226, 230, 240 };
    uint16_t col = rgb565(rgb_lerp(g_sky_hor, pale, 0.30f + 0.55f * fade));
    float sun_az = 6.2831853f * g_tod;
    for (int i = 0; i < CLOUDS; i++) {
        unsigned h = ((unsigned)i * 2654435761u) ^ 0x85ebca6bu;
        float az = (float)(h & 1023) * (6.2831853f / 1024.0f) + g_tod * 1.7f;
        /* Nothing within about 12 degrees of the sun's bearing. Two round pale
         * things side by side in the same patch of sky is the confusion, and
         * the cheapest fix is to not put them there. */
        float rel = az - sun_az;
        while (rel >  3.1415927f) rel -= 6.2831853f;
        while (rel < -3.1415927f) rel += 6.2831853f;
        if (fabsf(rel) < 0.21f) continue;
        float de = 0.020f + (float)((h >> 10) & 255) * (0.055f / 255.0f);
        float ce = cosf(de);
        Vec3 d = v3(sinf(az) * ce, sinf(de), cosf(az) * ce);
        Vec3 p = v3(cam_pos.x + d.x * CLOUD_D,
                    cam_pos.y + d.y * CLOUD_D,
                    cam_pos.z + d.z * CLOUD_D);
        float ux = cosf(az), uz = -sinf(az);          /* horizontal, across the view */

        /* FLAT BOTTOM, ROUND TOP, and a different shape every puff.
         *
         * Two discs with a quad UNDER them was still a pair of circles: the
         * quad only reached the disc centres, so a whole disc-radius of round
         * hung below the flat part and the eye read a ball.
         *
         * The lobes now sit ON the base line, and the skirt quad is drawn SIX
         * METRES NEARER than they are. Flat triangles write depth and the FX
         * discs are depth-TESTED against them, so the quad hides the lower
         * half of every lobe — a straight edge underneath with only the tops
         * showing. That is a real flat bottom rather than a suggestion of one.
         *
         * Two or three lobes, each a different radius and spacing off the same
         * hash, so no two clouds are the same shape. */
        float r = 9.0f + (float)((h >> 18) & 7);
        int nlobe = 2 + (int)((h >> 23) & 1);
        float lo = 1e9f, hi = -1e9f;
        for (int k = 0; k < nlobe; k++) {
            float off = ((float)k - (nlobe - 1) * 0.5f) * r * 1.05f;
            float rk  = r * (0.60f + 0.40f * (float)((h >> (3 * k + 4)) & 7) / 7.0f);
            mote->scene_add_disc(v3(p.x + ux * off, p.y, p.z + uz * off), rk, col);
            if (off - rk < lo) lo = off - rk;
            if (off + rk > hi) hi = off + rk;
        }
        /* the skirt: nearer than the lobes, so it wins the depth test */
        float sd = (CLOUD_D - 6.0f) / CLOUD_D;
        Vec3 q = v3(cam_pos.x + d.x * CLOUD_D * sd,
                    cam_pos.y + d.y * CLOUD_D * sd,
                    cam_pos.z + d.z * CLOUD_D * sd);
        float base = q.y - r * 0.85f;
        float x0 = q.x + ux * lo, z0 = q.z + uz * lo;
        float x1 = q.x + ux * hi, z1 = q.z + uz * hi;
        mote->scene_add_tri(v3(x0, base, z0), v3(x1, base, z1), v3(x1, q.y, z1), col, 0);
        mote->scene_add_tri(v3(x0, base, z0), v3(x1, q.y, z1), v3(x0, q.y, z0), col, 0);
    }
}

/* Traffic-light heads at the junctions around the player.
 *
 * Walks OUTWARD in rings from the camera tile and stops at LIGHTS_MAX heads,
 * so the ones that get dropped when the budget runs out are always the far
 * ones. Nothing is stored: corridor_info() finds the junctions and
 * light_state() colours them, both from the map and one clock.
 *
 * Two heads per junction, one per axis, set back toward the approach they
 * govern so you can tell which light is yours. A dark backing disc behind each
 * lamp gives it a housing — without it a bare coloured dot reads as a pickup. */
/* Lights are small and cheap now, so they stay visible well down the street
 * rather than popping in at the last moment. Buildings draw to VIEW_BLD_R
 * (112 m), which is what bounds this: past that there is nothing to occlude
 * them and a light would hang in the haze. */
#define LIGHTS_MAX   12      /* crossings drawn per frame */
/* 7 tiles, not 4. At one light per junction TILE the near ring was already
 * saturated; at one per intersection the nearest crossing is often further than
 * 16 m away — measured 47 m from one downtown vantage — and no light drew at
 * all. 7 tiles is 28 m, still inside reliable building range. */
#define LIGHT_RING   16      /* tiles (64 m) */
#define LIGHT_H      3.0f    /* head height, metres */

/* Traffic-light heads at the junctions around the player.
 *
 * Drawn as flat triangles, NOT discs, for two reasons. A disc is a bare
 * coloured dot with nothing holding it up, which read as floating; a head on a
 * post reads as a traffic light. And discs raster in the FX pass, which tests
 * depth but only against what was actually drawn — the banded building cull
 * can drop a building, and the light then shows through the hole where it
 * should have been. Flat tris raster BEFORE the textured building pass and
 * write depth, so a building drawn afterwards paints over them regardless.
 *
 * Kept small and few on purpose: a 128 px panel has no room to spare, so the
 * head is 0.34 m and only the nearest LIGHTS_MAX junctions inside LIGHT_RING
 * tiles get one. The ring walk goes outward, so what drops is always the far
 * ones.
 *
 * Still no state: corridor_info() finds the junctions and light_state()
 * colours them, both from the map and one clock.
 *
 * Head and post face ALONG the axis they govern, so the light you can read is
 * the one controlling the approach you are on. */
/* Railings on the BIG bridges, and benches in the parks.
 *
 * Both ride the same outward ring walk the traffic lights use, and both are
 * flat triangles so they raster before the building pass and are occluded by
 * it properly.
 *
 * A railing only goes on a bridge tile whose water crossing is genuinely long
 * — LONG_SPAN tiles or more measured along the span — so the little connectors
 * over inlets stay bare, which is what you asked for. The run is measured from
 * the tile outward in both directions along the crossing axis, which costs a
 * couple of tile lookups and needs nothing stored.
 *
 * A bench is a seat quad and a back quad, 4 triangles, on park grass that the
 * scenery pass left EMPTY — the same hash it uses to decide where trees go, so
 * a bench is never planted inside a canopy. */
#define LONG_SPAN   6      /* bridge tiles across the water before it gets railings */
#define DETAIL_RING 9      /* tiles: how far out benches and railings are drawn */
#define DETAIL_MAX  16     /* pieces per frame: at 4 tris each this is the
                            * cap that kept the worst scene under 750 of 850 */

/* Street furniture that stands UP: lamps and bus stops.
 *
 * Their own ring and their own cap, not the bench budget. They are tall and
 * thin, so they read from much further away than a bench does and want a
 * longer range — but they are also on nearly every pavement tile, so sharing
 * DETAIL_MAX would starve the benches and railings entirely.
 *
 * Placement is from the tile coordinate, not a hash: lamps go at a fixed
 * spacing along a kerb, which is what makes a line of them read as street
 * lighting rather than as scattered poles. A bus stop replaces a lamp at a
 * much rarer interval, so the two never collide.
 *
 * Nothing is stored. A lamp is four triangles (post plus head) and a stop is
 * six (post, sign, and the sign's back).
 *
 * Height: the head sits at 4.2 m, which the chase camera loses off the top of
 * the frame inside about 19 m in a car — but the POST runs to the ground, so
 * what you lose up close is the lamp, not the object. That is the same trade
 * the traffic lights make and it reads fine.
 */
#define LAMP_RING   12      /* tiles (48 m) */
#define LAMP_MAX    14      /* posts per frame */
#define LAMP_EVERY   5      /* tiles between lamps along a kerb */
#define STOP_EVERY  35      /* and between bus stops */
/* Puddles ride the same walk. They are on ROAD tiles, which this pass skips
 * anyway, so they cost one extra branch and no second scan. Two triangles
 * each, placed and sized from the tile hash, and only while it is actually
 * wet — they fade in with g_wet and are gone the moment the road dries, which
 * is the whole point of them. */
#define PUDDLE_MAX  10
static void draw_street_lamps(void) {
    int cx = (int)(view_x / TILE), cz = (int)(view_z / TILE), n = 0, np = 0;
    int night = (sun_elev() < 0.06f);
    int wet = (g_wet > 0.25f);
    uint16_t pud = rgb565(rgb_lerp(g_haze_near, (Rgb){70,96,124}, 0.55f + 0.35f*g_wet));
    const uint16_t POST = MOTE_RGB565(96, 98,108);
    const uint16_t HEAD = night ? MOTE_RGB565(255,232,150) : MOTE_RGB565(150,152,162);
    const uint16_t SIGN = MOTE_RGB565(40,110,180), SIGNB = MOTE_RGB565(28, 78,130);
    for (int r = 1; r <= LAMP_RING && n < LAMP_MAX; r++) {
        for (int dz = -r; dz <= r && n < LAMP_MAX; dz++)
        for (int dx = -r; dx <= r && n < LAMP_MAX; dx++) {
            if (dx != -r && dx != r && dz != -r && dz != r) continue;
            int x = cx + dx, z = cz + dz;
            char tt = tile_at(x, z);
            if (wet && np < PUDDLE_MAX && (tt == '.' || tt == 'B')) {
                unsigned ph = (unsigned)(x*374761393u ^ z*668265263u);
                if ((ph & 7) == 0) {                         /* one road tile in eight */
                    float wx2 = x*TILE + 0.8f + (float)((ph >> 4) & 3),
                          wz2 = z*TILE + 0.8f + (float)((ph >> 8) & 3);
                    if (gta3_view_tile(&g_view, wx2, 0.03f, wz2, VIEW_GROUND_R, TILE)) {
                        float rr = 0.55f + 0.30f * (float)((ph >> 12) & 3);
                        float ss = rr * 0.62f;               /* oval, not a circle */
                        np++;
                        mote->scene_add_tri(v3(wx2-rr,0.025f,wz2-ss), v3(wx2+rr,0.025f,wz2-ss),
                                            v3(wx2+rr,0.025f,wz2+ss), pud, 0);
                        mote->scene_add_tri(v3(wx2-rr,0.025f,wz2-ss), v3(wx2+rr,0.025f,wz2+ss),
                                            v3(wx2-rr,0.025f,wz2+ss), pud, 0);
                    }
                }
            }
            if (tt != ',') continue;
            /* Which side is the road? That is the way the lamp arm reaches and
             * the way a bus-stop sign faces. */
            int rx = 0, rz = 0;
            if      (is_roadlike(x+1, z)) rx =  1;
            else if (is_roadlike(x-1, z)) rx = -1;
            else if (is_roadlike(x, z+1)) rz =  1;
            else if (is_roadlike(x, z-1)) rz = -1;
            else continue;                      /* not a kerb tile */
            /* Spaced along the kerb, measured on the axis the kerb RUNS along,
             * so a straight run of pavement gets evenly spaced posts. */
            int along = rx ? z : x;
            int stop  = (along % STOP_EVERY) == 0;
            if (!stop && (along % LAMP_EVERY) != 0) continue;
            float wx = x*TILE + TILE*0.5f, wz = z*TILE + TILE*0.5f;
            if (!gta3_view_tile(&g_view, wx, 2.0f, wz, VIEW_GROUND_R, TILE)) continue;
            n++;
            /* stand it on the kerb edge, a little way toward the road */
            float px = wx + rx*TILE*0.30f, pz = wz + rz*TILE*0.30f;
            float ux = (float)rz, uz = (float)-rx;     /* along the kerb */
            const float PW = 0.085f;
            if (stop) {
                /* BUS STOP: a post with a flag sign facing the road. */
                mote->scene_add_tri(v3(px-ux*PW,0.0f,pz-uz*PW), v3(px+ux*PW,0.0f,pz+uz*PW),
                                    v3(px+ux*PW,2.45f,pz+uz*PW), POST, 0);
                mote->scene_add_tri(v3(px-ux*PW,0.0f,pz-uz*PW), v3(px+ux*PW,2.45f,pz+uz*PW),
                                    v3(px-ux*PW,2.45f,pz-uz*PW), POST, 0);
                float sw = 0.42f, y0 = 1.80f, y1 = 2.40f;
                float ax = px - ux*0.04f, az = pz - uz*0.04f;   /* clear of the post */
                mote->scene_add_tri(v3(ax,y0,az), v3(ax+ux*sw,y0,az+uz*sw),
                                    v3(ax+ux*sw,y1,az+uz*sw), SIGN, 0);
                mote->scene_add_tri(v3(ax,y0,az), v3(ax+ux*sw,y1,az+uz*sw),
                                    v3(ax,y1,az), SIGN, 0);
                /* a darker band along the bottom so it is not one flat card */
                mote->scene_add_tri(v3(ax,y0,az), v3(ax+ux*sw,y0,az+uz*sw),
                                    v3(ax+ux*sw,y0+0.14f,az+uz*sw), SIGNB, 0);
                mote->scene_add_tri(v3(ax,y0,az), v3(ax+ux*sw,y0+0.14f,az+uz*sw),
                                    v3(ax,y0+0.14f,az), SIGNB, 0);
            } else {
                /* LAMP: post, then a head cantilevered out over the road. */
                mote->scene_add_tri(v3(px-ux*PW,0.0f,pz-uz*PW), v3(px+ux*PW,0.0f,pz+uz*PW),
                                    v3(px+ux*PW,4.20f,pz+uz*PW), POST, 0);
                mote->scene_add_tri(v3(px-ux*PW,0.0f,pz-uz*PW), v3(px+ux*PW,4.20f,pz+uz*PW),
                                    v3(px-ux*PW,4.20f,pz-uz*PW), POST, 0);
                float hx = px + rx*0.85f, hz = pz + rz*0.85f;     /* out over the kerb */
                mote->scene_add_tri(v3(px,4.20f,pz), v3(hx,4.05f,hz),
                                    v3(hx+ux*0.26f,3.95f,hz+uz*0.26f), HEAD, 0);
                mote->scene_add_tri(v3(px,4.20f,pz), v3(hx+ux*0.26f,3.95f,hz+uz*0.26f),
                                    v3(px+ux*0.26f,4.10f,pz+uz*0.26f), HEAD, 0);
            }
        }
    }
}

static void draw_street_detail(void) {
    int cx = (int)(view_x / TILE), cz = (int)(view_z / TILE), n = 0;
    const uint16_t RAIL  = MOTE_RGB565(150,152,160);
    const uint16_t WOOD  = MOTE_RGB565(120, 82, 46);
    const uint16_t WOODD = MOTE_RGB565( 86, 58, 32);
    for (int r = 1; r <= DETAIL_RING && n < DETAIL_MAX; r++) {
        for (int dz = -r; dz <= r && n < DETAIL_MAX; dz++)
        for (int dx = -r; dx <= r && n < DETAIL_MAX; dx++) {
            if (dx != -r && dx != r && dz != -r && dz != r) continue;
            int x = cx + dx, z = cz + dz;
            char t = tile_at(x, z);
            float wx = x*TILE + TILE*0.5f, wz = z*TILE + TILE*0.5f;

            if (t == 'B') {
                /* Which way does the span run, and is it long enough to bother? */
                int ew = is_waterlike(x-1,z) || is_waterlike(x+1,z);
                int run = 1;
                for (int k=1;k<20;k++){ if (tile_at(ew? x-k:x, ew? z:z-k) != 'B') break; run++; }
                for (int k=1;k<20;k++){ if (tile_at(ew? x+k:x, ew? z:z+k) != 'B') break; run++; }
                if (run < LONG_SPAN) continue;
                if (!gta3_view_tile(&g_view, wx, 0.6f, wz, VIEW_GROUND_R, TILE)) continue;
                n++;
                /* a rail down each side, across the span direction */
                for (int side = 0; side < 2; side++) {
                    float o = (side ? 1.0f : -1.0f) * TILE * 0.46f;
                    float ax = ew ? wx - TILE*0.5f : wx + o, az = ew ? wz + o : wz - TILE*0.5f;
                    float bx = ew ? wx + TILE*0.5f : wx + o, bz = ew ? wz + o : wz + TILE*0.5f;
                    mote->scene_add_tri(v3(ax,0.10f,az), v3(bx,0.10f,bz), v3(bx,0.95f,bz), RAIL, 0);
                    mote->scene_add_tri(v3(ax,0.10f,az), v3(bx,0.95f,bz), v3(ax,0.95f,az), RAIL, 0);
                }
                continue;
            }

            /* Benches on PLAZA (' ') and on PAVEMENT (','). The pavement is
             * where most of the walking happens, so leaving it bare was the
             * gap; it gets them at a quarter the plaza rate so a street does
             * not turn into a waiting room. Pavement tiles are never planted
             * by the scenery pass, so they skip the tree test. */
            if (t != ' ' && t != ',') continue;
            unsigned h = (unsigned)(x*668265263u ^ z*374761393u);
            if (t == ' ') {
                if ((h & 3) != 0) continue;             /* the scenery pass PUT A TREE here */
                if (((h >> 6) & 3) != 0) continue;      /* and only a quarter of the rest */
            } else {
                if (((h >> 8) & 15) != 0) continue;     /* one pavement tile in 16 */
            }
            if (!gta3_view_tile(&g_view, wx, 0.5f, wz, VIEW_GROUND_R, TILE)) continue;
            n++;
            /* bench: seat then back. On a PAVEMENT tile the bench faces the
             * STREET — seat parallel to the kerb, back to the buildings —
             * which is where a real one points and what stops half of them
             * sitting side-on to the road. The turn code is two bits: bit 0
             * picks the seat's axis (0 = along Z, 1 = along X) and bit 1 flips
             * which side the backrest is on, so the road's direction maps
             * straight onto it:
             *     road east  (+x) -> seat along Z, back at -x -> 2
             *     road west  (-x) -> seat along Z, back at +x -> 0
             *     road south (+z) -> seat along X, back at -z -> 3
             *     road north (-z) -> seat along X, back at +z -> 1
             * Plaza benches keep the hash: there is no street to face. */
            { int turn = (int)((h >> 12) & 3);
              /* Three tiles, not one. Measured over three maps: only 68% of
               * pavement bench tiles touch a road directly, so a one-tile test
               * left a third of them on the random hash — which is the third
               * that faced a wall. Two tiles reaches 80-84%, three reaches
               * 84-92%, and 12 m is still plainly "the bench by that street".
               * At most twelve tile_at calls, on at most DETAIL_MAX 16 benches
               * a frame. */
              if (t == ',') {
                  for (int d = 1; d <= 3; d++) {
                      if      (is_roadlike(x+d, z)) { turn = 2; break; }
                      else if (is_roadlike(x-d, z)) { turn = 0; break; }
                      else if (is_roadlike(x, z+d)) { turn = 3; break; }
                      else if (is_roadlike(x, z-d)) { turn = 1; break; }
                  }
              }
              float ax = (turn & 1) ? 0.62f : 0.0f, az = (turn & 1) ? 0.0f : 0.62f;
              float bxo = (turn & 1) ? 0.0f : 0.22f,  bzo = (turn & 1) ? 0.22f : 0.0f;
              if (turn & 2) { bxo = -bxo; bzo = -bzo; }
              float sx = wx, sz = wz;
              mote->scene_add_tri(v3(sx-ax, 0.42f, sz-az), v3(sx+ax, 0.42f, sz+az),
                                  v3(sx+ax+bxo, 0.42f, sz+az+bzo), WOOD, 0);
              mote->scene_add_tri(v3(sx-ax, 0.42f, sz-az), v3(sx+ax+bxo, 0.42f, sz+az+bzo),
                                  v3(sx-ax+bxo, 0.42f, sz-az+bzo), WOOD, 0);
              mote->scene_add_tri(v3(sx-ax+bxo, 0.42f, sz-az+bzo), v3(sx+ax+bxo, 0.42f, sz+az+bzo),
                                  v3(sx+ax+bxo, 0.86f, sz+az+bzo), WOODD, 0);
              mote->scene_add_tri(v3(sx-ax+bxo, 0.42f, sz-az+bzo), v3(sx+ax+bxo, 0.86f, sz+az+bzo),
                                  v3(sx-ax+bxo, 0.86f, sz-az+bzo), WOODD, 0); }
        }
    }
}

static void draw_traffic_lights(void) {
    int cx = (int)(view_x / TILE), cz = (int)(view_z / TILE), n = 0;
    const uint16_t POST    = MOTE_RGB565(58, 62, 72);
    const uint16_t HOUSING = MOTE_RGB565(26, 28, 34);   /* dark box the lamp sits in */
    for (int r = 1; r <= LIGHT_RING && n < LIGHTS_MAX; r++) {
        for (int dz = -r; dz <= r && n < LIGHTS_MAX; dz++)
        for (int dx = -r; dx <= r && n < LIGHTS_MAX; dx++) {
            if (dx != -r && dx != r && dz != -r && dz != r) continue;   /* ring shell only */
            int x = cx + dx, z = cz + dz;
            /* ONE light per intersection, not one per junction TILE. A crossing
             * is ROADW-plus tiles across, so every tile in it is a junction and
             * this drew a housing on each — a dozen stacked in the same
             * junction. Measured: 2788 junction tiles on a 254x256 map, which is
             * only about 170 actual crossings. Taking the tile whose west and
             * north neighbours are NOT junctions picks exactly the top-left
             * corner of each block, and needs no state. */
            if (!is_junction(x, z) || is_junction(x-1, z) || is_junction(x, z-1)) continue;
            /* Measure the crossing so the posts can go on its CORNERS. (x,z) is
             * its top-left tile, so walk east and south while still in it. */
            int jw = 0, jh = 0;
            while (jw < 10 && is_junction(x+jw+1, z)) jw++;
            while (jh < 10 && is_junction(x, z+jh+1)) jh++;
            float wx = (x + jw*0.5f)*TILE + TILE*0.5f, wz = (z + jh*0.5f)*TILE + TILE*0.5f;
            /* Distance only here — the CONE test is per POST, below.
             *
             * It used to be per CROSSING, on the junction's centre, and the
             * posts stand on its corners up to half the crossing plus a tile
             * away. Walk up to a post and the centre goes behind you, the
             * whole crossing culls, and the light you are standing next to
             * vanishes. Measured walking in: visible right down to 2.3 m, then
             * gone for the rest of the approach. */
            { float cdx = wx - cam_pos.x, cdz = wz - cam_pos.z;
              if (cdx*cdx + cdz*cdz > (VIEW_GROUND_R + 2.0f*TILE) *
                                      (VIEW_GROUND_R + 2.0f*TILE)) continue; }
            n++;
            for (int axis = 0; axis < 2; axis++) {
                int st = light_state(x, z, axis);
                uint16_t col = (st == LIGHT_GREEN)   ? MOTE_RGB565(60,230,90)
                             : (st == LIGHT_AMBER_ON)? MOTE_RGB565(250,190,50)
                                                     : MOTE_RGB565(240,50,40);
                /* ON THE PAVEMENT CORNER, not in the carriageway. A post in the
                 * middle of the junction is both wrong and in the way; kerbside
                 * is where a real signal stands. The two axes take diagonally
                 * opposite corners — north-west and south-east of the crossing —
                 * so each approach has one on its right-hand side and they never
                 * overlap. One tile OUTSIDE the junction block is the pavement. */
                int px = (axis == 0) ? x - 1 : x + jw + 1;
                int pz = (axis == 0) ? z - 1 : z + jh + 1;
                /* If that corner is not somewhere a post could stand, try the
                 * other three. Measured over three maps: the preferred corner
                 * is pavement or verge about 97% of the time, but the rest land
                 * in the carriageway, a wall, or — worst — open water, and a
                 * signal standing in the river is not a detail anyone forgives.
                 * If no corner works the light is skipped rather than faked. */
                { const int CX[4] = { x-1, x+jw+1, x-1,      x+jw+1 };
                  const int CZ[4] = { z-1, z+jh+1, z+jh+1,   z-1    };
                  int ok = 0;
                  for (int t = 0; t < 4 && !ok; t++) {
                      int tx = CX[(axis + t) & 3], tz = CZ[(axis + t) & 3];
                      char tc = tile_at(tx, tz);
                      if (tc == ',' || tc == ' ') { px = tx; pz = tz; ok = 1; }
                  }
                  if (!ok) continue; }
                float lx = px*TILE + TILE*0.5f;
                float lz = pz*TILE + TILE*0.5f;
                if (!gta3_view_tile(&g_view, lx, LIGHT_H, lz, VIEW_GROUND_R, TILE)) continue;
                /* The head FACES THE CAMERA rather than the approach it governs.
                 *
                 * It used to lie in the plane across its own approach, so from
                 * the perpendicular street you saw it exactly edge-on: a flat
                 * quad with zero projected area. scene_add_tri is double-sided,
                 * so backfacing was never the issue; edge-on was.
                 *
                 * Turning the quad to face the viewer costs nothing — still two
                 * triangles — and is readable from anywhere. Which approach a
                 * light governs is carried by WHICH CORNER it stands on, which
                 * does not depend on the viewing angle at all. */
                float vx = lx - cam_pos.x, vz = lz - cam_pos.z;
                float vl = sqrtf(vx*vx + vz*vz); if (vl < 0.001f) vl = 0.001f;
                float nx = vx/vl, nz = vz/vl;        /* camera -> light, on the ground plane */
                float ux = -nz,   uz =  nx;          /* its horizontal perpendicular */

                /* A VERTICAL housing, hanging from the top of the post and
                 * straddling eye level, with the lit lamp in its slot: top
                 * red, middle amber, bottom green — a real signal head.
                 *
                 * The hang is what makes it visible CLOSE UP, and that is
                 * geometry, not taste. The chase camera pitches about 22
                 * degrees down with a 55 degree field, so the top of the frame
                 * sits near 5.5 degrees above the 2.4 m eye. Anything at height
                 * h is off the top of the screen nearer than (h - 2.4)/0.096
                 * metres: the old head topped out at 3.30 m, so it vanished
                 * inside 9.3 m — exactly when you are at the junction and
                 * actually need to read it. This head runs 3.10 m down to
                 * 1.90 m, and everything below 2.4 m is on screen at ANY
                 * distance. */
                /* Sized for a 128 px screen, not for scale: at 40 m a real
                 * 0.3 m lamp is under one pixel. 0.36 m of lamp in a 0.52 m
                 * housing reads from about 25 m in and still looks like a
                 * signal head close up. HTOP 3.10 keeps the RED lamp centre at
                 * 2.90 m, so it only leaves the top of the frame inside 5.2 m
                 * -- by which point you are in the junction. */
                const float PW = 0.08f;
                const float HTOP = 3.10f, HBOT = 1.90f, HW = 0.26f;
                const float SLOT = (HTOP - HBOT) / 3.0f, LW = 0.18f;

                /* post, ground to the top of the head */
                mote->scene_add_tri(v3(lx-ux*PW, 0.0f, lz-uz*PW),
                                    v3(lx+ux*PW, 0.0f, lz+uz*PW),
                                    v3(lx+ux*PW, HTOP, lz+uz*PW), POST, 0);
                mote->scene_add_tri(v3(lx-ux*PW, 0.0f, lz-uz*PW),
                                    v3(lx+ux*PW, HTOP, lz+uz*PW),
                                    v3(lx-ux*PW, HTOP, lz-uz*PW), POST, 0);
                /* housing */
                mote->scene_add_tri(v3(lx-ux*HW, HBOT, lz-uz*HW),
                                    v3(lx+ux*HW, HBOT, lz+uz*HW),
                                    v3(lx+ux*HW, HTOP, lz+uz*HW), HOUSING, 0);
                mote->scene_add_tri(v3(lx-ux*HW, HBOT, lz-uz*HW),
                                    v3(lx+ux*HW, HTOP, lz+uz*HW),
                                    v3(lx-ux*HW, HTOP, lz-uz*HW), HOUSING, 0);
                /* lit lamp: red top, amber middle, green bottom */
                { int slot = (st == LIGHT_RED) ? 0 : (st == LIGHT_AMBER_ON ? 1 : 2);
                  float cy = HTOP - SLOT*(slot + 0.5f);
                  float ly0 = cy - LW, ly1 = cy + LW;
                  /* TOWARD the camera, not away. This read `+ nx` and pushed the
                   * lamp 3 cm BEHIND the housing, where the depth test threw it
                   * away: every signal drew its dark box and no lit lamp at all,
                   * which is why they looked absent rather than dim. */
                  float cxx = lx - nx*0.06f, czz = lz - nz*0.06f;
                  mote->scene_add_tri(v3(cxx-ux*LW, ly0, czz-uz*LW),
                                      v3(cxx+ux*LW, ly0, czz+uz*LW),
                                      v3(cxx+ux*LW, ly1, czz+uz*LW), col, 0);
                  mote->scene_add_tri(v3(cxx-ux*LW, ly0, czz-uz*LW),
                                      v3(cxx+ux*LW, ly1, czz+uz*LW),
                                      v3(cxx-ux*LW, ly1, czz-uz*LW), col, 0); }
            }
        }
    }
}

static void draw_water_shimmer(void) {
    float t = (float)mote->micros() * 1e-6f;
    int cx = (int)(view_x / TILE), cz = (int)(view_z / TILE), n = 0;
    for (int z = cz - 10; z <= cz + 10 && n < WATER_FLECKS_MAX; z++)
        for (int x = cx - 10; x <= cx + 10 && n < WATER_FLECKS_MAX; x++) {
            if (tile_at(x, z) != '~') continue;
            if (!gta3_view_tile(&g_view, x*TILE + TILE*0.5f, 0.06f, z*TILE + TILE*0.5f,
                                VIEW_GROUND_R, TILE)) continue;
            unsigned h = (unsigned)(x * 2654435761u ^ z * 40503u);
            float shim = sinf(t * 1.6f + (float)(h & 255) * 0.0246f);
            if (shim <= 0.45f) continue;
            float wx = x*TILE + 1.0f + ((h >> 4) & 3), wz = z*TILE + 1.0f + ((h >> 9) & 3);
            uint16_t col = shim > 0.8f ? MOTE_RGB565(180,225,240) : MOTE_RGB565(110,185,215);
            mote->scene_add_point(v3(wx, 0.06f, wz), col, 1);
            n++;
        }
}

/* BEACHES, entirely at draw time — there is no sand tile in the map.
 *
 * A real T_SAND char would mean auditing every T_GRASS test in citygen.h (about
 * twenty) plus walkable_world, drivable_world and the bench, tree and ped
 * placement rules, and for a change that is purely how the ground is painted it
 * buys nothing. draw_ground_window already has (x,z), so the cell is chosen from
 * the tile's surroundings instead, which is the same test the palm rule uses —
 * so palms end up standing on the sand for free.
 *
 * Returns 0 not a beach, 1 wet sand (on the water), 2 dry sand (one tile back).
 * Sand does NOT change handling: drivable_world and walkable_world still see
 * plain grass, so nothing reaches the physics solver. */
static int beach_block(int x, int z) {
    /* Beaches come in STRETCHES, not speckle: one hash per 8x8 block (32 m)
     * decides whether this piece of waterfront is sand at all, so some shores
     * stay grass behind their seawall and the coast reads as varied. */
    unsigned h = ((unsigned)(x >> 3) * 0x27d4eb2du) ^ ((unsigned)(z >> 3) * 0x165667b1u);
    return ((h >> 11) & 3) == 0;
}
/* Grass with open water on one of its four sides. '~' directly, not
 * is_waterlike(), because that counts bridge tiles and a bridge deck is not a
 * shore. */
static int shore_tile(int x, int z) {
    if (tile_at(x, z) != ' ') return 0;
    return tile_at(x+1, z) == '~' || tile_at(x-1, z) == '~'
        || tile_at(x, z+1) == '~' || tile_at(x, z-1) == '~';
}
static int beach_at(int x, int z) {
    if (tile_at(x, z) != ' ' || !beach_block(x, z)) return 0;
    if (shore_tile(x, z)) return 1;
    if (shore_tile(x+1, z) || shore_tile(x-1, z) ||
        shore_tile(x, z+1) || shore_tile(x, z-1)) return 2;
    return 0;
}

static void draw_ground_skirt(void) {
    float s = VIEW_BLD_R;
    float x0 = view_x - s, x1 = view_x + s, z0 = view_z - s, z1 = view_z + s;
    /* Midway along the same ramp haze_tint walks, so the skirt sits between lit
     * ground and sky at every time of day rather than at one fixed dusk tone. */
    uint16_t col = rgb565(rgb_lerp(g_haze_near, g_sky_hor, 0.5f));
    mote->scene_add_tri(v3(x0,-0.05f,z0), v3(x1,-0.05f,z0), v3(x1,-0.05f,z1), col, 0);
    mote->scene_add_tri(v3(x0,-0.05f,z0), v3(x1,-0.05f,z1), v3(x0,-0.05f,z1), col, 0);
}

static void draw_ground_window(void) {
    int cx = (int)(view_x / TILE), cz = (int)(view_z / TILE);
    /* The radius is measured from the EYE in 3D (gta3_view_tile), so from a
     * helicopter at 40 m every ground tile is already more than the stock 52 m
     * away and NOTHING draws — measured: zero tiles. It has to grow with
     * altitude. Measured cost on the way up: 64 tiles at ground level, 118 at
     * 40 m, against a textured pool of 1100 tris shared with the buildings.
     * That is why HELI_CEIL is 45 m and not higher: at 80 m it is 404 tiles
     * and at 150 m it is 1308, which is the whole pool twice over.
     *
     * The 0.9 is measured too, not chosen. At 1.2 the ceiling cost 291 tiles
     * (582 tris) on top of 46 buildings, about 1042 of the 1100 pool — no
     * margin at all. 0.9 draws 158 tiles for 776 total, and the two frames are
     * indistinguishable: the extra radius was spending triangles on ground
     * that the haze skirt and the buildings already covered. */
    float gr = VIEW_GROUND_R + (cam_pos.y - CAM_FOOT_H) * 0.9f;
    if (gr < VIEW_GROUND_R) gr = VIEW_GROUND_R;
    int w = (int)(gr / TILE) + 1;
    draw_ground_skirt();
    for (int z = cz - w; z <= cz + w; z++) {
        for (int x = cx - w; x <= cx + w; x++) {
            if (!tile_visible_r(x, z, 0, gr)) continue;
            char c = tile_at(x, z);
            if (c == '.' || c == 'B') {              /* road + bridge use the road sheet */
                g_ground.texture = &roads_img;
                road_uv(roads_at.lut[road_mask(x, z)]);
            } else if (c == '~') {                    /* water: autotiled shorelines */
                /* The seawall — concrete cap, seam and shadow — is baked into
                 * the closed sides of every cell in water.png, so water next to
                 * a beach would draw a wall across it. water_beach.png is the
                 * same 16 cells with the wall replaced by wet sand shelving out
                 * through shallows, and it reuses water_at.lut because the
                 * mask-to-cell mapping is identical. */
                int sandy = beach_at(x+1, z) || beach_at(x-1, z)
                         || beach_at(x, z+1) || beach_at(x, z-1);
                g_ground.texture = sandy ? &water_beach_img : &water_img;
                road_uv(water_at.lut[water_mask(x, z)]);
            } else if (is_garage(x, z)) {            /* garage bay floor: use the pavement cell so it reads as a drive-in */
                g_ground.texture = &ground_img;
                ground_uv(ground_cell(','));
            } else {
                g_ground.texture = &ground_img;
                int b = (c == ' ') ? beach_at(x, z) : 0;
                ground_uv(b == 1 ? G_SANDWET : b == 2 ? G_SAND : ground_cell(c));
            }
            mote_draw(mote, &g_ground, v3(x*TILE+TILE*0.5f, 0, z*TILE+TILE*0.5f));
            if (c == '.' || c == 'B') road_markings(x, z);
        }
    }
}

/* Blend a building's tone toward the background over the far band, so the draw
 * distance reads as haze instead of a wall of nothing. t = 0 at VIEW_HAZE_R,
 * 1 at VIEW_BLD_R. */
static uint16_t haze_tint(float d) {
    float t = (d - VIEW_HAZE_R) / (VIEW_BLD_R - VIEW_HAZE_R);
    if (t < 0.0f) t = 0.0f; if (t > 1.0f) t = 1.0f;
    /* The FAR end is the sky's own horizon colour, not a constant: the whole
     * point of the band is that a building at the draw distance is
     * indistinguishable from the sky behind it, and the sky now moves. */
    return rgb565(rgb_lerp(g_haze_near, g_sky_hor, t));
}

static void draw_buildings_window(void) {
    int cx = (int)(view_x / TILE), cz = (int)(view_z / TILE);
    int w = (int)(VIEW_BLD_R / TILE) + 1;
    int submitted = 0;
    /* Walk outward in Chebyshev rings from the camera tile (same shape as the
     * tree scan below), classifying near/far by actual distance as each tile
     * is visited. That makes the cap drop the FARTHEST buildings, not
     * whichever tile a north-to-south raster scan happened to reach last: a
     * plain two-pass raster kept the first VIEW_BLD_CAP submissions in MAP
     * order, unrelated to camera distance, so a close building behind the
     * cap could be missing its mesh while its collider still stood, and a
     * saturated near pass could starve the far pass so the haze band never
     * rendered at all. Ring order also replaces the old double 59x59 scan
     * (~6,962 tile checks/frame across both passes) with one bounded walk. */
    for (int r = 0; r <= w && submitted < VIEW_BLD_CAP; r++) {
        for (int dz = -r; dz <= r; dz++) {
            for (int dx = -r; dx <= r; dx++) {
                if (r > 0 && dx != -r && dx != r && dz != -r && dz != r) continue; /* interior: visited at a smaller r */
                int x = cx + dx, z = cz + dz;
                char c = tile_at(x, z);
                if (c != '#' && c != 'O' && c != 'H') continue;
                int gdir = is_garage(x, z) ? garage_dir(x, z) : -1;
                float th, hy;
                if (gdir >= 0){ th = GARAGE_H; hy = th * 0.5f; }      /* garage: a low roofed bay, open front */
                else { int L = bld_level(x, z); th = g_lvl_h[L]; hy = th * 0.5f; }
                float wx = x*TILE+TILE*0.5f, wz = z*TILE+TILE*0.5f;
                float ddx = wx - cam_pos.x, ddz = wz - cam_pos.z;
                float d = sqrtf(ddx*ddx + ddz*ddz);
                int far = d > VIEW_HAZE_R;
                if (submitted >= VIEW_BLD_CAP) return;
                /* Base OR top in the cone: culling on the elevated centre alone
                 * made tall blocks blink out while their footprint was still
                 * plainly in view. */
                if (!gta3_view_tile(&g_view, wx, 0.1f, wz, VIEW_BLD_R, TILE) &&
                    !gta3_view_tile(&g_view, wx, th,   wz, VIEW_BLD_R, TILE)) continue;
                if (gdir >= 0) { mote_draw(mote, &gr_mesh[gdir], v3(wx, hy, wz)); }
                else if (far) {
                    MoteObject o = { .pos = v3(wx, hy, wz), .basis = m3_identity(),
                                     .mesh = &g_hmesh[bld_level(x,z)],
                                     .color = haze_tint(d) };
                    mote->scene_add_object(&o);
                } else {
                    mote_draw(mote, &g_bmesh[bld_level(x,z)][bld_tex(x,z)], v3(wx, hy, wz));
                }
                submitted++;
            }
        }
    }
}

/* -------------------------------------------------------- movement + AI ----- */
/* slide a body to (nx,nz) honouring a walkable/drivable test; returns hit flag. */
static int move_body(float *x, float *z, float nx, float nz, int drive) {
    int hit = 0;
    int (*ok)(float,float) = drive ? drivable_world : walkable_world;
    if (ok(nx, *z)) *x = nx; else hit = 1;
    if (ok(*x, nz)) *z = nz; else hit = 1;
    return hit;
}

/* Flying, which replaces drive_car entirely when you are in the helicopter.
 *
 * On the ground the aircraft does nothing but lift: no taxiing, no steering.
 * A helicopter that drove like a car would need a second set of handling
 * constants and would be worse than either thing.
 *
 * Airborne, the D-pad is pitch and yaw and the face buttons are the collective:
 * A climbs, B descends. That mirrors the car's A/B pedals rather than inventing
 * a third scheme.
 *
 * Nothing here reads or writes heat, and no crime is committed by flying. */
static void fly_heli(Car *c, int slot, float dt,
                     int up, int down, int fwd, int back, int yawL, int yawR) {
    MoteBody2D *b = &bodies[slot];
    float fl = heli_floor(c->x, c->z);
    int airborne = heli_aloft(c->x, c->z);

    /* collective */
    float want = up ? HELI_CLIMB : (down ? -HELI_CLIMB : 0.0f);
    g_heli_vy += (want - g_heli_vy) * mote_clampf(4.0f * dt, 0.0f, 1.0f);
    g_heli_y  += g_heli_vy * dt;
    if (g_heli_y > HELI_CEIL) { g_heli_y = HELI_CEIL; if (g_heli_vy > 0.0f) g_heli_vy = 0.0f; }
    if (g_heli_y < fl)        { g_heli_y = fl;        if (g_heli_vy < 0.0f) g_heli_vy = 0.0f; }

    /* The sensor flag is what lets it pass over traffic and walls. Cleared the
     * moment the skids are down, so a landed helicopter is solid again and cars
     * cannot drive through it. */
    if (airborne) b->flags |=  MOTE_B2D_SENSOR;
    else          b->flags &= (uint8_t)~MOTE_B2D_SENSOR;

    if (!airborne) {
        b->vx = b->vy = 0.0f; b->avel = 0.0f; c->spd = 0.0f;
        g_rotor += (up ? 22.0f : 6.0f) * dt;     /* spooling on the pad */
        return;
    }

    if (yawL) c->yaw += HELI_YAW * dt;           /* yaw+ turns visually LEFT, as in drive_car */
    if (yawR) c->yaw -= HELI_YAW * dt;
    b->angle = c->yaw;
    b->avel = 0.0f;

    float fx = cosf(c->yaw), fz = sinf(c->yaw);
    float th = (fwd ? 1.0f : 0.0f) - (back ? 1.0f : 0.0f);
    b->vx += fx * HELI_ACC * th * dt;
    b->vy += fz * HELI_ACC * th * dt;
    float damp = 1.0f - mote_clampf(HELI_DRAG * dt, 0.0f, 1.0f);
    b->vx *= damp; b->vy *= damp;
    float sp = sqrtf(b->vx*b->vx + b->vy*b->vy), cap = VSTAT[VEH_HELI].maxspd;
    if (sp > cap) { b->vx = b->vx / sp * cap; b->vy = b->vy / sp * cap; }
    c->spd = sp;
    g_rotor += 34.0f * dt;
}

/* Sailing, which replaces drive_car entirely when you are in the boat.
 *
 * OFF WATER the engine does nothing and the hull stops. That is what "only runs
 * on water" means mechanically, and it has to be a movement rule rather than a
 * collision rule: the boat is moored at a shoreline, so the tile under its
 * centre is legitimately land for a moment as it noses in, and a collision rule
 * would either trap it there or shove it out.
 *
 * ON WATER the throttle drives along the heading and the rudder turns, with the
 * hull's lat_damp of 4 (against a car's 22) doing the sliding — a boat carries
 * its momentum through a turn and that falls out of the existing solver for
 * free. Steering authority scales with speed because a rudder does nothing when
 * the hull is not moving, which is both true and what stops the boat spinning
 * on the spot at a jetty.
 *
 * B is astern, not a brake: a boat has no brakes, so there is no stop-then-
 * reverse dwell of the kind drive_car needs. */
#define BOAT_ACC    6.5f     /* m/s^2 ahead */
#define BOAT_ASTERN 0.45f    /* astern is this fraction of ahead */
#define BOAT_TURN   1.15f    /* rad/s at full rudder authority */
#define BOAT_DRAG   0.55f    /* per second: a hull coasts a long way */
static void sail_boat(Car *c, int slot, float dt,
                      int throttle, int brake, int steerL, int steerR) {
    MoteBody2D *b = &bodies[slot];
    float cc = cosf(b->angle), ss = sinf(b->angle);
    float fs = b->vx*cc + b->vy*ss;                    /* speed along the hull */

    if (!boat_afloat(c->x, c->z)) {
        /* Aground. Kill the way on and give back no steering: whatever put it
         * here, it is not going anywhere under power. */
        b->vx *= 0.80f; b->vy *= 0.80f; b->avel = 0.0f;
        c->spd = 0.0f; c->lamp = LAMP_OFF;
        return;
    }

    float th = (throttle ? 1.0f : 0.0f) - (brake ? BOAT_ASTERN : 0.0f);
    fs += th * BOAT_ACC * dt;
    float cap = VSTAT[VEH_BOAT].maxspd * 1.3f;
    if (fs >  cap)        fs =  cap;
    if (fs < -cap*0.45f)  fs = -cap*0.45f;
    /* Rewrite the along-hull component and leave the lateral alone: the solver
     * owns that, which is where the slide comes from. */
    float lat = -b->vx*ss + b->vy*cc;
    b->vx = cc*fs - ss*lat;
    b->vy = ss*fs + cc*lat;

    float damp = 1.0f - mote_clampf(BOAT_DRAG * dt, 0.0f, 1.0f);
    b->vx *= damp; b->vy *= damp;

    /* Rudder authority: nothing at rest, full by a third of top speed. */
    float auth = mote_clampf(fabsf(fs) / (cap * 0.33f), 0.0f, 1.0f);
    float rud  = ((steerL ? 1.0f : 0.0f) - (steerR ? 1.0f : 0.0f)) * BOAT_TURN * auth;
    if (fs < 0.0f) rud = -rud;                         /* astern, the stern leads */
    b->avel += (rud - b->avel) * mote_clampf(4.0f*dt, 0.0f, 1.0f);
    c->yaw = b->angle;
    c->spd = fs;
    c->lamp = (th < 0.0f) ? LAMP_REV : LAMP_OFF;
}

static void drive_car(Car *c, float dt, int throttle, int brake, int steerL, int steerR) {
    int ci = (int)(c - cars);
    /* Screen-relative, and the sign flipped with the camera: increasing yaw rotates
     * forward TOWARD +Z, which the top-down basis (r[0]=+X, up=-Z) put on the right
     * of the screen but the chase basis (r[0]=cross(up,fwd)) puts on the LEFT.
     * Measured, not assumed: d(fwd)/dyaw . cam_right = -1 at every yaw. */
    float steer = (steerL?1.0f:0.0f) - (steerR?1.0f:0.0f);
    MoteBody2D *b=&bodies[ci];
    float cc=cosf(b->angle), ss=sinf(b->angle), fs=b->vx*cc+b->vy*ss;
    /* TOTAL speed, not the forward component. A car mid-slide has a forward
     * speed passing through zero while it is still travelling 6 m/s sideways,
     * and "stopped" measured along the nose would drop it into reverse in the
     * middle of the corner — which is exactly what the first drift capture
     * did. Stopped means stopped. */
    float tot = sqrtf(b->vx*b->vx + b->vy*b->vy);
    /* LB = PROGRESSIVE BRAKE: soft on a tap, ramping harder the longer it is held.
     * It only becomes REVERSE once the car has actually STOPPED first.
     *
     * Two ways in. A FRESH press with the car already near a stop reverses at
     * once (so a car nudging you never locks reverse out). Otherwise the press
     * brakes — and then, once the car has actually come to rest and stayed
     * there for REV_DWELL, it drops into reverse WITHOUT needing a release,
     * the way an automatic does. Holding the pedal from speed used to brake to
     * a stop and sit there forever, which gave no hint that reverse existed.
     *
     * The dwell is what stops a hard stop from snapping straight into reverse:
     * the car settles for a quarter second first, which also covers the moment
     * the brake clamp pins fs to zero. */
    #define REV_STOP  0.35f      /* m/s: "stopped" */
    #define REV_DWELL 0.25f      /* s at rest before reverse engages */
    static float s_bhold; static int s_revok; static float s_stopt;
    if (brake){
        /* A fresh press only reverses when the car is ALREADY stopped. This
         * used to admit anything under 3 m/s, so a gentle press at walking
         * pace skipped the brake entirely and went straight to reverse —
         * which is exactly the case where you wanted the brake. */
        if (s_bhold == 0.0f){ s_revok = (tot < REV_STOP); s_stopt = 0.0f; }
        s_bhold += dt;
        if (!s_revok){                                        /* braked from speed: wait for rest */
            if (tot < REV_STOP) { s_stopt += dt; if (s_stopt >= REV_DWELL) s_revok = 1; }
            else s_stopt = 0.0f;
        }
    } else { s_bhold = 0; s_stopt = 0.0f; }                   /* release re-arms the decision */
    float thr = throttle?1.0f:0.0f, brk = 0.0f;
    int braking = 0;
    if (brake){
        if (!s_revok){                                        /* pressed while moving: brake ONLY —
                                                                 holds to a stop, never reverses */
            brk = 0.4f + mote_clampf(s_bhold*1.1f, 0.0f, 1.0f);
            braking = 1;
        } else thr = -0.55f;                                  /* pressed from a stop -> reverse */
    }
    /* A braked TURN is a handbrake turn, not an emergency stop. Full brake is
     * about 3 g and parks the car in well under a second, which leaves no
     * window in which to slide at all — measured: 20 m/s to rest in 20 frames,
     * with the lateral velocity never leaving zero. With the wheel over, the
     * pedal keeps under half its stopping power, so the car carries speed
     * through the corner. Braking in a STRAIGHT LINE is untouched. */
    int sliding = braking && steer != 0.0f;
    if (sliding) brk *= 0.42f;
    apply_drive(b, &VSTAT[c->type], thr, brk, steer, dt);
    /* BRAKING BREAKS THE REAR LOOSE. apply_drive sets lat_damp from the car's
     * grip every frame, so overriding it here (after the call, before the
     * solver steps) is the whole handbrake: less lateral scrub means the
     * momentum you carried into the corner keeps going sideways and the tail
     * comes round. Only the player's car — ai_drive_b brakes NPCs at red
     * lights in a straight line, where a grip cut would buy nothing and risk
     * sliding them through the junction. */
    if (braking) {
        /* 0.65, swept rather than picked. Measured over a braked left-hander
         * with the throttle held: 0.86 slides hardest but lets the heading run
         * away from the velocity until the car is travelling broadside, and
         * 0.35 barely beats an unbraked turn. At 0.65 the peak lateral speed
         * goes from 7.6 m/s unbraked to 10.3 m/s, the car still carries
         * 11 m/s forward through the corner, and it gathers itself up again
         * when the pedal comes off. */
        float cut = sliding ? 0.65f : 0.72f * mote_clampf(brk, 0.0f, 1.0f);
        b->lat_damp *= 1.0f - cut;
    }
    if (braking){                                             /* brakes stop the car, never reverse it */
        fs = b->vx*cc + b->vy*ss;
        if (fs < 0.0f){ b->vx -= cc*fs; b->vy -= ss*fs; }
    }
    /* Rear lamps follow what the pedal is actually doing, so the light matches
     * the manoeuvre: red under braking, white once LB has become reverse. */
    c->lamp = braking ? LAMP_BRAKE : ((brake && s_revok) ? LAMP_REV : LAMP_OFF);
}

/* follow the actual road shape: probe headings (prefer straight, then gentle
 * turns) for a drivable look-ahead, so cars track curving/irregular streets
 * instead of assuming a clean grid. Drive slowly + carefully. */
static int wanted(void);   /* crime layer, defined below */
static float pl_x(void), pl_z(void);   /* player world pos (car or foot), defined below */
/* metres of contiguous road from (x,z) along a unit dir, sampled at 0.5 m (cap ~m) */
static float road_run(float x,float z,float dx,float dz,float cap){
    float s; for (s=0.5f; s<=cap; s+=0.5f){ if(!road_world(x+dx*s, z+dz*s)) break; }
    return s-0.5f;
}

/* pick the cardinal turn (from d) whose road runs longest; right preferred on ties */
static float best_turn(float x,float z,float d,int allow_straight){
    const float R[4]={ 1.5708f,-1.5708f, allow_straight?0.0f:3.14159f, 3.14159f };
    float bestd=d, bestrun=-1;
    for (int k=0;k<4;k++){ float cd=d+R[k];
        float run=road_run(x,z, cosf(cd),sinf(cd), TILE*6.0f);
        if (run>bestrun+0.01f){ bestrun=run; bestd=cd; } }
    return 1.5708f * floorf(bestd/1.5708f + 0.5f);   /* normalise to a cardinal */
}

/* RACER navigation: among the drivable cardinals leaving (x,z) (relative to the
 * committed heading d), pick the one whose road best REDUCES the true road-network
 * distance to the checkpoint (tx,tz) — i.e. greedy descent on the coarse BFS field,
 * which converges on a connected grid. allow_back gates the 180° reverse: junction
 * turns pass 0 so the racer never U-turns mid-street; a boxed-in dead-end passes 1.
 * Only 'straight' open  → returns d (keep cruising, no turn). */
static float best_turn_toward(float x,float z,float d,float tx,float tz,int allow_straight,int allow_back){
    const float R[4]={ 1.5708f,-1.5708f, allow_straight?0.0f:3.14159f, 3.14159f };
    float cand[4], crun[4]; int nv=0;
    for (int k=0;k<4;k++){
        if (k==3 && !allow_back) continue;                       /* R[3] is the reverse */
        float cd=d+R[k];
        /* Require a real road run (>= 1.5 tiles) to count as an exit — the traffic AI's
         * anti-wedge rule: the racer only commits to a cardinal it can actually drive down,
         * so it never steers into a stub/kerb and freezes on the clamp. */
        float rr = road_run(x,z, cosf(cd),sinf(cd), TILE*5.0f);
        if (rr < TILE*1.5f) continue;
        cand[nv]=cd; crun[nv]=rr; nv++;
    }
    if (nv==0) return best_turn(x,z,d,allow_straight);           /* boxed in: fall back to longest run */
    if (nv==1) return 1.5708f * floorf(cand[0]/1.5708f + 0.5f);  /* only one way — take it */
    int bi=0; float bs=1e30f;
    for (int k=0;k<nv;k++){
        float fx=cosf(cand[k]), fz=sinf(cand[k]);
        /* sample the field cost where this road ACTUALLY reaches (its run extent, capped),
         * not a fixed distance that may overshoot a bend into a building — a bent exit was
         * being wrongly scored as unrouteable, which trapped the racer in dither loops. */
        float sd=crun[k]; if(sd>TILE*4.0f) sd=TILE*4.0f;
        float sx=x+fx*sd, sz=z+fz*sd;
        float g=sqrtf((sx-tx)*(sx-tx)+(sz-tz)*(sz-tz));         /* straight-line to the checkpoint */
        float cst=race_cost(sx,sz);                             /* true routed cost (cells) via the field */
        /* the routed cost DOMINATES (×1000) so the racer always descends the real road
         * network; the straight-line only breaks ties between equal-cost branches.  A
         * branch the field can't route from sorts last but still beats being boxed in. */
        float score = (cst>=1e6f) ? (1e9f + g) : (cst*1000.0f + g);
        if (score<bs-0.01f){ bs=score; bi=k; }
    }
    return 1.5708f * floorf(cand[bi]/1.5708f + 0.5f);
}
/* Traffic AI = a small STATE MACHINE on the tile grid:
 *   CRUISE — drive straight along the committed cardinal, holding the right-lane centre
 *            with PURE-PURSUIT (steer at a look-ahead point → smooth, no wiggle); go
 *            straight through cross-junctions; slow on the APPROACH to a turn; brake for
 *            a car ahead in-lane.
 *   TURN   — entered only when the road doesn't continue straight (corner/T/dead-end):
 *            commit ONE new cardinal with a clear run, slow right down, steer to it, then
 *            resume CRUISE once aligned and the exit is open ahead. */
static void update_traffic(float dt) {
    for (int i=0;i<NCAR;i++) {
        Car *c=&cars[i];
        int patrol = (c->driver==DRV_COP && wanted()==0 && c->type!=VEH_TANK);
        if (!c->alive || (c->driver!=DRV_NPC && !patrol)) { red_wait[i]=0; continue; }  /* patrols cruise like traffic */
        MoteBody2D *b=&bodies[i];
        const VStat *v=&VSTAT[c->type];
        if (mission==MI_REPO && i==mission_car && c->driver==DRV_NPC){   /* the debtor floors it away from you */
            float ay=atan2f(c->z-pl_z(), c->x-pl_x());
            float dd=1.5708f*floorf(ay/1.5708f+0.5f);
            if (road_run(c->x,c->z, cosf(dd),sinf(dd), TILE*1.5f) < TILE*1.2f) dd=best_turn(c->x,c->z,dd,0);
            ai_drive(i, dd, 1.0f, dt); red_wait[i]=0; continue;
        }
        float d = 1.5708f * floorf(npc_target[i]/1.5708f + 0.5f);   /* committed cardinal */
        float ba=b->angle, spd=b->vx*cosf(ba)+b->vy*sinf(ba);

        /* THE RACER: a real AI car that reuses this whole lane-keeping + CRUISE/TURN
         * machine (so it stays lane-centred and never trips the road-clamp), but steers
         * its junction choices toward the current checkpoint and runs a rubber-banded
         * top speed. rcx/rcz = the checkpoint it is currently chasing. */
        int is_racer = (mission==MI_RIVAL && i==rival_car && rival_i<cp_n);
        float rcx=0, rcz=0;
        /* racer escape state (single racer): drives a fixed cardinal straight for a beat to
         * break a wedge/orbit, and a DISPLACEMENT-based stuck timer that (unlike the forward-
         * speed one) also catches a car spinning-in-place on a turn waypoint. */
        static float rc_escd, rc_esc_t, rc_sx, rc_sz, rc_samp, rc_bestcost=1e9f, rc_prog_t;
        static int   rc_circ_n;
        if (is_racer){ rcx=cp_x[rival_i]; rcz=cp_z[rival_i];
            if (!rf_valid || rf_tx!=rcx || rf_tz!=rcz){ race_field(rcx,rcz); rc_bestcost=1e9f; rc_prog_t=0; rc_circ_n=0; }
            rc_samp += dt;
            if (rc_samp >= 0.5f){                            /* barely moved (<1 m) in 0.5 s → wedged */
                float mv=(c->x-rc_sx)*(c->x-rc_sx)+(c->z-rc_sz)*(c->z-rc_sz);
                if (mv < 1.0f) stuck_t[i]+=rc_samp; else stuck_t[i]=0;   /* real cornering still counts as moving */
                rc_sx=c->x; rc_sz=c->z; rc_samp=0;
            }
            /* ANTI-CIRCLE: a car looping a block still "moves", so displacement won't flag it.
             * Watch routed COST instead — if it hasn't dropped for 2 s the racer is going
             * nowhere. First couple of times, force an escape (may U-turn out of a dead-end).
             * If it KEEPS failing on the same checkpoint (a pathological layout the strict
             * field can't route), GUARANTEE progress: hop to a clear road tile nearer the
             * checkpoint and re-route. Never fires while normally descending the field, so a
             * healthy leg is never teleported. */
            float cc = race_cost(c->x,c->z);
            if (cc < rc_bestcost-0.5f){ rc_bestcost=cc; rc_prog_t=0; rc_circ_n=0; }
            else { rc_prog_t += dt;
                if (rc_prog_t > 2.0f){ rc_prog_t=0; rc_bestcost=cc;
                    if (++rc_circ_n < 3){ stuck_t[i]=1.05f; }        /* try to steer out first */
                    else {                                            /* persistent → guaranteed hop */
                        float curd=sqrtf((rcx-c->x)*(rcx-c->x)+(rcz-c->z)*(rcz-c->z));
                        float bx=0,bz=0, bestd=curd*0.7f; int got=0;
                        for (int t=0;t<96;t++){
                            float mxp=c->x+(rcx-c->x)*0.5f, mzp=c->z+(rcz-c->z)*0.5f;   /* bias toward the CP */
                            float a=frand()*6.2832f, r=8.0f+frand()*72.0f;
                            int tx=(int)((mxp+cosf(a)*r)/TILE), tz=(int)((mzp+sinf(a)*r)/TILE);
                            if (tx<2||tz<2||tx>=MAPW-2||tz>=MAPH-2||!is_drivable(tx,tz)) continue;
                            float wx=(tx+0.5f)*TILE, wz=(tz+0.5f)*TILE;
                            float dd=sqrtf((rcx-wx)*(rcx-wx)+(rcz-wz)*(rcz-wz)); if(dd>=bestd) continue;
                            int clear=1; for(int j=0;j<NCAR;j++){ if(!cars[j].alive||j==i) continue;
                                float ddx=cars[j].x-wx, ddz=cars[j].z-wz; if(ddx*ddx+ddz*ddz<36.0f){clear=0;break;} }
                            if (clear){ bestd=dd; bx=wx; bz=wz; got=1; }
                        }
                        if (got){ float yaw; place_in_lane(&bx,&bz,&yaw);
                            c->x=bx; c->z=bz; c->yaw=yaw; c->spd=0; car_body_init(i);
                            npc_target[i]=yaw; ai_state[i]=AIS_CRUISE; stuck_t[i]=0; rc_esc_t=0;
                            rc_sx=bx; rc_sz=bz; rc_samp=0; rc_bestcost=1e9f;
                            d=1.5708f*floorf(yaw/1.5708f+0.5f); ba=yaw; spd=0; }
                        rc_circ_n=0;
                    }
                }
            }
            if (rc_esc_t > 0.0f) rc_esc_t -= dt;
            /* HARD UNSTICK — safety net. The per-axis road-clamp can wedge a body in an
             * off-road pocket (both axes revert every step → frozen forever, and no steering
             * escapes it). If the racer is truly stuck a while, re-seat it lane-centred on a
             * nearby clear road tile and re-route. Only fires when genuinely frozen, so it is
             * rare; far cleaner than a rival glued to a kerb for the whole race. */
            if (stuck_t[i] > 2.0f){
                float ox,oz;
                if (find_road_clear(c->x,c->z, 2.0f, 26.0f, &ox,&oz)){
                    float yaw; place_in_lane(&ox,&oz,&yaw);
                    c->x=ox; c->z=oz; c->yaw=yaw; c->spd=0;
                    car_body_init(i);                        /* re-seat the physics body on the road */
                    npc_target[i]=yaw; ai_state[i]=AIS_CRUISE;
                    stuck_t[i]=0; rc_esc_t=0; rc_sx=ox; rc_sz=oz; rc_samp=0;
                    d = 1.5708f * floorf(yaw/1.5708f + 0.5f); ba=yaw; spd=0;
                }
            }
        }

        /* JAM RECOVERY: break free of a wedge/orbit. The racer commits to CRUISING straight
         * along a fresh checkpoint-ward cardinal (a tight turn waypoint here can re-orbit),
         * and holds it for ~1 s (rc_esc_t) so it clears the junction before turning again. */
        if (stuck_t[i] > 1.0f && !red_wait[i]){
            if (is_racer){
                d = best_turn_toward(c->x,c->z,d, rcx,rcz, 1,1);   /* escape onto any real road toward CP */
                npc_target[i]=d; ai_state[i]=AIS_CRUISE; rc_escd=d; rc_esc_t=1.0f;
            } else {
                d=best_turn(c->x,c->z,d,0); npc_target[i]=d; ai_state[i]=AIS_TURN;
                turn_wx[i]=c->x+cosf(d)*TILE*1.9f; turn_wz[i]=c->z+sinf(d)*TILE*1.9f;
            }
        }
        int racer_escaping = (is_racer && rc_esc_t > 0.0f);   /* hold a straight escape line */
        if (racer_escaping){ d=rc_escd; npc_target[i]=d; ai_state[i]=AIS_CRUISE; }
        float fx=cosf(d), fz=sinf(d), rx=-sinf(d), rz=cosf(d);   /* forward / driver's right */

        float run_ahead = road_run(c->x,c->z, fx,fz, TILE*3.0f);
        if (ai_state[i]==AIS_CRUISE){
            /* decide whether to commit a turn this frame, and to WHICH cardinal:
             *  - road ends straight ahead → must turn (traffic: longest run; racer: toward CP)
             *  - racer only: an open cross-junction is coming AND turning onto it heads
             *    toward the checkpoint → peel off the straight to make the turn. */
            int do_turn = 0; float newd = d; float kerb = run_ahead;
            if (is_racer && !racer_escaping){
                /* Descend the cost field: once per TILE, among the cardinals that have a real
                 * road run (best_turn_toward's >=2-tile gate → never a wedge), pick the one
                 * that most reduces routed distance to the checkpoint. Deciding per-tile (not
                 * per-frame) lets the car commit and drive smoothly instead of thrashing. */
                static int rc_dtx=-9999, rc_dtz=-9999;
                int ctx=(int)(c->x/TILE), ctz=(int)(c->z/TILE);
                if (ctx!=rc_dtx || ctz!=rc_dtz){
                    rc_dtx=ctx; rc_dtz=ctz;
                    float want = best_turn_toward(c->x,c->z, d, rcx,rcz, 1, 0);
                    if (fabsf(ang_diff(want,d)) > 0.1f){ do_turn=1; newd=want; kerb=TILE*1.0f; }
                }
                if (!do_turn && run_ahead < TILE*1.5f){         /* road ends straight ahead → must turn */
                    do_turn=1; newd = best_turn_toward(c->x,c->z,d, rcx,rcz, 0,1);
                }
            } else if (!is_racer && run_ahead < TILE*1.5f){
                do_turn = 1; newd = best_turn(c->x,c->z,d,0);
            }
            if (do_turn){                                        /* road ends straight ahead → turn */
                float odx=fx, odz=fz;                            /* old heading + room to the kerb */
                d = newd; npc_target[i]=d; ai_state[i]=AIS_TURN;
                fx=cosf(d); fz=sinf(d); rx=-sinf(d); rz=cosf(d);
                /* exit waypoint by TURN DIRECTION: rights HUG the near corner (shallow in,
                 * early out); lefts drive DEEPER into the junction before turning across —
                 * neither swings onto the oncoming side. */
                float cross = odx*fz - odz*fx;                   /* >0 = right turn */
                float in_k  = cross>0.5f ? 0.35f : 0.80f;        /* how far into the junction */
                float out_k = cross>0.5f ? 1.25f : 2.10f;        /* how far along the new road */
                float ex=c->x + odx*(kerb*in_k) + fx*(TILE*out_k);
                float ez=c->z + odz*(kerb*in_k) + fz*(TILE*out_k);
                float rr=road_run(ex,ez, rx,rz, 6.0f);           /* nudge toward the right kerb */
                float pull=rr - (VSTAT[c->type].wid*0.5f+0.9f); if(pull<0) pull=0; if(pull>2.2f) pull=2.2f;
                turn_wx[i]=ex+rx*pull; turn_wz[i]=ez+rz*pull;
            }
        } else { /* AIS_TURN: chase the exit waypoint; done once aligned/past it and the road opens */
            float wdx=turn_wx[i]-c->x, wdz=turn_wz[i]-c->z;
            int passed = (wdx*fx+wdz*fz) < 0.6f || (wdx*wdx+wdz*wdz) < 2.0f;
            if ((passed || fabsf(ang_diff(d,ba)) < 0.20f) && road_run(c->x,c->z, fx,fz, TILE*1.7f) >= TILE*1.5f)
                ai_state[i]=AIS_CRUISE;
        }
        int turning=(ai_state[i]==AIS_TURN), blocked=car_ahead(i);
        int approach = (!turning && run_ahead < TILE*2.6f);      /* a turn is coming → ease off early */
        /* HEAD-ON DODGE: someone is coming straight at me in MY lane (a bad spawn or a
         * mid-turn stray) — squeeze hard toward my right kerb and ease off. */
        float dodge = 0.0f;
        if (!turning){
            float hc=cosf(ba), hs=sinf(ba);
            for (int j=0;j<NCAR;j++){ if(j==i||!cars[j].alive) continue;
                float dx=cars[j].x-c->x, dz=cars[j].z-c->z;
                float fwd=dx*hc+dz*hs; if (fwd<1.0f || fwd>12.0f) continue;
                float lat=-dx*hs+dz*hc; if (fabsf(lat)>1.7f) continue;
                if (fabsf(ang_diff(bodies[j].angle, ba)) > 2.5f){ dodge=1.0f; break; } }
        }
        /* RED LIGHT: stop at the near edge of the junction ahead.
         *
         * Reuses `blocked`, which already cuts the throttle, so a stopping car
         * needs no new per-car state — the whole feature is one global clock.
         *
         * A car ALREADY inside the junction is never stopped: it must clear,
         * and amber exists so it can. The probe looks one tile ahead, which at
         * cruising speed is about where you would start braking. */
        int at_red = 0;
        if (!blocked && !turning){
            int px = (int)((c->x + fx*TILE*1.15f)/TILE), pz = (int)((c->z + fz*TILE*1.15f)/TILE);
            if (is_junction(px, pz) && !is_junction((int)(c->x/TILE), (int)(c->z/TILE))) {
                int st = light_state(px, pz, light_axis(ba));
                if (st == LIGHT_RED) { blocked = 1; at_red = 1; }
            }
        }
        red_wait[i] = (uint8_t)at_red;

        /* JUNCTION YIELD: give way to a MOVING perpendicular crosser near my entry point.
         * Priority: a car already IN the junction goes first; equal approaches → lower index
         * (a total order, so two arrivals can never mutually wait). */
        if (!blocked && !turning){
            float jx=c->x+fx*TILE*1.15f, jz=c->z+fz*TILE*1.15f;
            for (int j=0;j<NCAR;j++){ Car*o=&cars[j]; if(j==i||!o->alive||o->driver!=DRV_NPC) continue;
                float dx=o->x-jx, dz=o->z-jz, od2=dx*dx+dz*dz; if(od2>25.0f) continue;
                float ospd=sqrtf(bodies[j].vx*bodies[j].vx+bodies[j].vy*bodies[j].vy);
                if (ospd<1.5f) continue;                            /* only yield to a MOVING crosser */
                float rel=fabsf(ang_diff(bodies[j].angle, d));
                if (rel<0.9f || rel>2.3f) continue;                 /* perpendicular crossers only */
                if (od2 < 9.0f || j < i){ blocked=1; break; } }
        }

        /* target heading */
        float target;
        if (turning){
            target = atan2f(turn_wz[i]-c->z, turn_wx[i]-c->x);   /* pursue the corner exit point */
        } else {
            /* hold a chosen RIGHT-side lane (not always the kerb lane); more lanes fit on
             * wider roads. Occasionally change lane, staying in the right half. */
            float rdist=road_run(c->x,c->z, rx,rz, 7.0f);
            float ldist=road_run(c->x,c->z,-rx,-rz, 7.0f);
            float halfw=(rdist+ldist)*0.5f, want_min=v->wid*0.5f+0.7f;
            int maxlane=(int)((halfw-want_min)/3.6f); if(maxlane<0) maxlane=0;
            if (frand()<0.004f){ int lp=(int)lane_pref[i]+(irand(2)?1:-1);
                if(lp<0)lp=0; if(lp>maxlane)lp=maxlane; lane_pref[i]=(uint8_t)lp; }   /* lane change */
            int lp=lane_pref[i]; if(lp>maxlane) lp=maxlane;
            float want = want_min + (float)lp*3.6f;              /* this lane's clearance to right kerb */
            float off = mote_clampf(rdist - want, -3.5f, 3.5f);  /* +=move right toward the lane */
            if (dodge>0){ off = mote_clampf(rdist - (v->wid*0.5f+0.5f), 0.0f, 3.5f); }   /* hug the kerb */
            float L = 5.5f + fabsf(spd)*0.6f;                    /* look-ahead (speed-scaled) → damping */
            target = atan2f((c->z+fz*L+rz*off) - c->z, (c->x+fx*L+rx*off) - c->x);
        }

        float throttle = blocked ? 0.0f : (turning ? 0.45f : (approach ? 0.5f : (dodge>0 ? 0.5f : 1.0f)));
        if (stuck_t[i] > 1.0f && !red_wait[i]){ blocked=0;       /* recovery: push, or reverse if wedged */
            throttle = (road_run(c->x,c->z, fx,fz, TILE*1.4f) < TILE*0.9f) ? -0.9f : 1.0f; }
        /* A red light BRAKES; every other `blocked` reason keeps coasting, which
         * is what queueing behind another car should feel like. */
        ai_drive_b(i, target, throttle, at_red ? 0.85f : 0.0f, dt);

        float cc=cosf(ba), ss=sinf(ba), fs=b->vx*cc+b->vy*ss;    /* cap forward speed */
        float cap = blocked ? 2.0f : (turning ? 3.0f : (approach ? 4.6f : 9.5f));
        if (is_racer && !blocked){
            /* RUBBER-BAND top speed: a race car, faster than traffic on the straights,
             * eased when ahead of the player and floored when behind so the race stays
             * close and winnable. Corners still cap low (fast turns cut the lane and hit
             * the road-clamp) but a touch above traffic. */
            float rds;
            if      (rival_i > cp_i) rds = RIVAL_CAP_AHEAD;      /* a checkpoint ahead → back off */
            else if (rival_i < cp_i) rds = RIVAL_CAP_BEHIND;    /* behind → chase hard */
            else {                                              /* same leg → match the player's gap */
                float pdx=cp_x[cp_i]-pl_x(), pdz=cp_z[cp_i]-pl_z(), pd=sqrtf(pdx*pdx+pdz*pdz);
                float rdx=rcx-c->x, rdz=rcz-c->z, rrd=sqrtf(rdx*rdx+rdz*rdz);
                rds = rrd < pd-6.0f ? RIVAL_CAP_EVEN_LO : (rrd > pd+6.0f ? RIVAL_CAP_BEHIND : RIVAL_CAP_EVEN);
            }
            cap = turning ? 4.2f : (approach ? 6.0f : rds);   /* takes corners quicker than traffic */
        }
        if (fs>cap){ float lx=b->vx-cc*fs, lz=b->vy-ss*fs; b->vx=cc*cap+lx; b->vy=ss*cap+lz; }
#ifdef MOTE_HOST
        if (is_racer && getenv("MOTE_GTA_RTRACE"))
            fprintf(stderr,"[RTRACE] p=(%.1f,%.1f) d=%.2f cost=%.0f state=%d turn=%d on=%d ra=%.1f spd=%.1f st=%.1f\n",
                c->x,c->z, d, race_cost(c->x,c->z), ai_state[i], turning, road_world(c->x,c->z), run_ahead, spd, stuck_t[i]);
#endif
    }
}

/* headless AI instrumentation — set MOTE_GTA_DEBUG=1 to log lane-keeping health each ~1s */
static void ai_debug(float dt){
#ifdef MOTE_HOST
    static int on=-1; if(on<0) on = getenv("MOTE_GTA_DEBUG")?1:0; if(!on) return;
    static float acc; static int frames, s_n, s_off, s_stuck; static float s_spd, s_lat;
    for (int i=0;i<NCAR;i++){ Car*c=&cars[i]; if(!c->alive||c->driver!=DRV_NPC) continue;
        MoteBody2D*b=&bodies[i]; float spd=sqrtf(b->vx*b->vx+b->vy*b->vy);
        float ca=cosf(b->angle), sa=sinf(b->angle);
        float lat=fabsf(-b->vx*sa + b->vy*ca);   /* sideways speed = wiggle/slide */
        s_n++; s_spd+=spd; s_lat+=lat; if(!road_world(c->x,c->z)) s_off++; if(spd<1.5f) s_stuck++; }
    frames++; acc+=dt;
    if (acc>=1.0f){ if(s_n>0) fprintf(stderr,"[AI] npc/f=%.1f offroad=%.0f%% stuck=%.0f%% avgspd=%.1f wiggle=%.2f\n",
            (float)s_n/frames, 100.0f*s_off/s_n, 100.0f*s_stuck/s_n, s_spd/s_n, s_lat/s_n);
        acc=0; frames=0; s_n=s_off=s_stuck=0; s_spd=0; s_lat=0; }
#else
    (void)dt;
#endif
}

static void footcop_fire(Ped *p, float px, float pz);
static int  player_in_gun_reach(void);
static void sfx(const MoteSfx *s, float g);
static void rmbl(float in, int ms);          /* forward: the ped brawl uses both */
static void hurt_player(float dmg);
static void wreck_car(Car *c);
static void mission_win(void);
/* people cannot walk through/over cars (cars hitting THEM at speed is do_runovers') */
static int ped_blocked_by_car(float x, float z){
    for (int i=0;i<NCAR;i++){ Car*cc=&cars[i]; if(!cc->alive) continue;
        float dx=x-cc->x, dz=z-cc->z; if (dx*dx+dz*dz>36.0f) continue;
        float ca=cosf(cc->yaw), sa=sinf(cc->yaw);
        float lx=dx*ca+dz*sa, ly=-dx*sa+dz*ca;
        if (fabsf(lx)<bodies[i].hx+0.25f && fabsf(ly)<bodies[i].hy+0.25f) return 1; }
    return 0;
}
static void update_peds(float dt) {
    float px = (player.mode==MODE_CAR)? cars[player.car].x : player.x;
    float pz = (player.mode==MODE_CAR)? cars[player.car].z : player.z;
    int   armed = (player.mode==MODE_FOOT && weapon != W_FIST);  /* gun drawn on foot */
    if (g_panic > 0) g_panic -= dt;
    for (int i=0;i<NPED;i++) {
        Ped *p=&peds[i];
        if (!p->alive) continue;
        if (p->iscop){                                    /* bailed officer: close in, then shoot */
            float dx=px-p->x, dz=pz-p->z, cd2=dx*dx+dz*dz;
            if (wanted()==0){                              /* no heat: walk the BEAT (and witness) */
                int extra=0, seen=0;                       /* keep one; extras drift off-screen */
                for (int j2=0;j2<NPED;j2++) if(peds[j2].alive&&peds[j2].iscop){ if(&peds[j2]==p) break; seen++; }
                extra = (seen>=1);
                if (extra && cd2 > 45.0f*45.0f){ p->alive=0; continue; }
                if (frand() < 0.9f*dt) p->yaw=(float)irand(8)*0.7854f;
                { float nx=p->x+cosf(p->yaw)*1.5f*dt, nz=p->z+sinf(p->yaw)*1.5f*dt;
                  if (ped_blocked_by_car(nx,nz) && !ped_blocked_by_car(p->x,p->z)) p->yaw += 2.094f;
                  else if (move_body(&p->x,&p->z, nx, nz, 0)) p->yaw += 2.094f; }
                p->animt += 1.5f*dt*1.2f; continue;
            }
            p->yaw=atan2f(dz,dx); p->firecd-=dt;
            /* ARREST: an officer who reaches you on foot busts you */
            if (player.mode==MODE_FOOT && cd2<2.2f && g_state==ST_PLAY){
                g_state=ST_BUSTED; g_screen_t=2.6f; sfx(&bust_sfx,0.8f); continue; }
            if (cd2>36.0f){ float inv=1.0f/sqrtf(cd2>1e-4f?cd2:1.0f);
                float nx=p->x+dx*inv*3.6f*dt, nz=p->z+dz*inv*3.6f*dt;
                if (!ped_blocked_by_car(nx,nz) || ped_blocked_by_car(p->x,p->z))
                    move_body(&p->x,&p->z, nx, nz, 0);
                p->animt += 3.6f*dt*1.2f; }
            if (cd2<560.0f && player_in_gun_reach())
                footcop_fire(p, px, pz);                        /* fire when in range */
            continue;
        }
        float ddx=p->x-px, ddz=p->z-pz, d2=ddx*ddx+ddz*ddz;
        /* peds stay calm UNLESS: you're near with a gun out, OR someone was recently
         * hurt/shot near them (panic spreads from the violence). Then they flee. */
        int flee=0; float tx=px, tz=pz;
        if (armed && d2 < 64.0f){ flee=1; }                          /* sees your gun (8 m) */
        if (!flee && g_panic > 0){ float dx=p->x-g_panicx, dz=p->z-g_panicz;
            if (dx*dx+dz*dz < 144.0f){ flee=1; tx=g_panicx; tz=g_panicz; } }  /* panic (12 m) */
        /* A crew member comes for you on SIGHT, and keeps coming: the rage is
         * topped up every frame you are inside GANG_SIGHT rather than being a
         * one-shot timer, so they do not lose interest mid-fight. */
        if (p->gang && !p->iscop && d2 < GANG_SIGHT*GANG_SIGHT && g_state==ST_PLAY)
            p->rage = 2.5f;
        if (p->rage > 0.0f) flee = 0;                  /* the brave do not flee */
        if (flee){ p->flee = 1.4f; p->yaw = atan2f(p->z-tz, p->x-tx); }        /* run away from threat */
        if (p->flee>0) p->flee-=dt;
        /* FIGHTING BACK: close on the player and swing. Slower than a sprint —
         * you can always outrun them — and it times out, so a brawl does not
         * follow you across the city. */
        if (p->rage > 0.0f) {
            p->rage -= dt;
            p->flee = 0.0f;
            p->yaw = atan2f(pz - p->z, px - p->x);
            if (d2 < 3.2f) {
                p->firecd -= dt;
                if (p->firecd <= 0.0f) {
                    p->firecd = 0.85f;
                    hurt_player(5);
                    sfx(&punch_sfx, 0.45f);
                    rmbl(0.35f, 90);
                }
            }
        }
        float spd = (p->rage>0.0f) ? 3.4f : (p->flee>0 ? 4.2f : 1.3f);
        {
            int onr = is_roadlike((int)(p->x/TILE),(int)(p->z/TILE));
            if (!onr && frand() < (p->flee>0?0.0f:1.2f)*dt) p->yaw = (float)irand(8)*0.7854f;
        }
        float dx=cosf(p->yaw), dz=sinf(p->yaw);
        float nx=p->x+dx*spd*dt, nz=p->z+dz*spd*dt;
        /* calm peds only step onto a road AT A ZEBRA; once crossing they hold
         * course until they're back on the far pavement (fleeing peds ignore
         * the highway code, understandably) */
        int on_road = is_roadlike((int)(p->x/TILE),(int)(p->z/TILE));
        if (p->flee<=0){
            int nx_t=(int)(nx/TILE), nz_t=(int)(nz/TILE);
            int to_road = is_roadlike(nx_t,nz_t);
            if (!on_road && to_road && !zebra_at(nx_t,nz_t)){
                p->yaw += 2.094f;                             /* no jaywalking: turn away */
                p->animt += spd*dt*1.2f; continue;
            }
        }
        if (ped_blocked_by_car(nx,nz) && !ped_blocked_by_car(p->x,p->z)) p->yaw += 2.094f;
        else if (move_body(&p->x,&p->z, nx, nz, 0)) p->yaw += 2.094f;   /* turn on bump */
        else if (on_road && p->flee<=0) { /* mid-crossing: hold course */ }
        p->animt += spd*dt*1.2f;
    }
}

/* =================================================== crime layer helpers === */
static int wanted(void){ int w=(int)heat; return w>5?5:w; }
static void say(const char *m){ g_msg=m; g_msg_t=2.2f; }
/* Throttle repeated SFX so a crowd run-over (many cash/crash sounds in a few
 * frames) can't stack dozens of synth voices and stall the frame. Each distinct
 * recipe replays at most ~18x/sec; rumble is capped similarly. */
/* Slot 0: the record and the preferences, written together because they share
 * one blob. Called on every toggle and once more as the death screen fades. */
static void save_prefs(void){
    if (!mote->save) return;
    int b[3] = { SAVE0_MAGIC, best_cash,
                 (g_sound_on ? 1 : 0) | ((g_slot & 3) << 1) };
    mote->save(0, b, sizeof b);
}

static void sfx(const MoteSfx *s, float g){
    /* ONE gate for every sample in the game. The engine drone is separate and
     * is silenced at its own source — see g_eng_a in g_update. */
    if (!g_sound_on) return;
    if (!mote->audio_play_sfx) return;
    if (!mote->micros){ mote->audio_play_sfx(s,g); return; }
    static const MoteSfx *lp[8]={0}; static uint32_t lt[8]={0};
    uint32_t now = mote->micros();
    for (int i=0;i<8;i++) if (lp[i]==s){ if (now-lt[i]<55000u) return; lt[i]=now; mote->audio_play_sfx(s,g); return; }
    int o=0; for (int i=1;i<8;i++) if (lt[i]<lt[o]) o=i;
    lp[o]=s; lt[o]=now; mote->audio_play_sfx(s,g);
}
static uint32_t g_lastrumble;
static void rmbl(float in, int ms){
    if (!mote->rumble) return;
    uint32_t now = mote->micros ? mote->micros() : 0;
    if (mote->micros && now-g_lastrumble < 130000u) return;
    g_lastrumble = now; mote->rumble(in, ms);
}
static void add_heat(float a){ heat += a; if(heat>6) heat=6; heat_cool=0; }
/* Hitting a squad car is ALWAYS a felony, worth at least one full star.
 *
 * This used to be add_heat(0.55f), which could never show anything: the wanted
 * level is (int)heat, so half a point reads as zero stars and ramming a police
 * car looked like it did nothing at all. It now floors heat at 1.0 on the first
 * hit and adds half a star for each one after.
 *
 * The cooldown is because contact lasts several frames — without it a single
 * scrape would ladder you to six stars in under a second. */
static float g_ramcd;
static void cop_rammed(void) {
    if (g_ramcd > 0.0f) return;
    g_ramcd = 1.2f;
    if (heat < 1.0f) heat = 1.0f; else heat += 0.5f;
    if (heat > 6.0f) heat = 6.0f;
    heat_cool = 0;
    say("HIT A COP CAR");
}
/* line of sight blocked by buildings (samples the tile map every ~2 m) */
static int sight_clear(float x0,float z0,float x1,float z1){
    float dx=x1-x0, dz=z1-z0, d=sqrtf(dx*dx+dz*dz);
    int n=(int)(d*0.5f)+1;
    for (int k=1;k<n;k++){ float t=(float)k/(float)n;
        char c=tile_at((int)((x0+dx*t)/TILE),(int)((z0+dz*t)/TILE));
        if (c=='#'||c=='O'||c=='H') return 0; }
    return 1;
}
/* does any officer WITNESS an incident at (x,z)? sight = 30 m + LOS; loud incidents
 * (gunfire, explosions) are HEARD to 45 m regardless of line of sight. */
static int cops_witness(float x,float z,int loud){
    float R = loud?45.0f:30.0f, R2=R*R;
    for (int i=0;i<NCAR;i++){ Car*c=&cars[i];
        if (!c->alive || c->driver!=DRV_COP) continue;
        float dx=c->x-x, dz=c->z-z;
        if (dx*dx+dz*dz<R2 && (loud || sight_clear(c->x,c->z,x,z))) return 1; }
    for (int i=0;i<NPED;i++){ Ped*p=&peds[i];
        if (!p->alive || !p->iscop) continue;
        float dx=p->x-x, dz=p->z-z;
        if (dx*dx+dz*dz<R2 && (loud || sight_clear(p->x,p->z,x,z))) return 1; }
    return 0;
}
/* heat only rises when the law can see (or hear) the crime */
static void add_heat_at(float a,float x,float z,int loud){ if (cops_witness(x,z,loud)) add_heat(a); }
static void panic_at(float x,float z){ g_panic=4.5f; g_panicx=x; g_panicz=z; }  /* violence → peds nearby flee */
static void add_fx(float x,float z,int k){ for(int i=0;i<NFX;i++) if(fxs[i].t<=0){ fxs[i]=(Fx){x,z,(k==3)?0.9f:0.45f,(uint8_t)k}; return; } }
static void add_pickup(float x,float z,int kind){ for(int i=0;i<NPICK;i++) if(!picks[i].alive){ picks[i]=(Pickup){x,z,(uint8_t)kind,1,0}; return; } }

/* The player's height. Everything in this game is 2D except the helicopter, so
 * this is zero for every other state and the callers below are the only places
 * that care. */
static float pl_y(void){
    return (player.mode==MODE_CAR && player.car>=0 &&
            cars[player.car].type==VEH_HELI) ? g_heli_y : 0.0f;
}
/* How high small arms reach. Bullets are 2D — x, z and no height at all — so
 * without this gate a beat officer on the pavement shoots down a helicopter at
 * the 45 m ceiling. Below it you are in range and flying low over a chase is
 * genuinely dangerous; above it they can only watch. */
#define HELI_GUN_Y 18.0f
static int player_in_gun_reach(void){ return pl_y() <= HELI_GUN_Y; }
static float pl_x(void){ return player.mode==MODE_CAR ? cars[player.car].x : player.x; }
static float pl_z(void){ return player.mode==MODE_CAR ? cars[player.car].z : player.z; }
static float pl_yaw(void){ return player.mode==MODE_CAR ? cars[player.car].yaw : player.yaw; }

/* The camera's tile-solidity test. Buildings block; bridges, roads and water do
 * not — driving a bridge with the camera snapping to the deck would be worse
 * than letting it fly. */
static int cam_solid(int tx, int tz, void *ud) {
    (void)ud;
    char c = tile_at(tx, tz);
    return c == '#' || c == 'O' || c == 'H';
}

/* Place the chase camera and publish everything the rest of the file reads:
 * cam_basis + cam_pos for the engine and world_to_screen, view_x/view_z as the
 * centre the draw windows iterate around, and g_view as this frame's cone. */
static void chase_camera(float tx, float tz, float yaw, float dt) {
    /* Reset on discontinuity rather than at every player.mode assignment. There
     * are ~15 of those plus a debug teleport, so detecting it here is the only
     * version a later edit cannot forget: a mode change or a jump no walk or
     * drive could produce means the old smoothed pose is meaningless. */
    static int   g_cam_mode = -1;
    static float g_cam_lastx, g_cam_lastz;

    float jx = tx - g_cam_lastx, jz = tz - g_cam_lastz;
    if (player.mode != g_cam_mode || jx*jx + jz*jz > 64.0f) gta3_cam_reset(&g_cam);
    g_cam_mode = player.mode; g_cam_lastx = tx; g_cam_lastz = tz;

    float dist = CAM_FOOT_D, height = CAM_FOOT_H, look = CAM_FOOT_L;
    if (player.mode == MODE_CAR && cars[player.car].type == VEH_HELI) {
        dist = CAM_HELI_D; height = CAM_HELI_H; look = CAM_HELI_L;
    } else if (player.mode == MODE_CAR) {
        float s = fabsf(cars[player.car].spd) / CAM_SPD;
        if (s > 1.0f) s = 1.0f;
        dist   = CAM_CAR_D0 + (CAM_CAR_D1 - CAM_CAR_D0) * s;
        height = CAM_CAR_H0 + (CAM_CAR_H1 - CAM_CAR_H0) * s;
        look   = CAM_CAR_L0 + (CAM_CAR_L1 - CAM_CAR_L0) * s;
        /* BIG VEHICLES need the camera further back and a lot higher. The
         * framing above is one set of numbers for every vehicle, tuned on a
         * 4.5 m car; behind an 8.6 m bus or a tank with a turret on it the eye
         * sits below the roofline and you cannot see the road at all. Scaling
         * on length alone is enough because in this game the long vehicles are
         * also the tall ones. Height is lifted harder than distance: the
         * problem is seeing OVER the thing, not being close to it. */
        float big = mote_clampf((VSTAT[cars[player.car].type].len - 4.8f) / 3.8f,
                                0.0f, 1.0f);
        /* The tank is the one vehicle whose height its LENGTH does not
         * predict: at 6.2 m it scores 0.37, but the turret sitting on top of
         * the hull makes it taller in the frame than the 8.6 m bus. */
        if (cars[player.car].type == VEH_TANK && big < 0.80f) big = 0.80f;
        dist   *= 1.0f + big * 0.55f;
        height *= 1.0f + big * 1.10f;
        look   *= 1.0f + big * 0.40f;
    }
    /* Gate on MODE_FOOT at the point of USE, not at each mode transition.
     * player.mode can flip to CAR inside the on-foot input branch (jacking a
     * car with A), so the branch that clears this flag does not run until the
     * next frame — and that same frame is when the discontinuity guard resets
     * the camera, whose snap path has no smoothing. The result was a one-frame
     * hard-snap to a reversed pose on car entry with LB held. Gating here is
     * immune to whichever path changed the mode, and to paths added later. */
    if (g_lookback && player.mode == MODE_FOOT) { dist *= 0.8f; yaw += 3.14159265f; }

    /* An airborne anchor lifts BOTH the eye and the look target (see
     * gta3_cam_update_y), and above the tallest roof the tile-grid collision
     * DDA is switched off — it has no notion of height, so it would shove the
     * camera forward for a building the helicopter is flying over. */
    float anchor_y = 0.0f; int above_roofs = 0;
    if (player.mode==MODE_CAR && player.car>=0 && cars[player.car].type==VEH_HELI) {
        anchor_y = g_heli_y;
        above_roofs = (g_heli_y > g_lvl_h[NBLV-1] + 1.0f);
    }
    gta3_cam_update_y(&g_cam, tx, anchor_y, tz, yaw, dist, height, look, dt,
                      above_roofs ? 0 : cam_solid, 0, TILE);

    cam_pos   = g_cam.eye;
    cam_basis = mote_camera_look(g_cam.eye, g_cam.target);
    /* The draw windows iterate tiles around a centre. Centre them on a point
     * ahead of the camera, not on the camera itself: almost everything drawn is
     * in front, so a window centred on the eye wastes half its span behind. */
    view_x = g_cam.eye.x + cam_basis.r[2].x * 40.0f;
    view_z = g_cam.eye.z + cam_basis.r[2].z * 40.0f;

    gta3_view_set(&g_view, g_cam.eye, cam_basis.r[2], FOV, 1.45f);
}

static void place_markers(void) {
    /* snap each marker to the nearest pavement tile around a target block; the
     * STARTER set clusters around wherever the player spawned this run. */
    int cx=(int)(player.x/TILE), cz=(int)(player.z/TILE);
    /* spread across the WHOLE city: one phone per district (4x4 grid), gun shops and
     * pay-n-sprays in alternating far districts, plus the central starter set */
    struct { int tx,tz,kind; } want[24]; int nwant=0;
    want[nwant++]=(typeof(want[0])){cx-8,cz-6,MK_GUN};
    want[nwant++]=(typeof(want[0])){cx+10,cz+8,MK_SPRAY};
    want[nwant++]=(typeof(want[0])){cx-4,cz+10,MK_PHONE};
    want[nwant++]=(typeof(want[0])){cx+12,cz-8,MK_PHONE};
    for (int gz=0; gz<4; gz++) for (int gx=0; gx<4; gx++){
        int bx = gx*(MAPW/4) + MAPW/8 + (int)(frand()*20)-10;
        int bz = gz*(MAPH/4) + MAPH/8 + (int)(frand()*20)-10;
        if ((bx-cx)*(bx-cx)+(bz-cz)*(bz-cz) < 30*30) continue;   /* centre already served */
        int kind = MK_PHONE;
        if ((gx+gz)==2) kind=MK_GUN; else if ((gx+gz)==4) kind=MK_SPRAY;
        if (nwant<24) want[nwant++]=(typeof(want[0])){bx,bz,kind};
    }
    nmark=0; g_ngar=0;
    /* the SELL DOCK: a water-side drivable spot that is REACHABLE on the road network
     * from the spawn (flood fill — the map has isolated road fragments that look like
     * piers but connect to nothing). Prefers 20-90 tiles out, else nearest reachable. */
    { static uint8_t rvis[(MAPW*MAPH+7)/8];               /* road-reachability bitmap */
      uint16_t *q = rd_q;   /* borrow the road-BFS queue (transient; not in use at reset) — saves 8 KB RAM */
      for (unsigned i=0;i<sizeof rvis;i++) rvis[i]=0;
      int sx0=-1, sz0=-1;                                 /* nearest road to the spawn */
      for (int r=0;r<12 && sx0<0;r++)
          for (int dz=-r;dz<=r && sx0<0;dz++) for (int dx=-r;dx<=r;dx++)
              if (is_drivable(cx+dx,cz+dz)){ sx0=cx+dx; sz0=cz+dz; break; }
      if (sx0>=0){
          int head=0, tail=0;
          #define RIDX(x,z) ((z)*MAPW+(x))
          rvis[RIDX(sx0,sz0)>>3] |= 1<<(RIDX(sx0,sz0)&7);
          q[tail++] = (uint16_t)((sz0<<8)|sx0);           /* packed: works while MAPW,MAPH<=256 */
          while (head!=tail){
              uint16_t pc=q[head++ & 4095]; if(head>65000) break;
              int x=pc&0xFF, z=pc>>8;
              static const int DX4[4]={1,-1,0,0}, DZ4[4]={0,0,1,-1};
              for (int k=0;k<4;k++){
                  int nx=x+DX4[k], nz=z+DZ4[k];
                  if (nx<1||nz<1||nx>=MAPW-1||nz>=MAPH-1) continue;
                  if (!is_drivable(nx,nz)) continue;
                  int bi=RIDX(nx,nz);
                  if (rvis[bi>>3] & (1<<(bi&7))) continue;
                  if (((tail+1)&4095)==(head&4095)) continue;   /* ring full: skip (rare) */
                  rvis[bi>>3] |= 1<<(bi&7);
                  q[tail++ & 4095] = (uint16_t)((nz<<8)|nx);
              }
              if (tail>60000) break;
          }
          int best=-1, bx=0, bz=0, bestAny=-1, ax=0, az=0;
          for (int z=2;z<MAPH-2;z++) for (int x=2;x<MAPW-2;x++){
              int bi=RIDX(x,z);
              if (!(rvis[bi>>3] & (1<<(bi&7)))) continue;   /* must be REACHABLE */
              int water=0;
              for (int dz=-2;dz<=2 && !water;dz++) for (int dx=-2;dx<=2;dx++)
                  if (tile_at(x+dx,z+dz)=='~'){ water=1; break; }
              if (!water) continue;
              int d=(x-cx)*(x-cx)+(z-cz)*(z-cz);
              if (bestAny<0 || d<bestAny){ bestAny=d; ax=x; az=z; }
              if (d<20*20 || d>90*90) continue;
              if (best<0 || d<best){ best=d; bx=x; bz=z; }
          }
          if (best<0 && bestAny>=0){ bx=ax; bz=az; best=bestAny; }   /* any reachable water-side spot */
          if (best>=0) markers[nmark++]=(Marker){ bx*TILE+TILE*0.5f, bz*TILE+TILE*0.5f, MK_DOCK };
          #undef RIDX
      }
    }
    for (int m=0;m<nwant;m++){
        int bx=want[m].tx, bz=want[m].tz, fx=bx, fz=bz, found=0;
        if (want[m].kind==MK_SPRAY && g_ngar<NGARAGE){
            /* SPRAY = a drive-in GARAGE BAY carved INTO a building: pick a building tile
             * whose FRONT opens onto pavement leading to a road, and whose BACK (and ideally
             * sides) are still building — a recess in the mass, not a lone edge tile. You
             * drive road -> pavement -> INTO the bay. (ox,oz) = the opening direction. */
            static const int DX[4]={1,-1,0,0}, DZ[4]={0,0,1,-1};
            int gx=0, gz=0, gox=0, goz=0;
            for (int r=1;r<28 && !found;r++)
                for (int dz=-r;dz<=r && !found;dz++) for (int dx=-r;dx<=r && !found;dx++){
                    int x=bx+dx,z=bz+dz; if(x<3||z<3||x>=MAPW-3||z>=MAPH-3) continue;
                    if (!is_solid(x,z)) continue;                            /* the tile we carve is a building */
                    for (int d=0;d<4 && !found;d++){
                        int fx=x+DX[d],   fz=z+DZ[d];                        /* front (approach) */
                        int f2x=x+DX[d]*2,f2z=z+DZ[d]*2;                     /* one further out */
                        int kx=x-DX[d],   kz=z-DZ[d];                        /* back (must stay a wall) */
                        if (tile_at(fx,fz)!=',') continue;                  /* opening faces PAVEMENT */
                        if (tile_at(f2x,f2z)!='.' && tile_at(f2x,f2z)!=',') continue;  /* which reaches the street */
                        if (!is_solid(kx,kz)) continue;                     /* back wall behind the bay */
                        gx=x; gz=z; gox=DX[d]; goz=DZ[d]; found=1;
                    } }
            if (found){
                g_gar[g_ngar++] = (typeof(g_gar[0])){ (int16_t)gx,(int16_t)gz, MK_SPRAY, (int8_t)gox,(int8_t)goz };
                markers[nmark++] = (Marker){ gx*TILE+TILE*0.5f, gz*TILE+TILE*0.5f, MK_SPRAY };
                continue;
            }
            /* no bay found nearby → fall through to a pavement decal */
        }
        /* snap to a STREET-FACING pavement tile (one next to a road) so the shop/phone
         * is always reachable on foot — not buried in a building's inner courtyard. */
        for (int r=0;r<24 && !found;r++)
            for (int dz=-r;dz<=r && !found;dz++) for (int dx=-r;dx<=r && !found;dx++){
                int x=bx+dx,z=bz+dz; if(x<1||z<1||x>=MAPW-1||z>=MAPH-1) continue;
                if (tile_at(x,z)!=',') continue;
                if (is_drivable(x+1,z)||is_drivable(x-1,z)||is_drivable(x,z+1)||is_drivable(x,z-1)){ fx=x; fz=z; found=1; } }
        if (!found)                                          /* fallback: any pavement at all */
            for (int r=0;r<24 && !found;r++)
                for (int dz=-r;dz<=r && !found;dz++) for (int dx=-r;dx<=r && !found;dx++){
                    int x=bx+dx,z=bz+dz; if(x<1||z<1||x>=MAPW-1||z>=MAPH-1) continue;
                    if (tile_at(x,z)==','){ fx=x; fz=z; found=1; } }
        markers[nmark++]=(Marker){ fx*TILE+TILE*0.5f, fz*TILE+TILE*0.5f, (uint8_t)want[m].kind };
    }
#ifdef MOTE_HOST
    if (getenv("MOTE_GTA_DEBUG")){
        fprintf(stderr,"[MARKERS] %d placed:",nmark);
        for (int m2=0;m2<nmark;m2++) fprintf(stderr," %c(%d,%d)","GSPD"[markers[m2].kind],
            (int)(markers[m2].x/TILE),(int)(markers[m2].z/TILE));
        fprintf(stderr,"\n");
    }
#endif
}

static int g_kills;
static void kill_ped(int i, int gore) {
    Ped *p=&peds[i]; if(!p->alive) return;
    p->alive=0; g_kills++;
    add_fx(p->x,p->z,0); add_fx(p->x+0.4f,p->z-0.3f,0);
    panic_at(p->x,p->z);          /* a death near here scares everyone */
    if (p->iscop){ cash+=100; add_heat_at(1.2f,p->x,p->z,0); float_txt(p->x,p->z,"+$100");
        if (irand(2)) add_pickup(p->x,p->z,PK_PISTOL); }   /* ...and sometimes his sidearm */
    else { add_pickup(p->x,p->z,PK_CASH); add_heat_at(gore?0.6f:0.5f, p->x,p->z, 0); }
    /* THE CREW'S TAKINGS. Dropped by whoever goes down last rather than by a
     * nominated member, so you cannot lose the prize by killing the wrong one
     * first — and you have to finish all four to see any of it. */
    if (p->gang && g_gang_alive) {
        g_gang_alive--;
        if (g_gang_alive == 0) {
            for (int k = 0; k < GANG_PURSE; k++) {
                float a = (float)k * (6.2831853f / GANG_PURSE);
                add_pickup(p->x + cosf(a)*1.1f, p->z + sinf(a)*1.1f, PK_CASH);
            }
            say("THE CREW'S TAKINGS");
        }
    }
    /* KILL STREAK: chain kills inside 2.5 s for escalating bonus cash */
    { static float last_kill_t; static int streak;
      float now=(float)(mote->micros()/1000000.0);
      if (now-last_kill_t < 2.5f) streak++; else streak=1;
      last_kill_t=now;
      if (streak>=2){ int bonus=25*streak; cash+=bonus;
          char b[10]; b[0]='X'; b[1]='0'+(streak>9?9:streak); b[2]=' '; b[3]='+'; b[4]='$';
          int n=bonus,k=5; char d[4]; int dn=0; while(n){d[dn++]='0'+n%10;n/=10;} while(dn) b[k++]=d[--dn]; b[k]=0;
          float_txt(p->x,p->z-1.0f,b); } }
    if (mission==MI_RAMPAGE) mission_kills++;
    else if (mission==MI_VIGIL && !p->iscop) mission_kills++;   /* any gang member on the street counts */
}

static void fire_weapon(void) {
    if (fire_cd>0) return;
    float yaw = pl_yaw();
    if (weapon==W_FIST) {                                    /* melee */
        fire_cd = 0.3f; sfx(&punch_sfx,0.7f);
        float fxp=cosf(yaw), fzp=sinf(yaw), hx=pl_x()+fxp*1.4f, hz=pl_z()+fzp*1.4f;
        for (int i=0;i<NPED;i++){ Ped*p=&peds[i]; if(!p->alive) continue;
            float dx=p->x-hx,dz=p->z-hz; if(dx*dx+dz*dz<3.2f){ if(--p->hp<=0) kill_ped(i,1);
                else { add_fx(p->x,p->z,0);
                       /* Punched: most run, the brave square up. */
                       if (ped_brave(i) && !p->iscop) p->rage = 6.0f; else p->flee = 1.5f; } break; } }
        if (g_dm && rp_hp>0 && !rp_mode){ float dx=rp_x-hx,dz=rp_z-hz;
            if (dx*dx+dz*dz<3.2f){ dm_send2('D',12); add_fx(rp_x,rp_z,0); } }
        add_heat_at(0.05f, pl_x(), pl_z(), 0); return;
    }
    if (ammo[weapon]<=0){ say("NO AMMO"); fire_cd=0.25f; return; }
    if (weapon==W_ROCKET){
        /* ROCKET LAUNCHER: the tank's shell as a shoulder weapon */
        ammo[weapon]--; fire_cd=W_CD[weapon]; g_aim_t=0.8f;
        float ry=pl_yaw();
        float mx0=pl_x()+cosf(ry)*2.6f, mz0=pl_z()+sinf(ry)*2.6f;   /* clear of yourself */
        add_fx(mx0,mz0,2); sfx(&boom_sfx,0.45f); rmbl(0.5f,120);
        panic_at(pl_x(),pl_z()); add_heat_at(0.25f, pl_x(), pl_z(), 1);
        for (int b=0;b<NBULLET;b++) if(!bullets[b].alive){
            bullets[b]=(Bullet){ mx0,mz0, cosf(ry)*34.0f, sinf(ry)*34.0f, 1.5f, 1, 0, 1 }; break; }
        return;
    }
    if (weapon==W_FLAME){
        /* FLAMETHROWER: a licking cone of fire — no bullets, direct burn */
        ammo[weapon]--; fire_cd=W_CD[weapon]; g_aim_t=0.5f;
        float fy2=pl_yaw();
        for (int k=0;k<3;k++){
            float a=fy2+(frand()*2-1)*0.14f, r2=2.0f+frand()*4.6f;
            add_fx(pl_x()+cosf(a)*r2, pl_z()+sinf(a)*r2, 4);
        }
        float fc=cosf(fy2), fs2=sinf(fy2);
        for (int i2=0;i2<NPED;i2++){ Ped*pp=&peds[i2]; if(!pp->alive) continue;
            float dx=pp->x-pl_x(), dz=pp->z-pl_z();
            float fwd=dx*fc+dz*fs2, lat=-dx*fs2+dz*fc;
            if (fwd>0.8f && fwd<6.8f && fabsf(lat)<1.4f){ if(--pp->hp<=0) kill_ped(i2,1); else pp->flee=2.0f; } }
        for (int i2=0;i2<NCAR;i2++){ Car*cc=&cars[i2]; if(!cc->alive||i2==player.car) continue;
            float dx=cc->x-pl_x(), dz=cc->z-pl_z();
            float fwd=dx*fc+dz*fs2, lat=-dx*fs2+dz*fc;
            if (fwd>0.8f && fwd<6.8f && fabsf(lat)<2.0f){ cc->hp-=1.8f; if(cc->hp<=0) wreck_car(cc); } }
        if (g_dm && rp_hp>0){ float dx=rp_x-pl_x(), dz=rp_z-pl_z();
            float fwd=dx*fc+dz*fs2, lat=-dx*fs2+dz*fc;
            if (fwd>0.8f && fwd<6.8f && fabsf(lat)<1.8f) dm_send2('D',3); }
        panic_at(pl_x(),pl_z());
        add_heat_at(0.05f, pl_x(), pl_z(), 0);        /* fire is seen, not heard */
        if (frand()<0.15f) sfx(&boom_sfx,0.15f);
        return;
    }
    if (weapon==W_GRENADE){
        /* GRENADE: a lobbed charge — a slow shell round that flies a beat then blasts */
        ammo[weapon]--; fire_cd=W_CD[weapon]; g_aim_t=0.6f;
        float ry=pl_yaw(); float mx0=pl_x()+cosf(ry)*2.0f, mz0=pl_z()+sinf(ry)*2.0f;
        sfx(&punch_sfx,0.5f); panic_at(pl_x(),pl_z()); add_heat_at(0.2f, pl_x(), pl_z(), 1);
        for (int b=0;b<NBULLET;b++) if(!bullets[b].alive){
            bullets[b]=(Bullet){ mx0,mz0, cosf(ry)*17.0f, sinf(ry)*17.0f, 0.7f, 1, 0, 1 }; break; }  /* shell → explodes at ~12 m */
        return;
    }
    ammo[weapon]--; fire_cd=W_CD[weapon]; g_aim_t=0.8f; panic_at(pl_x(),pl_z());  /* gunshots scare bystanders */
    if (g_dm) dm_send1('F');
    sfx(weapon==W_SHOTGUN?&shotgun_sfx:weapon==W_SMG?&smg_sfx:weapon==W_MINIGUN?&smg_sfx:weapon==W_UZI?&smg_sfx:&shoot_sfx, 0.8f);
    float mx0=pl_x()+cosf(yaw)*1.8f, mz0=pl_z()+sinf(yaw)*1.8f;
    add_fx(mx0,mz0,2);
    for (int k=0;k<W_PELLETS[weapon];k++){
        float a=yaw + (frand()*2-1)*W_SPREAD[weapon];
        for (int b=0;b<NBULLET;b++) if(!bullets[b].alive){
            bullets[b]=(Bullet){ mx0,mz0, cosf(a)*52.0f, sinf(a)*52.0f, 0.55f, 1, 0 }; break; }
    }
    add_heat_at(0.06f, pl_x(), pl_z(), 1);   /* gunfire is HEARD */
}

/* a bailed-out officer on foot: an armed Ped that seeks + fires at the player */
static int spawn_footcop(float x, float z) {
    for (int j=0;j<NPED;j++) if(!peds[j].alive){
        peds[j]=(Ped){ x, z, 0,0, 3,1,4, 0,0, /*iscop*/1, /*firecd*/0.5f }; return 1; }
    return 0;
}
static void footcop_fire(Ped *p, float px, float pz) {
    if (p->firecd>0) return; p->firecd=1.0f+frand()*0.7f;
    float a=atan2f(pz-p->z, px-p->x)+(frand()*2-1)*0.06f;
    float mx0=p->x+cosf(a)*1.2f, mz0=p->z+sinf(a)*1.2f;
    sfx(&shoot_sfx,0.5f);
    for (int b=0;b<NBULLET;b++) if(!bullets[b].alive){
        bullets[b]=(Bullet){ mx0,mz0, cosf(a)*46.0f, sinf(a)*46.0f, 0.7f, 1, 1 }; break; }
}

static void hurt_player(float dmg) {
    health -= dmg; sfx(&hurt_sfx,0.6f); rmbl(0.5f,120);
    if (health<=0){ health=0;
        if (g_dm) dm_die();
        else { g_state=ST_WASTED; g_screen_t=2.6f; sfx(&bust_sfx,0.7f); } }
}

static void wreck_car(Car *c) {
    if (c->wrecked) return;                 /* already a husk — no second explosion */
    add_fx(c->x,c->z,1); for(int k=0;k<4;k++) add_fx(c->x+(frand()*2-1)*1.5f,c->z+(frand()*2-1)*1.5f,1);
    sfx(&boom_sfx,0.9f); rmbl(0.8f,180);
    if (c->driver==DRV_COP){ cash+=150; add_heat_at(1.0f, c->x, c->z, 1); }
    /* PERSISTENT WRECK: the car stays as a burnt husk — visible, pushable, blocks
     * traffic — instead of vanishing. Streamed away only once far off-screen. */
    /* Throw the driver clear. A car that wrecks with someone in it used to
     * simply set driver=DRV_NONE and the occupant ceased to exist; now they
     * bail out beside it and run. A cop bails as an armed officer — he was
     * chasing you a second ago and that should not stop because his car did. */
    if (c->driver == DRV_COP || c->driver == DRV_NPC) {
        float ry = c->yaw + 1.5708f;
        float ex = c->x + cosf(ry)*2.6f, ez = c->z + sinf(ry)*2.6f;
        if (c->driver == DRV_COP) spawn_footcop(ex, ez);
        else for (int j=0;j<NPED;j++) if(!peds[j].alive){
            peds[j] = (Ped){ ex, ez, ry, 0, (uint8_t)irand(4), 1, 2, 0, /*flee*/2.5f, 0, 0, 0 };
            break; }
    }
    c->wrecked=1; c->driver=DRV_NONE; c->hp=0; c->spd=0;
    c->firecd=0.0f;                          /* burn: see the husk fire below */
}

/* big area blast (tank shell / chained wrecks) */
static float g_shell_cd, g_tankrecoil;
/* Shells on board. The tank was an unlimited artillery piece, which made
 * finding it the end of the game rather than a prize you have to spend. It
 * carries TANK_SHELLS rounds and there is no resupply: run it dry and you
 * still have the toughest vehicle in the city, just without the gun. */
#define TANK_SHELLS 10
static int g_shells = TANK_SHELLS;
static float g_turret;      /* tank turret yaw (world) — aims independently of the hull */
static void explode(float x, float z) {
    /* A BIG blast. It was 4.5 m across and did 80 to a car, so a rocket could
     * not even destroy a 100 hp saloon outright — the one thing a rocket is
     * for. Peds die out to 7.5 m, cars take 140 inside 6.6 m (one shot on
     * anything but the tank's 600), and the fx cloud is wider to match. */
    add_fx(x,z,1); for(int k=0;k<10;k++) add_fx(x+(frand()*2-1)*3.6f, z+(frand()*2-1)*3.6f, 1);
    sfx(&boom_sfx,1.0f); rmbl(1.0f,260); add_heat_at(0.8f, x, z, 1);
    for (int p=0;p<NPED;p++){ Ped*pd=&peds[p]; if(!pd->alive) continue;
        float dx=pd->x-x, dz=pd->z-z; if(dx*dx+dz*dz<56.0f) kill_ped(p,1); }
    for (int c=0;c<NCAR;c++){ Car*cc=&cars[c]; if(!cc->alive||cc->driver==DRV_PLAYER) continue;
        float dx=cc->x-x, dz=cc->z-z; if(dx*dx+dz*dz<44.0f){ cc->hp-=140; if(cc->hp<=0) wreck_car(cc); } }
    /* the player takes blast damage too (unless snug in the tank) */
    if (!(player.mode==MODE_CAR && cars[player.car].type==VEH_TANK)){
        float dx=pl_x()-x, dz=pl_z()-z; if(dx*dx+dz*dz<16.0f) hurt_player(28); }
    if (g_dm && rp_hp>0){ float dx=rp_x-x, dz=rp_z-z;
        if (dx*dx+dz*dz<18.0f) dm_send2('D', 34); }
}
static void fire_shell(Car *c) {
    if (g_shell_cd>0) return;
    if (g_shells <= 0) { g_shell_cd = 0.45f; say("NO SHELLS"); return; }
    g_shells--;
    g_shell_cd=1.35f; g_tankrecoil=0.22f;
    sfx(&boom_sfx,0.6f); rmbl(0.6f,150);
    float a=g_turret;                                     /* the TURRET aims, not the hull */
    float mx0=c->x+cosf(a)*4.0f, mz0=c->z+sinf(a)*4.0f;   /* muzzle = barrel tip */
    add_fx(mx0,mz0,2);
    for (int b=0;b<NBULLET;b++) if(!bullets[b].alive){
        bullets[b]=(Bullet){ mx0,mz0, cosf(a)*40.0f, sinf(a)*40.0f, 0.8f, 1, 0, 1 }; break; }
    add_heat_at(0.15f, pl_x(), pl_z(), 1);
}

static void update_bullets(float dt) {
    for (int i=0;i<NBULLET;i++){ Bullet*b=&bullets[i]; if(!b->alive) continue;
        b->life-=dt;
        if (b->shell){                                   /* tank shell: fly, then blast */
            b->x+=b->vx*dt; b->z+=b->vz*dt;
            int boom = b->life<=0.02f || !drivable_world(b->x,b->z);
            for (int p=0;p<NPED && !boom;p++) if(peds[p].alive){ float dx=peds[p].x-b->x,dz=peds[p].z-b->z; if(dx*dx+dz*dz<2.6f) boom=1; }
            for (int c=0;c<NCAR && !boom;c++) if(cars[c].alive && (cars[c].driver!=DRV_PLAYER || b->fromcop)){ float dx=cars[c].x-b->x,dz=cars[c].z-b->z; if(dx*dx+dz*dz<4.0f) boom=1; }
            if (!boom && b->fromcop && player.mode==MODE_FOOT){ float dx=pl_x()-b->x,dz=pl_z()-b->z; if(dx*dx+dz*dz<2.2f) boom=1; }
            if (!boom && g_dm && rp_hp>0){ float dx=rp_x-b->x,dz=rp_z-b->z; if(dx*dx+dz*dz<3.5f) boom=1; }
            if (boom){ explode(b->x,b->z); b->alive=0; }
            continue;
        }
        if(b->life<=0){ b->alive=0; continue; }
        b->x+=b->vx*dt; b->z+=b->vz*dt;
        if (!drivable_world(b->x,b->z)){ add_fx(b->x,b->z,1); b->alive=0; continue; }
        if (b->fromcop){
            float dx=b->x-pl_x(), dz=b->z-pl_z(); float r=(player.mode==MODE_CAR)?2.0f:1.1f;
            if (!player_in_gun_reach()) continue;    /* it cannot climb to you */
            if (dx*dx+dz*dz<r*r){ b->alive=0; add_fx(b->x,b->z,0);
                if(player.mode==MODE_CAR){ cars[player.car].hp-=10; if(cars[player.car].hp<=0){wreck_car(&cars[player.car]); player.mode=MODE_FOOT; player.x=pl_x(); player.z=pl_z(); player.car=-1; hurt_player(20);} }
                else hurt_player(9); }
            continue;
        }
        int hit=0;
        if (g_dm && rp_hp>0){ float dx=b->x-rp_x, dz=b->z-rp_z;
            float r = rp_mode ? 2.0f : 1.1f;
            if (dx*dx+dz*dz<r*r){ hit=1; b->alive=0; add_fx(b->x,b->z,0);
                dm_send2('D', rp_mode?12:20); } }
        for (int p=0;p<NPED && !hit;p++){ Ped*pd=&peds[p]; if(!pd->alive) continue;
            float dx=b->x-pd->x, dz=b->z-pd->z; if(dx*dx+dz*dz<1.1f){ hit=1; b->alive=0;
                if(--pd->hp<=0) kill_ped(p,1);
                else if (ped_brave(p) && !pd->iscop) pd->rage = 6.0f; else pd->flee=1.5f; } }
        for (int c=0;c<NCAR && !hit;c++){ Car*cc=&cars[c]; if(!cc->alive||cc->driver==DRV_PLAYER) continue;
            float dx=b->x-cc->x, dz=b->z-cc->z; if(dx*dx+dz*dz<3.0f){ hit=1; b->alive=0;
                cc->hp-=18; if(cc->hp<=0) wreck_car(cc); } }
    }
}

static void update_pickups(float dt) {
    for (int i=0;i<NPICK;i++){ Pickup*p=&picks[i]; if(!p->alive) continue;
        p->bob+=dt*4;
        float dx=p->x-pl_x(), dz=p->z-pl_z();
        /* HEIGHT MATTERS for the rooftop caches. The reach test is 2D, so
         * without this you would hoover a roof cache up by walking under the
         * building. pl_y() is the helicopter's altitude when you are flying it
         * and zero otherwise, so a roof cache is reachable only by bringing
         * the aircraft level with the roof — which is the point of it. */
        float py = floor_y(p->x, p->z);
        if (fabsf(pl_y() - py) > 3.0f) continue;
        /* A wider reach up there. The 1.5 m the on-foot radius gives is fine
         * when you can walk onto a crate; hovering a 7 m aircraft that
         * precisely is not the game. */
        float reach = (py > 0.5f) ? 16.0f : 2.2f;
        if (dx*dx+dz*dz<reach){ p->alive=0; sfx(&cash_sfx,0.7f);
            if (g_dm){ dm_send2('T',(uint8_t)i); g_dmpkt[i]=20.0f; }
            switch(p->kind){
                case PK_CASH: { int amt=25+irand(40); cash+=amt;
                    char b[10]; b[0]='+'; b[1]='$'; int n=amt,k=2; char d[4]; int dn=0;
                    while(n){d[dn++]='0'+n%10;n/=10;} while(dn) b[k++]=d[--dn]; b[k]=0;
                    float_txt(p->x,p->z,b); } break;
                case PK_HEALTH: health=MAXHP; float_txt(p->x,p->z,"HEALTH"); break;
                case PK_FLAME: owned[W_FLAME]=1; ammo[W_FLAME]+=140; weapon=W_FLAME; float_txt(p->x,p->z,"FLAMER"); break;
                /* 3, not 6: the rocket one-shots cars and clears a crowd now,
                 * so the scarcity IS the balance. */
                case PK_ROCKET: owned[W_ROCKET]=1; ammo[W_ROCKET]+=3; weapon=W_ROCKET; float_txt(p->x,p->z,"ROCKET"); break;
                case PK_PISTOL: owned[W_PISTOL]=1; ammo[W_PISTOL]+=40; weapon=W_PISTOL; float_txt(p->x,p->z,"PISTOL"); break;
                case PK_SMG: owned[W_SMG]=1; ammo[W_SMG]+=80; weapon=W_SMG; float_txt(p->x,p->z,"SMG"); break;
                case PK_SHOTGUN: owned[W_SHOTGUN]=1; ammo[W_SHOTGUN]+=24; weapon=W_SHOTGUN; float_txt(p->x,p->z,"SHOTGUN"); break;
                case PK_PACKAGE: if(mission==MI_PICKUP){ mission_kills++; } float_txt(p->x,p->z,"PACKAGE"); break;
            } }
    }
}

static float g_runhitcd;   /* cooldown so an NPC car doesn't chew the on-foot player every frame */
static void do_runovers(void) {
    if (g_runhitcd>0) g_runhitcd-=0.033f;
    for (int ci=0; ci<NCAR; ci++){ Car*c=&cars[ci]; if(!c->alive) continue;
        float spd=fabsf(c->spd); if(spd<4.0f) continue;
        int is_player = (player.mode==MODE_CAR && ci==player.car);
        float cc=cosf(c->yaw), ss=sinf(c->yaw);
        float hl=bodies[ci].hx+0.3f, hw=bodies[ci].hy+0.3f;    /* the car's own footprint */
        /* pedestrians caught under ANY moving car */
        for (int i=0;i<NPED;i++){ Ped*p=&peds[i]; if(!p->alive) continue;
            float dx=p->x-c->x, dz=p->z-c->z, lx=dx*cc+dz*ss, ly=-dx*ss+dz*cc;
            if (fabsf(lx)<hl && fabsf(ly)<hw){
                if (is_player) kill_ped(i,1);                  /* player's kill: heat + cash + mission */
                else { p->alive=0; add_fx(p->x,p->z,0); add_fx(p->x+0.4f,p->z-0.3f,0); panic_at(p->x,p->z); }
                c->spd*=0.92f; if(is_player) rmbl(0.4f,90);
            } }
        /* an NPC / cop car mowing down the ON-FOOT player */
        if (!is_player && player.mode==MODE_FOOT && spd>5.0f && g_runhitcd<=0){
            float dx=player.x-c->x, dz=player.z-c->z, lx=dx*cc+dz*ss, ly=-dx*ss+dz*cc;
            if (fabsf(lx)<hl && fabsf(ly)<hw){
                hurt_player(spd*3.0f); rmbl(0.6f,160); g_runhitcd=0.6f;   /* fast car = big hit */
                player.x += -ss*1.2f; player.z += cc*1.2f;               /* knocked aside */
            }
        }
    }
}

/* keep cars from driving through each other: push overlapping pairs apart and
 * bleed speed (a bump). Circle approximation, ~car length between centres. */
static float g_copspawn;
static void update_cops(float dt) {
    int w=wanted(), px=pl_x(), pz=pl_z(), alivecops=0;
    for (int i=0;i<NCAR;i++) if(cars[i].alive && cars[i].driver==DRV_COP) alivecops++;
    for (int i=0;i<NPED;i++) if(peds[i].alive && peds[i].iscop) alivecops++;   /* foot cops count too */
    g_copspawn-=dt;
    if (w==0){
        /* AMBIENT PATROLS: one squad car cruising, one beat officer walking. They are
         * the WITNESSES — no officer around means crimes go unreported. */
        static float g_patrolt;
        g_patrolt-=dt;
        int pcars=0, bcops=0;
        for (int i=0;i<NCAR;i++) if(cars[i].alive && cars[i].driver==DRV_COP && cars[i].type!=VEH_TANK){
            pcars++;
            float dx=cars[i].x-px, dz=cars[i].z-pz;
            if (dx*dx+dz*dz > 110.0f*110.0f){                 /* wandered off: bring the patrol back */
                float wx,wz; if (find_road_clear(px,pz, 50.0f, 90.0f, &wx,&wz)){
                    float cy; place_in_lane(&wx,&wz,&cy);
                    cars[i]=(Car){wx,wz,cy,0,CAR_POLICE,DRV_COP,1,100,0}; car_body_init(i); } } }
        for (int i=0;i<NPED;i++) if(peds[i].alive && peds[i].iscop) bcops++;
        if (g_patrolt<=0){
            g_patrolt=2.5f;
            if (pcars<1){ int slot=-1;
                for (int i=0;i<NCAR;i++) if(!cars[i].alive){ slot=i; break; }
                float wx,wz;
                if (slot>=0 && find_road_clear(px,pz, 50.0f, 90.0f, &wx,&wz)){
                    float cy; place_in_lane(&wx,&wz,&cy);
                    cars[slot]=(Car){wx,wz,cy,0,CAR_POLICE,DRV_COP,1,100,0}; car_body_init(slot); } }
            else if (bcops<1){ float ox,oz;
                if (find_near(px,pz, 30.0f, 55.0f, pav_or_grass, &ox,&oz)) spawn_footcop(ox,oz); }
        }
    }
    if (w>0 && alivecops<w && g_copspawn<=0){
        g_copspawn = 1.7f - 0.2f*w;                  /* response quickens with the heat */
        int pairs = (w>=3)? 2 : 1;                   /* 3*+: squad cars roll in PAIRS */
        for (int sn=0; sn<pairs && alivecops<w; sn++){
            int slot=-1;
            for (int i=0;i<NCAR;i++) if(!cars[i].alive){ slot=i; break; }
            if (slot<0) for (int i=0;i<NCAR;i++) if(cars[i].driver==DRV_NONE && i!=player.car){
                float dx=cars[i].x-px, dz=cars[i].z-pz;
                if (dx*dx+dz*dz > 48.0f*48.0f){ slot=i; break; } }
            if (slot<0) break;
            float wx,wz;
            if (find_road_clear(px,pz, 48.0f, 90.0f, &wx,&wz)){
                float cy; place_in_lane(&wx,&wz,&cy);
                cars[slot]=(Car){wx,wz,cy,0,(uint8_t)(irand(2)?CAR_POLICE:CAR_POLICE2),DRV_COP,1,100,0};
                car_body_init(slot); if(sn==0) sfx(&siren_sfx,0.4f);
                alivecops++;
            }
        }
    }
    /* 4*+: ROADBLOCK thrown across the road ahead of a fleeing driver */
    static float g_rblock;
    g_rblock-=dt;
    if (w>=4 && g_rblock<=0 && player.mode==MODE_CAR && player.car>=0 && fabsf(cars[player.car].spd)>7.0f){
        g_rblock=9.0f;
        float hy=cars[player.car].yaw;
        float tx=px+cosf(hy)*62.0f, tz=pz+sinf(hy)*62.0f;      /* well ahead, off-screen */
        int bx=(int)(tx/TILE), bz=(int)(tz/TILE), fx2=-1, fz2=-1;
        for (int r=0;r<4 && fx2<0;r++) for (int dz2=-r;dz2<=r && fx2<0;dz2++) for (int dx2=-r;dx2<=r;dx2++)
            if (is_drivable(bx+dx2,bz+dz2)){ fx2=bx+dx2; fz2=bz+dz2; break; }
        if (fx2>=0){
            float cxw=(fx2+0.5f)*TILE, czw=(fz2+0.5f)*TILE;
            float rh=road_heading(fx2,fz2), bxv=cosf(rh+1.5708f), bzv=sinf(rh+1.5708f);
            int placed=0;
            for (int k=-1;k<=1 && placed<3;k++){
                int slot=-1; for (int i=0;i<NCAR;i++) if(!cars[i].alive){ slot=i; break; }
                if (slot<0) break;
                cars[slot]=(Car){ cxw+bxv*k*3.4f, czw+bzv*k*3.4f, rh+1.5708f, 0, CAR_POLICE, DRV_NONE, 1, 100, 0 };
                car_body_init(slot); placed++;
            }
            if (placed) spawn_footcop(cxw+cosf(rh)*2.5f, czw+sinf(rh)*2.5f);
        }
    }
    /* 5*: the ARMY — a hostile TANK joins the hunt */
    if (w>=5){
        int have=0;
        for (int i=0;i<NCAR;i++) if(cars[i].alive && cars[i].driver==DRV_COP && cars[i].type==VEH_TANK) have=1;
        if (!have){
            int slot=-1; for (int i=0;i<NCAR;i++) if(!cars[i].alive){ slot=i; break; }
            float wx,wz;
            if (slot>=0 && find_road_clear(px,pz, 55.0f, 95.0f, &wx,&wz)){
                cars[slot]=(Car){wx,wz,frand()*6.28f,0,VEH_TANK,DRV_COP,1,900.0f,0};
                car_body_init(slot); say("THE ARMY IS HERE"); sfx(&boom_sfx,0.5f);
            }
        }
    }
    for (int i=0;i<NCAR;i++){ Car*c=&cars[i]; if(!c->alive||c->driver!=DRV_COP) continue;
        if (w==0){ if (c->type==VEH_TANK) c->driver=DRV_NONE; continue; }  /* squad cars go back on PATROL */
        float pdx=c->x-px, pdz=c->z-pz, pd2=pdx*pdx+pdz*pdz;
        float cspd=sqrtf(bodies[i].vx*bodies[i].vx+bodies[i].vy*bodies[i].vy);
        /* ARRIVAL: the squad car pulls up near the player and stops (player on foot, or
         * their car is slow) → the officer steps OUT, clear of the car, and fights on
         * foot. The abandoned (DRV_NONE) car is stealable. Cars never shoot. */
        int player_slow = (player.mode==MODE_FOOT) ||
                          (player.car>=0 && fabsf(cars[player.car].spd) < 6.0f);
        if (pd2<130.0f && cspd<3.5f && player_slow && c->type!=VEH_TANK){
            float rx=cosf(c->yaw+1.5708f), rz=sinf(c->yaw+1.5708f);
            float ox=c->x+rx*2.5f, oz=c->z+rz*2.5f;              /* step clear of the car */
            if (ped_blocked_by_car(ox,oz)){ ox=c->x-rx*2.5f; oz=c->z-rz*2.5f; }
            if (spawn_footcop(ox,oz)){
                c->driver=DRV_NONE; bodies[i].vx=bodies[i].vy=0; continue; }
        }
        /* ROAD-AWARE SEEK: chase along the streets — pick the cardinal that has road AND
         * heads most toward the player, instead of beelining into a kerb and jamming. */
        float want = atan2f(pz-c->z, px-c->x), bestd=want, bestscore=-2.0f;
        for (int k=0;k<4;k++){ float t=k*1.5708f;
            float run=road_run(c->x,c->z, cosf(t),sinf(t), TILE*4.0f);
            if (run < TILE*0.9f) continue;
            float score = cosf(ang_diff(t,want)) + 0.015f*run;   /* toward player + longer road */
            if (score>bestscore){ bestscore=score; bestd=t; } }
        /* jam recovery: a wedged squad car backs out for ~1.2s instead of grinding forever */
        static float copstuck[NCAR];
        float cthr = 1.0f;
        if (copstuck[i]>1.2f){ cthr=-0.9f; copstuck[i]+=dt; if (copstuck[i]>2.4f) copstuck[i]=0; }
        else if (cspd<0.7f) copstuck[i]+=dt;
        else copstuck[i]=0;
        ai_drive(i, bestd, cthr, dt);                             /* seek the player via roads */
        if (pd2<9.0f){                                            /* ram */
            if (player.mode==MODE_CAR){ cars[player.car].hp-=26*dt*3; if(cars[player.car].hp<=0){ wreck_car(&cars[player.car]); player.mode=MODE_FOOT; player.car=-1; player.x=px; player.z=pz; hurt_player(25); } }
            else if (pd2<5.0f){ g_state=ST_BUSTED; g_screen_t=2.6f; sfx(&bust_sfx,0.8f); }
            c->hp-=20*dt*3;
        }
        if (c->type==VEH_TANK){                                   /* army armour: shells at range */
            c->firecd-=dt;
            if (c->firecd<=0 && pd2<45.0f*45.0f && pd2>9.0f*9.0f && player_in_gun_reach()){
                c->firecd=2.8f;
                float a=atan2f(pz-c->z, px-c->x)+(frand()*2-1)*0.04f;
                float mx0=c->x+cosf(a)*4.0f, mz0=c->z+sinf(a)*4.0f;   /* from the barrel tip */
                add_fx(mx0,mz0,2); sfx(&boom_sfx,0.5f);
                for (int b=0;b<NBULLET;b++) if(!bullets[b].alive){
                    bullets[b]=(Bullet){ mx0,mz0, cosf(a)*36.0f, sinf(a)*36.0f, 1.3f, 1, 1, 1 }; break; }
            }
        }
        if (c->hp<=0) wreck_car(c);
    }
}

static void update_heat(float dt) {
    heat_cool+=dt;
    int copnear=0; float px=pl_x(),pz=pl_z();
    for (int i=0;i<NCAR;i++) if(cars[i].alive&&cars[i].driver==DRV_COP){ float dx=cars[i].x-px,dz=cars[i].z-pz; if(dx*dx+dz*dz<900.0f){copnear=1;break;} }
    if(!copnear) for (int i=0;i<NPED;i++) if(peds[i].alive&&peds[i].iscop){ float dx=peds[i].x-px,dz=peds[i].z-pz; if(dx*dx+dz*dz<900.0f){copnear=1;break;} }
    /* Wanted stars are sticky: the law only starts to forget after you've been
     * clean AND out of sight for a while (longer the hotter you are), then bleeds
     * off slowly — ~10s per star, so a 5-star spree takes the better part of a
     * minute of laying low to shake. */
    float need = 6.0f + 1.4f*heat;
    if (heat_cool>need && !copnear && heat>0){ heat-=0.10f*dt; if(heat<0)heat=0; }
}

static void mission_cleanup(void);   /* defined with start_mission below */

/* The escort VIP walks himself toward the drop; he's fragile, so police gunfire
 * and speeding cars can drop him — the player's job is to keep the route clear. */
static void update_escort(Ped *v, float dt){
    float dx=drop_x-v->x, dz=drop_z-v->z, d=sqrtf(dx*dx+dz*dz);
    if (d>1.0f){ float sp=3.6f*dt, nx=v->x+dx/d*sp, nz=v->z+dz/d*sp;
        if (walkable_world(nx,v->z)) v->x=nx;             /* axis-separated: hug corners, don't jam */
        if (walkable_world(v->x,nz)) v->z=nz;
        v->yaw=atan2f(dz,dx); }
    v->animt += dt*6.0f;
    for (int i=0;i<NBULLET;i++){ Bullet*b=&bullets[i]; if(!b->alive||!b->fromcop) continue;
        float bx=b->x-v->x, bz=b->z-v->z; if(bx*bx+bz*bz<1.6f){ b->alive=0; if(v->hp>0)v->hp--; } }
    for (int i=0;i<NCAR;i++){ Car*c=&cars[i]; if(!c->alive||c->wrecked||fabsf(c->spd)<7.0f) continue;
        float cx=c->x-v->x, cz=c->z-v->z; if(cx*cx+cz*cz<3.0f && v->hp>0) v->hp--; }
    if (v->hp==0) v->alive=0;
}

static void update_missions(float dt) {
    if (mission==MI_NONE) return;
    mission_t-=dt;
    int lose=0;                              /* set to end the job as a failure this frame */
#ifdef MOTE_HOST
    if ((mission==MI_RIVAL||mission==MI_CIRCUIT) && getenv("MOTE_GTA_DEBUG")){
        static float acc; acc+=dt;
        if (acc>=1.0f){ acc=0;
            Car *rc=(mission==MI_RIVAL&&rival_car>=0)?&cars[rival_car]:0;
            float rspd = rc ? sqrtf(bodies[rival_car].vx*bodies[rival_car].vx+bodies[rival_car].vy*bodies[rival_car].vy) : 0;
            float tgx = (rival_i<cp_n)?cp_x[rival_i]:0, tgz=(rival_i<cp_n)?cp_z[rival_i]:0;
            fprintf(stderr,"[RACE] cp=%d/%d rival=%d rspd=%.1f rpos=(%.0f,%.0f) tgt=(%.0f,%.0f) stuck=%.1f alive=%d t=%.0f\n",
            cp_i,cp_n,rival_i, rspd, rc?rc->x:0,rc?rc->z:0, tgx,tgz,
            rc?stuck_t[rival_car]:0, rc?rc->alive:0, mission_t); } }
#endif
    switch (mission){
    case MI_COURIER: { float dx=pl_x()-mx, dz=pl_z()-mz;
        if (dx*dx+dz*dz<36.0f){ mission_win(); return; } } break;
    case MI_RAMPAGE: if (mission_kills>=mission_target){ mission_win(); return; } break;
    case MI_GETAWAY: if (wanted()==0){ mission_win(); return; } break;
    case MI_HIT: { Ped *t=(mission_target>=0)?&peds[mission_target]:0;
        if (!t||!t->alive){ mission_win(); return; }
        mx=t->x; mz=t->z; } break;                        /* marker follows the mark */
    case MI_DELIVER: { Car *c=(mission_car>=0)?&cars[mission_car]:0;
        if (!c||c->wrecked||!c->alive){ say("THE MOTOR'S TOTALLED"); lose=1; break; }
        if (mission_leg==0){ mx=c->x; mz=c->z;            /* leg 0: reach & board the car */
            if (player.mode==MODE_CAR && player.car==mission_car){ mission_leg=1; say("TO THE DROP - NO SCRATCHES"); } }
        else { mx=drop_x; mz=drop_z;                       /* leg 1: deliver it */
            float dx=c->x-drop_x, dz=c->z-drop_z;
            if (dx*dx+dz*dz<42.0f && player.mode==MODE_CAR && player.car==mission_car){
                if (c->hp>=88){ mission_pay += mission_pay/5; say("PRISTINE - BONUS PAID"); }
                else if (c->hp<45) mission_pay = mission_pay*7/10;   /* banged up: docked */
                mission_win(); return; } } } break;
    case MI_PICKUP: { if (mission_kills>=mission_target){ mission_win(); return; }
        float bd=1e18f;                                    /* beacon → nearest package left */
        for (int i=0;i<NPICK;i++){ Pickup*p=&picks[i]; if(!p->alive||p->kind!=PK_PACKAGE) continue;
            float dx=p->x-pl_x(), dz=p->z-pl_z(), d2=dx*dx+dz*dz; if(d2<bd){bd=d2;mx=p->x;mz=p->z;} } } break;
    case MI_REPO: { Car *c=(mission_car>=0)?&cars[mission_car]:0;
        if (!c){ lose=1; break; }
        if (c->wrecked){ mission_win(); return; }
        if (!c->alive){ say("HE SLIPPED AWAY"); lose=1; break; }   /* recycled/escaped */
        mx=c->x; mz=c->z; } break;
    case MI_ESCORT: { Ped *v=(mission_target>=0)?&peds[mission_target]:0;
        if (!v||!v->alive){ say("THE VIP IS DOWN"); lose=1; break; }
        update_escort(v, dt); mx=v->x; mz=v->z;            /* beacon rides the VIP */
        float dx=v->x-drop_x, dz=v->z-drop_z;
        if (dx*dx+dz*dz<36.0f){ mission_win(); return; } } break;
    case MI_SMUGGLE: { if (wanted()>mission_cap){ say("TOO HOT - DEAL'S OFF"); lose=1; break; }
        float dx=pl_x()-mx, dz=pl_z()-mz; if (dx*dx+dz*dz<36.0f){ mission_win(); return; } } break;
    case MI_DEMO: { int done=0; float bd=1e18f;
        for (int k=0;k<mtarg_n;k++){ Car*c=&cars[mtarg[k]];
            if (c->wrecked||!c->alive){ done++; continue; }
            float dx=c->x-pl_x(), dz=c->z-pl_z(), d2=dx*dx+dz*dz; if(d2<bd){bd=d2;mx=c->x;mz=c->z;} }
        mission_kills=done;
        if (done>=mtarg_n){ mission_win(); return; } } break;
    case MI_VIGIL: { if (mission_kills>=mission_target){ mission_win(); return; }
        float bd=1e18f;                                    /* beacon → nearest person on foot */
        for (int i=0;i<NPED;i++){ Ped*p=&peds[i]; if(!p->alive||p->iscop) continue;
            float dx=p->x-pl_x(), dz=p->z-pl_z(), d2=dx*dx+dz*dz; if(d2<bd){bd=d2;mx=p->x;mz=p->z;} } } break;
    case MI_WANTED: { if (wanted()>=mission_cap) mission_hold+=dt;
        if (mission_hold>=(float)mission_target){ mission_win(); return; } } break;
    case MI_CIRCUIT: { if (cp_i>=cp_n){ mission_win(); return; }
        float dx=pl_x()-cp_x[cp_i], dz=pl_z()-cp_z[cp_i];
        if (dx*dx+dz*dz<49.0f){ cp_i++; if(cp_i<cp_n){ mx=cp_x[cp_i]; mz=cp_z[cp_i]; sfx(&cash_sfx,0.5f); }
                                else { mission_win(); return; } } } break;
    case MI_RIVAL: { if (cp_i>=cp_n){ mission_win(); return; }
        /* the RIVAL is a real AI car (update_traffic steers it toward cp_x/z[rival_i]);
         * advance its checkpoint here from its true body position. If it is wrecked or
         * recycled it simply stops progressing — take it out and the race is yours. */
        Car *rc=(rival_car>=0)?&cars[rival_car]:0;
        if (rc && rc->alive && !rc->wrecked && rival_i<cp_n){
            float rdx=rc->x-cp_x[rival_i], rdz=rc->z-cp_z[rival_i];
            if (rdx*rdx+rdz*rdz < RIVAL_ARRIVE2){ rival_i++;
#ifdef MOTE_HOST
                if (getenv("MOTE_GTA_DEBUG")) fprintf(stderr,"[RACE] >>> RIVAL HIT CHECKPOINT %d/%d\n", rival_i, cp_n);
#endif
            }
        }
        if (rival_i>=cp_n){                                     /* he crossed the line first */
#ifdef MOTE_HOST
            if (getenv("MOTE_GTA_DEBUG")) fprintf(stderr,"[RACE] >>> RIVAL WON THE RACE (completed all %d checkpoints)\n", cp_n);
#endif
            say("THE RIVAL TOOK IT"); lose=1; break; }
        float dx=pl_x()-cp_x[cp_i], dz=pl_z()-cp_z[cp_i];
        if (dx*dx+dz*dz<49.0f){ cp_i++; if(cp_i<cp_n){ mx=cp_x[cp_i]; mz=cp_z[cp_i]; sfx(&cash_sfx,0.5f); }
                                else { mission_win(); return; } } } break;
    }
    if (mission_t<=0){ say("MISSION FAILED"); lose=1; }
    if (lose){ mission_cleanup(); mission=MI_NONE; mission_chain=0; g_recur_seed=0; }   /* streak lost → new contact */
}

/* Jobs that steer you to a place (mx,mz) get the pulsing magenta beacon; the
 * "make chaos anywhere" jobs (rampage/getaway/most-wanted) don't. */
static int mission_beacon(void){
    return mission!=MI_NONE && mission!=MI_RAMPAGE && mission!=MI_GETAWAY && mission!=MI_WANTED;
}

/* Word-wrap `s` in font `f` to fit `maxw` px across up to two lines (each < cap
 * chars). Breaks on the last space that keeps line 1 in bounds; l2 is "" if the
 * whole string fits on one line. Used so banners/titles never run off-screen. */
static void wrap2(const MoteFont *f, const char *s, int maxw, char *l1, char *l2, int cap){
    l1[0]=0; l2[0]=0;
    if (!f || mote_fontw(f,s) <= maxw){ int j=0; while(s[j]&&j<cap-1){l1[j]=s[j];j++;} l1[j]=0; return; }
    int brk=-1;
    for (int i=0; s[i]; i++){ if(s[i]!=' ') continue;
        char t[48]; int k=i<47?i:47; for(int j=0;j<k;j++)t[j]=s[j]; t[k]=0;
        if (mote_fontw(f,t) <= maxw) brk=i; else break; }
    if (brk<=0){ int j=0; for(;s[j]&&j<cap-1;j++)l1[j]=s[j]; l1[j]=0; return; }  /* no space fits: hard clip */
    int j=0; for(;j<brk&&j<cap-1;j++)l1[j]=s[j]; l1[j]=0;
    const char *r=s+brk+1; j=0; while(r[j]&&j<cap-1){l2[j]=r[j];j++;} l2[j]=0;
}
/* Same, wrapping to up to THREE lines (a long crew name can push a pitch to 3). */
static void wrap3(const MoteFont *f, const char *s, int maxw, char *l1, char *l2, char *l3, int cap){
    l1[0]=l2[0]=l3[0]=0;
    wrap2(f, s, maxw, l1, l2, cap);
    if (l2[0]){ char tmp[56]; int i=0; while(l2[i]&&i<55){tmp[i]=l2[i];i++;} tmp[i]=0;
        wrap2(f, tmp, maxw, l2, l3, cap); }
}

/* Left-aligned formatted HUD text with a 1px black drop shadow so it stays legible
 * over the busy street underneath. */
static void ftext_sh(const MoteFont *f, uint16_t *fb, int x, int y, uint16_t col, const char *fmt, ...){
    char b[64]; va_list ap; va_start(ap, fmt); mote_vfmt(b, sizeof b, fmt, ap); va_end(ap);
    mote_ftext(mote, fb, f, b, x+1, y+1, MOTE_RGB565(0,0,0));
    mote_ftext(mote, fb, f, b, x,   y,   col);
}

/* ================= phone-call CONTACTS ==================================
 * A fresh procedural character briefs every phone job: a seed-generated name and
 * a pixel portrait (skin/hair/face/outfit), GTA-style, drawn into the briefing. */
static int      g_brief_active;      /* freezes the world during a job briefing */
static uint32_t g_brief_seed;
static char     g_brief_name[24];
static const char *g_brief_role;
static const char *g_brief_body;
static char        g_brief_body_buf[72];   /* templated pitch (crew/target names) */

static uint32_t cr_mix(uint32_t x){ x^=x>>16; x*=0x7feb352du; x^=x>>15; x*=0x846ca68bu; x^=x>>16; return x; }

/* ================= procedural CREWS (factions) =========================
 * Each city spins up a handful of rival crews with generated names, a boss face,
 * a turf, and a standing with the player. Your recurring caller is a crew boss;
 * the wet-work jobs (hit/repo/vigilante/demo) target a RIVAL crew by name, so the
 * briefings read like an unfolding turf war rather than disconnected errands. */
#define NFACTION 4
typedef struct { uint32_t seed; char name[18]; int8_t standing; uint8_t hostile, colv; float tx, tz; } Faction;
static Faction g_fac[NFACTION];
static int  g_employer = -1;      /* crew you're working for this streak (your recurring boss) */
static int  g_job_rival = -1;     /* crew the current job hits (-1 = none) */
static char g_tgt_name[20];       /* named mark for a HIT */

static void make_crew_name(char *out, uint32_t s){
    static const char *ADJ[16]={"NEON","IRON","RED","GOLD","JADE","ASH","VOLT","GHOST","STEEL","ONYX","CRIMSON","DOCK","NIGHT","SILVER","RUST","COBALT"};
    static const char *NOUN[14]={"VIPERS","KINGS","SYNDICATE","CARTEL","WOLVES","SAINTS","DRAGONS","JACKALS","BARONS","REAPERS","CROWNS","SHARKS","HOUNDS","FANGS"};
    const char *a=ADJ[(s>>3)&15], *n=NOUN[(s>>9)%14]; char *o=out;
    while(*a)*o++=*a++; *o++=' '; while(*n)*o++=*n++; *o=0;
}
static void gen_person_name(char *out, uint32_t s){
    static const char *F[16]={"Tony","Rico","Sal","Vince","Nico","Marco","Yuri","Cole","Bruno","Omar","Gus","Ivan","Rosa","Nina","Lena","Sofia"};
    static const char *L[10]={"Costa","Voss","Ramos","Kane","Petrov","Reyes","Nash","Vex","Diallo","Moretti"};
    const char *f=F[(s>>2)&15], *l=L[(s>>7)%10]; char *o=out;
    while(*f)*o++=*f++; *o++=' '; while(*l)*o++=*l++; *o=0;
}
static void gen_factions(void){
    g_employer=-1; g_job_rival=-1;
    for (int i=0;i<NFACTION;i++){
        uint32_t s = cr_mix(((uint32_t)irand(1<<15)<<16) ^ (uint32_t)irand(1<<15) ^ (i*2654435761u) ^ 0x9e3779b9u);
        g_fac[i].seed=s; make_crew_name(g_fac[i].name, s);
        g_fac[i].standing=0; g_fac[i].hostile=0; g_fac[i].colv=(uint8_t)(s&3);
        float ox,oz;
        if (find_road_clear(player.x,player.z, 30.0f+i*45.0f, 320.0f, &ox,&oz)){ g_fac[i].tx=ox; g_fac[i].tz=oz; }
        else { g_fac[i].tx=player.x; g_fac[i].tz=player.z; }
    }
}
/* a rival crew for a wet-work job: any crew that isn't your employer */
static int pick_rival(void){
    if (NFACTION<2) return 0;
    int r; for (int t=0;t<8;t++){ r=irand(NFACTION); if(r!=g_employer) return r; }
    return (g_employer+1)%NFACTION;
}
static uint32_t g_seed_override;   /* host capture hook: force a specific contact seed */
#ifdef MOTE_HOST
static int g_force_mtype;           /* host test hook: force a specific mission type (MI_*) */
#endif

/* The contact's title and one-line pitch for a job type — used by the briefing and
 * by the branching call screen (which shows two of these side by side). */
static const char *job_role(int t){ switch(t){
    case MI_COURIER: return "THE FIXER";     case MI_RAMPAGE: return "THE ENFORCER";
    case MI_GETAWAY: return "YOUR HANDLER";  case MI_HIT:     return "THE CLIENT";
    case MI_DELIVER: return "THE DEALER";    case MI_PICKUP:  return "THE RUNNER";
    case MI_REPO:    return "THE COLLECTOR"; case MI_ESCORT:  return "THE BOSS";
    case MI_SMUGGLE: return "THE FIXER";     case MI_DEMO:    return "THE TORCH";
    case MI_VIGIL:   return "THE CAPO";      case MI_WANTED:  return "THE CLIENT";
    case MI_CIRCUIT: return "THE TIMEKEEPER";case MI_RIVAL:   return "THE RACER";
    default:         return "THE CLIENT"; } }
static const char *job_body(int t){ switch(t){
    case MI_COURIER: return "Move the package. No cops.";     case MI_RAMPAGE: return "Send a message. Drop 'em.";
    case MI_GETAWAY: return "You're too hot. Lose it.";       case MI_HIT:     return "Take out the mark. Clean.";
    case MI_DELIVER: return "Boost that motor. Not a scratch.";case MI_PICKUP: return "Packages are down. Collect 'em.";
    case MI_REPO:    return "A debt skipped. Total his ride."; case MI_ESCORT:  return "Walk my guy home. Keep him alive.";
    case MI_SMUGGLE: return "Quiet run. Don't draw heat.";    case MI_DEMO:    return "Insurance job. Wreck the lot.";
    case MI_VIGIL:   return "Rival crew's on my turf. Thin it.";case MI_WANTED: return "Bring the city down. Survive.";
    case MI_CIRCUIT: return "Run my course. Beat the clock.";  case MI_RIVAL:  return "Think you're fast? Prove it.";
    default:         return "Do the job. Get paid."; } }
static void gen_contact(int mtype){
    uint32_t s = g_seed_override ? cr_mix(g_seed_override)
               : g_recur_seed    ? g_recur_seed            /* same face keeps calling during a streak */
               : cr_mix((uint32_t)mote->micros() ^ ((uint32_t)mission_chain*2654435761u) ^ 0x9e3779b9u);
    g_brief_seed = s;
    int female = ((s>>20)&7) < 3;   /* ~37% women — MUST match draw_portrait's bit */
    static const char *FIRST_M[]={"Tony","Vince","Sal","Rico","Frank","Nico","Carl","Vic","Leon","Bruno",
        "Dwayne","Omar","Yuri","Marco","Gus","Paulie","Reggie","Tariq","Ivan","Cole","Mickey","Hank","Deshawn","Sergei"};
    static const char *FIRST_F[]={"Rosa","Maria","Nina","Lena","Priya","Dana","Tanya","Sofia","Yara","Renee",
        "Carmen","Zoe","Naomi","Bex","Aria","Ivy","Marta","Kim"};
    static const char *LAST []={"Costa","Vercetti","Marlowe","Delgado","Ramos","Voss","Okafor","Salieri","Bishop",
        "Cruz","Nash","Petrov","Diallo","Moretti","Kane","Solano","Reyes","Vex"};
    const char *fn = female ? FIRST_F[(s>>2)%(sizeof FIRST_F/sizeof*FIRST_F)]
                            : FIRST_M[ s     %(sizeof FIRST_M/sizeof*FIRST_M)];
    const char *ln = LAST[(s>>8)%(sizeof LAST/sizeof*LAST)];
    { char *b=g_brief_name; const char*p=fn; while(*p)*b++=*p++; *b++=' '; p=ln; while(*p)*b++=*p++; *b=0; }
    g_brief_role = job_role(mtype);
    /* wet-work jobs name the rival crew (and the mark) so the call reads like a turf war */
    if (g_job_rival>=0 && g_job_rival<NFACTION){
        const char *rc = g_fac[g_job_rival].name;
        switch (mtype){
            case MI_HIT:  snprintf(g_brief_body_buf,sizeof g_brief_body_buf,"Take out %s, %s.", g_tgt_name, rc); break;
            case MI_REPO: snprintf(g_brief_body_buf,sizeof g_brief_body_buf,"A %s debtor ran. Wreck it.", rc); break;
            case MI_VIGIL:snprintf(g_brief_body_buf,sizeof g_brief_body_buf,"%s on our turf. Thin 'em.", rc); break;
            case MI_DEMO: snprintf(g_brief_body_buf,sizeof g_brief_body_buf,"Torch every %s car.", rc); break;
            default:      snprintf(g_brief_body_buf,sizeof g_brief_body_buf,"%s", job_body(mtype)); break;
        }
        g_brief_body = g_brief_body_buf;
    } else g_brief_body = job_body(mtype);
}

/* Procedural 44x46 mugshot from a seed. Blocky GTA-1 flavour with real variety:
 * face shape (width/height/jaw), sex, skin/hair/outfit, many hair + hat styles. */
static void draw_portrait(uint16_t *fb, int ox, int oy, uint32_t s){
    #define PR(X,Y,W,H,C) mote->draw_rect(fb,(X),(Y),(W),(H),(C),1,0,128)
    static const uint16_t SKIN[6]={MOTE_RGB565(246,208,170),MOTE_RGB565(228,176,132),MOTE_RGB565(200,142,98),
        MOTE_RGB565(152,102,66),MOTE_RGB565(112,76,52),MOTE_RGB565(236,192,150)};
    static const uint16_t HAIR[7]={MOTE_RGB565(26,22,20),MOTE_RGB565(74,46,28),MOTE_RGB565(206,174,92),
        MOTE_RGB565(184,186,194),MOTE_RGB565(150,52,32),MOTE_RGB565(44,38,42),MOTE_RGB565(120,80,50)};
    static const uint16_t CLOTH[8]={MOTE_RGB565(58,72,122),MOTE_RGB565(124,46,46),MOTE_RGB565(42,92,62),
        MOTE_RGB565(92,92,102),MOTE_RGB565(152,122,42),MOTE_RGB565(72,52,92),MOTE_RGB565(32,62,92),MOTE_RGB565(112,72,42)};
    static const int FHAIR[6]={1,7,9,10,11,12};                   /* female-leaning styles */
    static const uint16_t EYE[6]={MOTE_RGB565(96,56,30),MOTE_RGB565(72,122,182),MOTE_RGB565(80,142,92),
        MOTE_RGB565(134,112,58),MOTE_RGB565(122,132,142),MOTE_RGB565(44,32,28)};  /* brown/blue/green/hazel/grey/dark */
    uint16_t skin=SKIN[s%6], hair=HAIR[(s>>3)%7], cloth=CLOTH[(s>>6)%8], hc=hair, eye=EYE[(s>>28)%6];
    int female=((s>>20)&7)<3;                                     /* MUST match gen_contact */
    int hw=9+(int)((s>>22)%4), fh=22+(int)((s>>24)%5), jaw=(int)((s>>26)%3);
    int beard=female?0:(int)((s>>13)%4), shades=((s>>16)&7)<2;
    int hs=female?FHAIR[(s>>10)%6]:(int)((s>>10)%9);
    int sr=((skin>>11)&31)<<3, sg=((skin>>5)&63)<<2, sb=(skin&31)<<3;
    uint16_t sh=MOTE_RGB565(sr*3/4,sg*3/4,sb*3/4), dk=MOTE_RGB565(22,24,28), bg=MOTE_RGB565(38,42,56);
    int cx=ox+22, fx=cx-hw, fy=oy+9, cy=fy+fh;                    /* face box; cy = chin */
    PR(ox,oy,44,46, MOTE_RGB565(26,28,38)); PR(ox+2,oy+2,40,42, bg);   /* backdrop */
    PR(cx-5, cy-3, 10, 10, skin);                                 /* neck */
    PR(ox+4, oy+38, 36, 8, cloth);                                /* shoulders */
    PR(cx-6, oy+38, 12, 3, cloth); PR(cx-3, oy+38, 6, 2, MOTE_RGB565(sr*9/10,sg*9/10,sb*9/10)); /* collar */
    PR(fx, fy, hw*2, fh, skin);                                   /* face */
    if (jaw==0){ PR(fx,cy-2,2,2,bg); PR(fx+hw*2-2,cy-2,2,2,bg); }            /* round chin */
    else if (jaw==2){ PR(fx,cy-5,2,5,bg); PR(fx+hw*2-2,cy-5,2,5,bg); }      /* tapered chin */
    PR(fx-2,fy+10,2,5,skin); PR(fx+hw*2,fy+10,2,5,skin);          /* ears */
    if (female?((s>>18)&1):(((s>>18)&7)==0)){ uint16_t g=MOTE_RGB565(240,220,120);
        PR(fx-2,fy+15,1,1,g); PR(fx+hw*2+1,fy+15,1,1,g); }        /* earrings */
    switch(hs){                                                  /* hair / hat */
        case 0: break;                                                              /* bald */
        case 1: PR(fx+1,fy-3,hw*2-2,5,hc); break;                                   /* short */
        case 2: PR(fx,fy-3,hw*2,5,hc); PR(fx,fy,2,9,hc); PR(fx+hw*2-2,fy,2,9,hc); break; /* slick */
        case 3: PR(fx-3,fy-6,hw*2+6,9,hc); PR(fx-3,fy,3,11,hc); PR(fx+hw*2,fy,3,11,hc); break; /* afro */
        case 4: PR(fx+1,fy-3,hw*2-2,5,hc); PR(cx-4,fy-7,8,5,hc); break;              /* quiff */
        case 5: PR(fx-1,fy-5,hw*2+2,6,cloth); PR(fx-4,fy,9,2,cloth); break;          /* cap */
        case 6: PR(fx-2,fy-5,hw*2+4,9,cloth); break;                                /* beanie */
        case 7: PR(fx,fy-2,hw*2,4,cloth); PR(fx+1,fy+2,hw*2-2,2,hc); break;          /* bandana */
        case 8: PR(fx-3,fy-5,hw*2+6,fh+4,cloth); PR(fx,fy,hw*2,fh,skin);             /* hood */
                PR(fx-3,fy+5,3,fh-2,cloth); PR(fx+hw*2,fy+5,3,fh-2,cloth); break;
        case 9: PR(fx-2,fy-4,hw*2+4,7,hc); PR(fx-3,fy,3,fh+7,hc); PR(fx+hw*2,fy,3,fh+7,hc); break; /* long */
        case 10: PR(fx,fy-4,hw*2,6,hc); PR(fx+hw*2,fy,4,16,hc); break;               /* ponytail */
        case 11: PR(fx,fy-3,hw*2,5,hc); PR(cx-4,fy-8,8,6,hc); break;                 /* bun */
        case 12: PR(fx-2,fy-4,hw*2+4,7,hc); PR(fx-3,fy,3,fh+2,hc); PR(fx+hw*2,fy,3,fh+2,hc);
                 PR(cx-4,fy-8,8,5,hc); break;                                        /* long + updo */
    }
    { int ey=fy+9, exl=cx-8, exr=cx+3;                           /* bigger eyes with colour */
      if (shades){ PR(cx-9,ey,7,4,dk); PR(cx+2,ey,7,4,dk); PR(cx-2,ey+1,4,1,dk); }
      else { uint16_t wq=MOTE_RGB565(234,236,240);
             PR(exl,ey,5,3,wq); PR(exr,ey,5,3,wq);                          /* whites */
             PR(exl+2,ey,2,3,eye); PR(exr+1,ey,2,3,eye);                    /* iris */
             PR(exl+2,ey+1,1,1,dk); PR(exr+2,ey+1,1,1,dk);                  /* pupil */
             if (female){ PR(exl-1,ey-1,6,1,dk); PR(exr-1,ey-1,6,1,dk); }   /* lashes */
             else { PR(exl,ey-2,5,1,hair); PR(exr,ey-2,5,1,hair); } }       /* brows */
    }
    PR(cx-1, fy+13, 2,3, sh);                                     /* nose */
    if (beard==1) PR(cx-6,fy+16,12,2,hair);                       /* moustache */
    else if (beard==2 || beard==3){                              /* stubble / full beard: the WHOLE jaw */
        uint16_t bc = beard==3 ? hair : MOTE_RGB565(sr*11/20,sg*11/20,sb*11/20);
        PR(fx, fy+15, hw*2, cy-(fy+15), bc);                      /* fill the lower face, full width */
        if (jaw==0){ PR(fx,cy-2,2,2,bg); PR(fx+hw*2-2,cy-2,2,2,bg); }              /* follow the chin shape */
        else if (jaw==2){ PR(fx,cy-5,2,5,bg); PR(fx+hw*2-2,cy-5,2,5,bg); }
        if (beard==2) PR(fx, fy+15, hw*2, 1, skin);              /* stubble: soften its top edge */
    }
    PR(cx-3, fy+18, 6,1, female?MOTE_RGB565(210,70,96):MOTE_RGB565(120,60,60));      /* mouth */
    if (female) PR(cx-2, fy+19, 4,1, MOTE_RGB565(180,54,78));                        /* lower lip */
    mote->draw_rect(fb, ox,oy,44,46, MOTE_RGB565(150,120,60), 0,0,128);              /* frame */
    #undef PR
}

/* Nearest jackable car (parked OR ordinary traffic, undamaged) in a distance band —
 * the DELIVER target. Cops/tanks/buses excluded; the caller parks whatever it picks. */
static int find_parked_car(float rmin, float rmax){
    int best=-1; float bd=1e18f, px=pl_x(), pz=pl_z();
    for (int i=0;i<NCAR;i++){ Car*c=&cars[i];
        if(!c->alive||c->wrecked||i==player.car||c->type==VEH_TANK||c->type==VEH_BUS||c->type==VEH_HELI) continue;
        if(c->driver!=DRV_NONE && c->driver!=DRV_NPC) continue;
        float dx=c->x-px, dz=c->z-pz, d2=dx*dx+dz*dz;
        if(d2<rmin*rmin||d2>rmax*rmax) continue;
        if(d2<bd){ bd=d2; best=i; } }
    return best;
}
/* Nearest cruising traffic car (for the repo target). */
static int find_npc_car(float rmin, float rmax){
    int best=-1; float bd=1e18f, px=pl_x(), pz=pl_z();
    for (int i=0;i<NCAR;i++){ Car*c=&cars[i];
        if(!c->alive||c->wrecked||c->driver!=DRV_NPC||c->type==VEH_TANK||c->type==VEH_BUS||c->type==VEH_HELI) continue;
        float dx=c->x-px, dz=c->z-pz, d2=dx*dx+dz*dz;
        if(d2<rmin*rmin||d2>rmax*rmax) continue;
        if(d2<bd){ bd=d2; best=i; } }
    return best;
}
/* Chain up to `n` checkpoints along the roads, each a fresh clear road point a
 * medium hop from the previous — the racecourse for CIRCUIT/RIVAL. */
static int build_route(int n){
    float px=pl_x(), pz=pl_z(); cp_n=0;
    for (int k=0;k<n && cp_n<5;k++){ float ox,oz; int ok=0;
        for (int t=0;t<8 && !ok;t++){                    /* insist each leg is road-REACHABLE */
            if (!find_road_clear(px,pz, 55.0f, 115.0f, &ox,&oz)) break;
            if (road_dist(px,pz, ox,oz) > 0) ok=1;       /* so the player AND the rival can complete it */
        }
        if (!ok) break;
        cp_x[cp_n]=ox; cp_z[cp_n]=oz; cp_n++; px=ox; pz=oz; }
    return cp_n>=2;
}

/* Undo any world spawns a job placed (packages, escort VIP) — run on win, fail,
 * or a declined briefing so a refused call leaves no litter. */
static void mission_cleanup(void){
    for(int i=0;i<NPICK;i++) if(picks[i].alive && picks[i].kind==PK_PACKAGE) picks[i].alive=0;
    if(mission==MI_ESCORT && mission_target>=0 && mission_target<NPED) peds[mission_target].alive=0;
}

/* ROGUELIKE phone jobs: random type, randomized stakes, and a CHAIN — each success
 * bumps the multiplier (+25% per job, up to x2.25); a failure resets it. Some jobs
 * need the right props nearby (a parked car, a debtor in traffic); when setup fails
 * we just roll another type, so the phone never dead-ends unless the city is empty. */
/* Set up ONE specific job type: spawn its props, set timer/pay/objective. Returns 1
 * if the type's preconditions were met, 0 if it couldn't place (roll another). */
static int setup_mission(int rot, float mult){
    mission=MI_NONE;
    mission_car=-1; mission_leg=0; mission_hold=0; mission_cap=0; mtarg_n=0; rival_car=-1; cp_n=0; cp_i=0; g_job_rival=-1;
    if (rot==MI_COURIER){ mission=MI_COURIER;
        float rmin = 100.0f + frand()*80.0f, rmax = rmin + 80.0f + frand()*140.0f;
        float route=-1.0f;
        for (int t=0;t<6 && route<0;t++){                 /* insist on a sane route */
            if (!find_road_clear(pl_x(),pl_z(), rmin, rmax, &mx,&mz)) break;
            float d=sqrtf((mx-pl_x())*(mx-pl_x())+(mz-pl_z())*(mz-pl_z()));
            float r=road_dist(pl_x(),pl_z(), mx,mz);
            if (r>0 && r < d*2.6f) route=r;               /* reachable, not a silly detour */
        }
        if (route>0){
            mission_t = (14.0f + frand()*8.0f) + route/7.5f;   /* timer knows the REAL route */
            mission_pay = (int)((350.0f + route*1.6f + frand()*220.0f)*mult);
            say("COURIER: REACH THE MARKER");
        } else mission=MI_NONE;
    } else if (rot==MI_RAMPAGE){ mission=MI_RAMPAGE;
        mission_target = 5 + irand(7);                      /* 5-11 kills */
        mission_t = 22.0f + mission_target*4.5f + frand()*8.0f;
        mission_kills=0;
        mission_pay = (int)((mission_target*95.0f + frand()*200.0f)*mult);
        owned[W_PISTOL]=1; if(ammo[W_PISTOL]<40)ammo[W_PISTOL]=40; if(weapon==W_FIST)weapon=W_PISTOL;
        say("RAMPAGE: MOW THEM DOWN");
    } else if (rot==MI_GETAWAY){ mission=MI_GETAWAY;
        float h = 2.4f + frand()*1.8f;                      /* 2-4 stars of trouble */
        mission_t = 55.0f + h*12.0f;
        mission_pay = (int)((h*260.0f + frand()*180.0f)*mult);
        add_heat(h); say("SET UP! LOSE THE HEAT");
    } else if (rot==MI_HIT){ mission=MI_HIT;
        g_job_rival = pick_rival();                       /* the mark belongs to a rival crew */
        gen_person_name(g_tgt_name, cr_mix(g_fac[g_job_rival].seed + (uint32_t)irand(1<<16)));
        float ox,oz; mission_target=-1;
        float rmin = 70.0f + frand()*70.0f;
        if (find_near(pl_x(),pl_z(), rmin, rmin+130.0f, pav_or_grass, &ox,&oz)){
            for (int j=0;j<NPED;j++) if(!peds[j].alive || !peds[j].iscop){
                peds[j]=(Ped){ ox,oz,(float)(irand(4))*1.5708f,0,(uint8_t)irand(4),1,2,0,0 };
                mission_target=j; mx=ox; mz=oz; break; }
        }
        if (mission_target>=0){ float d=sqrtf((mx-pl_x())*(mx-pl_x())+(mz-pl_z())*(mz-pl_z()));
            float r=road_dist(pl_x(),pl_z(), mx,mz);
            if (r>0) d=r;                                /* the REAL route sets the clock */
            mission_t = 20.0f + frand()*10.0f + d/7.5f;
            mission_pay = (int)((520.0f + d*1.2f + frand()*260.0f)*mult);
            say("HIT: TAKE OUT THE MARK"); }
        else mission=MI_NONE;
    } else if (rot==MI_DELIVER){
        int car = find_parked_car(20.0f, 150.0f);
        if (car>=0 && find_road_clear(pl_x(),pl_z(), 90.0f, 210.0f, &drop_x,&drop_z)){
            cars[car].driver=DRV_NONE; cars[car].spd=0;      /* the mark leaves it parked for you */
            mission=MI_DELIVER; mission_car=car; mission_leg=0;
            mx=cars[car].x; mz=cars[car].z;                 /* leg 0: reach the car */
            float d=road_dist(pl_x(),pl_z(), drop_x,drop_z); if(d<=0) d=180.0f;
            mission_t = 32.0f + d/6.0f;                      /* generous — precision, not speed */
            mission_pay = (int)((440.0f + d*1.4f + frand()*200.0f)*mult);
            say("DELIVER: STEAL THE MOTOR");
        }
    } else if (rot==MI_PICKUP){
        int want = 3 + irand(2), got=0;                     /* 3-4 packages */
        for (int k=0;k<want;k++){ float ox,oz;
            if (find_road_clear(pl_x(),pl_z(), 40.0f+k*16.0f, 105.0f+k*28.0f, &ox,&oz)){ add_pickup(ox,oz,PK_PACKAGE); got++; } }
        if (got>=2){
            for (int i=0;i<NPICK;i++) if(picks[i].alive && picks[i].kind==PK_PACKAGE) picks[i].seen=1;  /* show on the map */
            mission=MI_PICKUP; mission_target=got; mission_kills=0;
            mission_t = 20.0f + got*11.0f;
            mission_pay = (int)((got*170.0f + frand()*160.0f)*mult);
            say("PICKUP: GRAB THE PACKAGES");
        } else for (int i=0;i<NPICK;i++) if(picks[i].kind==PK_PACKAGE) picks[i].alive=0;   /* undo a partial place */
    } else if (rot==MI_REPO){
        g_job_rival = pick_rival();
        int car = find_npc_car(30.0f, 150.0f);
        if (car>=0){
            mission=MI_REPO; mission_car=car; mx=cars[car].x; mz=cars[car].z;
            mission_t = 38.0f + frand()*14.0f;
            mission_pay = (int)((480.0f + frand()*260.0f)*mult);
            say("REPO: WRECK THE DEBTOR'S CAR");
        }
    } else if (rot==MI_ESCORT){
        float ox,oz;
        if (find_near(pl_x(),pl_z(), 8.0f, 26.0f, pav_or_grass, &ox,&oz) &&
            find_road_clear(pl_x(),pl_z(), 80.0f, 190.0f, &drop_x,&drop_z)){
            int slot=-1;
            for (int j=0;j<NPED;j++) if(!peds[j].alive || !peds[j].iscop){ slot=j; break; }
            if (slot>=0){
                peds[slot]=(Ped){ ox,oz,0,0,(uint8_t)(irand(4)),1,8,0,0,0,0 };  /* VIP: tougher, hp 8 */
                mission=MI_ESCORT; mission_target=slot; mx=ox; mz=oz;
                float d=road_dist(ox,oz, drop_x,drop_z); if(d<=0) d=160.0f;
                mission_t = 40.0f + d/5.0f;
                mission_pay = (int)((560.0f + d*1.5f + frand()*220.0f)*mult);
                add_heat(1.4f);                             /* the route runs hot */
                say("ESCORT: WALK THE VIP HOME");
            }
        }
    } else if (rot==MI_SMUGGLE){
        if (find_road_clear(pl_x(),pl_z(), 90.0f, 210.0f, &mx,&mz)){
            float d=road_dist(pl_x(),pl_z(), mx,mz); if(d<=0) d=160.0f;
            mission=MI_SMUGGLE; mission_cap = 2;             /* busted if you reach 3 stars */
            mission_t = 28.0f + d/6.0f;
            mission_pay = (int)((620.0f + d*1.7f + frand()*220.0f)*mult);
            say("SMUGGLE: STAY UNDER THE RADAR");
        }
    } else if (rot==MI_DEMO){
        int want = 3 + irand(3);                             /* 3-5 cars */
        for (int i=0;i<NCAR && mtarg_n<want && mtarg_n<6;i++){ Car*c=&cars[i];
            if(!c->alive||c->wrecked||i==player.car||c->type==VEH_TANK||c->type==VEH_HELI) continue;
            float dx=c->x-pl_x(),dz=c->z-pl_z(),d2=dx*dx+dz*dz;
            if(d2<18.0f*18.0f||d2>170.0f*170.0f) continue;
            mtarg[mtarg_n++]=i; }
        if (mtarg_n>=2){
            g_job_rival = pick_rival();
            mission=MI_DEMO; mission_target=mtarg_n; mission_kills=0;
            mission_t = 24.0f + mtarg_n*11.0f;
            mission_pay = (int)((mtarg_n*190.0f + frand()*160.0f)*mult);
            say("DEMOLITION: WRECK THEM ALL");
        } else mtarg_n=0;
    } else if (rot==MI_VIGIL){ mission=MI_VIGIL;
        g_job_rival = pick_rival();
        mission_cap = irand(4);                              /* which gang variant to cull */
        mission_target = 4 + irand(4);                       /* 4-7 kills */
        mission_kills = 0;
        mission_t = 28.0f + mission_target*4.5f;
        mission_pay = (int)((mission_target*125.0f + frand()*180.0f)*mult);
        owned[W_PISTOL]=1; if(ammo[W_PISTOL]<40)ammo[W_PISTOL]=40; if(weapon==W_FIST)weapon=W_PISTOL;
        say("VIGILANTE: THIN THE CREW");
    } else if (rot==MI_WANTED){ mission=MI_WANTED;
        mission_cap = 3;                                     /* reach & hold 3 stars */
        mission_hold = 0;
        mission_target = 20 + irand(10);                     /* seconds to survive at >=cap */
        mission_t = mission_target + 30.0f;
        mission_pay = (int)((900.0f + frand()*320.0f)*mult);
        owned[W_PISTOL]=1; if(ammo[W_PISTOL]<40)ammo[W_PISTOL]=40; if(weapon==W_FIST)weapon=W_PISTOL;
        say("MOST WANTED: SURVIVE THE HEAT");
    } else if (rot==MI_CIRCUIT){
        if (build_route(3+irand(2))){                        /* 3-4 checkpoints */
            mission=MI_CIRCUIT; cp_i=0; mx=cp_x[0]; mz=cp_z[0];
            float total=0, lx=pl_x(), lz=pl_z();
            for (int k=0;k<cp_n;k++){ float dx=cp_x[k]-lx, dz=cp_z[k]-lz; total+=sqrtf(dx*dx+dz*dz); lx=cp_x[k]; lz=cp_z[k]; }
            mission_t = 11.0f + total/8.5f;                   /* tight — you must actually drive it */
            mission_pay = (int)((300.0f + total*1.3f + frand()*160.0f)*mult);
            say("CIRCUIT: BEAT THE CLOCK");
        }
    } else { /* MI_RIVAL — a REAL AI sports car races the same checkpoint route */
        float ox,oz;
        if (build_route(3+irand(2)) && find_road_clear(pl_x(),pl_z(), 8.0f, 34.0f, &ox,&oz)){
            /* claim a car slot for the rival: reuse a nearby ambient traffic car, else a
             * free slot. is_mission_car(rival_car) then exempts it from the recycler. */
            int slot=-1;
            for (int j=6;j<NCAR;j++){ if(j==player.car) continue;
                if(cars[j].alive && cars[j].driver==DRV_NPC && cars[j].type!=VEH_TANK && cars[j].type!=VEH_BUS){ slot=j; break; } }
            if (slot<0) for (int j=6;j<NCAR;j++){ if(j!=player.car && !cars[j].alive){ slot=j; break; } }
            if (slot>=0){
                float yaw; place_in_lane(&ox,&oz,&yaw);       /* start on-road, lane-centred, facing the street */
                cars[slot]=(Car){ ox,oz,yaw,0,CAR_SPORTS,DRV_NPC,1,100.0f,0 };
                car_body_init(slot); npc_target[slot]=yaw; ai_state[slot]=AIS_CRUISE; stuck_t[slot]=0;
                mission=MI_RIVAL; cp_i=0; rival_i=0; rival_car=slot; mx=cp_x[0]; mz=cp_z[0];
                float total=0, lx=pl_x(), lz=pl_z();
                for (int k=0;k<cp_n;k++){ float dx=cp_x[k]-lx, dz=cp_z[k]-lz; total+=sqrtf(dx*dx+dz*dz); lx=cp_x[k]; lz=cp_z[k]; }
                mission_t = 20.0f + total/5.5f;               /* enough to finish if you push */
                mission_pay = (int)((520.0f + total*1.5f + frand()*220.0f)*mult);
                say("RACE: BEAT THE RIVAL");
            }
        }
    }
    return mission!=MI_NONE;
}

static float mission_mult(void){ return 1.0f + 0.25f*(float)(mission_chain>5?5:mission_chain); }

/* Job stakes rise with the streak: early calls lean to soft jobs; a hot streak
 * surfaces the heavy, better-paying work — the same contact escalating over time. */
static int pick_offer_type(int chain){
    static const int EASY[] = { MI_COURIER, MI_PICKUP, MI_DELIVER, MI_CIRCUIT, MI_SMUGGLE, MI_ESCORT, MI_REPO };
    static const int HARD[] = { MI_HIT, MI_RAMPAGE, MI_DEMO, MI_VIGIL, MI_WANTED, MI_RIVAL, MI_GETAWAY };
    int hardbias = chain>=3 ? 55 : chain>=1 ? 35 : 18;   /* % chance of a heavy job */
    if ((int)irand(100) < hardbias) return HARD[irand((int)(sizeof HARD/sizeof*HARD))];
    return EASY[irand((int)(sizeof EASY/sizeof*EASY))];
}

/* Roll job types (biased up by the streak) until one's props are in place. */
static int roll_mission(float mult){
    for (int a=0;a<8;a++){ int rot = pick_offer_type(mission_chain);
#ifdef MOTE_HOST
        if (g_force_mtype) rot = g_force_mtype;
#endif
        if (setup_mission(rot, mult)) return 1;
    }
    return 0;
}

/* Answer the phone: a contact offers ONE job — accept or decline. Land it and the
 * SAME contact rings back with something bigger (mission_win keeps the streak). */
static void start_mission(void) {
    if (mission!=MI_NONE) return;
    if (g_recur_seed==0){ g_employer = irand(NFACTION); g_recur_seed = g_fac[g_employer].seed; }  /* a crew boss takes you on */
    if (!roll_mission(mission_mult())){ say("LINE DEAD..."); return; }
    gen_contact(mission);                              /* face = your employer's boss (via g_recur_seed) */
    g_brief_active=1;
}

static char g_evt[44];   /* persistent buffer for a procedural event line passed to say() */
static void mission_win(void){
    cash += mission_pay; mission_chain++;
    sfx(&win_sfx,0.8f); float_txt(pl_x(),pl_z(),"PAID");
    if (g_employer>=0){ int s=g_fac[g_employer].standing+12; g_fac[g_employer].standing=(int8_t)(s>100?100:s); }
    int became_hostile=0;
    if (g_job_rival>=0){                                    /* hitting a crew turns them against you */
        int was=g_fac[g_job_rival].hostile;
        int s=g_fac[g_job_rival].standing-22; if(s<-100)s=-100; g_fac[g_job_rival].standing=(int8_t)s;
        if (s<=-55 && !was){ g_fac[g_job_rival].hostile=1; became_hostile=1; }
    }
    if (became_hostile){ snprintf(g_evt,sizeof g_evt,"THE %s WANT YOU DEAD", g_fac[g_job_rival].name); say(g_evt); }
    else say(mission_chain>=2 ? "THEY'LL REMEMBER THIS" : "JOB DONE");
    mission_cleanup(); mission=MI_NONE;
}

static int near_marker(int kind, float rad) {
    for (int i=0;i<nmark;i++) if(markers[i].kind==kind){
        float dx=markers[i].x-pl_x(), dz=markers[i].z-pl_z();
        if (dx*dx+dz*dz<rad*rad) return 1; }
    return 0;
}

static void buy_gun(void) {
    /* the gun shop stocks a tiered arsenal; each visit buys the next one you lack,
     * then just tops up ammo for the best gun you own. */
    if      (!owned[W_PISTOL]  && cash>=150) { owned[W_PISTOL]=1;  ammo[W_PISTOL]+=60;   cash-=150;  weapon=W_PISTOL;  say("PISTOL -$150"); }
    else if (!owned[W_UZI]     && cash>=250) { owned[W_UZI]=1;     ammo[W_UZI]+=120;     cash-=250;  weapon=W_UZI;     say("UZI -$250"); }
    else if (!owned[W_SMG]     && cash>=400) { owned[W_SMG]=1;     ammo[W_SMG]+=90;      cash-=400;  weapon=W_SMG;     say("SMG -$400"); }
    else if (!owned[W_GRENADE] && cash>=550) { owned[W_GRENADE]=1; ammo[W_GRENADE]+=8;   cash-=550;  weapon=W_GRENADE; say("GRENADES -$550"); }
    else if (!owned[W_SHOTGUN] && cash>=700) { owned[W_SHOTGUN]=1; ammo[W_SHOTGUN]+=28;  cash-=700;  weapon=W_SHOTGUN; say("SHOTGUN -$700"); }
    else if (!owned[W_MINIGUN] && cash>=1200){ owned[W_MINIGUN]=1; ammo[W_MINIGUN]+=300; cash-=1200; weapon=W_MINIGUN; say("MINIGUN -$1200"); }
    else if (cash>=50){
        int w = owned[W_MINIGUN]?W_MINIGUN : owned[W_SHOTGUN]?W_SHOTGUN : owned[W_GRENADE]?W_GRENADE :
                owned[W_SMG]?W_SMG : owned[W_UZI]?W_UZI : W_PISTOL;
        owned[w]=1; ammo[w] += (w==W_MINIGUN?150 : w==W_GRENADE?4 : 40); cash-=50; weapon=w; say("AMMO -$50");
    }
    else say("NEED MORE CASH");
    sfx(&cash_sfx,0.7f);
}

static void reset_game(void) {
    gta3_cam_reset(&g_cam);   /* cold start: nothing to smooth from yet */
    g_shells = TANK_SHELLS;   /* a fresh city means a fresh tank, fully loaded */
    g_titlet = 0.0f;          /* restart the title-screen orbit from a fixed angle each game */
    /* EVERY NEW GAME IS A NEW CITY: regenerate the whole map, then everything
     * below (colliders, markers, traffic, dock) rebuilds from the fresh tiles */
    {
        uint32_t seed = mote->micros ? (uint32_t)mote->micros() ^ (cg_rng*2654435761u) : cg_rng+1;
#ifdef MOTE_HOST
        { const char *sd=getenv("MOTE_GTA_SEED"); if (sd) seed=(uint32_t)strtoul(sd,0,10); }
#endif
        citygen(g_city, seed);
    }
    build_zebra_map();
    for (int i=0;i<NBULLET;i++) bullets[i].alive=0;
    for (int i=0;i<NPICK;i++) picks[i].alive=0;
    for (int i=0;i<NFX;i++) fxs[i].t=0;
    cash=0; health=MAXHP; heat=0; heat_cool=99; fire_cd=0;
    weapon=W_FIST; for(int i=0;i<NWEAP;i++){owned[i]=0;ammo[i]=0;} owned[W_FIST]=1; g_kills=0;
    mission=MI_NONE; g_msg_t=0; mission_chain=0; g_recur_seed=0;
    g_rng ^= (uint32_t)mote->micros();     /* each run is a different city day */
#ifdef MOTE_HOST
    if (getenv("MOTE_GTA_DEBUG")) fprintf(stderr,"[SEED] micros=%u rng=%u\n",(unsigned)mote->micros(),g_rng);
#endif
    spawn_world();
    place_markers();
    gen_factions();                                 /* fresh rival crews for this city */
    for (int i=0;i<nmark;i++){ float dx=markers[i].x-player.x, dz=markers[i].z-player.z;
        if (dx*dx+dz*dz < 60.0f*60.0f) markers[i].seen=1; }
    for (int i=0;i<NCAR;i++) car_body_init(i);      /* physics bodies for every vehicle */
    hosp_x=player.x; hosp_z=player.z;
    /* weapon CACHES hidden at random spots across the whole city */
    /* The ROCKET is out of the common table. As one of eight kinds across 28
     * caches it turned up three or four times per city, which is not a rare
     * prize — it is standard issue. It now appears in only a third of cities,
     * once, somewhere in the whole map. */
    { static const uint8_t CACHE[8]={PK_PISTOL,PK_SMG,PK_SHOTGUN,PK_FLAME,PK_HEALTH,PK_CASH,PK_SHOTGUN,PK_SMG};
      for (int k=0;k<28;k++){
        for (int t=0;t<40;t++){ int tx=2+irand(MAPW-4), tz=2+irand(MAPH-4);
            if (pav_or_grass(tx,tz)){ add_pickup(tx*TILE+TILE*0.5f, tz*TILE+TILE*0.5f, CACHE[irand(8)]); break; } } } }
    if (irand(3) == 0) {
        for (int t=0;t<200;t++){ int tx=2+irand(MAPW-4), tz=2+irand(MAPH-4);
            if (pav_or_grass(tx,tz)){ add_pickup(tx*TILE+TILE*0.5f, tz*TILE+TILE*0.5f, PK_ROCKET); break; } }
    }
    /* CACHES IN THE TREES. The scatter above lands anywhere walkable, which is
     * mostly pavement; nothing rewarded pushing into a park. A tile counts as
     * wooded when the scenery pass would put a tree on it — the SAME hash it
     * draws from, so a cache is always found under actual canopy rather than on
     * a bare patch that merely happens to be grass. */
    { static const uint8_t WOOD[6]={PK_CASH,PK_HEALTH,PK_SHOTGUN,PK_CASH,PK_SMG,PK_HEALTH};
      int placed=0;
      for (int t=0;t<3000 && placed<12;t++){
          int tx=2+irand(MAPW-4), tz=2+irand(MAPH-4);
          if (tile_at(tx,tz)!=' ') continue;
          unsigned h=(unsigned)(tx*668265263u ^ tz*374761393u);
          if ((h&3)==0) continue;                     /* the scenery pass skips these */
          add_pickup(tx*TILE+TILE*0.5f+1.6f, tz*TILE+TILE*0.5f+1.6f, WOOD[irand(6)]);
          placed++;
      } }
    /* THE STREET CREW. One city in three, four of them on one patch of
     * pavement well away from where you start, all wearing the same variant so
     * they read as a crew rather than four strangers who happen to be cross. */
    g_gang_alive = 0;
    int want_gang = (irand(3) == 0);
#ifdef MOTE_HOST
    /* test: MOTE_GTA_GANG=1 forces the crew to exist. One city in three means
     * hunting for a seed that has one, and the seed also fixes where they are. */
    if (getenv("MOTE_GTA_GANG")) want_gang = 1;
#endif
    if (want_gang) {
        float ox, oz;
        if (find_near(player.x, player.z, 60.0f, 220.0f, pav_or_grass, &ox, &oz)) {
            uint8_t v = (uint8_t)irand(4);
            for (int k = 0; k < GANG_N; k++) {
                int slot = -1;
                for (int j = 0; j < NPED; j++) if (!peds[j].alive) { slot = j; break; }
                if (slot < 0) break;
                float a = (float)k * 1.5708f;
                peds[slot] = (Ped){ ox + cosf(a)*1.6f, oz + sinf(a)*1.6f,
                                    0, 0, v, 1, 3, 0, 0, 0, 0, 0, /*gang*/1 };
                g_gang_alive++;
            }
        }
    }

    /* ROOFTOP CACHES — the reward for finding the helicopter.
     *
     * Five of them, on the roofs of TALL buildings only ('H', the top height
     * band), so they cannot be reached on foot and are worth the trip. The
     * best prizes in the game go here: the rocket, the flamer, a full medkit
     * and cash, rather than another pistol.
     *
     * They need no new field. A pickup's height is floor_y() at its position,
     * which is the roof it stands on, and update_pickups uses the same lookup
     * to decide you have to be level with it to take it. */
    { static const uint8_t ROOF[5]={PK_ROCKET,PK_FLAME,PK_HEALTH,PK_CASH,PK_SHOTGUN};
      int placed=0;
      for (int t=0;t<4000 && placed<5;t++){
          int tx=2+irand(MAPW-4), tz=2+irand(MAPH-4);
          if (tile_at(tx,tz)!='H' || is_garage(tx,tz)) continue;
          add_pickup(tx*TILE+TILE*0.5f, tz*TILE+TILE*0.5f, ROOF[placed]);
          placed++;
      } }
    /* weapons + medkits scattered on pavements around the start */
    add_pickup(markers[0].x+2, markers[0].z+2, PK_PISTOL);
    { static const uint8_t scatter[8]={PK_PISTOL,PK_SMG,PK_HEALTH,PK_SHOTGUN,PK_SMG,PK_HEALTH,PK_PISTOL,PK_HEALTH};
      for (int k=0;k<8;k++){ float ox,oz;
        if (find_near(player.x,player.z, 20.0f+k*9.0f, 40.0f+k*11.0f, pav_or_grass, &ox,&oz))
            add_pickup(ox,oz,scatter[k]); } }
#ifdef MOTE_HOST
    { const char *vw=getenv("MOTE_GTA_VIEW");            /* teleport: "x,z" tile coords */
      float tx,tz;
      if (vw && sscanf(vw,"%f,%f",&tx,&tz)==2){ player.mode=MODE_FOOT; player.x=tx*TILE; player.z=tz*TILE; } }
#endif
}

static void respawn(int busted) {
    cash = cash>150 ? cash-150 : 0;
    health=MAXHP; heat=0; heat_cool=99;
    for (int i=0;i<NCAR;i++) if(cars[i].alive&&cars[i].driver==DRV_COP) cars[i].driver=DRV_NPC;
    player.mode=MODE_FOOT; player.car=-1; player.x=hosp_x; player.z=hosp_z;
    if (busted){ weapon=W_FIST; }        /* busted: lose your guns */
    g_state=ST_PLAY;
}

/* ============================================== 2P deathmatch (see state block) */
static void dm_send_hello(void){
    uint8_t m[5]={0xA5,'H',DM_PROTO,(uint8_t)dm_my_nonce,(uint8_t)(dm_my_nonce>>8)};
    mote->link_send(m,5);
}
static void dm_send_state(void){
    static float lx, lz;
    float x=pl_x(), z=pl_z();
    int moving = (x-lx)*(x-lx)+(z-lz)*(z-lz) > 0.05f; lx=x; lz=z;
    int16_t xi=(int16_t)(x*8.0f), zi=(int16_t)(z*8.0f);
    uint8_t fl=(uint8_t)((player.mode==MODE_CAR?1:0)|(moving?2:0)|(dm_dead_t>0?4:0));
    uint8_t m[10]={0xA5,'P',(uint8_t)xi,(uint8_t)(xi>>8),(uint8_t)zi,(uint8_t)(zi>>8),
                   (uint8_t)(int8_t)(pl_yaw()*40.5845f), fl,
                   (uint8_t)(player.car>=0?cars[player.car].type:0),
                   (uint8_t)(health<0?0:health)};
    mote->link_send(m,10);
}
static void dm_send_carback(int ci){                 /* car ci re-enters the shared world */
    Car *c=&cars[ci];
    int16_t xi=(int16_t)(c->x*8.0f), zi=(int16_t)(c->z*8.0f);
    /* carry the car's MOMENTUM back too, so a car you bail out of at speed
     * keeps rolling on the other screen instead of snapping to a stop */
    int16_t vx=(int16_t)(bodies[ci].vx*64.0f), vz=(int16_t)(bodies[ci].vy*64.0f);
    uint8_t m[13]={0xA5,'X',(uint8_t)ci,(uint8_t)xi,(uint8_t)(xi>>8),(uint8_t)zi,(uint8_t)(zi>>8),
                  (uint8_t)(int8_t)(c->yaw*40.5845f),(uint8_t)(c->wrecked?1:0),
                  (uint8_t)vx,(uint8_t)(vx>>8),(uint8_t)vz,(uint8_t)(vz>>8)};
    mote->link_send(m,13);
}
static void dm_die(void){
    dm_send1('K');
    dm_peer_frags++;
    dm_dead_t=2.5f;
    sfx(&bust_sfx,0.7f);
    add_fx(pl_x(),pl_z(),0);
    if (player.mode==MODE_CAR && player.car>=0){     /* release the car for the peer */
        cars[player.car].driver=DRV_NONE; cars[player.car].spd=0;
        dm_send_carback(player.car);
        player.mode=MODE_FOOT; player.x=pl_x(); player.z=pl_z(); player.car=-1;
    }
    if (dm_peer_frags>=DM_FRAGS && !dm_end) dm_end=2;
}
static void dm_respawn_me(void){
    health=MAXHP;
    player.mode=MODE_FOOT; player.car=-1;
    player.x=dm_spawnx; player.z=dm_spawnz; player.yaw=-1.5708f;
}
static void dm_handle(const uint8_t *m){
    switch (m[1]) {
        case 'H': dm_got_hello=1; dm_peer_nonce=(uint16_t)(m[3]|(m[4]<<8)); break;
        case 'S': if (dm_got_hello && dm_my_nonce > dm_peer_nonce) break;   /* I generate; a crossed 'S' is stale */
                  dm_seed=(uint32_t)m[2]|((uint32_t)m[3]<<8)|((uint32_t)m[4]<<16)|((uint32_t)m[5]<<24);
#ifdef MOTE_HOST
                  if (getenv("MOTE_GTA_DEBUG")) fprintf(stderr,"[SEED-RX] %08x\n",dm_seed);
#endif
                  dm_phase=1; dm_map_recv=0; break;   /* peer: seed known, expect the map */
        case 'm': { int seq=m[2]|(m[3]<<8), len=m[4], off=seq*DM_CHUNK;
                    for (int i=0;i<len && off+i<CITY_BYTES;i++) g_city[off+i]=m[5+i];
                    if (off+len > dm_map_recv) dm_map_recv=off+len; } break;
        case 'P': {
            int16_t xi=(int16_t)(m[2]|(m[3]<<8)), zi=(int16_t)(m[4]|(m[5]<<8));
            rp_x=xi/8.0f; rp_z=zi/8.0f; rp_yaw=(int8_t)m[6]/40.5845f;
            rp_mode=m[7]&1; rp_moving=(m[7]>>1)&1; rp_cartype=m[8];
            rp_hp=(m[7]&4)?0:m[9];
            dm_rx_age=0;
        } break;
        case 'F': rp_fire_t=0.25f;
                  { float d=sqrtf((rp_x-pl_x())*(rp_x-pl_x())+(rp_z-pl_z())*(rp_z-pl_z()));
                    float g=1.0f-d/50.0f; if(g<0.08f)g=0.08f; if(g>0.5f)g=0.5f;
                    sfx(&shoot_sfx,g); }
                  break;
        case 'D': if (dm_dead_t<=0 && !dm_end){ add_fx(pl_x(),pl_z(),0); hurt_player((float)m[2]); } break;
        case 'K': dm_frags++;
                  add_fx(rp_x,rp_z,0); add_fx(rp_x+0.5f,rp_z-0.4f,0);
                  sfx(&boom_sfx,0.4f);
                  if (dm_frags>=DM_FRAGS && !dm_end) dm_end=1;
                  break;
        case 'V': {                              /* peer: the authority's ambient traffic */
            for (int i=0;i<NCAR;i++) dm_tpresent[i]=0;
            int n=m[2];
            for (int k=0;k<n;k++){ const uint8_t *e=m+3+k*6; int ci=e[0]&0x7f;
                if (ci>=NCAR) continue;
                int16_t xi=(int16_t)(e[1]|(e[2]<<8)), zi=(int16_t)(e[3]|(e[4]<<8));
                float nx=xi/8.0f, nz=zi/8.0f;
                if (dm_tpresent[ci] || cars[ci].alive){    /* velocity from the position delta (~12 Hz stream) */
                    float vx=(nx-dm_tx[ci])*12.0f, vz=(nz-dm_tz[ci])*12.0f;
                    float sp2=vx*vx+vz*vz; if (sp2 < 60.0f*60.0f){ dm_tvx[ci]=vx; dm_tvz[ci]=vz; }  /* reject teleport/recycle jumps */
                }
                dm_tx[ci]=nx; dm_tz[ci]=nz; dm_tyaw2[ci]=(int8_t)e[5]/40.5845f;
                cars[ci].alive=1; cars[ci].wrecked=(e[0]&0x80)?1:0; dm_tpresent[ci]=1;
            }
            for (int i=0;i<NCAR;i++)             /* not in 'V' & not mine → the authority's own car slot: hide */
                if (!dm_tpresent[i] && i!=player.car){ cars[i].alive=0; bodies[i].inv_mass=0;
                    bodies[i].x=1e6f+i*4; bodies[i].y=1e6f; }
#ifdef MOTE_HOST
            if(getenv("MOTE_GTA_DEBUG")){ float sx=0; for(int i=0;i<NCAR;i++) if(dm_tpresent[i])sx+=dm_tx[i];
                static int c; if((c++%12)==0) fprintf(stderr,"[PEER] traffic=%d sumx=%.0f\n",n,sx); }
#endif
        } break;
        case 'C': { int ci=m[2]; if (ci<NCAR && ci!=player.car){ dm_peer_car=ci; cars[ci].alive=0; } } break;
        case 'X': { int ci=m[2]; if (ci==dm_peer_car) dm_peer_car=-1;   /* peer released it */
            if (ci<NCAR){
                int16_t xi=(int16_t)(m[3]|(m[4]<<8)), zi=(int16_t)(m[5]|(m[6]<<8));
                cars[ci].alive=1; cars[ci].x=xi/8.0f; cars[ci].z=zi/8.0f;
                cars[ci].yaw=(int8_t)m[7]/40.5845f;
                cars[ci].driver=DRV_NONE; cars[ci].wrecked=(m[8]&1);
                cars[ci].hp=cars[ci].wrecked?0:100.0f;
                car_body_init(ci);
                int16_t vx=(int16_t)(m[9]|(m[10]<<8)), vz=(int16_t)(m[11]|(m[12]<<8));
                bodies[ci].vx=vx/64.0f; bodies[ci].vy=vz/64.0f;   /* restore momentum from the handoff */
                cars[ci].spd=bodies[ci].vx*cosf(cars[ci].yaw)+bodies[ci].vy*sinf(cars[ci].yaw);
                dm_tvx[ci]=bodies[ci].vx; dm_tvz[ci]=bodies[ci].vy;
            } } break;
        case 'T': { int i=m[2]; if (i<NPICK && picks[i].alive){ picks[i].alive=0; g_dmpkt[i]=20.0f; } } break;
        case 'Z': dm_peer_hash=(uint32_t)m[2]|((uint32_t)m[3]<<8)|((uint32_t)m[4]<<16)|((uint32_t)m[5]<<24);
                  dm_got_hash=1;
                  if (dm_phase>=2){ uint8_t a[2]={0xA5,'Y'}; mote->link_send(a,2); }  /* late re-'Z': re-ack */
                  break;
        case 'R': dm_map_pos=0; dm_map_acked=0;             /* peer wants the map again */
                  break;
        case 'Y': dm_map_acked=1; break;
        case 'y': dm_world_acked=1; break;                  /* peer holds the world */
        case 'W': if (!(dm_my_nonce>dm_peer_nonce)){    /* cars + spawns */
                  if (!dm_w_done){
                      dm_w_done=1;
                      int p=2;
                      int sax=m[p++], saz=m[p++], sbx=m[p++], sbz=m[p++];
                      player.x=sbx*TILE+TILE*0.5f; player.z=sbz*TILE+TILE*0.5f;
                      rp_x=rp_dx2=sax*TILE+TILE*0.5f; rp_z=rp_dz2=saz*TILE+TILE*0.5f;
                      dm_spawnx=player.x; dm_spawnz=player.z; hosp_x=player.x; hosp_z=player.z;
                      for (int i=0;i<16;i++){
                          int tx=m[p++], tz=m[p++], ty=m[p++]; float yaw=(int8_t)m[p++]/40.5845f;
                          cars[i]=(Car){ tx*TILE+TILE*0.5f, tz*TILE+TILE*0.5f, yaw, 0,(uint8_t)ty,
                                         (i<6)?DRV_NONE:DRV_NPC, 1,100.0f,0 };
                          car_body_init(i);
                          dm_tx[i]=cars[i].x; dm_tz[i]=cars[i].z; dm_tyaw2[i]=cars[i].yaw; dm_tpresent[i]=1;
                      }
                  }
                  if (dm_w_done && dm_wc_done){ uint8_t a[2]={0xA5,'y'}; mote->link_send(a,2); }
                  } break;
        case 'w': if (!(dm_my_nonce>dm_peer_nonce)){    /* weapon caches */
                  if (!dm_wc_done){
                      dm_wc_done=1;
                      for (int i=0;i<NPICK;i++) picks[i].alive=0;
                      int p=2;
                      for (int k=0;k<40;k++){
                          int tx=m[p++], tz=m[p++], ty=m[p++];
                          add_pickup(tx*TILE+TILE*0.5f, tz*TILE+TILE*0.5f, ty);
                      }
                      for (int i=0;i<NPICK;i++) picks[i].seen=1;
#ifdef MOTE_HOST
                      dm_world_hash_log("peer-applied");
#endif
                  }
                  if (dm_w_done && dm_wc_done){ uint8_t a[2]={0xA5,'y'}; mote->link_send(a,2); }
                  } break;
        case 'Q': if (!dm_end) dm_end=3; break;
    }
}
static void dm_poll(void){
    uint8_t chunk[48]; int n;
    while ((n=mote->link_recv(chunk,(int)sizeof chunk))>0){
        for (int i=0;i<n;i++){
            uint8_t b=chunk[i];
            if (dm_msg_len==0){ if (b==0xA5) dm_msg[dm_msg_len++]=b; continue; }
            dm_msg[dm_msg_len++]=b;
            int t=dm_msg[1];
            int want;
            if (t=='m') want = dm_msg_len<5 ? 5 : 5+dm_msg[4];   /* header then len bytes */
            else if (t=='V') want = dm_msg_len<3 ? 3 : 3+dm_msg[2]*6; /* n entries × 6 */
            else want = t=='w'?122 : t=='W'?70 : t=='P'?10 : t=='X'?13 : (t=='S'||t=='Z')?6 : t=='H'?5
                     : (t=='D'||t=='C'||t=='T')?3 : (t=='F'||t=='K'||t=='Q'||t=='R'||t=='Y'||t=='y')?2 : -1;
            if (want<0){ dm_msg_len=0; continue; }
            if (dm_msg_len<want) continue;
            dm_msg_len=0; dm_handle(dm_msg);
        }
    }
}
static void dm_stop(void){ g_dm=0; mote->link_stop(); }
/* DM shared-traffic recycler (AUTHORITY only): the map is huge and the two players
 * are far apart, so a fixed scatter leaves both streets empty. Each tick, take the
 * ambient car farthest from BOTH players and, if it's out of sight of both, drop it
 * onto a road near whichever player currently has fewer cars around — so the shared
 * pool keeps BOTH players' streets alive. Peer just renders the stream. */
static float dm_recyc_t;
static int dm_cars_near(float px,float pz,float r){ int n=0; float r2=r*r;
    for(int i=0;i<NCAR;i++){ if(!cars[i].alive||cars[i].driver!=DRV_NPC) continue;
        float dx=cars[i].x-px,dz=cars[i].z-pz; if(dx*dx+dz*dz<r2)n++; } return n; }
static void dm_recycle_traffic(float dt){
    dm_recyc_t-=dt; if(dm_recyc_t>0) return; dm_recyc_t=0.5f;
    float ax=pl_x(),az=pl_z(), bx=rp_x,bz=rp_z;      /* my pos + the peer's (from 'P') */
    int far=-1; float fbest=55.0f*55.0f;
    for(int i=0;i<NCAR;i++){ if(!cars[i].alive||cars[i].driver!=DRV_NPC||i==dm_peer_car) continue;
        float da=(cars[i].x-ax)*(cars[i].x-ax)+(cars[i].z-az)*(cars[i].z-az);
        float db=(cars[i].x-bx)*(cars[i].x-bx)+(cars[i].z-bz)*(cars[i].z-bz);
        float d=da<db?da:db;                          /* distance to the NEARER player */
        if(d>fbest){ fbest=d; far=i; } }
    if(far<0) return;                                 /* everything's already near someone */
    float tx=ax,tz=az;                                /* refill around the needier player */
    if(dm_cars_near(bx,bz,45.0f) < dm_cars_near(ax,az,45.0f)){ tx=bx; tz=bz; }
    float ox,oz;
    if(find_road_clear(tx,tz, 26.0f, 52.0f, &ox,&oz)){
        int ty=irand(NCARTYPE); if(ty==CAR_POLICE||ty==CAR_POLICE2||ty==CAR_FIRETRUCK)ty=CAR_SEDAN;

        cars[far]=(Car){ ox,oz, road_heading((int)(ox/TILE),(int)(oz/TILE)), 0,(uint8_t)ty,DRV_NPC,1,100.0f,0 };
        car_body_init(far);
    }
}

/* Everything after the map exists (identical on both units): zebra, clears,
 * deterministic spawns/cars/caches from the integer RNG. Called by the authority
 * once its map is generated + sent, and by the peer once the map has arrived. */
static void reset_game_dm_finish(uint32_t seed){
    /* EVERYTHING below derives from g_rng (spawn search, PARKED CAR placement,
     * traffic init). The authority consumed RNG while GENERATING the city; the
     * peer received it and consumed none — their g_rng states differed, so the
     * two units placed the jackable cars (and spawns) in DIFFERENT spots: you
     * could see a car your unit invented and fail to enter it ('can't get in
     * cars'). Reseed BOTH units identically from the shared match seed. */
    g_rng = seed ^ 0x51ED2701u; if (!g_rng) g_rng = 1u;
    g_dm=1; dm_started=1; dm_end=0; dm_frags=dm_peer_frags=0; dm_dead_t=0; dm_send_t=0; dm_rx_age=0; dm_ramcd=0;
    rp_hp=100; rp_mode=0; rp_fire_t=0; rp_cartype=0; dm_msg_len=0; rp_anim=0;
    build_zebra_map();
#ifdef MOTE_HOST
    if(getenv("MOTE_GTA_DEBUG")){
        unsigned long h=1469598103934665603UL;
        for(int i=0;i<CITY_BYTES;i++){ h^=g_city[i]; h*=1099511628211UL; }
        fprintf(stderr,"[DMMAP] city fnv=%016lx seed=%08x\n",h,(unsigned)seed); }
#endif
    for (int i=0;i<NBULLET;i++) bullets[i].alive=0;
    for (int i=0;i<NPICK;i++){ picks[i].alive=0; g_dmpkt[i]=0; }
    for (int i=0;i<NFX;i++) fxs[i].t=0;
    for (int i=0;i<NPED;i++) peds[i].alive=0;              /* an empty city: just you two */
    cash=0; health=MAXHP; heat=0; heat_cool=99; fire_cd=0;
    weapon=W_PISTOL; for(int i=0;i<NWEAP;i++){owned[i]=0;ammo[i]=0;}
    owned[W_FIST]=1; owned[W_PISTOL]=1; ammo[W_PISTOL]=60; g_kills=0;
    mission=MI_NONE; g_msg_t=0; mission_chain=0; g_recur_seed=0; nmark=0;  /* no shops/phones/missions */
    g_rng = seed*2246822519u | 1u;   /* DETERMINISTIC: both units roll identically below */
    /* spawn A: the seeded pavement-by-a-road search (same result on both units) */
    int sx=MAPW/2, sz=MAPH/2, done=0;
    for (int t=0;t<24 && !done;t++){
        int bx=MAPW/4+irand(MAPW/2), bz=MAPH/4+irand(MAPH/2);   /* central half */
        for (int r=0;r<10 && !done;r++)
            for (int dz=-r;dz<=r && !done;dz++) for (int dx=-r;dx<=r && !done;dx++){
                int x=bx+dx,z=bz+dz; if(x<2||z<2||x>=MAPW-2||z>=MAPH-2) continue;
                if (tile_at(x,z)==',' && (is_roadlike(x+1,z)||is_roadlike(x-1,z)||is_roadlike(x,z+1)||is_roadlike(x,z-1)))
                    { sx=x; sz=z; done=1; } }
    }
    float axp=sx*TILE+TILE*0.5f, azp=sz*TILE+TILE*0.5f;
    /* spawn B: a pavement tile a MODERATE distance from A — close enough that the
     * fight starts quickly, far enough not to spawn-camp. Both spawns stay inside
     * the central half of the map; among candidates in a 30..70-tile ring from A,
     * take the one closest to 45 tiles (deterministic: same scan on both units).
     * (The old rule picked the map-corner FARTHEST tile — a dull trek.) */
    float bd=1e18f; int fx2=sx, fz2=sz;
    { int cx0=MAPW/4, cx1=MAPW-MAPW/4, cz0=MAPH/4, cz1=MAPH-MAPH/4;   /* central half */
      for (int z=cz0;z<cz1;z+=2) for (int x=cx0;x<cx1;x+=2){
          if (tile_at(x,z)!=',') continue;
          float dx=(float)(x-sx), dz=(float)(z-sz), d2=dx*dx+dz*dz;
          if (d2 < 30.0f*30.0f || d2 > 70.0f*70.0f) continue;
          float score = (d2-45.0f*45.0f)*(d2-45.0f*45.0f);
          if (score<bd){ bd=score; fx2=x; fz2=z; } }
      if (fx2==sx && fz2==sz){                    /* no ring candidate (odd map): widen */
          float far2=-1;
          for (int z=cz0;z<cz1;z+=2) for (int x=cx0;x<cx1;x+=2){
              if (tile_at(x,z)!=',') continue;
              float dx=(float)(x-sx), dz=(float)(z-sz), d2=dx*dx+dz*dz;
              if (d2>far2){ far2=d2; fx2=x; fz2=z; } }
      } }
    float bxp=fx2*TILE+TILE*0.5f, bzp=fz2*TILE+TILE*0.5f;
    int i_won = dm_my_nonce>dm_peer_nonce;
    player.mode=MODE_FOOT; player.car=-1; player.yaw=-1.5708f; player.animt=0;
    if (i_won){ player.x=axp; player.z=azp; rp_x=rp_dx2=bxp; rp_z=rp_dz2=bzp; }
    else      { player.x=bxp; player.z=bzp; rp_x=rp_dx2=axp; rp_z=rp_dz2=azp; }
    dm_spawnx=player.x; dm_spawnz=player.z;
    hosp_x=player.x; hosp_z=player.z;
#ifdef MOTE_HOST
    if (getenv("MOTE_GTA_DEBUG")){
        float ddx=(axp-bxp)/TILE, ddz=(azp-bzp)/TILE;
        fprintf(stderr,"[SPAWN] A=(%d,%d) B=(%d,%d) dist=%.0f tiles (map %dx%d)\n",
                sx,sz,fx2,fz2,(float)__builtin_sqrtf(ddx*ddx+ddz*ddz),MAPW,MAPH);
    }
#endif
    /* Shared cars (deterministic on both units — identical map + integer RNG):
     *   slots 0..5   PARKED, jackable (ownership via the tested 'C'/'X' path),
     *   slots 6..15  MOVING ambient traffic — the AUTHORITY drives them (DRV_NPC)
     *                and streams positions ('V'); the peer renders them from the
     *                stream. Ambient traffic isn't jackable in DM (V1). */
    dm_auth = dm_my_nonce > dm_peer_nonce;
    dm_peer_car = -1;
    for (int i=0;i<NCAR;i++) cars[i].alive=0;
    for (int i=0;i<16;i++){
        int parked = (i<6);
        /* slots 0 and 1 are each player's STARTING car, parked right by their
         * spawn (0 = spawn A, 1 = spawn B), random type. The authority places
         * them and transmits the whole world via 'W', so both units agree. */
        if (i<2){
            float sxp=(i==0)?axp:bxp, szp=(i==0)?azp:bzp, ox,oz;
            if (find_near(sxp,szp, 2.0f, 8.0f, is_drivable, &ox,&oz)){
                int ty=irand(NCARTYPE); if(ty==CAR_POLICE||ty==CAR_POLICE2||ty==CAR_FIRETRUCK)ty=CAR_SEDAN;

                cars[i]=(Car){ ox,oz, road_heading((int)(ox/TILE),(int)(oz/TILE)), 0,(uint8_t)ty, DRV_NONE,1,100.0f,0 };
                continue;
            }
        }
        for (int t=0;t<80;t++){ int tx=2+irand(MAPW-4), tz=2+irand(MAPH-4);
            if (parked ? !is_drivable(tx,tz) : !is_road(tx,tz)) continue;
            int ty=irand(NCARTYPE); if(ty==CAR_POLICE||ty==CAR_POLICE2||ty==CAR_FIRETRUCK)ty=CAR_SEDAN;

            cars[i]=(Car){ tx*TILE+TILE*0.5f, tz*TILE+TILE*0.5f,
                           road_heading(tx,tz), 0,(uint8_t)ty, parked?DRV_NONE:DRV_NPC, 1,100.0f,0 };
            break; }
    }
    for (int i=0;i<NCAR;i++){ car_body_init(i); dm_tx[i]=cars[i].x; dm_tz[i]=cars[i].z; dm_tyaw2[i]=cars[i].yaw; dm_tpresent[i]=1; }
    dm_vsend_t=0;
    /* weapon caches across the city (seeded, identical, respawning) */
    { static const uint8_t CACHE[8]={PK_PISTOL,PK_SMG,PK_SHOTGUN,PK_FLAME,PK_HEALTH,PK_SMG,PK_ROCKET,PK_SHOTGUN};
      for (int k=0;k<40;k++)
        for (int t=0;t<40;t++){ int tx=2+irand(MAPW-4), tz=2+irand(MAPH-4);
            if (pav_or_grass(tx,tz)){ add_pickup(tx*TILE+TILE*0.5f, tz*TILE+TILE*0.5f, CACHE[irand(8)]); break; } } }
    /* TREASURE ISLE cache. citygen carved the island and its footbridge and
     * exported the centre; this stocks it. Placed here, near the end of
     * spawn_world, because add_pickup and the PK_ kinds are declared well
     * below the spawn code that runs first.
     *
     * Cash, health and a shotgun: worth the walk, and the pair you most want
     * after fighting your way out of somewhere. */
    if (cg_isle_x >= 0) {
        float ix = (cg_isle_x + 0.5f) * TILE, iz = (cg_isle_y + 0.5f) * TILE;
        add_pickup(ix,             iz,             PK_CASH);
        add_pickup(ix + TILE*1.2f, iz,             PK_CASH);
        add_pickup(ix - TILE*1.2f, iz,             PK_CASH);
        add_pickup(ix,             iz + TILE*1.2f, PK_HEALTH);
        add_pickup(ix,             iz - TILE*1.2f, PK_SHOTGUN);
    }
    for (int i=0;i<NPICK;i++) picks[i].seen=1;   /* caches show on the DM map */
    g_state=ST_PLAY;
#ifdef MOTE_HOST
    if (getenv("MOTE_GTA_DEBUG")){
        uint32_t h=2166136261u;
        for (int i=0;i<16;i++){ h^=(int)(cars[i].x/TILE); h*=16777619u; h^=(int)(cars[i].z/TILE); h*=16777619u; h^=cars[i].type; h*=16777619u; }
        for (int i=0;i<NPICK;i++){ if(!picks[i].alive)continue; h^=(int)(picks[i].x/TILE); h*=16777619u; h^=(int)(picks[i].z/TILE); h*=16777619u; h^=picks[i].kind; h*=16777619u; }
        fprintf(stderr,"[WORLD] local-gen fnv=%08x spawn=(%d,%d)\n",h,(int)(player.x/TILE),(int)(player.z/TILE));
    }
#endif
}
#ifdef MOTE_HOST
static void dm_world_hash_log(const char *tag){
    if (!getenv("MOTE_GTA_DEBUG")) return;
    uint32_t h=2166136261u;
    for (int i=0;i<16;i++){ h^=(int)(cars[i].x/TILE); h*=16777619u; h^=(int)(cars[i].z/TILE); h*=16777619u; h^=cars[i].type; h*=16777619u; }
    for (int i=0;i<NPICK;i++){ if(!picks[i].alive)continue; h^=(int)(picks[i].x/TILE); h*=16777619u; h^=(int)(picks[i].z/TILE); h*=16777619u; h^=picks[i].kind; h*=16777619u; }
    fprintf(stderr,"[WORLD] %s fnv=%08x me=(%d,%d) peer=(%d,%d)\n",tag,h,(int)(player.x/TILE),(int)(player.z/TILE),(int)(rp_x/TILE),(int)(rp_z/TILE));
}
#endif
/* Authority ships the PLACED world — both spawns, all 16 cars, all 40 caches —
 * so the peer never derives placement from the seed. (Identical RNG streams
 * are not guaranteed across builds: device vs preview is ARM vs x86.)
 * Re-offered every 0.5s until the peer acks with 'y'. */
static void dm_send_world(void){
    { uint8_t w[70]; int p=0;
      w[p++]=0xA5; w[p++]='W';
      w[p++]=(uint8_t)((int)(dm_spawnx/TILE)); w[p++]=(uint8_t)((int)(dm_spawnz/TILE));
      w[p++]=(uint8_t)((int)(rp_x/TILE));      w[p++]=(uint8_t)((int)(rp_z/TILE));
      for (int i=0;i<16;i++){
          w[p++]=(uint8_t)((int)(cars[i].x/TILE)); w[p++]=(uint8_t)((int)(cars[i].z/TILE));
          w[p++]=cars[i].type; w[p++]=(uint8_t)(int8_t)(cars[i].yaw*40.5845f);
      }
      mote->link_send(w,p); }
    { uint8_t w[122]; int p=0;
      w[p++]=0xA5; w[p++]='w';
      int sent=0;
      for (int i=0;i<NPICK && sent<40;i++){ if(!picks[i].alive) continue;
          w[p++]=(uint8_t)((int)(picks[i].x/TILE)); w[p++]=(uint8_t)((int)(picks[i].z/TILE));
          w[p++]=picks[i].kind; sent++; }
      while (sent<40){ w[p++]=0; w[p++]=0; w[p++]=PK_HEALTH; sent++; }
      mote->link_send(w,p); }
}
static void dm_draw_remote(void){
    if (!g_dm || !dm_started || rp_hp<=0) return;
    if (rp_mode){                                     /* they're driving */
        int ty=rp_cartype; if (ty>=NCARTYPE) ty%=NCARTYPE;
        Car rpc = { rp_dx2, rp_dz2, rp_yaw, 0, (uint8_t)ty, DRV_NONE, 1, 0, 0, 0 };
        draw_vehicle_mesh(&rpc);
    } else {                                          /* on foot, same hero sprite */
        int fr = rp_fire_t>0 ? 5 : rp_moving ? ((int)(rp_anim*8.0f)&3) : 0;
        draw_character(&player_img, rp_dx2, rp_dz2, rp_yaw, 0, fr, 6);
    }
}

/* step the engine 2D solver over the vehicle bodies, then read results back into
 * the cars. Bodies own position/rotation/velocity; buildings + water stay tile-
 * based (revert an axis that would leave the road/land). */
/* drop NPC car i onto a fresh, clear road tile near the player, facing along it */
static void respawn_npc(int i) {
    float ox,oz;
    if (find_road_clear(pl_x(),pl_z(), 46.0f, 78.0f, &ox,&oz)){
        int ty=irand(NCARTYPE); if(ty==CAR_POLICE||ty==CAR_POLICE2||ty==CAR_FIRETRUCK)ty=CAR_SEDAN;
   /* no far-recycled buses */
        float yaw; place_in_lane(&ox,&oz,&yaw);                   /* right lane, facing along the street */
        cars[i]=(Car){ ox,oz,yaw,0,(uint8_t)ty,DRV_NPC,1,100,0 };
        car_body_init(i); npc_target[i]=yaw; stuck_t[i]=0;
    }
}

/* keep a lively bubble of traffic + peds around the player: anything too far, or
 * wedged/stuck too long, is recycled to a fresh clear spot. Constant entity count
 * → the city can be any size. Cops (heat) and the tank are left alone. */
/* A car the active job depends on (rival, repo/deliver target, a demo target) must
 * NOT be recycled when it drifts far from the player, or the job breaks. */
static int is_mission_car(int i){
    if (mission==MI_NONE) return 0;
    if (i==mission_car || i==rival_car) return 1;
    if (mission==MI_DEMO) for(int k=0;k<mtarg_n;k++) if(mtarg[k]==i) return 1;
    return 0;
}
static void stream_entities(float dt) {
    if (g_dm) return;              /* DM: index-shared world — nothing recycles */
    float px=pl_x(), pz=pl_z();
    /* The entity streamer sizes its spawn bubble from how far the camera can
     * actually see. The chase camera's ground draw distance is constant
     * (VIEW_GROUND_R), unlike the old top-down camera's height, which zoomed
     * out with speed — so the bubble is now a flat radius rather than a speed
     * curve. */
    float vis_h = VIEW_GROUND_R;
    for (int i=0;i<NCAR;i++){ Car*c=&cars[i];
        /* The helicopter is exempt from recycling for the same reason the tank
          * is: it is a one-off prize placed at generation, and stream_entities
          * would respawn a parked one as ordinary traffic the moment you walked
          * away from it. */
        if (!c->alive || i==player.car || c->driver==DRV_COP ||
            c->type==VEH_TANK || c->type==VEH_HELI) continue;
        if (is_mission_car(i)) continue;      /* the job's own cars are exempt from recycling */
        float dx=c->x-px, dz=c->z-pz, d2=dx*dx+dz*dz;
        if (c->driver==DRV_NPC){       /* moving traffic: recycle ONLY when off-screen */
            if (fabsf(c->spd) < 0.6f && !red_wait[i]) stuck_t[i]+=dt; else stuck_t[i]=0;
            /* NEVER teleport a car the player can see — that looks ridiculous. Cars only
             * recycle once well off-screen (visible radius ~32 m even at max zoom-out):
             * far behind, or wedged AND out of view. On-screen jams clear via jam-recovery. */
            int offscreen = d2 > 48.0f*48.0f;
            if (d2 > 92.0f*92.0f || (offscreen && stuck_t[i] > 2.0f)) respawn_npc(i);
        } else if (d2 > 92.0f*92.0f) { /* parked car left far behind → bring it back as traffic */
            respawn_npc(i);
        }
    }
    /* DENSITY-SCALED TRAFFIC: the moving-car target tracks how much ROAD is in view —
     * zoomed out over big avenues you see more cars; zoomed in on a back street, fewer.
     * Adjustments happen strictly OFF-SCREEN (spawn at 46-78 m, despawn only >48 m). */
    static float s_denst;
    s_denst -= dt;
    if (s_denst <= 0){
        s_denst = 0.8f;
        int R=(int)(vis_h*0.62f/TILE)+3; if(R>11) R=11;      /* ~visible radius, in tiles */
        int cx=(int)(px/TILE), cz=(int)(pz/TILE), rt=0;
        for (int z=cz-R; z<=cz+R; z++) for (int x=cx-R; x<=cx+R; x++) if (is_drivable(x,z)) rt++;
        int target = rt/7; if(target<3) target=3; if(target>10) target=10;
        int nn=0; for (int i=0;i<NCAR;i++) if(cars[i].alive && cars[i].driver==DRV_NPC) nn++;
#ifdef MOTE_HOST
        if (getenv("MOTE_GTA_DEBUG")) fprintf(stderr,"[DENS] R=%d rt=%d target=%d nn=%d camh=%.0f\n",R,rt,target,nn,vis_h);
#endif
        if (nn < target){                                      /* grow: revive a dead slot off-screen */
            for (int i=0;i<NCAR;i++) if(!cars[i].alive){ respawn_npc(i); break; }
        } else if (nn > target+1){                             /* shrink: drop the FARTHEST (off-screen) */
            int far=-1; float fd=48.0f*48.0f;
            for (int i=0;i<NCAR;i++){ if(!cars[i].alive||cars[i].driver!=DRV_NPC||i==player.car||is_mission_car(i)) continue;
                float dx=cars[i].x-px, dz=cars[i].z-pz, d2=dx*dx+dz*dz;
                if (d2>fd){ fd=d2; far=i; } }
            if (far>=0) cars[far].alive=0;
        }
    }
    /* peds stream in a ring JUST outside the current view (scales with zoom), so streets
     * ahead are already populated — not 50 m away where they were never seen again. */
    { float vis = vis_h*0.82f + 3.0f;                       /* ~visible diagonal radius */
      float rmin = vis + 2.0f, rmax = vis + 14.0f;
      for (int i=0;i<NPED;i++){ Ped*p=&peds[i];
        if (!p->alive) continue;
        if (p->iscop) continue;                               /* officers manage themselves */
        if (mission==MI_HIT && i==mission_target) continue;   /* the mark doesn't vanish */
        float dx=p->x-px, dz=p->z-pz;
        if (dx*dx+dz*dz > (rmax+16.0f)*(rmax+16.0f)){
            float ox,oz; if (find_near(px,pz, rmin, rmax, pav_or_grass, &ox,&oz))
                peds[i]=(Ped){ ox,oz,(float)(irand(4))*1.5708f,0,(uint8_t)irand(4),1,2,0,0 };
        }
      }
    }
}

static int blocked_bldg_w(float wx,float wz){ int tx=(int)(wx/TILE),tz=(int)(wz/TILE); char c=tile_at(tx,tz); return (c=='#'||c=='O'||c=='H') && !is_garage(tx,tz); }
static int in_water_w(float wx,float wz){ return tile_at((int)(wx/TILE),(int)(wz/TILE))=='~'; }

/* drove/walked into the river — splash, sink the car, WASTED */
static void drown(void) {
    add_fx(pl_x(),pl_z(),2); add_fx(pl_x()+1.2f,pl_z()+0.4f,2); add_fx(pl_x()-0.6f,pl_z()+1.0f,2);
    sfx(&hurt_sfx,0.7f); rmbl(0.5f,160); say("SPLASH!");
    if (player.mode==MODE_CAR && player.car>=0){ cars[player.car].alive=0; player.mode=MODE_FOOT; player.car=-1; }
    g_state=ST_WASTED; g_screen_t=2.6f;
}

static void physics_pass(float dt) {
    static float prex[NCAR], prez[NCAR], prespd[NCAR];
    int peer_traffic = g_dm && !dm_auth;
    for (int i=0;i<NCAR;i++){
        if (!cars[i].alive){ bodies[i].inv_mass=0; bodies[i].x=1e6f+i*4; bodies[i].y=1e6f;
                             bodies[i].vx=bodies[i].vy=bodies[i].avel=0; continue; }
        if (peer_traffic && i!=player.car){       /* streamed car → solid static obstacle */
            bodies[i].inv_mass=0; bodies[i].x=cars[i].x; bodies[i].y=cars[i].z; bodies[i].angle=cars[i].yaw;
            bodies[i].vx=bodies[i].vy=bodies[i].avel=0;
        }
        prex[i]=bodies[i].x; prez[i]=bodies[i].y;
        prespd[i]=sqrtf(bodies[i].vx*bodies[i].vx+bodies[i].vy*bodies[i].vy);
    }
    /* STATIC world colliders near the player: buildings = full-tile boxes, trees =
     * a small trunk circle. Cars collide + bounce off them with real momentum. */
    int ns=NCAR;
    int cx=(int)(pl_x()/TILE), cz=(int)(pl_z()/TILE), R=3;
    for (int z=cz-R; z<=cz+R && ns<NCAR+NSTAT; z++)
        for (int x=cx-R; x<=cx+R && ns<NCAR+NSTAT; x++){
            char t=tile_at(x,z);
            if ((t=='#'||t=='O'||t=='H') && !is_garage(x,z)){   /* garage bays have no wall — drive in */
                bodies[ns]=mote_body2d_box(x*TILE+TILE*0.5f, z*TILE+TILE*0.5f, TILE*0.5f, TILE*0.5f, 0.0f, 0.0f);
                bodies[ns].friction=0.7f; bodies[ns].restitution=0.05f; ns++;
            } else if (t==' '){
                unsigned h=(unsigned)(x*668265263u ^ z*374761393u); if((h&3)==0) continue;  /* matches scenery draw */
                float tx=x*TILE+((h>>4)&7)*0.4f+1.0f, tz=z*TILE+((h>>8)&7)*0.4f+1.0f;
                bodies[ns]=mote_body2d_circle(tx, tz, 0.55f, 0.0f);   /* tree trunk */
                bodies[ns].friction=0.6f; ns++;
            }
        }
    pworld.gx=0; pworld.gy=0; pworld.iterations=8;
    g_nbodies = ns;
    if (mote->phys2d_step) mote->phys2d_step(&pworld, bodies, ns, dt);
#ifdef MOTE_HOST
    if (getenv("MOTE_GTA_DEBUG"))
        for (int i=0;i<NCAR;i++){ if(!cars[i].alive) continue;
            float ex=prex[i]+bodies[i].vx*dt, ez=prez[i]+bodies[i].vy*dt;
            float jx=bodies[i].x-ex, jz=bodies[i].y-ez, j2=jx*jx+jz*jz;
            if (j2 > 0.5f*0.5f)
                fprintf(stderr,"[JUMP] car%d %s d=%.2fm pre=(%.1f,%.1f) post=(%.1f,%.1f) v=(%.1f,%.1f) spd=%.1f\n",
                    i, i==player.car?"PLAYER":"", sqrtf(j2), prex[i],prez[i],
                    bodies[i].x,bodies[i].y, bodies[i].vx,bodies[i].vy, prespd[i]); }
#endif
    for (int i=0;i<NCAR;i++){
        if (!cars[i].alive) continue;
        MoteBody2D *b=&bodies[i];
        if (i==player.car){
            /* BOTH of these are ground rules, and neither an airborne
             * helicopter nor a floating boat is on the ground. The building
             * snap-back rewinds any car whose centre lands on a solid tile,
             * which would bounce the helicopter off every roof it flies over;
             * the water check drowns you, which is exactly what must not
             * happen to the one vehicle whose whole job is being on water. */
            int flying = (cars[i].type==VEH_HELI && heli_aloft(b->x, b->y)) ||
                         (cars[i].type==VEH_BOAT && boat_afloat(b->x, b->y));
            if (!flying && blocked_bldg_w(b->x, b->y)){ b->x=prex[i]; b->y=prez[i]; b->vx*=0.2f; b->vy*=0.2f; }  /* anti-tunnel backstop */
            if (!flying && in_water_w(b->x, b->y)){ cars[i].x=b->x; cars[i].z=b->y; drown(); continue; }
            /* ANY real contact with a squad car counts, not just a heavy crash.
             * The speed-drop test below only fires when you lose 45% of your
             * speed in a frame; a scrape or a nudge at junction speed left you
             * completely clean, which is the case you reported. */
            for (int j=0;j<NCAR;j++){ Car *oc=&cars[j];
                if (j==i || !oc->alive || oc->wrecked || oc->driver!=DRV_COP) continue;
                float ddx=oc->x-cars[i].x, ddz=oc->z-cars[i].z;
                /* Threshold from the ACTUAL car lengths, not a constant. A flat
                 * 4.9 m never fired: two 5.5 m cars touching nose-to-tail sit
                 * about 5.5 m centre-to-centre, so the test was tighter than
                 * contact itself. */
                float rad = (VSTAT[cars[i].type].len + VSTAT[oc->type].len) * 0.55f;
                if (ddx*ddx+ddz*ddz > rad*rad) continue;
                float rvx=b->vx-bodies[j].vx, rvy=b->vy-bodies[j].vy;
                if (rvx*rvx+rvy*rvy < 4.0f) continue;           /* a hit, not parked alongside */
                cop_rammed(); break;
            }
            float now=sqrtf(b->vx*b->vx+b->vy*b->vy);            /* crash feel: big speed drop */
            if (prespd[i]>12.0f && now<prespd[i]*0.55f){
                sfx(&crash_sfx,0.6f); rmbl(0.5f,120); cars[i].hp -= (prespd[i]-12.0f)*2.0f;
                /* RAMMING A POLICE CAR is a crime in itself — the cop you just
                 * hit is the witness, so this adds heat directly rather than
                 * going through cops_witness. Damage is dealt to them as well;
                 * a squad car should not be a bollard. */
                for (int j=0;j<NCAR;j++){ Car *oc=&cars[j];
                    if (j==i || !oc->alive || oc->wrecked) continue;
                    float ddx=oc->x-cars[i].x, ddz=oc->z-cars[i].z;
                    if (ddx*ddx+ddz*ddz > 30.0f) continue;
                    oc->hp -= (prespd[i]-12.0f)*1.6f;
                    if (oc->driver==DRV_COP) cop_rammed();
                    if (oc->hp<=0) wreck_car(oc);
                }
                if (cars[i].hp<=0){ wreck_car(&cars[i]); player.mode=MODE_FOOT; player.car=-1;
                                    player.x=b->x; player.z=b->y; hurt_player(16); continue; }
            }
        } else if (cars[i].driver != DRV_NONE){                 /* AI cars clamp to ROAD (off pavement) */
            /* Other cars take crash damage too. Only the player's did, so you
             * could ram traffic all day and nothing happened to it. Same speed
             * -drop test, and wrecking one throws its driver clear. */
            float onow = sqrtf(b->vx*b->vx + b->vy*b->vy);
            if (prespd[i] > 12.0f && onow < prespd[i]*0.55f && !cars[i].wrecked) {
                cars[i].hp -= (prespd[i] - 12.0f) * 1.6f;
                if (cars[i].hp <= 0) wreck_car(&cars[i]);
            }
            if (!road_world(b->x, prez[i])){ b->x=prex[i]; b->vx=0; }
            if (!road_world(prex[i], b->y)){ b->y=prez[i]; b->vy=0; }
        }                                                       /* DRV_NONE (jackable/parked) = freely pushable */
        cars[i].x=b->x; cars[i].z=b->y; cars[i].yaw=b->angle;
        /* A wrecked car BURNS. One explosion at the moment of death read as a
         * car that had simply turned black; a husk that keeps throwing flame
         * reads as destroyed. Gated on distance so a wreck left across the
         * city is not spending fx slots you cannot see. */
        if (cars[i].wrecked) {
            float fdx=cars[i].x-pl_x(), fdz=cars[i].z-pl_z();
            if (fdx*fdx+fdz*fdz < 46.0f*46.0f) {
                cars[i].firecd -= dt;
                if (cars[i].firecd <= 0.0f) {
                    cars[i].firecd = 0.28f + frand()*0.30f;
                    add_fx(cars[i].x + (frand()*2-1)*1.1f,
                           cars[i].z + (frand()*2-1)*1.1f, 0);
                }
            }
        }
        float cc=cosf(b->angle), ss=sinf(b->angle);
        cars[i].spd = b->vx*cc + b->vy*ss;
    }
}

/* Draw one vehicle as two tinted boxes plus a ground shadow.
 *
 * Two objects, not one: MoteObject.color is a single colour for the whole
 * object, so a one-box car has no windows and reads as a brick. The body takes
 * the type's paint from CAR_COL, the cabin a dark glass tone.
 *
 * A wreck is the same geometry in a charred tone — the husk stays visible and
 * pushable, exactly as the sprite version did. VEH_BUS/VEH_TANK sit above
 * CARS2_N with no CAR_CLS/CAR_COL entry, so both are handled explicitly: a
 * van silhouette for the bus, a truck silhouette for the tank hull, both in a
 * neutral grey (the tank's turret keeps drawing as its own sprite below). */
/* Vehicle-decal emitters.
 *
 * These exist for ONE reason: stack. The decals, lamps, spoiler and police
 * lightbar were written as VPT/QUAD/ZFACE macros, where every VPT is a
 * statement expression yielding a Vec3 and every QUAD takes four of them by
 * value. At -O2 GCC gives each inlined temporary its own slot rather than
 * reusing them, which took draw_vehicle_mesh's frame from 384 to 1472 bytes —
 * measured with -fstack-usage.
 *
 * The device gives core0 PICO_STACK_SIZE = 0x1000, four kilobytes, in
 * SCRATCH_Y; below it sit core1's stack and then GAME_RAM. The host has
 * megabytes, so every headless capture looked perfect while the device fell
 * over. Keeping these out of line means one small transient frame instead of a
 * permanent 1.4 KB one in the caller.
 *
 * veh_pt maps a point in the mesh's normalised int8 space through the car's
 * basis and scale, exactly as the body/cabin meshes are transformed. */
static Vec3 veh_pt(const Mat3 *b, float cx, float cz, float k,
                   float lx, float ly, float lz) {
    Vec3 l = m3_mul_v3(b, v3(lx * k, ly * k, lz * k));
    return v3(cx + l.x, l.y, cz + l.z);
}

/* One quad as two double-sided triangles. scene_add_tri is winding-proof, so a
 * decal is two triangles with no winding to get wrong. */
__attribute__((noinline))
static void veh_quad(const Mat3 *b, float cx, float cz, float k,
                     const float q[4][3], uint16_t col) {
    Vec3 p0 = veh_pt(b, cx, cz, k, q[0][0], q[0][1], q[0][2]);
    Vec3 p1 = veh_pt(b, cx, cz, k, q[1][0], q[1][1], q[1][2]);
    Vec3 p2 = veh_pt(b, cx, cz, k, q[2][0], q[2][1], q[2][2]);
    Vec3 p3 = veh_pt(b, cx, cz, k, q[3][0], q[3][1], q[3][2]);
    mote->scene_add_tri(p0, p1, p2, col, 0);
    mote->scene_add_tri(p0, p2, p3, col, 0);
}

/* veh_pt with a HEIGHT. Every other vehicle sits on the road, so veh_pt drops
 * the anchor's y entirely; the helicopter is the one thing that does not. */
__attribute__((noinline))
static void heli_quad(const Mat3 *b, float cx, float cy, float cz, float k,
                      const float q[4][3], uint16_t col) {
    Vec3 p[4];
    for (int i = 0; i < 4; i++) {
        Vec3 l = m3_mul_v3(b, v3(q[i][0]*k, q[i][1]*k, q[i][2]*k));
        p[i] = v3(cx + l.x, cy + l.y, cz + l.z);
    }
    mote->scene_add_tri(p[0], p[1], p[2], col, 0);
    mote->scene_add_tri(p[0], p[2], p[3], col, 0);
}

/* A quad on an end face (constant z), which is where every lamp lives. */
__attribute__((noinline))
static void veh_zface(const Mat3 *b, float cx, float cz, float k,
                      float x0, float x1, float y0, float y1, float z,
                      uint16_t col) {
    const float q[4][3] = { {x0,y0,z}, {x1,y0,z}, {x1,y1,z}, {x0,y1,z} };
    veh_quad(b, cx, cz, k, q, col);
}

static void draw_vehicle_mesh(const Car *c) {
    int sil = (c->type < CARS2_N) ? gta3_sil_for_class(CAR_CLS[c->type])
            : (c->type == VEH_BUS)  ? GTA3_SIL_BUS
            : (c->type == VEH_HELI) ? GTA3_SIL_HELI
            : (c->type == VEH_BOAT) ? GTA3_SIL_BOAT
            : (c->type == VEH_TANK) ? GTA3_SIL_TANK : GTA3_SIL_TRUCK;
    const VStat *vs = &VSTAT[c->type];
    Gta3VehMesh *m = &g_veh[sil];

    Mat3 b = m3_identity();
    /* pi/2 - yaw, NOT -yaw. gta3_veh builds the nose along +Z, while the game's
     * heading is (cos yaw, sin yaw) in x/z — and -yaw lands the nose exactly 90
     * degrees off at every yaw, which is cars driving sideways. Same family as
     * the sprite path's -(yaw + pi/2) above, which points a -Z nose and so
     * differs by pi. Verified numerically against both conventions rather than
     * derived: a plausible-looking alternative, yaw - pi/2, is 180 degrees out. */
    m3_rotate_local(&b, 1, 1.5707963f - c->yaw);

    /* The mesh is authored square in x/z (both span +/-127) and the engine's
     * only scale is uniform, so a uniform scale alone draws every car as wide
     * as it is long. Squeeze x per car to its measured width/length ratio
     * before submitting. Safe to mutate a shared mesh: scene_add_object
     * consumes the vertices at submit time, the same reason g_ground and
     * g_quad are mutated per draw. box()'s corner order puts +x at indices
     * 1,2,5,6 and -x at 0,3,4,7. */
    float ar = vs->wid / vs->len;
    /* Clamp before narrowing: every cars2 cell today is 28x60 (ar < 1), but a
     * future vehicle with wid > len would push g_veh_bx[sil]*ar past 127 and
     * wrap negative in the int8_t cast, inverting the box in x and flipping
     * the +/-X faces' winding -- silently invisible sides on the flat path. */
    int8_t bx = (int8_t)mote_clampf(g_veh_bx[sil] * ar, -127.0f, 127.0f);
    int8_t cx = (int8_t)mote_clampf(g_veh_cx[sil] * ar, -127.0f, 127.0f);
    int8_t wx = (int8_t)mote_clampf(g_veh_wx[sil] * ar, -127.0f, 127.0f);
    static const int XP[4] = {1,2,5,6}, XN[4] = {0,3,4,7};
    /* Not the helicopter: it is authored at its final width (see gta3_veh.c),
     * and this loop assigns ONE x to all four corners of both third-box slabs,
     * which would fold its two skids onto the centreline.
     * The boat is exempt for the same reason: its gunwales are one per side. */
    if (sil != GTA3_SIL_HELI && sil != GTA3_SIL_BOAT)
    for (int k = 0; k < 4; k++) {
        m->bv[XP[k]].x =  bx; m->bv[XN[k]].x = -bx;
        m->cv[XP[k]].x =  cx; m->cv[XN[k]].x = -cx;
        /* both axle slabs: the wheel mesh is two boxes now, so the second
         * box's corners live 8 vertices further along. */
        m->wv[XP[k]].x   =  wx; m->wv[XN[k]].x   = -wx;
        m->wv[XP[k]+8].x =  wx; m->wv[XN[k]+8].x = -wx;
    }

    /* Per-TYPE cabin jitter, riding the same mutate-the-shared-mesh trick the x
     * squeeze above uses. Eleven silhouettes over 54 car types meant two cars on
     * the same silhouette differed only in paint and overall size; nudging the
     * roofline and where the glasshouse sits gives them different profiles too,
     * for no triangles and no extra meshes.
     *
     * Deterministic from the type, so a given car always looks like itself, and
     * it must start from the PRISTINE g_veh_cy/cz values — reading back the
     * mutated mesh would let the jitter compound draw after draw.
     *
     * The roof is clamped to stay at least 6 units above the cabin floor
     * (the body top, cv[0].y). A cabin whose top crosses its bottom is an
     * INVERTED box: every face's winding flips and the sides silently vanish on
     * the flat path. Same trap the x clamp above guards against. */
    /* Not the helicopter: there is exactly one of it, so jitter buys no variety,
     * and nudging the canopy off the nose is the one thing that stops it
     * reading as an aircraft. */
    if (sil != GTA3_SIL_HELI && sil != GTA3_SIL_BOAT)
    { unsigned jh = (unsigned)c->type * 0x9E3779B1u;
      int base   = m->cv[0].y;                        /* cabin floor = body top */
      int top    = g_veh_cy[sil] + (int)((jh >> 3) & 7) - 3;     /* +-3 units of roof */
      int zshift = (int)((jh >> 9) & 7) - 3;                     /* +-3 units fore/aft */
      if (top < base + 6) top = base + 6;
      int z0 = g_veh_cz0[sil] + zshift, z1 = g_veh_cz1[sil] + zshift;
      if (z0 < -127) z0 = -127;
      if (z1 >  127) z1 =  127;
      static const int YT[4] = {2,3,6,7};
      static const int Z0[4] = {0,1,2,3}, Z1[4] = {4,5,6,7};
      for (int k = 0; k < 4; k++) {
          m->cv[YT[k]].y = (int8_t)top;
          m->cv[Z0[k]].z = (int8_t)z0;
          m->cv[Z1[k]].z = (int8_t)z1;
      } }

    /* z already spans the full +/-127, so keying the (uniform) scale to
     * half-length makes the car's length exact; the x squeeze above then
     * makes the width exact too. */
    float sc = vs->len * 0.5f;

    /* CAR_COL is sampled from cars2.png and that sheet's cab is TEAL, which is
     * not what anyone pictures when they see a taxi. This one type overrides
     * its sample rather than the generated table being hand-edited, since
     * make_carcolors.py would put the teal straight back. */
    uint16_t paint = c->wrecked ? MOTE_RGB565(38,34,34)
                   : (c->type == CAR_TAXI) ? MOTE_RGB565(240,190,26)
                   : (c->type == VEH_TANK) ? MOTE_RGB565(74,86,58)   /* army green, same as the turret */
                   : (c->type == VEH_BOAT) ? MOTE_RGB565(232,236,242)   /* white hull */
                   : (c->type < CARS2_N ? CAR_COL[c->type] : MOTE_RGB565(190,190,200));
    /* Glass takes its tint from the car's own paint rather than one shared slate
     * blue: a quarter of the body colour plus a cool floor, so a red car gets warm
     * dark glass and a blue one cool dark glass. Free — it is arithmetic on a
     * colour we already have — and it stops 54 cars sharing one window. */
    uint16_t glass;
    if (c->wrecked) glass = MOTE_RGB565(24,22,22);
    /* A tank has no windows. Its superstructure takes a slightly darker green
     * than the hull rather than the glass tint every car gets, so the whole
     * vehicle is green and only the tracks are dark. */
    else if (c->type == VEH_TANK) glass = MOTE_RGB565(62,72,48);
    /* A wheelhouse is glass on three sides; the cool dark tint every car gets
     * is right for it, but a white hull makes that tint nearly black, so the
     * boat takes a mid blue instead. */
    else if (c->type == VEH_BOAT) glass = MOTE_RGB565(58,92,126);
    else {
        int pr = (paint >> 11) & 31, pg = (paint >> 5) & 63, pb = paint & 31;
        glass = MOTE_RGB565(18 + (pr * 8) / 31 * 2, 20 + (pg * 8) / 63 * 2, 30 + (pb * 8) / 31 * 2);
    }

    /* Everything below is placed at vy rather than 0. Only the helicopter ever
     * leaves the road, so for every other vehicle this is the same y it was. */
    float vy = (c->type == VEH_HELI) ? g_heli_y : 0.0f;

    MoteObject body = { .pos=v3(c->x, vy, c->z), .basis=b, .mesh=&m->body, .color=paint };
    mote->scene_add_object_scaled(&body, sc);
    MoteObject cab  = { .pos=v3(c->x, vy, c->z), .basis=b, .mesh=&m->cabin, .color=glass };
    mote->scene_add_object_scaled(&cab, sc);

    /* TAXI ROOF SIGN: a small black box on the roof, which is the one thing
     * that says "taxi" at a glance. Drawn with the body rather than with the
     * close-range trim, because it is the identifying feature and a car you
     * can see at all should be identifiable. Four quads — the two long sides
     * and the two ends — so it has a section from every angle instead of
     * vanishing edge-on. */
    if (c->type == CAR_TAXI && !c->wrecked) {
        float k = sc * (1.0f / 127.0f);
        float q[4][3];
        float sx = m->cv[1].x * 0.30f;                /* a third of the cabin's half-width */
        float y0 = m->cv[3].y + 1.0f, y1 = y0 + 9.0f; /* just clear of the roofline */
        float z0 = -13.0f, z1 = 13.0f;
        const uint16_t SIGN = MOTE_RGB565(24,24,28);
        q[0][0]=-sx; q[0][1]=y0; q[0][2]=z0;  q[1][0]= sx; q[1][1]=y0; q[1][2]=z0;
        q[2][0]= sx; q[2][1]=y1; q[2][2]=z0;  q[3][0]=-sx; q[3][1]=y1; q[3][2]=z0;
        veh_quad(&b, c->x, c->z, k, q, SIGN);
        q[0][2]=z1; q[1][2]=z1; q[2][2]=z1; q[3][2]=z1;
        veh_quad(&b, c->x, c->z, k, q, SIGN);
        q[0][0]=-sx; q[0][1]=y0; q[0][2]=z0;  q[1][0]=-sx; q[1][1]=y0; q[1][2]=z1;
        q[2][0]=-sx; q[2][1]=y1; q[2][2]=z1;  q[3][0]=-sx; q[3][1]=y1; q[3][2]=z0;
        veh_quad(&b, c->x, c->z, k, q, SIGN);
        q[0][0]= sx; q[1][0]= sx; q[2][0]= sx; q[3][0]= sx;
        veh_quad(&b, c->x, c->z, k, q, SIGN);
    }

    /* Wheel line: detail that drops off with distance. 12 more triangles per car,
     * and at 18 live cars that is 216 against a budget whose measured peak is
     * already 597 of 850 — so only the cars close enough to actually resolve a
     * tyre get one. The chase camera means that is usually your own car plus
     * whatever you are about to hit. */
    float ddx = c->x - cam_pos.x, ddz = c->z - cam_pos.z, d2 = ddx*ddx + ddz*ddz;
    if (d2 < VEH_WHEEL_R * VEH_WHEEL_R) {
        MoteObject wh = { .pos=v3(c->x, vy, c->z), .basis=b, .mesh=&m->wheels,
                          .color = c->wrecked ? MOTE_RGB565(16,14,14) : MOTE_RGB565(24,24,28) };
        mote->scene_add_object_scaled(&wh, sc);
    }

    /* ---- close-range detail: two-tone panels and lit lamps ----------------
     * Both are gated on the same radius as the wheel line, for the same reason:
     * this is detail that only reads up close, and the budget cannot carry it
     * on all 18 cars at once.
     *
     * Panels go through scene_add_tri rather than a mesh: it is DOUBLE-SIDED
     * and depth-tested, so a decal is 2 triangles with no winding to get wrong
     * — and this project has got winding wrong five times. Their corners come
     * from the car's OWN built mesh vertices, pushed through the SAME basis and
     * scale the body uses, so they lie on the surface instead of being
     * re-derived and drifting off it. */
    /* Not the helicopter: veh_quad places its corners on the road plane, so the
     * roof stripe and the lamps would stay behind on the tarmac while the
     * aircraft climbed away from them. */
    if (d2 < VEH_DETAIL_R * VEH_DETAIL_R && !c->wrecked && c->type != VEH_HELI) {
        float k = sc * (1.0f / 127.0f);
        float q[4][3];                       /* ONE reused quad buffer — see veh_quad */
        float cabx = m->cv[1].x, cabtop = m->cv[3].y;         /* squeezed cabin half-width, roofline */
        float cz0 = m->cv[0].z, cz1 = m->cv[4].z;             /* cabin z extent */
        float bodyx = m->bv[1].x, bodytop = m->bv[3].y;

        /* Deterministic per-type trim, so a given car always looks like itself. */
        unsigned th = (unsigned)c->type * 2654435761u;
        uint16_t trim = (th & 3) == 0 ? MOTE_RGB565(232,228,220)      /* cream roof   */
                      : (th & 3) == 1 ? MOTE_RGB565(30,30,36)         /* black roof   */
                      : (th & 3) == 2 ? MOTE_RGB565(120,124,134)      /* silver       */
                                      : glass;                        /* body-matched */

        /* roof panel, lifted 2 units clear of the cabin so it cannot z-fight */
        { float rx = cabx * 0.86f, z0 = cz0 + 8, z1 = cz1 - 8, y = cabtop + 2;
          q[0][0]=-rx; q[0][1]=y; q[0][2]=z0;  q[1][0]= rx; q[1][1]=y; q[1][2]=z0;
          q[2][0]= rx; q[2][1]=y; q[2][2]=z1;  q[3][0]=-rx; q[3][1]=y; q[3][2]=z1;
          veh_quad(&b, c->x, c->z, k, q, trim); }

        /* bonnet stripe: a narrow band up the middle of the front deck */
        { float sx = bodyx * 0.22f, z0 = cz1 + 4, z1 = 118.0f, y = bodytop + 2;
          q[0][0]=-sx; q[0][1]=y; q[0][2]=z0;  q[1][0]= sx; q[1][1]=y; q[1][2]=z0;
          q[2][0]= sx; q[2][1]=y; q[2][2]=z1;  q[3][0]=-sx; q[3][1]=y; q[3][2]=z1;
          veh_quad(&b, c->x, c->z, k, q, trim); }

        /* A rear spoiler for the supercars: a blade standing clear of the tail
         * on two end plates. RACER only, and only this close — the lowered
         * SILDEF row is what makes a racer read as a racer at distance; this is
         * the flourish you get when one is right in front of you. 6 triangles. */
        if (sil == GTA3_SIL_RACER) {
            /* +11, not +26: a local unit is sc/127 metres and a racer's sc is about
             * 2.9 m, so +26 put the blade 1.05 m off the deck — measured, and about
             * four times a real spoiler. +11 is roughly 0.25 m above the bodywork. */
            float sx = bodyx * 0.92f, y = bodytop + 11, z = -104;
            q[0][0]=-sx; q[0][1]=y; q[0][2]=z-9;  q[1][0]= sx; q[1][1]=y; q[1][2]=z-9;
            q[2][0]= sx; q[2][1]=y; q[2][2]=z+9;  q[3][0]=-sx; q[3][1]=y; q[3][2]=z+9;
            veh_quad(&b, c->x, c->z, k, q, paint);
            for (int e = 0; e < 2; e++) {       /* the two end plates */
                float ex = e ? sx : -sx;
                q[0][0]=ex; q[0][1]=bodytop; q[0][2]=z;    q[1][0]=ex; q[1][1]=y; q[1][2]=z;
                q[2][0]=ex; q[2][1]=y;       q[2][2]=z+9;  q[3][0]=ex; q[3][1]=bodytop; q[3][2]=z+9;
                veh_quad(&b, c->x, c->z, k, q, paint);
            }
        }

        /* Lamps, lit only once the sun is low, in the shape the silhouette asks
         * for — round discs, square lamps, or a full-width bar. Every car on the
         * road wearing the same round pair was the thing this replaces.
         *
         * z = +-133, NOT +-122: the body box spans +-127, so a lamp at 122 sits
         * INSIDE the solid and the depth test buries it. Nothing rendered at
         * 122 — measured. 133 puts the lamp just proud of the face, the same
         * trick the panels above use with their +2 lift.
         *
         * A disc carries a world radius, so the round style shrinks with
         * distance like a real lamp and costs no triangles at all; the other two
         * are 8 and 6 triangles respectively. */
        /* Rear lamps light when it is dark OR when the pedal says so, so a
         * brake light reads in broad daylight — that is the whole point of it.
         * Headlights stay night-only: a car running its beams at noon looks
         * wrong, and nothing about braking should switch them on. */
        int night = sun_elev() < 0.10f;
        int rear  = c->lamp;
        if (night || rear) {
            uint16_t TAIL = (rear == LAMP_BRAKE) ? MOTE_RGB565(255, 40, 28)    /* hard on the brakes */
                          : (rear == LAMP_REV)   ? MOTE_RGB565(250,250,235)    /* reversing: white */
                                                 : MOTE_RGB565(246, 70, 52);   /* running lamps */
            const uint16_t HEAD = MOTE_RGB565(255,244,206);
            float lx = bodyx * 0.66f, ly = bodytop * 0.55f;
            /* Braking and reversing fatten the lamp as well as recolouring it,
             * so it still reads at the distance a chase camera puts you at. */
            float gain = rear ? 1.45f : 1.0f;
            switch (gta3_lamp_style(sil)) {
            case GTA3_LAMP_RECT: {
                float w = bodyx * 0.20f * gain, h = bodytop * 0.22f * gain;
                if (h < 5.0f) h = 5.0f;
                veh_zface(&b, c->x, c->z, k, -lx-w, -lx+w, ly-h, ly+h, -133, TAIL);
                veh_zface(&b, c->x, c->z, k,  lx-w,  lx+w, ly-h, ly+h, -133, TAIL);
                if (night) {
                    veh_zface(&b, c->x, c->z, k, -lx-w, -lx+w, ly-h, ly+h,  133, HEAD);
                    veh_zface(&b, c->x, c->z, k,  lx-w,  lx+w, ly-h, ly+h,  133, HEAD);
                }
                break; }
            case GTA3_LAMP_BAR: {
                float w = bodyx * 0.80f, h = bodytop * 0.13f * gain, sw = bodyx * 0.30f;
                if (h < 4.0f) h = 4.0f;
                veh_zface(&b, c->x, c->z, k, -w, w, ly-h, ly+h, -133, TAIL);   /* bar across the tail */
                if (night) {
                    veh_zface(&b, c->x, c->z, k, -lx-sw, -lx+sw, ly-h, ly+h, 133, HEAD); /* front slits */
                    veh_zface(&b, c->x, c->z, k,  lx-sw,  lx+sw, ly-h, ly+h, 133, HEAD);
                }
                break; }
            default: {
                float r = 0.17f * gain;
                mote->scene_add_disc(veh_pt(&b, c->x, c->z, k, -lx, ly, -133), r, TAIL);
                mote->scene_add_disc(veh_pt(&b, c->x, c->z, k,  lx, ly, -133), r, TAIL);
                if (night) {
                    mote->scene_add_disc(veh_pt(&b, c->x, c->z, k, -lx, ly,  133), 0.17f*1.15f, HEAD);
                    mote->scene_add_disc(veh_pt(&b, c->x, c->z, k,  lx, ly,  133), 0.17f*1.15f, HEAD);
                }
                break; }
            }
        }

        /* Police livery: a white panel down each flank, over whatever paint the
         * type carries. x = +-121 puts it just outside the body's +-118 so it
         * cannot z-fight, and inside the wheel slab's +-127 so it does not poke
         * through the tyre line. 4 triangles. */
        if (c->type == CAR_POLICE || c->type == CAR_POLICE2) {
            const uint16_t LIVERY = MOTE_RGB565(238,240,244);
            float y0 = bodytop * 0.30f, y1 = bodytop * 0.82f;
            for (int e = 0; e < 2; e++) {
                float ex = e ? 121.0f : -121.0f;
                q[0][0]=ex; q[0][1]=y0; q[0][2]=-70;  q[1][0]=ex; q[1][1]=y0; q[1][2]= 70;
                q[2][0]=ex; q[2][1]=y1; q[2][2]= 70;  q[3][0]=ex; q[3][1]=y1; q[3][2]=-70;
                veh_quad(&b, c->x, c->z, k, q, LIVERY);
            }
        }
    }

    /* Police lightbar. Gated at the WHEEL radius, not the detail radius: the bar
     * is what tells you a cruiser is a cruiser, so it has to survive further out
     * than a bonnet stripe does. Top face plus rear face per half, 8 triangles,
     * and only cop cars ever reach here.
     *
     * It flashes only while the car is actually on you (DRV_COP). A cruiser
     * parked at the station sits dark, which is also how you tell the two apart
     * at a glance. The phase comes from micros(), the same source as the radar
     * strobe and the marker rings below, so the two bars stay in step. */
    if ((c->type == CAR_POLICE || c->type == CAR_POLICE2) && !c->wrecked &&
        d2 < VEH_WHEEL_R * VEH_WHEEL_R) {
        float k = sc * (1.0f / 127.0f);
        float q[4][3];
        float cabx = m->cv[1].x, cabtop = m->cv[3].y;
        float bw = cabx * 0.88f, y0 = cabtop + 2, y1 = cabtop + 14;
        int phase = c->driver == DRV_COP ? ((int)(mote->micros() / 250000ull) & 1) : -1;
        uint16_t red  = phase < 0 ? MOTE_RGB565(96,26,22)  : (phase == 0 ? MOTE_RGB565(255,40,32) : MOTE_RGB565(70,18,16));
        uint16_t blue = phase < 0 ? MOTE_RGB565(24,34,102) : (phase == 1 ? MOTE_RGB565(60,110,255) : MOTE_RGB565(18,26,74));
        for (int h = 0; h < 2; h++) {
            float x0 = h ? 0.0f : -bw, x1 = h ? bw : 0.0f;
            uint16_t col = h ? blue : red;
            /* top */
            q[0][0]=x0; q[0][1]=y1; q[0][2]=-19;  q[1][0]=x1; q[1][1]=y1; q[1][2]=-19;
            q[2][0]=x1; q[2][1]=y1; q[2][2]= 19;  q[3][0]=x0; q[3][1]=y1; q[3][2]= 19;
            veh_quad(&b, c->x, c->z, k, q, col);
            /* rear face, so the bar is still there from directly behind */
            q[0][0]=x0; q[0][1]=y0; q[0][2]=-19;  q[1][0]=x1; q[1][1]=y0; q[1][2]=-19;
            q[2][0]=x1; q[2][1]=y1; q[2][2]=-19;  q[3][0]=x0; q[3][1]=y1; q[3][2]=-19;
            veh_quad(&b, c->x, c->z, k, q, col);
        }
    }

    /* One oriented shadow, replacing the eight-triangle octagon that used to
     * be assembled by hand from scene_add_tri in g_update. Semi-axes (0.55
     * length, 0.62 width) deliberately exceed the box's own half-extents
     * (0.5/0.5) so the ellipse peeks out past the opaque body on all sides —
     * sized to the box's own footprint or smaller, it would be entirely
     * hidden underneath from a chase camera. The (0.22, 0.28) world-space
     * offset toward the sun's shadow is carried over unchanged from the
     * octagon this replaced (visually tuned there, not re-derived here). */
    /* Gated on g_view the same way bb_add() gates billboards: the mesh itself
     * is saved by the pipe's own bound-sphere cull, but scene_add_shadow_ex
     * has no such cull, and this call used to run for all 18 alive cars
     * unconditionally. Worst case that's 18 car + up to 34 in-view ped
     * shadows = 52 against a max_shadows of 40, dropped silently past the
     * cap; see max_shadows=64 below. */
    if (gta3_view_tile(&g_view, c->x, 0.02f, c->z, VIEW_GROUND_R, vs->len)) {
        float fx = cosf(c->yaw), fz = sinf(c->yaw);
        /* The helicopter's shadow lands on whatever is UNDER it — road or roof
         * — and shrinks and fades as it climbs. Without that, altitude is
         * unreadable: the aircraft just gets smaller with no cue as to whether
         * it is high or far away. */
        float sy = 0.02f, shrink = 1.0f, alpha = 0.55f;
        if (c->type == VEH_HELI) {
            float fl = floor_y(c->x, c->z), h = g_heli_y - fl;
            sy = fl + 0.03f;
            shrink = 1.0f / (1.0f + h * 0.05f);
            alpha  = 0.55f * shrink;
            if (alpha < 0.12f) alpha = 0.12f;
        }
        mote->scene_add_shadow_ex(v3(c->x + 0.22f, sy, c->z + 0.28f),
                                  v3(fx * vs->len * 0.55f * shrink, 0, fz * vs->len * 0.55f * shrink),
                                  v3(-fz * vs->wid * 0.62f * shrink, 0, fx * vs->wid * 0.62f * shrink),
                                  alpha);
    }
}

static void draw_vehicle(int i){
    Car*c=&cars[i]; if(!c->alive) return;
        draw_vehicle_mesh(c);
        if (c->type==VEH_HELI && !c->wrecked){
            /* TAIL BOOM, FIN AND BOTH ROTORS: triangles, not mesh. The rotors
             * spin and Gta3VehMesh is built once at init, and the boom is thin
             * enough that a box would spend 12 triangles on something two
             * quads say just as well. All of it is placed through the same
             * basis and scale the fuselage uses, so it stays attached. */
            const float k = VSTAT[VEH_HELI].len * 0.5f / 127.0f;
            Mat3 hb = m3_identity();
            m3_rotate_local(&hb, 1, 1.5707963f - c->yaw);
            const uint16_t SHELL = MOTE_RGB565(150,152,164);
            float q[4][3];
            /* boom: one horizontal and one vertical quad, so it has a section
             * from every angle instead of vanishing edge-on from above. */
            { float y = 34.0f, w = 9.0f, z0 = -20.0f, z1 = -122.0f;
              q[0][0]=-w; q[0][1]=y; q[0][2]=z0;  q[1][0]= w; q[1][1]=y; q[1][2]=z0;
              q[2][0]= w; q[2][1]=y; q[2][2]=z1;  q[3][0]=-w; q[3][1]=y; q[3][2]=z1;
              heli_quad(&hb, c->x, g_heli_y, c->z, k, q, SHELL);
              q[0][0]=0; q[0][1]=y-w; q[0][2]=z0;  q[1][0]=0; q[1][1]=y+w; q[1][2]=z0;
              q[2][0]=0; q[2][1]=y+w; q[2][2]=z1;  q[3][0]=0; q[3][1]=y-w; q[3][2]=z1;
              heli_quad(&hb, c->x, g_heli_y, c->z, k, q, SHELL); }
            /* fin: upright at the end of the boom */
            { q[0][0]=0; q[0][1]=34.0f; q[0][2]=-96.0f;  q[1][0]=0; q[1][1]=34.0f; q[1][2]=-127.0f;
              q[2][0]=0; q[2][1]=86.0f; q[2][2]=-127.0f; q[3][0]=0; q[3][1]=74.0f; q[3][2]=-104.0f;
              heli_quad(&hb, c->x, g_heli_y, c->z, k, q, SHELL); }
            /* tail rotor: one blade pair on the fin, spinning with the main */
            { float a = g_rotor * 2.0f, ca = cosf(a), sa = sinf(a), R = 30.0f, W = 4.0f;
              q[0][0]=3; q[0][1]=60.0f - ca*R; q[0][2]=-112.0f - sa*R;
              q[1][0]=3; q[1][1]=60.0f + ca*R; q[1][2]=-112.0f + sa*R;
              q[2][0]=3; q[2][1]=60.0f + ca*R + sa*W; q[2][2]=-112.0f + sa*R - ca*W;
              q[3][0]=3; q[3][1]=60.0f - ca*R + sa*W; q[3][2]=-112.0f - sa*R - ca*W;
              heli_quad(&hb, c->x, g_heli_y, c->z, k, q, MOTE_RGB565(40,42,50)); }
            /* MAIN AND TAIL ROTOR, four triangles, not in the mesh: they spin,
             * and Gta3VehMesh is built once at init. Two blades crossed at the
             * phase angle, drawn as thin flat quads. scene_add_tri is
             * double-sided, so a blade that has rotated past edge-on is still
             * drawn — which is exactly what a rotor disc needs. */
            const float R = VSTAT[VEH_HELI].len * 0.62f;   /* disc radius */
            const float BW = 0.16f;                        /* blade half-width */
            float hy = g_heli_y + VSTAT[VEH_HELI].len * 0.42f;
            const uint16_t BLADE = MOTE_RGB565(40,42,50);
            for (int k = 0; k < 2; k++) {
                float a = g_rotor + k * 1.5707963f;
                float ax = cosf(a), az = sinf(a);
                float px = -az * BW, pz = ax * BW;          /* across the blade */
                mote->scene_add_tri(v3(c->x - ax*R - px, hy, c->z - az*R - pz),
                                    v3(c->x + ax*R - px, hy, c->z + az*R - pz),
                                    v3(c->x + ax*R + px, hy, c->z + az*R + pz), BLADE, 0);
                mote->scene_add_tri(v3(c->x - ax*R - px, hy, c->z - az*R - pz),
                                    v3(c->x + ax*R + px, hy, c->z + az*R + pz),
                                    v3(c->x - ax*R + px, hy, c->z - az*R + pz), BLADE, 0);
            }
        }
        if (c->type==VEH_TANK && !c->wrecked){
            /* independent TURRET: swings smoothly toward the hull heading (lags the
             * hull through turns) and kicks back on recoil. Pivot = image centre. */
            float tyaw;
            if (i==player.car) tyaw = g_turret;                      /* player aims it */
            else if (c->driver==DRV_COP)                             /* the army tracks YOU */
                tyaw = atan2f(pl_z()-c->z, pl_x()-c->x);
            else tyaw = c->yaw;
            float rec = (i==player.car)? g_tankrecoil*1.4f : 0.0f;
            float tx=c->x - cosf(tyaw)*rec, tz=c->z - sinf(tyaw)*rec;
            /* mesh, not sprite (Task 9): a box cab + a box barrel, parented to
             * the hull's position but rotated to tyaw independently of c->yaw
             * (the hull mesh above is rotated to c->yaw). 1.9 m sits the
             * pivot atop the hull's superstructure (TANK silhouette, cab_top
             * 70 of 127 at this tank's 6.2 m length) rather than buried in
             * it. */
            Mat3 tb = m3_identity(); m3_rotate_local(&tb, 1, 1.5707963f - tyaw);  /* +Z nose, as the hull above */
            Vec3 tpos = v3(tx, 1.9f, tz);
            MoteObject tcab = { .pos=tpos, .basis=tb, .mesh=&g_turcab, .color=MOTE_RGB565(74,86,58) };
            mote->scene_add_object_ex(&tcab, 0);
            MoteObject tbar = { .pos=tpos, .basis=tb, .mesh=&g_turbar, .color=MOTE_RGB565(58,66,46) };
            mote->scene_add_object_ex(&tbar, 0);
        } }

/* ---- progress save -------------------------------------------------------
 *
 * PROGRESS ONLY: cash, the best-cash record, wanted level, weapon and ammo,
 * the mission chain position, and where the player is standing. NOT the world
 * — no cars, peds, wrecks or pickups. The city is regenerated from its seed on
 * load, so you come back to a fresh street at your saved spot with your
 * progress intact. A full world snapshot would need a versioned serialiser and
 * a buffer that GAME_RAM (under 4 KB spare) cannot hold.
 *
 * Slot 1. Slot 0 stays the best-cash record the death screen writes, so a
 * manual save can never cost you that.
 *
 * `ver` is checked on load and a mismatch is refused rather than read: these
 * structs are written straight to flash, so a layout change from a later build
 * would otherwise be reinterpreted as live state. */
#define SAVE_MAGIC 0x33415447u          /* 'GTA3' */
#define SAVE_VER   1u
/* The platform slot the game's save lives in. Slot 0 is the preferences and
 * record blob, so the three game slots are 1, 2 and 3. */
#define SAVE_SLOT  (1 + g_slot)
typedef struct {
    uint32_t magic, ver;
    int32_t  cash, best;
    float    px, pz, pyaw;
    float    heat;
    int32_t  weapon;
    int32_t  owned[NWEAP], ammo[NWEAP];
    int32_t  mission_chain;
    float    tod;
} SaveGame;

static int save_game(void) {
    if (!mote->save) return 0;
    SaveGame g;
    /* Zero by hand rather than memset: <string.h> is not pulled into this
     * freestanding module, and the struct is small. */
    { unsigned char *q = (unsigned char *)&g; for (unsigned i = 0; i < sizeof g; i++) q[i] = 0; }
    g.magic = SAVE_MAGIC; g.ver = SAVE_VER;
    g.cash = cash; g.best = best_cash;
    g.px = player.x; g.pz = player.z; g.pyaw = player.yaw;
    g.heat = heat; g.weapon = weapon; g.mission_chain = mission_chain; g.tod = g_tod;
    for (int i = 0; i < NWEAP; i++) { g.owned[i] = owned[i]; g.ammo[i] = ammo[i]; }
    return mote->save(SAVE_SLOT, &g, sizeof g) == (int)sizeof g;
}

static int load_game(void) {
    if (!mote->load) return 0;
    SaveGame g;
    if (mote->load(SAVE_SLOT, &g, sizeof g) != (int)sizeof g) return 0;
    if (g.magic != SAVE_MAGIC || g.ver != SAVE_VER) return 0;
    cash = g.cash; best_cash = g.best;
    heat = g.heat; heat_cool = 0;
    weapon = g.weapon; if (weapon < 0 || weapon >= NWEAP) weapon = W_FIST;
    mission_chain = g.mission_chain; g_tod = g.tod;
    for (int i = 0; i < NWEAP; i++) { owned[i] = g.owned[i]; ammo[i] = g.ammo[i]; }
    /* Put the player on foot at the saved spot: the car they were in belonged
     * to the old world and no longer exists. */
    if (player.mode == MODE_CAR && player.car >= 0) cars[player.car].driver = DRV_NONE;
    player.mode = MODE_FOOT; player.car = -1;
    player.x = g.px; player.z = g.pz; player.yaw = g.pyaw;
    return 1;
}

/* Is there a car the player could get into right now?
 *
 * The SAME predicate the enter branch uses (14 m^2, alive, not wrecked, not
 * already yours, not the peer's in a deathmatch). RB on foot is contextual —
 * use when something is in reach, cycle weapon otherwise — and if these two
 * tests ever drifted apart a single press would do both. */
/* The nearest vehicle you could get into, or -1.
 *
 * The reach scales with the vehicle's LENGTH instead of being a flat 3.74 m
 * from its centre. A flat radius works for cars because they are all about
 * 4.5 m long; it fails for anything bigger, and it failed completely for the
 * 7 m helicopter, whose own collision box holds you further out than the
 * radius allowed — so RB cycled your weapon instead of putting you in it.
 *
 * Shared with the USE branch so the two can never disagree: if this says a
 * vehicle is in reach, that is the vehicle RB takes. */
static int car_reach_pick(void) {
    int best = -1; float bd = 1e9f;
    for (int i = 0; i < NCAR; i++) {
        if (!cars[i].alive || cars[i].wrecked || cars[i].driver == DRV_PLAYER) continue;
        if (g_dm && i == dm_peer_car) continue;
        float dx = cars[i].x - player.x, dz = cars[i].z - player.z, d = dx*dx + dz*dz;
        float r = 1.9f + VSTAT[cars[i].type].len * 0.5f;   /* arm's length past the hull */
        if (d < r*r && d < bd) { bd = d; best = i; }
    }
    return best;
}
static int car_in_reach(void) { return car_reach_pick() >= 0; }

static void g_update(float dt) {
    const MoteInput *in = mote->input();
    if (dt > 0.05f) dt = 0.05f;

    /* Time of day, advanced here for the same reason the billboard counter
     * below is: every early-return path (map overlay, briefing freeze,
     * deathmatch end) still renders a frame, and a sky that stopped moving
     * whenever one of them was up would be visible as a stall. It also keeps
     * the title screen's orbit cycling. */
    /* Weather advances BEFORE the sky is baked, so the tint and any flash land
     * in this frame's palette rather than the next one's. */
    g_ltime += dt;                     /* traffic-light phase (see light_state) */
    if (g_ramcd > 0.0f) g_ramcd -= dt;
    weather_advance(dt);
    tod_advance(dt);

    /* Per-frame billboard-pool bookkeeping: reset unconditionally at the START
     * of the frame, before any early-return path (deathmatch end/respawn,
     * briefing freeze, map overlay, ...) can draw a billboard. bb_add()
     * increments g_bb_used, and it used to be reset only in the main play
     * path further down -- any branch that returned before reaching that
     * reset (e.g. the dm_end/dm_dead_t branch, which draws the remote
     * player's avatar via dm_draw_remote -> draw_character -> bb_add) left
     * the counter climbing frame over frame until the pool saturated and
     * bb_add started silently rejecting everything. */
    g_bb_used = 0; g_bb_budget_drop = 0;

    if (g_brief_active){                                  /* the job briefing freezes the city */
        if (mote_just_pressed(in, MOTE_BTN_A)) g_brief_active = 0;         /* accept */
        else if (mote_just_pressed(in, MOTE_BTN_B)){                       /* decline (the contact still calls back) */
            g_brief_active=0; mission_cleanup(); mission=MI_NONE; say("DECLINED"); }
        return;
    }
#ifdef MOTE_HOST
    { static int bdone=0; const char *e=getenv("MOTE_GTA_BRIEF");
      if (e && g_state==ST_PLAY && !g_brief_active && !bdone){
          uint32_t sd=(uint32_t)atoi(e);
          if (sd){ mote_rand_seed(sd|1u); g_seed_override=sd; }   /* vary job type + contact per seed */
          const char *mt=getenv("MOTE_GTA_MTYPE"); if(mt) g_force_mtype=atoi(mt);
          start_mission(); bdone=1; } }
    /* test: MOTE_GTA_HEAT=3 starts play at that wanted level, so a capture can
     * reach cop cars and a pursuit without scripting a crime spree first.
     * PROFILING.md notes combat has never been profiled; this is how. */
    { static int hd=0; const char *hv=getenv("MOTE_GTA_HEAT");
      if (hv && g_state==ST_PLAY && !hd){ hd=1; heat=(float)atof(hv); heat_cool=0; } }
    /* test: MOTE_GTA_TP_LIGHT=1 stands the player a few metres south of the
     * nearest junction, looking north at it, so a capture can actually see a
     * traffic light instead of hunting for a vantage where one happens to be
     * in frame. */
    { static int tpl=0;
      if (getenv("MOTE_GTA_TP_LIGHT") && g_state==ST_PLAY && !tpl && player.mode==MODE_FOOT){
          int px0=(int)(player.x/TILE), pz0=(int)(player.z/TILE), bx=-1, bz=-1, bd=1<<30;
          for (int z=pz0-20; z<=pz0+20; z++) for (int x=px0-20; x<=px0+20; x++){
              if (!is_junction(x,z)) continue;
              int d=(x-px0)*(x-px0)+(z-pz0)*(z-pz0);
              if (d<bd){ bd=d; bx=x; bz=z; } }
          /* The value picks WHICH SIDE to stand on: 0 south, 1 north, 2 east,
           * 3 west, each looking in at the junction. One side is not a test of
           * a traffic light — a flat head is only edge-on from some approaches,
           * so all four have to be checked. */
          if (bx>=0){ tpl=1;
              int side = atoi(getenv("MOTE_GTA_TP_LIGHT")) & 3;
              float jx=(bx+0.5f)*TILE, jz=(bz+0.5f)*TILE, D=TILE*2.2f;
              const float OX[4]={0.0f,0.0f, D,   -D  };
              const float OZ[4]={D,   -D,   0.0f, 0.0f};
              const float YW[4]={-1.5708f, 1.5708f, 3.14159f, 0.0f};
              player.x=jx+OX[side]; player.z=jz+OZ[side]; player.yaw=YW[side]; } } }
    /* test: MOTE_GTA_TP_TANK=1 stands the player beside the hidden tank. Its
     * spawn draws on the game RNG, which MOTE_GTA_SEED does not pin (that
     * fixes the city layout only), so it lands somewhere different every run
     * and cannot be reached with MOTE_GTA_VIEW. */
    { static int tpt=0;
      if (getenv("MOTE_GTA_TP_TANK") && g_state==ST_PLAY && !tpt && player.mode==MODE_FOOT){
          Car *t = &cars[NCAR-1];
          if (t->alive && t->type==VEH_TANK){ tpt=1;
              /* 3.2 m, not 4: car_in_reach uses 14 m^2, i.e. 3.74 m, so a
               * 4 m drop lands just outside and RB never enters. */
              player.x = t->x - 3.2f; player.z = t->z; player.yaw = 0.0f; } } }
    /* test: MOTE_GTA_TP_HELI=1 stands the player beside the helicopter, and
     * =2 puts them in it and already airborne, which is the only way to reach
     * the flight code from a scripted capture. Same reason as the tank's hook:
     * the pad is picked from the game RNG, which MOTE_GTA_SEED does not pin. */
    { static int tph=0; const char *hv=getenv("MOTE_GTA_TP_HELI");
      if (hv && g_state==ST_PLAY && !tph && player.mode==MODE_FOOT){
          Car *h = &cars[HELI_SLOT];
          if (h->alive && h->type==VEH_HELI){ tph=1;
              int m2 = atoi(hv);
              if (m2 >= 2){
                  player.mode=MODE_CAR; player.car=HELI_SLOT;
                  h->driver=DRV_PLAYER; g_heli_y=20.0f; g_heli_vy=0.0f;
                  /* =3 also parks it over the nearest TALL roof, which is the
                   * only practical way to capture a roof landing: steering
                   * there with scripted key presses takes hundreds of frames
                   * and lands somewhere different every build. */
                  /* =3 parks it over the nearest tall ROOF and =4 over the
                   * nearest WATER, the two surfaces with their own landing
                   * rule. Steering to either with scripted key presses takes
                   * hundreds of frames and lands somewhere different every
                   * build. The scan is the whole map: some seeds have no water
                   * within reach of the pad, and a hook that silently does
                   * nothing is worse than no hook. */
                  /* =5 parks it over the nearest ROOFTOP CACHE, which is the
                   * only practical way to test those: they land on random tall
                   * roofs and finding one by flying about takes thousands of
                   * frames. */
                  if (m2 == 5){
                      int best=-1; float bd=1e18f;
                      for (int k=0;k<NPICK;k++){ Pickup*pk=&picks[k];
                          if (!pk->alive) continue;
                          float fy=floor_y(pk->x,pk->z); if (fy < 0.5f) continue;
                          float dx2=pk->x-h->x, dz2=pk->z-h->z, d2=dx2*dx2+dz2*dz2;
                          if (d2<bd){ bd=d2; best=k; } }
                      if (best>=0){ h->x=picks[best].x; h->z=picks[best].z;
                                    bodies[HELI_SLOT].x=h->x; bodies[HELI_SLOT].y=h->z;
                                    g_heli_y = floor_y(h->x,h->z) + 10.0f; }
                  } else if (m2 >= 3){
                      char want = (m2 >= 4) ? '~' : 'H';
                      int px0=(int)(h->x/TILE), pz0=(int)(h->z/TILE), bx=-1, bz=-1, bd=1<<30;
                      for (int z=0; z<MAPH; z++) for (int x=0; x<MAPW; x++){
                          char tc=tile_at(x,z);
                          if (tc!=want || (want=='H' && is_garage(x,z))) continue;
                          int d=(x-px0)*(x-px0)+(z-pz0)*(z-pz0);
                          if (d<bd){ bd=d; bx=x; bz=z; } }
                      if (bx>=0){ h->x=(bx+0.5f)*TILE; h->z=(bz+0.5f)*TILE;
                                  bodies[HELI_SLOT].x=h->x; bodies[HELI_SLOT].y=h->z;
                                  g_heli_y = (want=='~' ? 0.0f : g_lvl_h[bld_level(bx,bz)]) + 12.0f; } }
                  gta3_cam_reset(&g_cam);
              } else {
                  /* 3.2 m, not 4: car_in_reach uses 14 m^2 — see the tank hook. */
                  player.x = h->x - 3.2f; player.z = h->z; player.yaw = 0.0f;
              } } } }
    /* test: MOTE_GTA_TP_GANG=1 stands the player just inside the street crew's
     * sight radius, facing them — the only way to reach the fight from a
     * scripted capture, since they spawn on a random corner. */
    { static int tpg=0;
      if (getenv("MOTE_GTA_TP_GANG") && g_state==ST_PLAY && !tpg && player.mode==MODE_FOOT){
          for (int i=0;i<NPED;i++) if (peds[i].alive && peds[i].gang){
              tpg=1; player.x = peds[i].x - 9.0f; player.z = peds[i].z;
              player.yaw = 0.0f; break; } } }
    /* test: MOTE_GTA_TP_PED=1 stands the player next to the nearest pedestrian,
     * facing them. Punching range is under 2 m and the scripted walks never
     * reliably land inside it. */
    { static int tpp=0;
      if (getenv("MOTE_GTA_TP_PED") && g_state==ST_PLAY && !tpp && player.mode==MODE_FOOT){
          int best=-1; float bd=1e9f;
          for (int i=0;i<NPED;i++){ Ped*p=&peds[i]; if(!p->alive||p->iscop) continue;
              float dx=p->x-player.x, dz=p->z-player.z, d=dx*dx+dz*dz;
              if (d<bd){ bd=d; best=i; } }
          if (best>=0){ tpp=1;
              player.x = peds[best].x - 1.0f; player.z = peds[best].z;
              player.yaw = 0.0f; } } }
    /* test: MOTE_GTA_INCAR=1 drops the player straight into the nearest car at
     * the start of play. The scripted "walk into traffic and hammer A" dance in
     * the capture harness stops landing whenever a physics or spawn change
     * moves the cars, which has cost three separate verification attempts. */
    { static int icd=0;
      if (getenv("MOTE_GTA_INCAR") && g_state==ST_PLAY && !icd && player.mode==MODE_FOOT){
          int best=-1; float bd=1e9f;
          for (int i=0;i<NCAR;i++){ Car *c=&cars[i];
              if (!c->alive || c->wrecked || c->driver==DRV_COP) continue;
              float dx=c->x-player.x, dz=c->z-player.z, d=dx*dx+dz*dz;
              if (d<bd){ bd=d; best=i; } }
          if (best>=0){ icd=1; cars[best].driver=DRV_PLAYER;
                        player.mode=MODE_CAR; player.car=best; } } }
    { static int tpd=0; if (getenv("MOTE_GTA_TP_PHONE") && g_state==ST_PLAY && !tpd){   /* test: stand by a phone box */
          for (int m=0;m<nmark;m++) if(markers[m].kind==MK_PHONE){
              if(player.mode==MODE_CAR){cars[player.car].alive=0;player.mode=MODE_FOOT;player.car=-1;}
              player.x=markers[m].x-3; player.z=markers[m].z; tpd=1; break; } } }
    { static int tps=0; if (getenv("MOTE_GTA_TP_SPRAY") && g_state==ST_PLAY && !tps && g_ngar>0){   /* test: stand on the approach, look into the bay */
          if(player.mode==MODE_CAR){cars[player.car].alive=0;player.mode=MODE_FOOT;player.car=-1;}
          player.x=(g_gar[0].x + g_gar[0].ox*2)*TILE+TILE*0.5f; player.z=(g_gar[0].z + g_gar[0].oz*2)*TILE+TILE*0.5f;
          player.yaw=atan2f(-(float)g_gar[0].oz, -(float)g_gar[0].ox); tps=1; } }
#endif

    /* high score is flushed to flash ONCE per death, but only AFTER the death
     * screen has shown for a few frames (the flash write stalls, so we let the
     * WASTED/BUSTED screen paint first and hide the hitch). */
    static int prev_state = ST_TITLE, death_saved = 0;
    if (g_state != prev_state) {
        if (g_state==ST_WASTED || g_state==ST_BUSTED) death_saved = 0;
        prev_state = g_state;
    }

    /* ---- title / death screens ---- */
    if (g_state != ST_PLAY) {
        /* Title and death screens: a slow orbit round the block, which is also the
         * shot the gallery screenshot wants. chase_camera on a stationary player
         * framed the back of a parked car, and at spawn was often jammed against
         * a building — so this does not call chase_camera at all; its
         * discontinuity guard (see chase_camera) picks the gameplay camera back
         * up cleanly on re-entry because reset_game()/respawn() always move the
         * player far enough for the guard's jump check to fire. */
        g_titlet += dt * 0.15f;
        float ox = pl_x() + cosf(g_titlet) * 22.0f;
        float oz = pl_z() + sinf(g_titlet) * 22.0f;
        cam_pos = v3(ox, 12.0f, oz);
        cam_basis = mote_camera_look(cam_pos, v3(pl_x(), 3.0f, pl_z()));
        view_x = pl_x(); view_z = pl_z();
        gta3_view_set(&g_view, cam_pos, cam_basis.r[2], FOV, 1.45f);
        mote->scene_camera(&cam_basis, cam_pos, FOV);
        draw_ground_window(); draw_buildings_window();
        if (g_state==ST_TITLE){
            if (mote_just_pressed(in,MOTE_BTN_A)){ reset_game(); g_state=ST_PLAY; }
            else if (mote->abi_version>=44 && mote_just_pressed(in,MOTE_BTN_B)){
                /* the engine lobby connects (USB/LAN/Internet) and resolves the
                 * authority; nonce 2 beats 1 so the existing hello + city transfer
                 * handshake runs unchanged, tie-free */
                int host=0;
                MoteNetCfg cfg={"GrandThumbAutoIII",DM_PROTO,MOTE_NET_ALL};
                if (mote->net_lobby(&cfg,&host)==MOTE_NET_CONNECTED){
                    dm_my_nonce=(uint16_t)(host?2:1);
                    dm_sent_hello=dm_got_hello=dm_started=0; dm_msg_len=0; dm_hello_t=0;
                    dm_phase=0; dm_map_pos=dm_map_recv=0; dm_out_len=dm_out_off=0;
                    dm_got_hash=dm_map_acked=0; dm_verify_t=0; dm_w_done=dm_wc_done=0;
                    dm_world_acked=0; dm_world_t=0; dm_rreq_t=2.0f; dm_rreq_mark=0;
                    g_state=ST_DMLINK;
                }
            }
        }
        else if (g_state==ST_DMLINK){
            dm_hello_t -= dt;
            if (mote->link_status() != MOTE_LINK_CONNECTED) {
                dm_sent_hello=dm_got_hello=0; dm_msg_len=0; dm_phase=0;   /* (re)connect restarts */
            } else if (dm_phase==0) {                                    /* --- handshake --- */
                if (!dm_sent_hello || dm_hello_t<=0){ dm_send_hello(); dm_sent_hello=1; dm_hello_t=0.5f; }
                dm_poll();                                              /* a peer 'S' arms dm_phase=1 */
                if (dm_got_hello && dm_peer_nonce==dm_my_nonce){        /* 1-in-65536 tie */
                    dm_my_nonce=(uint16_t)(mote->micros()*2654435761u>>8)^0x5A5Au;
                    dm_got_hello=0; dm_send_hello();
                } else if (dm_phase==0 && dm_got_hello &&
                           dm_my_nonce > dm_peer_nonce){    /* authority: seed, gen, xfer.
                    * MUST be evaluated HERE, after dm_poll(): a frame-top 'authority'
                    * snapshot read peer_nonce=0 on the very frame the first hello
                    * landed, so BOTH sides won, BOTH rolled seeds and streamed maps,
                    * and each adopted the OTHER's seed — same city (hash-verified),
                    * different seed-derived spawns and parked cars ('can't get in
                    * cars', 'can't find the opponent'). The oldest bug of the lot. */
                    dm_send_hello();
                    dm_seed=(uint32_t)mote->micros()*2654435761u ^ ((uint32_t)dm_my_nonce<<16) ^ dm_peer_nonce;
#ifdef MOTE_HOST
                    if (getenv("MOTE_GTA_DEBUG")) fprintf(stderr,"[SEED-TX] %08x (nonces my=%u peer=%u)\n",dm_seed,dm_my_nonce,dm_peer_nonce);
#endif
                    { uint8_t m[6]={0xA5,'S',(uint8_t)dm_seed,(uint8_t)(dm_seed>>8),
                                    (uint8_t)(dm_seed>>16),(uint8_t)(dm_seed>>24)};
                      mote->link_send(m,6); }
                    citygen(g_city, dm_seed);                           /* generate locally, then stream */
                    dm_phase=1; dm_map_pos=0; dm_out_len=dm_out_off=0;
                }
            } else if (dm_phase==1) {                                   /* --- map transfer --- */
                int authority = dm_my_nonce > dm_peer_nonce;            /* nonces final here */
                if (authority){
                    dm_poll();                                          /* serve 'R' / 'Y' */
                    for (int guard=0; guard<24; guard++){
                        if (!dm_flush_out()) break;                     /* FIFO full — resume next frame */
                        if (dm_map_pos>=CITY_BYTES) break;
                        int seq=dm_map_pos/DM_CHUNK, len=CITY_BYTES-dm_map_pos; if(len>DM_CHUNK)len=DM_CHUNK;
                        dm_out[0]=0xA5; dm_out[1]='m'; dm_out[2]=(uint8_t)seq; dm_out[3]=(uint8_t)(seq>>8); dm_out[4]=(uint8_t)len;
                        for (int i=0;i<len;i++) dm_out[5+i]=g_city[dm_map_pos+i];
                        dm_out_len=5+len; dm_out_off=0; dm_map_pos+=len;
                    }
                    if (dm_map_pos>=CITY_BYTES && dm_flush_out()){
                        dm_verify_t -= dt;
                        if (dm_verify_t<=0){                            /* offer the hash until acked */
                            uint32_t h=dm_city_fnv();
#ifdef MOTE_HOST
                            if (getenv("MOTE_GTA_DEBUG")) fprintf(stderr,"[CITY] auth fnv=%08x\n",h);
#endif
                            uint8_t m[6]={0xA5,'Z',(uint8_t)h,(uint8_t)(h>>8),(uint8_t)(h>>16),(uint8_t)(h>>24)};
                            mote->link_send(m,6); dm_verify_t=0.5f;
                        }
                        if (dm_map_acked){
                            reset_game_dm_finish(dm_seed); dm_phase=2;
                            dm_world_acked=0; dm_world_t=0.5f;
                            dm_send_world();                 /* re-offered from play upkeep until 'y' */
#ifdef MOTE_HOST
                            dm_world_hash_log("auth-sent");
#endif
                        }
                    }
                } else {
                    dm_poll();                                          /* 'm' frames fill g_city */
                    if (dm_map_recv < CITY_BYTES){
                        if (dm_map_recv > dm_rreq_mark){ dm_rreq_mark=dm_map_recv; dm_rreq_t=2.0f; }
                        else if ((dm_rreq_t -= dt) <= 0){               /* stream stalled: nudge */
                            uint8_t r[2]={0xA5,'R'}; mote->link_send(r,2); dm_rreq_t=2.0f;
                        }
                    }
                    if (dm_map_recv>=CITY_BYTES && dm_got_hash){
                        uint32_t h=dm_city_fnv();
#ifdef MOTE_HOST
                        if (getenv("MOTE_GTA_DEBUG")) fprintf(stderr,"[CITY] peer fnv=%08x (want %08x)\n",h,dm_peer_hash);
#endif
                        if (h==dm_peer_hash){
                            uint8_t a[2]={0xA5,'Y'}; mote->link_send(a,2);
                            reset_game_dm_finish(dm_seed); dm_phase=2;
                        } else {                                        /* corrupt: full re-stream */
                            dm_map_recv=0; dm_got_hash=0;
                            uint8_t r[2]={0xA5,'R'}; mote->link_send(r,2);
                            dm_rreq_t=2.0f; dm_rreq_mark=0;             /* repeat 'R' until 'm' resumes */
#ifdef MOTE_HOST
                            if (getenv("MOTE_GTA_DEBUG")) fprintf(stderr,"[CITY] MISMATCH - requesting re-stream\n");
#endif
                        }
                    }
                }
            }
            if (mote_just_pressed(in,MOTE_BTN_B)){ dm_stop(); g_state=ST_TITLE; }
        }
        else { g_screen_t-=dt;
            if (!death_saved && g_screen_t < 2.35f && mote->save) {   /* screen shown first, then flush */
                save_prefs(); death_saved=1;
            }
            if (g_screen_t<=0) respawn(g_state==ST_BUSTED); }
        return;
    }

    int A = mote_just_pressed(in, MOTE_BTN_A);
    /* USE = enter a car, exit a car, or work a shop/phone. It moved from A to
     * RB so that A can be the throttle while driving, which is where a thumb
     * naturally rests. On foot RB stays CONTEXTUAL: it only means "use" when
     * something is actually in reach, and otherwise still cycles your weapon —
     * so nothing had to be evicted to another button. */
    int USE = mote_just_pressed(in, MOTE_BTN_RB);
    if (g_msg_t>0) g_msg_t-=dt;
    if (fire_cd>0) fire_cd-=dt;
    if (g_shell_cd>0) g_shell_cd-=dt;
    if (g_tankrecoil>0) g_tankrecoil-=dt;

    if (g_dm){                                   /* deathmatch upkeep, every frame */
        dm_poll();
        dm_rx_age += dt;
        if (mote->net_health()==MOTE_NET_LOST && !dm_end) dm_end=3; /* v45: engine-measured loss (blips recover) */
        heat=0; heat_cool=99;                    /* no police in DM */
        if (rp_fire_t>0) rp_fire_t-=dt;
        rp_anim += dt;
        if (dm_ramcd>0) dm_ramcd-=dt;
        { float k=dt*10.0f; if(k>1)k=1;          /* smooth the replicated avatar */
          rp_dx2 += (rp_x-rp_dx2)*k; rp_dz2 += (rp_z-rp_dz2)*k; }
        dm_send_t -= dt;
        if (dm_send_t<=0){ dm_send_state(); dm_send_t=1.0f/15; }
        if (dm_auth){                                   /* authority broadcasts the shared traffic */
            if (!dm_world_acked){                       /* world offer until the peer confirms */
                dm_world_t -= dt;
                if (dm_world_t<=0){ dm_send_world(); dm_world_t=0.5f; }
            }
            dm_vsend_t -= dt;
            if (dm_vsend_t<=0){ dm_send_traffic(); dm_vsend_t=1.0f/12;
#ifdef MOTE_HOST
                if(getenv("MOTE_GTA_DEBUG")){ int n=0; float sx=0;
                    for(int i=0;i<NCAR;i++) if(cars[i].alive&&i!=player.car&&i!=dm_peer_car){n++;sx+=cars[i].x;}
                    static int c; if((c++%12)==0) fprintf(stderr,"[AUTH] traffic=%d sumx=%.0f\n",n,sx); }
#endif
            }
        } else {                                        /* peer: ease traffic toward streamed targets */
            float k=dt*12.0f; if(k>1)k=1;
            for (int i=0;i<NCAR;i++){ if(!cars[i].alive||i==player.car||!dm_tpresent[i]) continue;
                float dx=dm_tx[i]-cars[i].x, dz=dm_tz[i]-cars[i].z;
                if (dx*dx+dz*dz > 15.0f*15.0f){ cars[i].x=dm_tx[i]; cars[i].z=dm_tz[i]; cars[i].yaw=dm_tyaw2[i]; }  /* recycle: snap */
                else { cars[i].x += dx*k; cars[i].z += dz*k; cars[i].yaw += ang_diff(dm_tyaw2[i], cars[i].yaw)*k; } }
        }
        for (int i=0;i<NPICK;i++)                /* caches come back */
            if (!picks[i].alive && g_dmpkt[i]>0){ g_dmpkt[i]-=dt; if (g_dmpkt[i]<=0) picks[i].alive=1; }
        /* RAMMING: my car at speed over their on-foot avatar */
        if (player.mode==MODE_CAR && rp_hp>0 && !rp_mode && dm_ramcd<=0 &&
            fabsf(cars[player.car].spd)>6.0f){
            float dx=rp_x-pl_x(), dz=rp_z-pl_z();
            if (dx*dx+dz*dz<2.6f){ dm_send2('D',(uint8_t)(fabsf(cars[player.car].spd)*2.2f)); dm_ramcd=0.7f; }
        }
        if (dm_end || dm_dead_t>0){              /* end box / respawn wait: world holds */
            if (dm_dead_t>0){ dm_dead_t-=dt; if (dm_dead_t<=0) dm_respawn_me(); }
            if (dm_end && mote_just_pressed(in,MOTE_BTN_B)){ dm_stop(); g_state=ST_TITLE; return; }
            chase_camera(pl_x(), pl_z(), pl_yaw(), dt);
            mote->scene_camera(&cam_basis, cam_pos, FOV);
            draw_ground_window();
            dm_draw_remote();
            draw_buildings_window();       /* after the avatar: budget priority */
            return;
        }
    }

    /* MENU toggles the pause screen; while open, gameplay pauses. */
    if (mote_just_pressed(in, MOTE_BTN_MENU)){
        if (g_ctlpage) { g_ctlpage = 0; return; }    /* back out one level first */
        g_showmap = !g_showmap;
        if (g_showmap){ g_mapsx=(int)(pl_x()/TILE)-64; g_mapsy=(int)(pl_z()/TILE)-64; }
    }
    if (g_showmap){
        g_maptime += dt;
        if (g_setmsg_t > 0.0f) g_setmsg_t -= dt;
        if (g_ctlpage) {                     /* the page owns every button until dismissed */
            if (mote_just_pressed(in,MOTE_BTN_A) || mote_just_pressed(in,MOTE_BTN_B) ||
                mote_just_pressed(in,MOTE_BTN_RB) || mote_just_pressed(in,MOTE_BTN_LB))
                g_ctlpage = 0;
            return;
        }
        /* LB/RB flip tabs on either screen, so you can always get back. */
        if (mote_just_pressed(in,MOTE_BTN_RB)) g_menutab = (g_menutab+1) % TAB_N;
        if (mote_just_pressed(in,MOTE_BTN_LB)) g_menutab = (g_menutab+TAB_N-1) % TAB_N;
        if (g_menutab == TAB_SET) {
            if (mote_just_pressed(in,MOTE_BTN_UP))   g_setsel = (g_setsel+SET_N-1) % SET_N;
            if (mote_just_pressed(in,MOTE_BTN_DOWN)) g_setsel = (g_setsel+1) % SET_N;
            /* LEFT/RIGHT adjusts the highlighted row where it has something to
             * adjust. On SAVE or LOAD that is WHICH SLOT, which is why the two
             * need no row of their own: the number is shown on the row you are
             * about to act on. */
            { int adj = (mote_just_pressed(in,MOTE_BTN_RIGHT) ? 1 : 0)
                      - (mote_just_pressed(in,MOTE_BTN_LEFT)  ? 1 : 0);
              if (adj) {
                  if (g_setsel == SET_SAVE || g_setsel == SET_LOAD) {
                      g_slot = (uint8_t)((g_slot + NSAVE_SLOT + adj) % NSAVE_SLOT);
                      save_prefs();
                      g_setmsg = 0;      /* the old SAVED/LOADED line is about another slot */
                  } else if (g_setsel == SET_MINIMAP) {
                      g_radar_on = !g_radar_on;
                  } else if (g_setsel == SET_SOUND) {
                      g_sound_on = !g_sound_on; save_prefs();
                  }
              } }
            if (mote_just_pressed(in,MOTE_BTN_A)) {
                switch (g_setsel) {
                case SET_MINIMAP: g_radar_on = !g_radar_on; break;
                case SET_SOUND:   g_sound_on = !g_sound_on; save_prefs(); break;
                case SET_CONTROLS: g_ctlpage = 1; break;
                /* TEMPORARY DEBUG — see the SET_HELI comment at the enum. */
                case SET_TANK: {
                    Car *h = &cars[NCAR-1];
                    float ox, oz; bring_here(&ox, &oz);
                    *h = (Car){ ox, oz, pl_yaw(), 0, VEH_TANK, DRV_NONE, 1, 600.0f, 0 };
                    car_body_init(NCAR-1);
                    g_shells = TANK_SHELLS;      /* a delivered tank is a loaded one */
                    g_setmsg = "TANK DELIVERED"; g_setmsg_t = 2.0f;
                } break;
                case SET_HELI: {
                    Car *h = &cars[HELI_SLOT];
                    float ox, oz; bring_here(&ox, &oz);
                    *h = (Car){ ox, oz, pl_yaw(), 0, VEH_HELI, DRV_NONE, 1, 100.0f, 0 };
                    car_body_init(HELI_SLOT);
                    g_heli_y = 0.0f; g_heli_vy = 0.0f;
                    g_setmsg = "HELI DELIVERED"; g_setmsg_t = 2.0f;
                } break;
                case SET_SAVE:    g_setmsg = save_game() ? "SAVED" : "SAVE FAILED"; g_setmsg_t = 2.0f; break;
                case SET_LOAD:    g_setmsg = load_game() ? "LOADED" : "NO SAVE";    g_setmsg_t = 2.0f; break;
                }
            }
            return;                     /* settings tab does not pan the map */
        }
        int sp = mote_pressed(in,MOTE_BTN_B) ? 6 : 3;   /* B = pan faster */
        if (mote_pressed(in,MOTE_BTN_LEFT))  g_mapsx-=sp;
        if (mote_pressed(in,MOTE_BTN_RIGHT)) g_mapsx+=sp;
        if (mote_pressed(in,MOTE_BTN_UP))    g_mapsy-=sp;
        if (mote_pressed(in,MOTE_BTN_DOWN))  g_mapsy+=sp;
        if (g_mapsx<0) g_mapsx=0; if (g_mapsx>MAPW-128) g_mapsx=MAPW-128;
        if (g_mapsy<0) g_mapsy=0; if (g_mapsy>MAPH-128) g_mapsy=MAPH-128;
        mote->scene_set_background(MOTE_RGB565(8,10,16));
        return;                                              /* pause the sim while the map is up */
    }

    if (player.mode == MODE_FOOT) {
        /* Tank controls: left/right turn in place, up/down walk along the
         * facing. The camera swings to follow the player, so a camera-
         * relative d-pad (the old 8-way absolute scheme) flips direction
         * under the player's hands every time the camera comes round a
         * corner; turning in place is invariant to that. */
        const float TURN = 3.0f;              /* rad/s */
        const float WALK_SPD = 5.0f;          /* m/s, same as the old 8-way walk */
        /* SPRINT: hold A while walking FORWARD — "enter a car, or run".
         *
         * A's other job, entering a car or using a shop/phone, fires on the
         * PRESS EDGE (mote_just_pressed), while this reads the HELD state. The
         * two cannot collide: a tap enters the car and the hold then does
         * nothing because you are no longer on foot. Holding A in open street
         * with nothing to interact with just runs.
         *
         * Burns in STAM_BURN seconds and refills in STAM_FILL, and once it is
         * emptied you cannot sprint again until it has recovered past
         * STAM_ARM — without that latch you get a stutter where the player
         * flickers between running and walking at zero stamina. */
        #define STAM_BURN 2.6f
        #define STAM_FILL 4.2f
        #define STAM_ARM  0.35f
        #define SPRINT_MUL 1.75f
        /* yaw+ turns visually LEFT under the chase camera — see drive_car. */
        if (mote_pressed(in, MOTE_BTN_LEFT))  player.yaw += TURN * dt;
        if (mote_pressed(in, MOTE_BTN_RIGHT)) player.yaw -= TURN * dt;
        player.yaw = gta3_wrap_angle(player.yaw);

        float drive = 0.0f;
        if (mote_pressed(in, MOTE_BTN_UP))   drive =  1.0f;
        if (mote_pressed(in, MOTE_BTN_DOWN)) drive = -0.5f;   /* backing up is slower, and does not turn */

        int want_run = drive > 0.0f && mote_pressed(in, MOTE_BTN_A) && !g_stam_spent;
        if (want_run && g_stam > 0.0f) {
            g_stam -= dt / STAM_BURN;
            if (g_stam <= 0.0f) { g_stam = 0.0f; g_stam_spent = 1; }   /* latch until recovered */
        } else {
            g_stam += dt / STAM_FILL;
            if (g_stam > 1.0f) g_stam = 1.0f;
            if (g_stam_spent && g_stam >= STAM_ARM) g_stam_spent = 0;
            want_run = 0;
        }
        float spd = WALK_SPD * (want_run ? SPRINT_MUL : 1.0f);

        if (drive != 0.0f) {
            float nx = player.x + cosf(player.yaw) * spd * drive * dt;
            float nz = player.z + sinf(player.yaw) * spd * drive * dt;
            if (!ped_blocked_by_car(nx,nz) || ped_blocked_by_car(player.x,player.z))
                move_body(&player.x, &player.z, nx, nz, 0);
            player.animt += dt * (want_run ? 13.0f : 8.0f);   /* legs keep up with the pace */
        }
        g_lookback = mote_pressed(in, MOTE_BTN_LB);

        if (mote_pressed(in, MOTE_BTN_B)) fire_weapon();
        /* RB with nothing in reach: cycle your weapon, as it always did. The
         * reach test below is the same one the USE branch runs, so the two can
         * never both fire on one press. */
        if (USE && !near_marker(MK_GUN,3.0f) && !near_marker(MK_PHONE,3.0f) && !car_in_reach()) {
            for (int t=0;t<NWEAP;t++){ weapon=(weapon+1)%NWEAP;
                if (weapon==W_FIST || (owned[weapon] && ammo[weapon]>0)) break; }
            say(WNAME[weapon]);
        }
        /* RB: work a shop/phone if in range, else enter/jack a car */
        else if (USE) {
            if (near_marker(MK_GUN, 3.0f))        buy_gun();
            else if (near_marker(MK_PHONE, 3.0f)) start_mission();
            else {
                int best = car_reach_pick();
                if (best>=0) {
                    if (cars[best].driver==DRV_COP) {            /* eject a fighting officer */
                        float ry=cars[best].yaw+1.5708f;
                        add_heat(0.3f); spawn_footcop(cars[best].x+cosf(ry)*2.5f, cars[best].z+sinf(ry)*2.5f);
                    } else if (cars[best].driver==DRV_NPC) {     /* the DRIVER bails out + runs */
                        float ry=cars[best].yaw+1.5708f;
                        float ex=cars[best].x+cosf(ry)*2.6f, ez=cars[best].z+sinf(ry)*2.6f;
                        if (ped_blocked_by_car(ex,ez)){ ex=cars[best].x-cosf(ry)*2.6f; ez=cars[best].z-sinf(ry)*2.6f; }
                        int slot=-1;
                        for (int j=0;j<NPED;j++) if(!peds[j].alive){ slot=j; break; }
                        if (slot<0){                              /* pool full: reuse the farthest civilian */
                            float fd=0;
                            for (int j=0;j<NPED;j++){ if(peds[j].iscop) continue;
                                if (mission==MI_HIT && j==mission_target) continue;
                                float dx=peds[j].x-player.x, dz=peds[j].z-player.z, d2=dx*dx+dz*dz;
                                if (d2>fd){ fd=d2; slot=j; } }
                        }
                        if (slot>=0){
                            peds[slot]=(Ped){ ex,ez, ry,0,(uint8_t)irand(4),1,2,0, /*flee*/3.0f };
                            panic_at(cars[best].x, cars[best].z);  /* they scatter, shaken */
                        }
                        add_heat_at(0.9f, cars[best].x, cars[best].z, 0);  /* grand theft auto, witnessed */
                    }
                    cars[best].driver=DRV_PLAYER; player.mode=MODE_CAR; player.car=best;
                    /* PEER ONLY: give the car a LIVE physics body. On the peer,
                     * physics_pass pins every car except player.car to
                     * inv_mass=0 (a static streamed obstacle) every frame, so a
                     * freshly-jacked car still had zero mass — drive force did
                     * nothing and it wouldn't collide ('engine noise but the
                     * car won't move'). Re-init restores real mass; physics_pass
                     * then skips it (i==player.car). The authority's bodies are
                     * always live, so leave its jack feel (rolling entry) alone. */
                    if (g_dm && !dm_auth){ car_body_init(best);
                        bodies[best].vx=dm_tvx[best]; bodies[best].vy=dm_tvz[best];  /* keep the car's momentum */
                        cars[best].spd = bodies[best].vx*cosf(cars[best].yaw)+bodies[best].vy*sinf(cars[best].yaw); }
                    if (g_dm) dm_send2('C',(uint8_t)best);   /* peer hides its copy */
                    if (cars[best].type==VEH_TANK) g_turret=cars[best].yaw;
                }
            }
        }
    } else {                                                   /* MODE_CAR */
        g_lookback = 0;                    /* can't stick from a foot session before entering */
        Car *c=&cars[player.car];
        /* Behind the wheel the pedals sit under the two face buttons — A gas,
         * B brake/reverse — and shooting moves to the left shoulder. On foot B
         * is still attack and LB is still look-back; the two modes are
         * separate, so neither binding had to give anything up. */
        if (c->type==VEH_HELI)
            fly_heli(c, player.car, dt,
                     mote_pressed(in,MOTE_BTN_A),    mote_pressed(in,MOTE_BTN_B),
                     mote_pressed(in,MOTE_BTN_UP),   mote_pressed(in,MOTE_BTN_DOWN),
                     mote_pressed(in,MOTE_BTN_LEFT), mote_pressed(in,MOTE_BTN_RIGHT));
        else if (c->type==VEH_BOAT)
            sail_boat(c, player.car, dt,
                      mote_pressed(in,MOTE_BTN_A),    mote_pressed(in,MOTE_BTN_B),
                      mote_pressed(in,MOTE_BTN_LEFT), mote_pressed(in,MOTE_BTN_RIGHT));
        else
        drive_car(c, dt, mote_pressed(in,MOTE_BTN_A), mote_pressed(in,MOTE_BTN_B),
                  mote_pressed(in,MOTE_BTN_LEFT), mote_pressed(in,MOTE_BTN_RIGHT));
        if (c->type==VEH_TANK){
            /* TURRET CONTROL: when the tank is (near) still, LEFT/RIGHT traverse the
             * turret instead of steering (steering is dead when stopped anyway);
             * once rolling, the turret eases back onto the hull line. */
            if (fabsf(c->spd) < 0.8f){
                if (mote_pressed(in,MOTE_BTN_LEFT))  g_turret += 2.2f*dt;   /* yaw+ = screen left */
                if (mote_pressed(in,MOTE_BTN_RIGHT)) g_turret -= 2.2f*dt;
            } else g_turret += ang_diff(c->yaw, g_turret) * mote_clampf(2.5f*dt,0,1);
        }
        /* No weapons from the helicopter: shooting from a hover would make the
         * rampage and vigilante jobs trivially winnable, and it needs bullets
         * that start at altitude and aim down. LB is dead in the air.
         * The boat is out for the same reason as the helicopter: bullets are
         * 2D and start at the hull, and a gunboat is a different feature. */
        if (mote_pressed(in, MOTE_BTN_LB) && c->type!=VEH_HELI && c->type!=VEH_BOAT){
            if(c->type==VEH_TANK) fire_shell(c); else fire_weapon(); }
        /* SELL DOCK: roll onto the pier slowly and the fence takes the car */
        if (near_marker(MK_DOCK, 3.4f) && fabsf(c->spd)<3.0f && !c->wrecked){
            static const uint16_t SELL[19]={ 180,140,220,700,1200,450,300,350,550,650,
                                             200,250,220,300,260,800,400,900,500 };
            /* Every non-car type needs its own price. SELL is indexed by
             * CAR_CLS, which has one entry per CARS2 car and none for the
             * bus, tank, helicopter or boat — so a type past CARS2_N read off
             * the end of CAR_CLS and then indexed a 19-entry table with
             * whatever byte came back. The helicopter has been doing that
             * since it was added. */
            int price = (c->type==VEH_BUS)  ?  350
                      : (c->type==VEH_TANK) ? 2500
                      : (c->type==VEH_HELI) ? 3000
                      : (c->type==VEH_BOAT) ?  900
                      : (c->type < CARS2_N) ? SELL[CAR_CLS[c->type]]
                                            :  300;
            cash += price; sfx(&cash_sfx,0.8f);
            { char b[10]; b[0]='+'; b[1]='$'; int n=price,k=2; char d2[5]; int dn=0;
              while(n){d2[dn++]='0'+n%10;n/=10;} while(dn) b[k++]=d2[--dn]; b[k]=0;
              float_txt(c->x,c->z,b); }
            say("SOLD TO THE FENCE");
            float ry=c->yaw+1.5708f;
            player.x=c->x+cosf(ry)*2.4f; player.z=c->z+sinf(ry)*2.4f;
            player.mode=MODE_FOOT; player.car=-1;
            c->alive=0;                                   /* shipped out on the barge */
        }
        else
        /* pay-n-spray: drive in with heat to lose the cops for a fee */
        if (near_marker(MK_SPRAY, 3.2f) && wanted()>0 && cash>=SPRAY_FEE){
            cash-=SPRAY_FEE; heat=0; if(c->alive)c->hp=100; say("SPRAYED - HEAT CLEARED"); sfx(&cash_sfx,0.7f); }
        /* You cannot step out of a helicopter in mid-air. The check is against
         * the floor UNDER the aircraft, so setting down on a roof counts as
         * landed and you get out on the roof. */
        if (USE && player.mode==MODE_CAR && c->type==VEH_HELI &&
            heli_aloft(c->x, c->z)) {
            say("LAND FIRST");
        } else
        if (USE && player.mode==MODE_CAR) {                    /* RB: step out beside the car */
            int ci=player.car;
            float rx=cosf(c->yaw+1.5708f), rz=sinf(c->yaw+1.5708f);
            player.x=c->x+rx*2.2f; player.z=c->z+rz*2.2f; player.yaw=c->yaw;
            c->driver=DRV_NONE; c->spd=0; player.mode=MODE_FOOT; player.car=-1;
            if (g_dm) dm_send_carback(ci);                     /* peer re-materialises it */
        }
    }

    if (!g_dm || dm_auth){      /* peer's ambient traffic comes from the stream, not local AI */
        stream_entities(dt);    /* recycle far/stuck traffic + peds into a bubble near the player */
        if (g_dm) dm_recycle_traffic(dt);   /* keep the shared pool near BOTH players */
        update_traffic(dt);     /* control: NPC/cop AI set body velocity + steering */
    }
    ai_debug(dt);               /* MOTE_GTA_DEBUG: log lane-keeping health */
    update_cops(dt);
    physics_pass(dt);           /* engine 2D solver: integrate + collide + read back */
    update_peds(dt);
    do_runovers();
    update_bullets(dt);
    update_pickups(dt);
    { float px2=pl_x(), pz2=pl_z();                       /* discovery: note what you pass */
      for (int i=0;i<nmark;i++){ if(markers[i].seen) continue;
          float dx=markers[i].x-px2, dz=markers[i].z-pz2;
          if (dx*dx+dz*dz < 32.0f*32.0f) markers[i].seen=1; }
      for (int i=0;i<NPICK;i++){ if(!picks[i].alive||picks[i].seen) continue;
          float dx=picks[i].x-px2, dz=picks[i].z-pz2;
          if (dx*dx+dz*dz < 32.0f*32.0f) picks[i].seen=1; } }
    update_heat(dt);
    update_missions(dt);
    for (int i=0;i<NFX;i++) if(fxs[i].t>0) fxs[i].t-=dt;
    for (int i=0;i<6;i++) if(g_ftxt[i].t>0) g_ftxt[i].t-=dt;
    if (g_aim_t>0) g_aim_t-=dt;
    /* battle-damage: hurt cars trail smoke, nearly-dead ones burn */
    for (int i=0;i<NCAR;i++){ Car*cc=&cars[i]; if(!cc->alive||cc->wrecked) continue;
        if (cc->hp<45.0f && frand()<dt*5.0f)
            add_fx(cc->x+(frand()*2-1)*0.8f, cc->z+(frand()*2-1)*0.8f, 3);
        if (cc->hp<18.0f && frand()<dt*7.0f)
            add_fx(cc->x+(frand()*2-1)*0.6f, cc->z+(frand()*2-1)*0.6f, 4);
    }
    /* two-tone siren wails while a squad car is actively on you: the chase loop
     * alternates a high and a low tone (~597/436 Hz) for a continuous wee-woo. */
    { static float s_siren; static int s_tone;
      s_siren-=dt; int chase=0;
      if (wanted()>0) for (int i=0;i<NCAR;i++) if(cars[i].alive&&cars[i].driver==DRV_COP){
          float dx=cars[i].x-pl_x(), dz=cars[i].z-pl_z();
          if (dx*dx+dz*dz<70.0f*70.0f){ chase=1; break; } }
      if (chase && s_siren<=0){ sfx(s_tone?&siren_hi_sfx:&siren_lo_sfx, 0.34f); s_tone^=1; s_siren=0.44f; } }
    /* CITY AMBIENCE: a siren somewhere else in the city, now and then, at a
     * gain low enough to read as distance. It only plays when you are NOT
     * wanted — with heat on you the chase siren is already running and a
     * second one would just muddy it. Costs one float and one sample that is
     * already in flash. */
    { static float s_amb = 9.0f;
      s_amb -= dt;
      if (s_amb <= 0.0f) {
          s_amb = 14.0f + frand() * 26.0f;
          if (wanted() == 0 && g_state == ST_PLAY) sfx(&siren_sfx, 0.10f);
      } }
    /* a phone box RINGS when you're looking for work and get close — louder the nearer you are */
    { static float s_ring; s_ring-=dt;
      if (mission==MI_NONE && !g_brief_active && g_state==ST_PLAY){
          float best=1e18f;
          for (int m=0;m<nmark;m++){ if(markers[m].kind!=MK_PHONE) continue;
              float dx=markers[m].x-pl_x(), dz=markers[m].z-pl_z(), d2=dx*dx+dz*dz; if(d2<best)best=d2; }
          float d=sqrtf(best);
          if (d<22.0f && s_ring<=0){ float g=0.55f*(1.0f-d/22.0f); if(g<0.06f)g=0.06f;
              sfx(&phone_sfx, g); s_ring=1.9f; } } }
    if (cash>best_cash) best_cash=cash;    /* in memory only — flushed to flash at death */

    /* engine pitch rides speed: quiet on foot, loud with speed */
    /* The engine drone is a STREAM, not a sample, so sfx()'s gate does not
     * reach it — its amplitude is silenced here instead. Eased to zero rather
     * than cut, so toggling sound off mid-drive fades out instead of clicking. */
    if (player.mode==MODE_CAR && g_sound_on){ float s=fabsf(cars[player.car].spd);
        g_eng_f = 30.0f + s*5.0f;   /* lower, rumblier drone (was 46 + s*7.5) */
        float at = 0.11f + s*0.012f; if(at>0.30f)at=0.30f; g_eng_a += (at-g_eng_a)*0.3f;
    } else g_eng_a *= 0.85f;

    float tx = (player.mode==MODE_CAR)? cars[player.car].x : player.x;
    float tz = (player.mode==MODE_CAR)? cars[player.car].z : player.z;
    float tyaw = (player.mode==MODE_CAR)? cars[player.car].yaw : player.yaw;
    chase_camera(tx, tz, tyaw, dt);
    mote->scene_camera(&cam_basis, cam_pos, FOV);
    /* g_bb_used / g_bb_budget_drop reset at the top of g_update now, not here
     * -- see the comment there for why. */

    draw_ground_window();
    stars_update(cam_basis.r[2]);   /* before the background pass paints the sky */
    draw_sky_body();
    draw_clouds();
    draw_traffic_lights();
    draw_street_lamps();
    draw_street_detail();
    draw_water_shimmer();
    /* Buildings are submitted AFTER the entities below: the textured-tri pool is
     * first-come (extra tris are silently dropped), and a clipped far building is
     * far less jarring than a vanished car. The raster is depth-buffered, so
     * drawing buildings last still occludes correctly (order-independent). */

    /* Car ground shadows: draw_vehicle_mesh now issues one scene_add_shadow_ex
     * per car (oriented semi-axes from VSTAT len/wid), replacing the eight-
     * triangle hand-built octagon that used to be assembled here. */

    /* people, vehicles, then TREES as flat GROUND QUADS in the 3D scene — depth-tested, so
     * buildings occlude them all. Draw order = height order for the NO_DEPTH_WRITE layers:
     * peds on the ground, cars above them, and tree CANOPIES last (they're ~5 m up, so
     * people and cars pass UNDERNEATH — the canopy overlaps them, never the reverse). */
    if (player.mode==MODE_CAR && g_state==ST_PLAY)
        draw_vehicle(player.car);        /* FIRST claim on the textured-tri pool:
                                            your own car must never be the one culled */
    /* world props: phonebox / gun-shop mat at each marker (spray shops are garage bays,
     * marked by an arrow into the opening instead of a floor decal). */
    for (int m=0;m<nmark;m++){
        if (markers[m].kind==MK_SPRAY) continue;             /* garage: drawn as an arrow below */
        float dx=markers[m].x-view_x, dz=markers[m].z-view_z;
        if (dx*dx+dz*dz > 2500.0f) continue;
        if (markers[m].kind==MK_PHONE){          /* has volume: an upright billboard, not a decal */
            draw_upright(&props_img, markers[m].x, markers[m].z, 0,0,16,16, 2.2f, VIEW_GROUND_R, 1.0f);
            continue;
        }
        int cell = markers[m].kind==MK_GUN?1 : 3;             /* gun mat / dock marker: genuinely flat decals */
        draw_ground_sprite(&props_img, markers[m].x, markers[m].z, 0, cell*16,0,16,16, 2.1f, 2.1f, 0);
    }
    for (int i=0;i<g_ngar;i++){                               /* an arrow on the approach, pointing INTO the bay */
        float ax=(g_gar[i].x + g_gar[i].ox)*TILE + TILE*0.5f;
        float az=(g_gar[i].z + g_gar[i].oz)*TILE + TILE*0.5f;
        float dx=ax-view_x, dz=az-view_z; if (dx*dx+dz*dz > 2500.0f) continue;
        float yaw=atan2f((float)g_gar[i].oz, (float)g_gar[i].ox);     /* heading points INTO the garage (sprite +Z is -x at yaw 0) */
        draw_ground_sprite(&props_img, ax, az, yaw, 4*16,0,16,16, 2.6f, 2.2f, 1);
    }
    /* pickups: upright billboards with a small vertical bob so they read as
     * collectable, not painted on the road like the decals above. PK_PACKAGE
     * has no atlas cell — it stays a crate marker drawn in the overlay.
     * NPICK=44 are scattered across the WHOLE map (unlike peds, which
     * stream_entities already keeps near the player) with no frustum test of
     * their own before this task, so distance + view-cone gating here both
     * matter — see bb_add. */
    for (int i=0;i<NPICK;i++){ Pickup*p=&picks[i]; if(!p->alive||p->kind==PK_PACKAGE) continue;
        float bob = 0.15f * sinf(p->bob);
        /* floor_y, not 0: a cache on a roof sits ON that roof. Every other
         * pickup is on a street tile, where floor_y is 0 and this is the
         * height it always had. */
        bb_add(&pickups_img, p->x, floor_y(p->x,p->z) + 0.6f + bob, p->z,
              p->kind*16, 0, 16, 16, 1.0f, MOTE_BLEND_NONE, VIEW_GROUND_R, 1.0f);
    }
    for (int i=0;i<NPED;i++){ Ped*p=&peds[i]; if(!p->alive) continue;
        if (p->iscop){
            /* cop_img genuinely has only 2 walk rows (no dedicated aim/fire
             * art) — in combat, toggle between them off firecd instead of
             * walking, so there's still a visible cue that they're shooting. */
            int fr=((int)p->animt)&1;
            if (wanted()>0){
                float dx=pl_x()-p->x, dz=pl_z()-p->z;
                if (dx*dx+dz*dz < 560.0f) fr = (p->firecd > 0.85f) ? 1 : 0;
            }
            draw_character(&cop_img, p->x, p->z, p->yaw, 0, fr, 2);
        } else {
            /* ped_img has 4 walk frames (make_chars3d.py); &1 only ever hit
             * rows 0/1 of each variant, leaving rows variant*4+2/+3 unreachable. */
            int fr=((int)p->animt)&3;
            draw_character(&ped_img, p->x, p->z, p->yaw, p->variant, fr, 4);
        }
    }
    if (player.mode==MODE_FOOT && g_state==ST_PLAY){          /* player walks under trees too */
        int fr;
        if      (g_aim_t > 0.62f) fr = 5;                      /* muzzle flash */
        else if (g_aim_t > 0.0f)  fr = 4;                      /* holding aim */
        else                      fr = ((int)player.animt)&3;  /* walk cycle */
        draw_character(&player_img, player.x, player.z, player.yaw, 0, fr, 6); }
    /* vehicles: draw_vehicle_mesh sizes each car's boxes from VSTAT.len/wid directly
     * (no sprite art proportions to preserve now that cars are mesh, not sprite). */
    for (int i=0;i<NCAR;i++){
        if (player.mode==MODE_CAR && i==player.car) continue;   /* already drawn first */
        draw_vehicle(i);
    }
    dm_draw_remote();                                           /* the OTHER player */
    /* the rival is a real DRV_NPC car — draw_vehicle() above already renders it */
    draw_buildings_window();                                    /* after entities (budget priority) */
#ifdef MOTE_HOST
    { static int on=-1; if(on<0) on=getenv("MOTE_GTA_DEBUG")?1:0;
      if(on) fprintf(stderr,"[BB] pre-trees used=%d/%d\n", g_bb_used, MAX_BILLBOARDS); }
#endif
    /* scenery LAST — trees drawn over everyone passing beneath. Upright billboards now
     * (Task 9), not flat canopies: a tree lying flat read as a green disc from any
     * angle but straight down. The hash still only ever picks column 0 or 1 of the
     * sheet (oak / pine); scenery.png also carries autumn/bush/flowers/boulder cells
     * for future use, but the selection below is unchanged from before this task.
     *
     * bb_add's view-cone test (VIEW_GROUND_R, tile_m~2m for a canopy) does most of
     * the culling. The scan itself walks OUTWARD in Chebyshev rings from the camera
     * tile, rather than a plain top-left-to-bottom-right raster, and bails once the
     * billboard budget (MAX_BILLBOARDS) is gone: if the pool does run dry, the trees
     * that get dropped are the far ones, not whichever the raster order happened to
     * reach first. Peds/pickups/markers are drawn earlier and so get first claim on
     * the pool; trees are the last billboard consumer this frame. */
    { int cx=(int)(view_x/TILE), cz=(int)(view_z/TILE);
      for (int r=0; r<=11 && g_bb_used<MAX_BILLBOARDS; r++){
          for (int dz=-r; dz<=r; dz++) for (int dx=-r; dx<=r; dx++){
              if (r>0 && dx!=-r && dx!=r && dz!=-r && dz!=r) continue;   /* interior: visited at a smaller r */
              int x=cx+dx, z=cz+dz;
              if (tile_at(x,z)!=' ') continue;
              unsigned h=(unsigned)(x*668265263u ^ z*374761393u); if ((h&3)==0) continue;
              float tx=x*TILE+((h>>4)&7)*0.4f+1.0f, tz=z*TILE+((h>>8)&7)*0.4f+1.0f;
              /* Palms on the beaches: any park tile that touches water gets the
               * palm cell instead of an oak, and stands taller. The test is the
               * four neighbours of a tile we are already visiting, so it costs
               * four tile_at() calls on park tiles only — no table, no extra
               * pass, and nothing stored. */
              int shore = tile_at(x+1,z)=='~' || tile_at(x-1,z)=='~'
                       || tile_at(x,z+1)=='~' || tile_at(x,z-1)=='~';
              int cell  = shore ? SCEN_PALM : (int)((h>>2)&1);
              float ht  = shore ? 7.0f : 5.5f;
              draw_upright(&scenery_img, tx, tz, cell*20, 0, 20, 20, ht, VIEW_GROUND_R, 2.0f);
          }
      } }
    /* bullet tracers: depth-tested 3D lines (Task 9), not overlay draw_line — so a
     * tracer fired past a building's corner is actually occluded by it. */
    for (int i=0;i<NBULLET;i++){ Bullet*b=&bullets[i]; if(!b->alive) continue;
        mote->scene_add_line(v3(b->x, 0.9f, b->z),
                             v3(b->x - b->vx*0.03f, 0.9f, b->z - b->vz*0.03f),
                             b->fromcop ? MOTE_RGB565(120,180,255) : MOTE_RGB565(255,230,140));
    }
#ifdef MOTE_HOST
    /* billboard-budget evidence: MOTE_GTA_DEBUG logs this frame's count, the
     * running peak, and how many submissions this frame were IN VIEW but
     * dropped for lack of a slot (as opposed to the much more common
     * frustum/radius rejection in bb_add) — so "is 48 enough" is a measured
     * answer, and if it ever isn't, this says so instead of guessing. */
    if (getenv("MOTE_GTA_DEBUG")) {
        static int peak=0; if (g_bb_used>peak) peak=g_bb_used;
        fprintf(stderr,"[BB] used=%d/%d peak=%d dropped=%d\n",
                g_bb_used, MAX_BILLBOARDS, peak, g_bb_budget_drop);
    }
#endif
}

/* -------------------------------------------------------------- overlay ----- */
/* small helper: project a world point + draw a filled screen dot */
static void world_dot(uint16_t *fb, float wx, float wz, int r, uint16_t col) {
    float sx, sy; if (!world_to_screen(v3(wx,0.1f,wz), &sx, &sy, 0)) return;
    if (sx<-4||sx>132||sy<8||sy>128) return;
    mote->draw_circle(fb, (int)sx, (int)sy, r, col, 1, 0, 128);
}
/* A HOLLOW 2px ring around a world point — highlights a sprite (phonebox, mark, VIP)
 * without covering it, unlike a filled dot. */
static void world_ring(uint16_t *fb, float wx, float wz, int r, uint16_t col) {
    float sx, sy; if (!world_to_screen(v3(wx,0.1f,wz), &sx, &sy, 0)) return;
    if (sx<-8||sx>136||sy<4||sy>132) return;
    mote->draw_circle(fb, (int)sx, (int)sy, r,   col, 0, 0, 128);
    mote->draw_circle(fb, (int)sx, (int)sy, r-1, col, 0, 0, 128);
}
/* A filled arrowhead at (cx,cy) pointing along screen angle `ang` — edge pointer to
 * an off-screen objective. Rasterised as perpendicular spans from tip to tail. */
/* A small, slim, SOLID filled arrowhead (scanline-fill of the triangle, so no gaps). */
static void draw_arrow(uint16_t *fb, float cx, float cy, float ang, uint16_t col){
    float dx=cosf(ang), dy=sinf(ang), px=-dy, py=dx;
    float Tx=cx+dx*5.5f,          Ty=cy+dy*5.5f;                 /* tip */
    float B1x=cx-dx*3.5f+px*3.5f, B1y=cy-dy*3.5f+py*3.5f;        /* tail corners (slim) */
    float B2x=cx-dx*3.5f-px*3.5f, B2y=cy-dy*3.5f-py*3.5f;
    int minx=(int)floorf(fminf(Tx,fminf(B1x,B2x))), maxx=(int)ceilf(fmaxf(Tx,fmaxf(B1x,B2x)));
    int miny=(int)floorf(fminf(Ty,fminf(B1y,B2y))), maxy=(int)ceilf(fmaxf(Ty,fmaxf(B1y,B2y)));
    for (int y=miny;y<=maxy;y++) for (int x=minx;x<=maxx;x++){
        float fx=(float)x+0.5f, fy=(float)y+0.5f;               /* inside-triangle edge test */
        float d1=(fx-B1x)*(Ty-B1y)-(Tx-B1x)*(fy-B1y);
        float d2=(fx-Tx )*(B2y-Ty )-(B2x-Tx )*(fy-Ty );
        float d3=(fx-B2x)*(B1y-B2y)-(B1x-B2x)*(fy-B2y);
        int neg=(d1<0)||(d2<0)||(d3<0), pos=(d1>0)||(d2>0)||(d3>0);
        if (!(neg&&pos)) mote->draw_pixel(fb, x, y, col);
    }
}

/* Where does a world point belong on screen — and if it is not on screen, which
 * edge does it point to?
 *
 * Returns 1 when the point projects normally (sx, sy are its screen position).
 * Returns 0 when it is behind the camera or off the edge; sx/sy are then
 * clamped to the screen border and `ang` is the direction to draw an arrow.
 *
 * The behind-camera case cannot use the projection at all — it failed, and
 * world_to_screen does not write its outputs on failure — so the bearing
 * comes from the world-space angle between the camera forward and the
 * direction to the point. */
static int screen_or_edge(float wx, float wz, float *sx, float *sy, float *ang) {
    if (world_to_screen(v3(wx, 0.6f, wz), sx, sy, 0) &&
        *sx > 4 && *sx < 124 && *sy > 4 && *sy < 124) {
        *ang = 0.0f;
        return 1;
    }
    /* World-space bearing, relative to where the camera looks. */
    float dx = wx - cam_pos.x, dz = wz - cam_pos.z;
    float fwd_a = atan2f(cam_basis.r[2].z, cam_basis.r[2].x);
    float rel = gta3_wrap_angle(atan2f(dz, dx) - fwd_a);
    /* rel = 0 straight ahead, +/-pi behind. Screen up is ahead.
     * rel is expressed in the game's own yaw convention, where "driver's
     * right" is (-sin(yaw), cos(yaw)) (see the rx/rz comment at game.c:835).
     * cam_basis.r[0] (what world_to_screen actually projects against) is
     * cross((0,1,0), forward) instead, which points the other way — so the
     * screen-x offset here needs the opposite sign of what a naive sin(rel)
     * would give, to agree with what world_to_screen would have produced. */
    float ex = -sinf(rel), ey = -cosf(rel);
    float k = 54.0f / (fabsf(ex) > fabsf(ey) ? fabsf(ex) : fabsf(ey));
    *sx = 64.0f + ex * k;
    *sy = 64.0f + ey * k;
    /* draw_arrow wants a SCREEN angle (dx=cosf(ang), dy=sinf(ang) straight into
     * framebuffer coords), not the world bearing `rel`. Derive it from the same
     * ex/ey used for position, so the arrow's rotation and its position agree. */
    *ang = atan2f(ey, ex);
    return 0;
}

static uint16_t map_color(char c){
    switch(c){
        case '.': return MOTE_RGB565(70,70,78);    case 'B': return MOTE_RGB565(120,92,64);
        case ',': return MOTE_RGB565(142,140,128); case ' ': return MOTE_RGB565(94,130,51);
        case '~': return MOTE_RGB565(58,150,168);  case '#': return MOTE_RGB565(150,80,70);
        case 'O': return MOTE_RGB565(100,110,130); default:  return MOTE_RGB565(118,118,128);
    }
}
/* full city map at 1px/tile, scrollable; the player is a flashing dot. */
static void draw_map(uint16_t *fb){
    for (int py=0; py<128; py++){ int tz=g_mapsy+py;
        for (int px=0; px<128; px++) fb[py*128+px]=map_color(tile_at(g_mapsx+px, tz)); }
    /* shops / phones */
    for (int i=0;i<nmark;i++){
        if (!markers[i].seen) continue;                   /* only what you've discovered */
        int sx=(int)(markers[i].x/TILE)-g_mapsx, sy=(int)(markers[i].z/TILE)-g_mapsy;
        if (sx<1||sx>126||sy<1||sy>126) continue;
        uint16_t col=markers[i].kind==MK_GUN?MOTE_RGB565(230,200,60):
                     markers[i].kind==MK_SPRAY?MOTE_RGB565(80,200,120):
                     markers[i].kind==MK_DOCK?MOTE_RGB565(235,150,60):MOTE_RGB565(80,160,240);
        mote->draw_rect(fb, sx-1, sy-1, 3, 3, col, 1, 0, 128);
    }
    for (int i=0;i<NPICK;i++){ Pickup*p2=&picks[i];      /* discovered caches: small white dots */
        if (!p2->alive || !p2->seen) continue;
        int sx=(int)(p2->x/TILE)-g_mapsx, sy=(int)(p2->z/TILE)-g_mapsy;
        if (sx<1||sx>126||sy<1||sy>126) continue;
        mote->draw_rect(fb, sx, sy, 2, 2, MOTE_RGB565(235,235,245), 1, 0, 128);
    }
    if (mission_beacon()){                                       /* the JOB target: unmistakable */
        int sx=(int)(mx/TILE)-g_mapsx, sy=(int)(mz/TILE)-g_mapsy;
        if (sx<8) sx=8; if (sx>119) sx=119; if (sy<16) sy=16; if (sy>112) sy=112;   /* clamp: always on-map */
        uint16_t mc=MOTE_RGB565(255,60,200);                     /* magenta — no shop marker uses it */
        int ph=((int)(g_maptime*4.0f))&1;
        mote->draw_circle(fb, sx, sy, ph?6:4, mc, 0, 0, 128);    /* pulsing target ring */
        mote->draw_rect(fb, sx-7, sy, 5,1, mc,1,0,128); mote->draw_rect(fb, sx+3, sy, 5,1, mc,1,0,128);
        mote->draw_rect(fb, sx, sy-7, 1,5, mc,1,0,128); mote->draw_rect(fb, sx, sy+3, 1,5, mc,1,0,128);  /* crosshair */
        mote->draw_rect(fb, sx-1, sy-1, 3,3, mc,1,0,128);
        mote->draw_rect(fb, sx, sy, 1,1, MOTE_RGB565(255,255,255),1,0,128); }
    if (mission==MI_RIVAL && rival_car>=0 && cars[rival_car].alive){   /* the rival: a red blip on the map */
        int sx=(int)(cars[rival_car].x/TILE)-g_mapsx, sy=(int)(cars[rival_car].z/TILE)-g_mapsy;
        if (sx>=1&&sx<=126&&sy>=1&&sy<=126) mote->draw_rect(fb, sx-1, sy-1, 3,3, MOTE_RGB565(240,60,50), 1,0,128); }
    if (g_dm && rp_hp>0){                              /* the OPPONENT: flashing red.
        CLAMPED to the window edge when they're outside the panned view, so the
        map always points the hunt in the right direction. */
        int rsx=(int)(rp_x/TILE)-g_mapsx, rsy=(int)(rp_z/TILE)-g_mapsy;
        int off = rsx<3||rsx>124||rsy<14||rsy>113;
        if (rsx<3) rsx=3; if (rsx>124) rsx=124;
        if (rsy<14) rsy=14; if (rsy>113) rsy=113;      /* clear of the header/footer */
        uint16_t rc = (((int)(g_maptime*5.0f))&1) ? MOTE_RGB565(255,70,60) : MOTE_RGB565(150,26,20);
        mote->draw_circle(fb, rsx, rsy, 2, rc, 1, 0, 128);
        mote->draw_circle(fb, rsx, rsy, 3, off?MOTE_RGB565(255,160,150):MOTE_RGB565(255,220,220), 0, 0, 128);
    }
    /* player: flashing dot */
    int psx=(int)(pl_x()/TILE)-g_mapsx, psy=(int)(pl_z()/TILE)-g_mapsy;
    if (psx>=-2&&psx<130&&psy>=-2&&psy<130){
        uint16_t col = (((int)(g_maptime*4.0f))&1) ? MOTE_RGB565(255,240,80) : MOTE_RGB565(230,50,50);
        mote->draw_circle(fb, psx, psy, 2, col, 1, 0, 128);
        mote->draw_circle(fb, psx, psy, 3, MOTE_RGB565(20,20,26), 0, 0, 128);
    }
    mote_ui_panel(fb, 0, 0, 128, 11, MOTE_RGB565(14,16,24), MOTE_RGB565(60,70,110));
    mote_ftext(mote, fb, g_fmed, "CITY MAP", 3, 1, MOTE_RGB565(240,230,120));
    /* two lines now, so the pair sits one line-height apart ending where the single
     * line used to: 118 is the lowest that clears the bottom edge at 1.5x. */
    mote_ftextc(mote, fb, g_fmed, 64, 106, MOTE_RGB565(150,160,180), "MENU CLOSE    DPAD PAN");
    mote_ftextc(mote, fb, g_fmed, 64, 118, MOTE_RGB565(150,160,180), "RB  SETTINGS");
}

/* The SETTINGS tab of the pause screen. Same framing as the map — a title
 * panel at the top and the control hints on the bottom two lines — so the two
 * tabs read as one screen you flip between rather than two different menus.
 *
 * Toggles show their state on the right; actions do not. The selected row gets
 * a filled bar rather than just a bright colour, which stays legible over the
 * dimmed city behind it. */
/* The CONTROLS page. Rows use the built-in 3x5 font rather than the 1.5x UI
 * font: twelve lines have to fit under a title bar on a 128 px panel, and at
 * the larger size they do not. Two columns — button, then what it does — with
 * the button column in a brighter colour so the list scans down the left. */
static void draw_controls(uint16_t *fb) {
    mote_dim_box(fb, 0, 0, 128, 128, 4);
    mote_ui_panel(fb, 0, 0, 128, 11, MOTE_RGB565(14,16,24), MOTE_RGB565(60,70,110));
    mote_ftext(mote, fb, g_fmed, "CONTROLS", 3, 1, MOTE_RGB565(240,230,120));

    static const char *ROW[][2] = {
        { "",     "ON FOOT"          },
        { "DPAD", "MOVE / TURN"      },
        { "A",    "RUN (HOLD)"       },
        { "B",    "ATTACK"           },
        { "RB",   "ENTER / WEAPON"   },
        { "LB",   "LOOK BACK"        },
        { "",     "IN CAR"           },
        { "DPAD", "STEER"            },
        { "A",    "GAS"              },
        { "B",    "BRAKE / REVERSE"  },
        { "LB",   "FIRE"             },
        { "RB",   "GET OUT"          },
        { "",     "IN THE HELI"      },
        { "DPAD", "PITCH / YAW"      },
        { "A",    "CLIMB"            },
        { "B",    "DESCEND"          },
        { "RB",   "GET OUT (LANDED)" },
        { "",     "ANYWHERE"         },
        { "MENU", "MAP / SETTINGS"   },
    };
    const uint16_t HEAD = MOTE_RGB565(240,200,110);
    const uint16_t KEY  = MOTE_RGB565(160,210,250);
    const uint16_t TXT  = MOTE_RGB565(206,212,226);
    int y = 15;
    for (unsigned i = 0; i < sizeof ROW / sizeof ROW[0]; i++) {
        if (ROW[i][0][0] == 0) {                       /* section heading */
            y += (i ? 3 : 0);
            mote->text(fb, ROW[i][1], 6, y, HEAD);
        } else {
            mote->text(fb, ROW[i][0], 10, y, KEY);
            mote->text(fb, ROW[i][1], 42, y, TXT);
        }
        y += 7;
    }
    mote_ftextc(mote, fb, g_fmed, 64, 118, MOTE_RGB565(150,160,180), "ANY BUTTON: BACK");
}

static void draw_settings(uint16_t *fb) {
    mote_dim_box(fb, 0, 0, 128, 128, 5);                  /* the city stays faintly visible */
    mote_ui_panel(fb, 0, 0, 128, 11, MOTE_RGB565(14,16,24), MOTE_RGB565(60,70,110));
    mote_ftext(mote, fb, g_fmed, "SETTINGS", 3, 1, MOTE_RGB565(240,230,120));

    /* "BRING HELI" and "BRING TANK" are the temporary debug rows — see the
     * SET_HELI comment. Rows are 11 px apart, not the original 16: seven of
     * them at 16 would run off the bottom of the panel, and at 12 the last
     * highlight overlaps the result message at y = 94. */
    static const char *NAME[SET_N] = { "MINIMAP", "SOUND", "CONTROLS", "BRING HELI",
                                       "BRING TANK", "SAVE GAME", "LOAD GAME" };
    for (int i = 0; i < SET_N; i++) {
        int y = 19 + i * 11;
        int sel = (i == g_setsel);
        if (sel) mote->draw_rect(fb, 6, y - 3, 116, 14, MOTE_RGB565(46,56,86), 1, 0, 128);
        uint16_t fg = sel ? MOTE_RGB565(250,244,200) : MOTE_RGB565(168,176,196);
        mote_ftext(mote, fb, g_fmed, NAME[i], 12, y, fg);
        const char *val = (i == SET_MINIMAP) ? (g_radar_on ? "ON" : "OFF")
                        : (i == SET_SOUND)   ? (g_sound_on ? "ON" : "OFF") : 0;
        if (val) {
            uint16_t vc = (val[1] == 'N') ? MOTE_RGB565(140,230,140) : MOTE_RGB565(200,120,120);
            mote_ftext(mote, fb, g_fmed, val, 92, y, vc);
        } else if (i == SET_SAVE || i == SET_LOAD) {
            /* The slot number, and a dot when that slot already holds a game.
             * load(slot, 0, 0) returns the stored length, so this is the same
             * question the loader asks, not a second record of it. */
            int used = (mote->load && mote->load(1 + g_slot, 0, 0) > 0);
            char sb[6]; sb[0] = (char)('1' + g_slot); sb[1] = used ? ' ' : 0;
            sb[2] = used ? '*' : 0; sb[3] = 0;
            mote_ftext(mote, fb, g_fmed, sb, 92, y,
                       used ? MOTE_RGB565(235,238,245) : MOTE_RGB565(120,128,146));
        }
    }
    if (g_setmsg && g_setmsg_t > 0.0f)
        mote_ftextc(mote, fb, g_fmed, 64, 99, MOTE_RGB565(250,230,120), g_setmsg);

    mote_ftextc(mote, fb, g_fmed, 64, 109, MOTE_RGB565(150,160,180), "UP/DN PICK  L/R SET");
    mote_ftextc(mote, fb, g_fmed, 64, 119, MOTE_RGB565(150,160,180), "LB  MAP     MENU CLOSE");
}

/* DEBUG: outline every 2D physics body (green = vehicle OBB, orange = static building/tree)
 * exactly where the collider is, so the boxes can be compared with the drawn cars. Toggle
 * on the host with MOTE_GTA_BOXES=1; on device with a MENU+RB hold (g_showboxes). */
static int g_showboxes = 0;   /* OFF in-game; host debug toggle via MOTE_GTA_BOXES=1 */
static void draw_phys_boxes(uint16_t *fb){
    for (int i=0;i<g_nbodies;i++){ MoteBody2D*b=&bodies[i];
        if (i<NCAR && !cars[i].alive) continue;
        uint16_t col = (i<NCAR)? MOTE_RGB565(0,255,0) : MOTE_RGB565(255,90,0);
        if (b->shape==MOTE_C2D_CIRCLE){
            float sx,sy,ppm; if(!world_to_screen(v3(b->x,0.1f,b->y),&sx,&sy,&ppm)) continue;
            mote->draw_circle(fb,(int)sx,(int)sy,(int)(b->radius*ppm),col,0,0,128);
        } else {
            float ca=cosf(b->angle), sa=sinf(b->angle);
            float lx[4]={ b->hx, b->hx,-b->hx,-b->hx}, ly[4]={ b->hy,-b->hy,-b->hy, b->hy};
            int X[4],Y[4],ok=1;
            for(int k=0;k<4;k++){ float wx=b->x+lx[k]*ca-ly[k]*sa, wz=b->y+lx[k]*sa+ly[k]*ca, sx,sy;
                if(!world_to_screen(v3(wx,0.1f,wz),&sx,&sy,0)){ok=0;break;} X[k]=(int)sx;Y[k]=(int)sy; }
            if(!ok) continue;
            for(int k=0;k<4;k++){ int n=(k+1)&3; mote->draw_line(fb,X[k],Y[k],X[n],Y[n],col,0,128); }
        }
    }
}

/* A live radar, rotated so up is where the camera looks.
 *
 * Top-down, the street grid ahead was simply visible in the play view. Behind a
 * car at 3 m it is not, and the missions route across the city. The MENU map
 * still exists for planning; this is for driving.
 *
 * 40 px across, bottom-left, sampling the tile map on a coarse step — fine
 * enough to show which way a street runs, cheap enough to run every frame.
 *
 * Rotation: derived from the engine's own camera basis, NOT the game's
 * "driver's right" vocabulary (-sin(yaw), cos(yaw)) — see the note at
 * screen_or_edge (game.c:4489), which hit exactly this mismatch for the
 * off-screen mission arrow. mote_camera_look sets r[2]=forward and
 * r[0]=cross((0,1,0), forward); for forward=(cos a, 0, sin a) that gives
 * r[0]=(sin a, 0, -cos a) as the camera's REAL right.
 *
 * World offset (dx,dz) from the player -> radar offset (rx,ry), screen-style
 * (y down), derived so "ahead" -> top (rx=0,ry<0) and "real right" -> right
 * (rx>0,ry=0):
 *   rx = (dx*sa - dz*ca) / RADAR_M
 *   ry = -(dx*ca + dz*sa) / RADAR_M
 * Check: dead ahead is dx=cos a,dz=sin a -> rx=0, ry=-1/RADAR_M (top). Real
 * right is dx=sin a,dz=-cos a -> rx=1/RADAR_M (right), ry=0. Both correct.
 *
 * That 2x2 matrix is its own inverse (it's an orthogonal reflection: N^2=I),
 * so radar-pixel -> world drops out algebraically to the same coefficients
 * with (px,py) and (dx,dz) swapped:
 *   wx = pl_x() + RADAR_M*(px*sa - py*ca)
 *   wz = pl_z() - RADAR_M*(px*ca + py*sa)
 * (This is a property of this particular rotation, not a shortcut taken on
 * faith — the brief's version used the SAME matrix in both directions, which
 * is wrong in general; it only happens to be right here because N is its own
 * inverse. Verified both directions round-trip: feeding a radar (10,0) back
 * through the marker formula returns (10,0).) */
#define RADAR_X   4
#define RADAR_Y   14   /* NOT 84: that placement (x 3..45, y 83..125) sat directly under the
                        * on-foot prompt line (centred x=64, y=102..108, wide enough to run
                        * under the disc) and over the health bar (x2..42,y116..122) / weapon
                        * label (x60,y115), and draw_radar is called last in g_overlay so it
                        * painted over both. y=14 tucks it just under the top HUD panel
                        * (y0..11) so it eats as little of the view as possible, and still
                        * clears the prompt line and the health bar / weapon label. It can
                        * also be hidden outright — RB on the map screen toggles g_radar_on. */
#define RADAR_R   20
#define RADAR_M   2.6f        /* world metres per radar pixel */
static void draw_radar(uint16_t *fb) {
    int cx = RADAR_X + RADAR_R, cy = RADAR_Y + RADAR_R;
    float a = atan2f(cam_basis.r[2].z, cam_basis.r[2].x);
    float ca = cosf(a), sa = sinf(a);

    mote->draw_circle(fb, cx, cy, RADAR_R + 1, MOTE_RGB565(16,18,24), 1, 0, 128);
    for (int py = -RADAR_R; py <= RADAR_R; py++)
        for (int px = -RADAR_R; px <= RADAR_R; px++) {
            if (px*px + py*py > RADAR_R*RADAR_R) continue;
            /* radar pixel -> world */
            float wx = pl_x() + RADAR_M*(px*sa - py*ca);
            float wz = pl_z() - RADAR_M*(px*ca + py*sa);
            char c = tile_at((int)floorf(wx/TILE), (int)floorf(wz/TILE));
            uint16_t col;
            if (c=='.'||c=='B') col = MOTE_RGB565(120,124,136);
            else if (c=='~')    col = MOTE_RGB565(30,44,86);
            else if (c==','||c==' ') col = MOTE_RGB565(58,62,72);
            else                col = MOTE_RGB565(38,40,50);
            mote->draw_pixel(fb, cx + px, cy + py, col);
        }

    /* mission markers, then wanted cops on top of them */
    for (int m = 0; m < nmark; m++) {
        float dx = markers[m].x - pl_x(), dz = markers[m].z - pl_z();
        float rx = (dx*sa - dz*ca) / RADAR_M, ry = -(dx*ca + dz*sa) / RADAR_M;
        if (rx*rx + ry*ry > RADAR_R*RADAR_R) continue;
        mote->draw_rect(fb, cx+(int)rx-1, cy+(int)ry-1, 3, 3,
                        MOTE_RGB565(240,200,80), 1, 0, 128);
    }
    if (wanted() > 0)
        for (int i = 0; i < NCAR; i++) {
            Car *c = &cars[i];
            if (!c->alive || c->driver != DRV_COP) continue;
            float dx = c->x - pl_x(), dz = c->z - pl_z();
            float rx = (dx*sa - dz*ca) / RADAR_M, ry = -(dx*ca + dz*sa) / RADAR_M;
            if (rx*rx + ry*ry > RADAR_R*RADAR_R) continue;
            mote->draw_rect(fb, cx+(int)rx-1, cy+(int)ry-1, 3, 3,
                            MOTE_RGB565(90,150,255), 1, 0, 128);
        }

    /* the player: always dead centre, always pointing up */
    mote->draw_pixel(fb, cx, cy, MOTE_RGB565(255,255,255));
    mote->draw_pixel(fb, cx, cy-1, MOTE_RGB565(255,255,255));
    mote->draw_pixel(fb, cx, cy-2, MOTE_RGB565(200,255,200));
}

/* Rain, drawn over the finished frame.
 *
 * Every streak is a hash of its index: a fixed column, its own fall speed and
 * its own length. The column drifts slowly sideways with the clock so the
 * field does not read as fixed vertical lanes, and y scrolls and wraps. That
 * makes the whole system stateless — no particle array, which matters because
 * GAME_RAM had under 4 KB spare.
 *
 * Streak COUNT scales with intensity, so drizzle and downpour differ in
 * density rather than only in colour, and the streaks lean the same way at all
 * times so it reads as wind-driven rather than as noise. */
static void draw_rain(uint16_t *fb) {
    if (g_wet < 0.05f) return;
    int n = (int)(g_wet * 74.0f);
    uint16_t col = MOTE_RGB565(158, 176, 206);
    float drift = g_wtime * 13.0f;
    for (int i = 0; i < n; i++) {
        unsigned h = ((unsigned)i * 2654435761u) ^ 0x9e3779b9u;
        int spd = 150 + (int)((h >> 8) & 63);                 /* px/s, varied per streak */
        int x   = (int)((float)(h % MOTE_FB_W) + drift) % MOTE_FB_W;
        int y   = (int)(g_wtime * (float)spd + (float)((h >> 16) % 128)) % 128;
        int len = 4 + (int)((h >> 22) & 3);
        mote->draw_line(fb, x, y, x - 2, y + len, col, 0, MOTE_FB_H);
    }
    /* The flash washes the ground too, not just the sky the palette already
     * lit, so a strike reads as lighting the street rather than a sky effect.
     *
     * NOT mote_dim_box with keep16 > 16: it does r*keep16>>4 with no clamp, so
     * a channel at 31 lands on 38 and bleeds into the next field — a brighten
     * that corrupts colour. This lifts each channel toward white and clamps. */
    if (g_flash > 0.35f) {
        int lift = (int)(g_flash * 6.0f);
        for (int j = 0; j < MOTE_FB_H; j++)
            for (int i = 0; i < MOTE_FB_W; i++) {
                uint16_t c = fb[j*MOTE_FB_W+i];
                int r=(c>>11)&31, g=(c>>5)&63, b=c&31;
                r += lift;      if (r > 31) r = 31;
                g += lift*2;    if (g > 63) g = 63;
                b += lift;      if (b > 31) b = 31;
                fb[j*MOTE_FB_W+i] = (uint16_t)((r<<11)|(g<<5)|b);
            }
    }
}

static void g_overlay(uint16_t *fb) {
    if (g_showmap){ if (g_ctlpage) draw_controls(fb);
                    else if (g_menutab == TAB_SET) draw_settings(fb);
                    else draw_map(fb); return; }
    if (g_state==ST_DMLINK){
        mote_ui_panel(fb, 12, 36, 104, 58, MOTE_RGB565(14,16,24), MOTE_RGB565(160,60,50));
        mote_ftextc(mote, fb, g_fread, 64, 40, MOTE_RGB565(245,110,95), "DEATHMATCH");
        if (dm_phase==1){                                   /* streaming the shared city */
            int done = dm_my_nonce>dm_peer_nonce ? dm_map_pos : dm_map_recv;
            int pct = done*100/CITY_BYTES; if(pct>100)pct=100;
            mote_ftextc(mote, fb, g_fmed, 64, 56, MOTE_RGB565(245,230,90), "SYNCING CITY");
            mote->draw_rect(fb, 24, 70, 80, 6, MOTE_RGB565(60,60,80), 0, 0,128);
            mote->draw_rect(fb, 25, 71, 78*pct/100, 4, MOTE_RGB565(120,230,120), 1, 0,128);
        } else if (mote->link_status()==MOTE_LINK_CONNECTED)
            mote_ftextc(mote, fb, g_fmed, 64, 56, MOTE_RGB565(120,230,120), "WAITING FOR PEER");
        else {
            mote_ftextc(mote, fb, g_fmed, 64, 54, MOTE_RGB565(235,238,245), "CONNECT USB CABLE");
            mote_ftextc(mote, fb, g_fmed, 64, 66, MOTE_RGB565(150,160,180), "OR STUDIO LINK");
        }
        { static float t2; t2+=0.033f; int dots=((int)(t2*3))%4;
          if (dm_phase!=1) for (int i2=0;i2<dots;i2++) mote->draw_rect(fb,56+i2*6,78,3,3,MOTE_RGB565(245,230,90),1,0,128); }
        mote_ftextc(mote, fb, g_fmed, 64, 84, MOTE_RGB565(150,160,180), "B CANCEL");
        return;
    }
    /* markers are drawn as prop sprites in the scene pass now (phonebox/gun mat/spray) */
    if (g_state==ST_PLAY && mission_beacon()){   /* target: beating ring if on-screen, else an edge ARROW pointing to it */
        uint16_t mc = MOTE_RGB565(255,70,200);
        float sx, sy, ang;
        if (screen_or_edge(mx, mz, &sx, &sy, &ang)){
            int ph=((int)(mote->micros()/200000ull))&1;
            world_ring(fb, mx, mz, ph?10:8, mc);
        } else {                                  /* off-screen: edge arrow, steady (no flashing) */
            draw_arrow(fb, sx, sy, ang, mc);
        } }
    if (g_state==ST_PLAY && mission==MI_NONE){   /* looking for work: beating ring on every phone box */
        int ph=((int)(mote->micros()/240000ull))&1;
        for (int m=0;m<nmark;m++){ if (markers[m].kind!=MK_PHONE) continue;
            float dx=markers[m].x-view_x, dz=markers[m].z-view_z; if (dx*dx+dz*dz>2500.0f) continue;
            world_ring(fb, markers[m].x, markers[m].z, ph?7:6, MOTE_RGB565(120,200,255)); } }

    /* trees, pickups, people and vehicles are drawn as depth-tested billboards/ground
     * quads/meshes in the scene pass; only the on-foot PLAYER and the PK_PACKAGE crate
     * marker (no atlas cell) stay overlay drawing. */
    for (int i=0;i<NPICK;i++){ Pickup*p=&picks[i]; if(!p->alive||p->kind!=PK_PACKAGE) continue;
        world_dot(fb, p->x, p->z, 4, MOTE_RGB565(28,20,10));
        world_dot(fb, p->x, p->z, 3, MOTE_RGB565(196,150,78));
        world_dot(fb, p->x, p->z, 1, MOTE_RGB565(120,86,40)); }
    /* police LIGHTBAR: alternating red/blue strobes on active squad cars */
    { int phase = (int)(mote->micros()/200000u)&1;
      for (int i=0;i<NCAR;i++){ Car*c=&cars[i];
        if (!c->alive || c->driver!=DRV_COP || wanted()==0) continue;   /* patrols run dark */
        float fxh=cosf(c->yaw), fzh=sinf(c->yaw), rxh=-fzh, rzh=fxh;
        float lx=c->x+fxh*0.35f, lz=c->z+fzh*0.35f;   /* the bar sits just ahead of centre */
        float ax,ay,bx2,by2;
        if (world_to_screen(v3(lx+rxh*0.55f,0.8f,lz+rzh*0.55f),&ax,&ay,0) &&
            world_to_screen(v3(lx-rxh*0.55f,0.8f,lz-rzh*0.55f),&bx2,&by2,0)){
            mote->draw_rect(fb,(int)ax-1,(int)ay-1,2,2, phase?MOTE_RGB565(255,60,50):MOTE_RGB565(70,110,255),1,0,128);
            mote->draw_rect(fb,(int)bx2-1,(int)by2-1,2,2, phase?MOTE_RGB565(70,110,255):MOTE_RGB565(255,60,50),1,0,128);
        } } }
    /* floating score popups (rise + fade) */
    for (int i=0;i<6;i++){ FloatTxt*ft=&g_ftxt[i]; if(ft->t<=0) continue;
        float sx,sy; if(!world_to_screen(v3(ft->x,0.2f,ft->z),&sx,&sy,0)) continue;
        sy -= (1.1f-ft->t)*14.0f;
        mote->text(fb, ft->txt, (int)sx-8, (int)sy, ft->t>0.35f?MOTE_RGB565(250,230,90):MOTE_RGB565(150,140,70)); }
#ifdef MOTE_HOST
    { static int e=-1; if(e<0) e=getenv("MOTE_GTA_BOXES")?1:0; if(e) g_showboxes=1; }
#endif
    if (g_showboxes) draw_phys_boxes(fb);

    /* bullet tracers are added as depth-tested scene lines in the 3D build now
     * (Task 9) — see the loop near draw_upright's scenery pass in g_update —
     * so they disappear behind buildings instead of painting over them here. */
    for (int i=0;i<NFX;i++){ Fx*f=&fxs[i]; if(f->t<=0) continue;
        if (f->kind==3){                                        /* smoke: grey puff that grows + fades */
            uint16_t g = f->t>0.5f?MOTE_RGB565(120,120,128):MOTE_RGB565(78,78,88);
            world_dot(fb, f->x, f->z, 1+(int)((0.9f-f->t)*4.0f), g); continue; }
        if (f->kind==4){                                        /* flame: flickering orange/yellow */
            world_dot(fb, f->x, f->z, 2, (((int)(f->t*20))&1)?MOTE_RGB565(255,150,40):MOTE_RGB565(255,220,90)); continue; }
        uint16_t c = f->kind==0?MOTE_RGB565(170,20,24) : f->kind==1?MOTE_RGB565(250,180,60) : MOTE_RGB565(255,244,180);
        world_dot(fb, f->x, f->z, f->kind==2?3:2, c); }

    if (g_brief_active){
        mote_dim_box(fb, 0, 0, 128, 128, 7);                       /* translucent — the city stays visible */
        draw_portrait(fb, 44, 12, g_brief_seed);                   /* the contact's mugshot */
        char l1[28], l2[28], l3[28];
        mote_dim_box(fb, 3, 44, 122, 82, 5);
        /* a returning contact reads as CALLING BACK (streak) rather than a cold call */
        if (mission_chain>0) mote_ftextc (mote, fb, g_fmed, 64, 2, MOTE_RGB565(120,210,255), "CALLING BACK");
        else                 mote_ftextc (mote, fb, g_fmed, 64, 2, MOTE_RGB565(150,200,240), "INCOMING CALL");
        mote_ftextc (mote, fb, g_fmed, 64, 60, MOTE_RGB565(236,238,245), g_brief_name);
        mote_ftextfc(mote, fb, g_fmed, 64, 71, MOTE_RGB565(244,204,72), "%s   $%d", g_brief_role, mission_pay);
        mote->draw_rect(fb, 14, 83, 100, 1, MOTE_RGB565(120,96,40), 1, 0, 128);
        wrap3(g_fread, g_brief_body, 118, l1, l2, l3, 28);
        int nl = l3[0]?3 : l2[0]?2 : 1;
        int by = nl==3?84 : nl==2?90 : 96;
        uint16_t bc=MOTE_RGB565(232,234,240);
        mote_ftextc(mote, fb, g_fread, 64, by, bc, l1);
        if (l2[0]) mote_ftextc(mote, fb, g_fread, 64, by+12, bc, l2);
        if (l3[0]) mote_ftextc(mote, fb, g_fread, 64, by+24, bc, l3);
        mote_ftextc(mote, fb, g_fmed, 64, 118, MOTE_RGB565(150,230,150), "A ACCEPT    B DECLINE");
        return;
    }
    if (g_state==ST_TITLE){
        /* big serif logo straight over the live city, GTA1-style: black drop shadow,
         * warm gold face, thin underline — no boxed-in panel */
        if (mote->text_font){                                    /* logo moved up to free the lower half */
            /* GRAND THUMB / AUTO III, each centred on its own line.
             *
             * The x values used to be hand-measured constants ("THUMBAUTO
             * measures 97 px from x=7"), which is a number that silently stops
             * being true if the font is ever re-baked at another size. The
             * MoteFont struct carries each glyph's pen advance, so title_w()
             * sums the real widths and both lines centre themselves. */
            title_line(fb, "GRAND THUMB", 18);
            title_line(fb, "AUTO III",    38);
        } else {
            /* The 3x5 built-in advances MOTE_FONT_CELL_W (4) per glyph, so 8 at
             * 2x: 11 chars = 88 px and 8 chars = 64 px, both centred on 128. */
            mote->text_2x(fb, "GRAND THUMB", (MOTE_FB_W - 11*8)/2, 24, MOTE_RGB565(240,210,80));
            mote->text_2x(fb, "AUTO III",    (MOTE_FB_W -  8*8)/2, 40, MOTE_RGB565(240,210,80));
        }
        /* translucent dark banner so the body text pops over the live city, framed by
         * the gold rule on top (dim the real pixels — you can still see the road) */
        mote_dim_box(fb, 4, 67, 120, 54, 6);   /* keep 6/16 ≈ 38% */
        mote->draw_rect(fb, 10, 63, 108, 1, MOTE_RGB565(12,10,14), 1, 0, 128);
        mote->draw_rect(fb, 10, 62, 108, 1, MOTE_RGB565(244,204,72), 1, 0, 128);
        /* engine Audiowide (v47): CTA as a 1.66x banner, stats/labels at 1.5x */
        mote_ftextfc(mote, fb, g_fmed,  64, 71, MOTE_RGB565(235,238,245), "BEST $%d", best_cash);
        mote_ftextc (mote, fb, g_fread, 64, 87, MOTE_RGB565(150,230,150), "PRESS A TO PLAY");
        if (mote->abi_version>=44)
          mote_ftextc(mote, fb, g_fmed, 64, 107, MOTE_RGB565(245,110,95), "B  2P DEATHMATCH");
        return;
    }
    if (g_state==ST_WASTED || g_state==ST_BUSTED){
        uint16_t c = g_state==ST_WASTED?MOTE_RGB565(210,40,40):MOTE_RGB565(60,120,240);
        mote_dim_box(fb, 0, 40, 128, 52, 5);   /* readability over the frozen city */
        mote_ftextc (mote, fb, g_flarge, 64, 46, c, g_state==ST_WASTED?"WASTED":"BUSTED");
        mote_ftextfc(mote, fb, g_fmed, 64, 70, MOTE_RGB565(220,220,230), "CASH $%d", cash);
        mote_ftextfc(mote, fb, g_fmed, 64, 82, MOTE_RGB565(180,190,200), "KILLS %d", g_kills);
        return;
    }

    /* ---------------- HUD ---------------- */
    mote_ui_panel(fb, 0, 0, 128, 11, MOTE_RGB565(14,16,24), MOTE_RGB565(60,70,110));
    if (g_dm && g_state==ST_PLAY){
        if (dm_end){
            mote_ui_panel(fb, 16, 46, 96, 40, MOTE_RGB565(14,16,24), MOTE_RGB565(160,60,50));
            { const char *r = dm_end==1?"YOU WIN!":dm_end==2?"YOU LOSE!":"LINK LOST";
              mote_ftextc(mote, fb, g_fread, 64, 51, dm_end==1?MOTE_RGB565(120,230,120):MOTE_RGB565(245,110,95), r); }
            mote_ftextfc(mote, fb, g_fmed, 64, 64, MOTE_RGB565(235,238,245), "FRAGS %d-%d", dm_frags, dm_peer_frags);
            mote_ftextc (mote, fb, g_fmed, 64, 75, MOTE_RGB565(245,230,90), "B  TITLE");
        } else if (dm_dead_t>0){
            mote_ui_panel(fb, 32, 54, 64, 18, MOTE_RGB565(30,12,12), MOTE_RGB565(160,60,50));
            mote_ftextc(mote, fb, g_fread, 64, 58, MOTE_RGB565(245,110,95), "WASTED");
        }
    }
    if (g_dm) ftext_sh(g_fmed, fb, 3, 0, MOTE_RGB565(245,110,95), "FRAGS %d:%d", dm_frags, dm_peer_frags);
    else      ftext_sh(g_fmed, fb, 3, 0, MOTE_RGB565(120,230,120), "$%d", cash);
    /* wanted heads */
    for (int i=0;i<5;i++) mote->draw_circle(fb, 70+i*8, 5, 2, i<wanted()?MOTE_RGB565(250,210,70):MOTE_RGB565(50,54,64), 1, 0,128);
    draw_rain(fb);
    /* health bar */
    mote->draw_rect(fb, 2, 116, 40, 6, MOTE_RGB565(40,20,20), 1, 0,128);
    mote->draw_rect(fb, 2, 116, (int)(40*health/MAXHP), 6, MOTE_RGB565(210,60,60), 1, 0,128);
    /* Stamina: a thin strip under the health bar, shown ONLY when it is not
     * full. A permanent second bar would cost screen on a 128 px panel for
     * something that reads as "fine" almost all the time; appearing when you
     * start sprinting is the whole signal. Amber while it recovers, dim red
     * while the latch is holding you at a walk. */
    if (player.mode==MODE_CAR && player.car>=0) {
        /* DRIVING: the strip shows the CAR's condition instead of your stamina,
         * which you cannot spend from behind the wheel anyway. Without it the
         * only warning that a car is about to die is that it dies. Green down
         * to amber to red, and the tank is scaled by its own 600 hp so a full
         * tank reads full rather than pinned. */
        const Car *pc = &cars[player.car];
        float maxhp = (pc->type==VEH_TANK) ? 600.0f : 100.0f;
        float frac = mote_clampf(pc->hp / maxhp, 0.0f, 1.0f);
        uint16_t cc2 = frac > 0.55f ? MOTE_RGB565(90,200,110)
                     : frac > 0.25f ? MOTE_RGB565(230,180,60)
                                    : MOTE_RGB565(220,70,55);
        mote->draw_rect(fb, 2, 123, 40, 2, MOTE_RGB565(26,26,30), 1, 0,128);
        mote->draw_rect(fb, 2, 123, (int)(40*frac), 2, cc2, 1, 0,128);
    } else if (g_stam < 1.0f) {
        uint16_t sc = g_stam_spent ? MOTE_RGB565(150,60,40) : MOTE_RGB565(230,180,60);
        mote->draw_rect(fb, 2, 123, 40, 2, MOTE_RGB565(30,26,20), 1, 0,128);
        mote->draw_rect(fb, 2, 123, (int)(40*g_stam), 2, sc, 1, 0,128);
    }
    /* weapon + ammo */
    /* In the tank the weapon label is meaningless — B fires the cannon, not
     * whatever you were carrying — so the round count takes that slot. It
     * turns red at empty, which is the moment the tank stops being a weapon
     * and becomes just armour. */
    if (player.mode==MODE_CAR && player.car>=0 && cars[player.car].type==VEH_TANK)
        mote_ftextf(mote, fb, g_fmed, 52, 115,
                    g_shells ? MOTE_RGB565(220,220,140) : MOTE_RGB565(210,90,80),
                    "SHELL %d", g_shells);
    else
        mote_ftextf(mote, fb, g_fmed, 60, 115, MOTE_RGB565(220,220,140), "%s", WNAME[weapon]);
    if (weapon!=W_FIST && player.mode!=MODE_CAR)
        mote_ftextf(mote, fb, g_fmed, 108, 115, MOTE_RGB565(200,200,210), "%d", ammo[weapon]);
    /* SPEEDO, bottom right, only while driving. The built-in 3x5 font, not the
     * 1.5x UI one: "120MPH" at the larger size does not fit beside the weapon
     * label, and a speed readout wants to sit quietly in the corner. It takes
     * the ammo slot, which is the one thing on this row you are not reading
     * while your hands are on the wheel.
     *
     * c->spd is metres per second along the heading and goes negative in
     * reverse, so it is the magnitude that is shown. */
    if (player.mode==MODE_CAR && player.car>=0) {
        char sb[10];
        if (cars[player.car].type==VEH_HELI) {
            /* Height above the ground, not above whatever roof is underneath:
             * "0M" over a tower would be wrong when you are 24 m up. */
            int alt = (int)(g_heli_y + 0.5f); if (alt > 999) alt = 999;
            snprintf(sb, sizeof sb, "%dM", alt);
        } else {
        int mph = (int)(fabsf(cars[player.car].spd) * 2.2369f + 0.5f);
        if (mph > 999) mph = 999;
        snprintf(sb, sizeof sb, "%dMPH", mph); }
        int w = 0; for (const char *q = sb; *q; q++) w += 4;      /* 3x5 cell advance */
        mote->text(fb, sb, 126 - w, 117, MOTE_RGB565(210,222,240));
    }

    if (mission!=MI_NONE){
        uint16_t mcol=MOTE_RGB565(250,230,90); int t=(int)mission_t;
        switch (mission){
        case MI_COURIER: ftext_sh(g_fmed, fb, 2,12, mcol, "COURIER $%d %ds", mission_pay, t); break;
        case MI_RAMPAGE: ftext_sh(g_fmed, fb, 2,12, mcol, "RAMPAGE %d/%d %ds", mission_kills, mission_target, t); break;
        case MI_GETAWAY: ftext_sh(g_fmed, fb, 2,12, mcol, "LOSE HEAT %ds", t); break;
        case MI_HIT:     ftext_sh(g_fmed, fb, 2,12, mcol, "HIT $%d %ds", mission_pay, t); break;
        case MI_DELIVER: ftext_sh(g_fmed, fb, 2,12, mcol, mission_leg?"DELIVER $%d %ds":"STEAL CAR %ds", mission_leg?mission_pay:t, t); break;
        case MI_PICKUP:  ftext_sh(g_fmed, fb, 2,12, mcol, "PACKAGES %d/%d %ds", mission_kills, mission_target, t); break;
        case MI_REPO:    ftext_sh(g_fmed, fb, 2,12, mcol, "WRECK CAR %ds", t); break;
        case MI_ESCORT:  ftext_sh(g_fmed, fb, 2,12, mcol, "ESCORT VIP %ds", t); break;
        case MI_SMUGGLE: ftext_sh(g_fmed, fb, 2,12, mcol, "SMUGGLE (<%d*) %ds", mission_cap+1, t); break;
        case MI_DEMO:    ftext_sh(g_fmed, fb, 2,12, mcol, "WRECK %d/%d %ds", mission_kills, mission_target, t); break;
        case MI_VIGIL:   ftext_sh(g_fmed, fb, 2,12, mcol, "CULL %d/%d %ds", mission_kills, mission_target, t); break;
        case MI_WANTED:  ftext_sh(g_fmed, fb, 2,12, mcol, "SURVIVE %d/%ds", (int)mission_hold, mission_target); break;
        case MI_CIRCUIT: ftext_sh(g_fmed, fb, 2,12, mcol, "CP %d/%d %ds", cp_i, cp_n, t); break;
        case MI_RIVAL:   ftext_sh(g_fmed, fb, 2,12, mcol, "RACE %d-%d %ds", cp_i, rival_i, t); break;
        }
    }
    if (g_msg_t>0){ char l1[28], l2[28]; wrap2(g_fread, g_msg, 122, l1, l2, 28);  /* banner: wrap, never clip */
        uint16_t mtc=MOTE_RGB565(250,240,160);
        if (l2[0]){ mote_dim_box(fb, 0, 83, 128, 31, 6);
            mote_ftextc(mote, fb, g_fread, 64, 85, mtc, l1);
            mote_ftextc(mote, fb, g_fread, 64, 99, mtc, l2); }
        else { mote_dim_box(fb, 0, 99, 128, 17, 5);
            mote_ftextc(mote, fb, g_fread, 64, 102, mtc, l1); } }
    else if (near_marker(MK_GUN,3.0f)) mote_ftextc(mote, fb, g_fmed, 64,104, MOTE_RGB565(230,220,120), "RB: BUY WEAPON");
    else if (near_marker(MK_PHONE,3.0f)) mote_ftextc(mote, fb, g_fmed, 64,104, MOTE_RGB565(150,200,240), "RB: ANSWER PHONE");
    else if (near_marker(MK_SPRAY,3.4f)) {
        if (player.mode==MODE_CAR && wanted()>0) mote_ftextc(mote, fb, g_fmed, 64,104, MOTE_RGB565(120,220,150), "DRIVE IN: RESPRAY $100");
        else mote_ftextc(mote, fb, g_fmed, 64,104, MOTE_RGB565(120,220,150), "SPRAY SHOP: LOSE HEAT"); }
    else if (near_marker(MK_DOCK,3.6f)) mote_ftextc(mote, fb, g_fmed, 64,104, MOTE_RGB565(235,170,90), "DRIVE A CAR IN TO SELL");
    /* No standing control hint during play. It sat there permanently for
     * something you need once, on a 128 px panel where that line is 8% of the
     * height. The full list lives behind SETTINGS > CONTROLS instead. The
     * CONTEXTUAL prompts above stay — "RB: ANSWER PHONE" is telling you a phone
     * is in reach, which is state you cannot get any other way. */

    if (g_state==ST_PLAY && !g_showmap && g_radar_on) draw_radar(fb);

#ifdef MOTE_HOST
    /* Profiling HUD (Task 13). perf() fills [fps, update_us, raster_us, flush_us,
     * core0_pct, core1_pct] for the LATEST FRAME RECORDED — one frame behind this
     * draw, since mote_perf_record() runs after overlay() (os/mote_os.c:378-382).
     * That record also does NOT include overlay()'s own cost — see PROFILING.md.
     * scene_tri_count() IS current: it reflects this frame's committed scene,
     * built earlier in update(). Left in permanently, behind MOTE_GTA_DEBUG, so
     * whoever next tunes the VIEW_ radii or pool sizes has a live readout
     * instead of guessing. */
    if (getenv("MOTE_GTA_DEBUG")) {
        uint32_t pf[6] = {0};
        if (mote->perf) mote->perf(pf);
        char line[48];
        /* The HUD shows this frame; the pool has to be sized for the WORST
         * frame, so the peak goes to stderr where a headless run can read it. */
        int tris = mote->scene_tri_count();
        { static int tpeak = 0;
          if (tris > tpeak) { tpeak = tris; fprintf(stderr, "[TRI] peak=%d\n", tpeak); } }
        snprintf(line, sizeof line, "%ufps u%u r%u t%d",
                 pf[0], pf[1], pf[2], tris);
        mote_ftext(mote, fb, g_fmed, line, 2, 2, MOTE_RGB565(200,255,140));
        snprintf(line, sizeof line, "bb%d/%d drop%d", g_bb_used, MAX_BILLBOARDS, g_bb_budget_drop);
        mote_ftext(mote, fb, g_fmed, line, 2, 12, MOTE_RGB565(200,255,140));
    }
#endif
}

static const MoteGameVtbl k_vtbl = {
    .init = g_init, .update = g_update, .overlay = g_overlay,
    /* Task 13 profile (games/grandthumbauto3/PROFILING.md): max_tris and
     * max_tex_tris carry a wider-than-usual margin over their measured peaks
     * (~42% / ~38%, not the usual ~15%) because the host survey never
     * profiled COMBAT. It covered downtown/alley/park/bridge/facade-jam on
     * foot, combat-idle — no scene combined dense building geometry with a
     * firefight's vehicle count. wreck_car() (game.c) never removes a
     * wrecked car from the draw list, and the traffic streamer's target
     * moving-vehicle count is independent of wrecks, so husks accumulate ON
     * TOP of normal traffic rather than replacing it; a tank alone costs 4
     * boxes (body, cabin, turret cab, turret barrel) against a car's 2. A
     * prolonged firefight in a dense area can plausibly put more vehicle
     * geometry on screen than any profiled scene. Starvation is silent
     * (flat-tinted buildings, or objects that just don't draw), the arena
     * has ~35% headroom to spend even at the old, tighter margin, and there
     * is no cost argument for cutting it close when the failure mode is
     * invisible until someone hits it on hardware. */
    .config = { .max_tex_tris = 1100, .max_tris = 850, .depth = 1,
                .max_points = WATER_FLECKS_MAX,   /* water shimmer, depth-tested in the 3D pass */
                /* sun (halo + core = 2, or the moon's 1) + car lamps (4 per
                 * car inside VEH_DETAIL_R, so up to ~36) + cloud lobes
                 * (CLOUDS * 2 = 14) = 52. 40 left no room for the clouds, and
                 * since they are submitted first the overflow would have
                 * silently eaten CAR LAMPS instead. 16 more discs is 256 bytes
                 * of engine arena, not GAME_RAM. */
                .max_discs  = 56,
                /* max_shadows = 64, not 40: worst case is 18 car + up to 34
                 * in-view ped shadows = 52, which already exceeded 40 with
                 * vehicle shadows left ungated (fixed above). Same
                 * "combat was never profiled" argument as max_tris/
                 * max_tex_tris above, applied here too. */
                .max_shadows = 64,
                .max_bodies = NCAR+NSTAT, .max_contacts = 220,     /* 2D physics pool (ABI v42; 2-pt box manifolds, capped) */
                /* 112 slots (measured peak: downtown avenue, 92 live billboards
                 * with the pool uncapped — the entity-heaviest of the profiled
                 * scenes, so this already carries the most generous ratio of the
                 * three pools, +~22%), shared by peds, cops, pickups, the
                 * phonebox marker and trees, all gated through bb_add (see
                 * MAX_BILLBOARDS/g_bb_used above): a view-cone + distance test
                 * before anything is spent on an entity the camera can't see, and a
                 * budget guard so a pool that does fill degrades on purpose (far
                 * trees drop first) instead of silently dropping whatever the engine
                 * happened to see last. Keep this in sync with MAX_BILLBOARDS. See
                 * PROFILING.md for the full measurement. */
                /* max_lines = 48, not 24: game.c submits one tracer per alive
                 * bullet (NBULLET = 40), ungated, so an SMG burst could lose
                 * tracers silently past the old cap. */
                .max_billboards = MAX_BILLBOARDS, .max_lines = 48 },
};
static const MoteGameVtbl *mote_game_vtbl(void) { return &k_vtbl; }

MOTE_GAME_META("Grand Thumb Auto III", "austinio7116");
MOTE_GAME_VERSION("0.1.0");
